/*
 * Raspberry Pi 4 Model B — Soil Moisture Sensor (DFRobot v2.0)
 * ADC: MCP3008 on SPI0 (CE0 / GPIO8), MOSI / MISO / SCLK on BCM 10, 9, 11
 * Sensor analog out -> MCP3008 CH0
 * Sample period: 1 s, log raw 10-bit ADC value with timestamp
 * Build: gcc -O2 -Wall -o soil_moisture soil_moisture.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_DELAY_US    0
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_S 1          /* seconds between samples */
#define MAX_SPI_RETRIES 3          /* retries on transient SPI errors */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4       (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret >= 0) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc < 0 || adc > 1023) {
                fprintf(stderr, "ADC value out of range: %d\n", adc);
                return -1;
            }
            return adc;
        }

        fprintf(stderr, "SPI ioctl(SPI_IOC_MESSAGE): attempt %d/%d: %s\n",
                attempt, MAX_SPI_RETRIES, strerror(errno));
        if (attempt < MAX_SPI_RETRIES) {
            usleep(100000);  /* 100 ms backoff */
        }
    }

    fprintf(stderr, "SPI ioctl(SPI_IOC_MESSAGE) failed after %d attempts\n",
            MAX_SPI_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_moisture(int adc_value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] ADC Value: %d\n", ts, adc_value);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor (MCP3008 CH0) — sampling every %d s\n",
           SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int adc = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; continuing after backoff.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        log_moisture(adc);

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; ++i) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    if (close(spi_fd) != 0) {
        fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
    }
    return EXIT_SUCCESS;
}

