#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define ADS1115_CONFIG (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_raw(void) {
    char config_buf[3];
    char conv_buf[2];
    int16_t raw = 0;
    int retries = 0;

    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG & 0xFF;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
            fprintf(stderr, "Error: Failed to write ADS1115 config (attempt %d).\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        usleep(10000);

        config_buf[0] = ADS1115_REG_CONVERSION;
        if (i2cWriteDevice(i2c_handle, config_buf, 1) != 0) {
            fprintf(stderr, "Error: Failed to set ADS1115 conversion register (attempt %d).\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        if (i2cReadDevice(i2c_handle, conv_buf, 2) != 2) {
            fprintf(stderr, "Error: Failed to read ADS1115 conversion (attempt %d).\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        raw = (int16_t)((conv_buf[0] << 8) | conv_buf[1]);
        return raw;
    }

    fprintf(stderr, "Error: Failed to read ADS1115 after %d retries.\n", MAX_RETRIES);
    return 0;
}

static float convert_to_amperes(int16_t raw) {
    return (float)raw * 0.000125f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor Reader\n");
    printf("I2C Bus: %d, ADS1115 Addr: 0x%02X\n", I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int16_t raw = read_ads1115_raw();
        float current = convert_to_amperes(raw);

        printf("Current: %.4f A\n", current);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

