#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(int *flame_detected) {
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    *flame_detected = (level == 1);
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(const char *filename, int flame_detected, int adc_value) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open file %s for appending\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
