#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000
#define TEMPERATURE_THRESHOLD 60.0f
#define LOG_FILE_NAME "fire_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_ads1115(void) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error: ADS1115 config write failed\n");
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: ADS1115 conversion register select failed\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: ADS1115 conversion read failed\n");
        return -1;
    }
    *raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

static float convert_to_celsius(int16_t raw) {
    return (raw * 4.096f) / 32768.0f * 100.0f;
}

static void log_fire_event(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Fire detected! Both sensors active.\n", timestamp);
    fflush(log_file);
}

static void log_temperature(float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Temperature: %.2f C\n", timestamp, temp);
    fflush(log_file);
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION_US);
    gpioWrite(BUZZER_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_pigpio() != 0) {
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flame sensor pin\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin\n");
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_raw;
        if (read_ads1115(&flame_raw) != 0) {
            fprintf(stderr, "Warning: flame sensor read failed, skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        float flame_temp = convert_to_celsius(flame_raw);
        bool flame_active = (flame_temp > 50.0f);

        int debounce_count = 0;
        while (running && debounce_count < 5) {
            if (gpioRead(FLAME_SENSOR_PIN) == 1) {
                debounce_count++;
            } else {
                debounce_count = 0;
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }
        bool flame_confirmed = (debounce_count >= 5 && gpioRead(FLAME_SENSOR_PIN) == 1);

        int temp_raw;
        if (read_ads1115(&temp_raw) != 0) {
            fprintf(stderr, "Warning: temperature sensor read failed, skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        float temp = convert_to_celsius(temp_raw);

        if (flame_confirmed && flame_active) {
            printf("Flame detected! Temperature: %.2f C\n", flame_temp);
            log_fire_event();
        } else if (flame_active) {
            printf("Flame detected! Temperature: %.2f C\n", flame_temp);
        } else if (temp > TEMPERATURE_THRESHOLD) {
            printf("Temperature: %.2f C\n", temp);
            log_temperature(temp);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

