}

/* --------------------------- ADS1115 read -------------------------------- */

static int read_ads1115_raw(int16_t *raw)
{
    if (raw == NULL) {
        return -1;
    }

    /*
     * Write the config word to start a single-shot conversion.
     * i2cWriteWordData sends the data as [high_byte, low_byte] on the bus.
     */
    uint16_t cfg = ADS1115_CONFIG_BASE;
    int rc = i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG, cfg);
    if (rc < 0) {
        fprintf(stderr, "ADS1115 config write failed: %s\n", pigpio_error(rc));
        return -1;
    }

    /*
     * Wait for the conversion to complete.  128 SPS -> ~7.8 ms; 10 ms is safe.
     */
    gpioDelay(10000);  /* microseconds */

    /*
     * Read the conversion register (16-bit big-endian).
     * i2cReadWordData returns the raw 16-bit value (no sign extension).
     */
    int16_t val = i2cReadWordData(g_i2c_handle, ADS1115_REG_CONVERSION);
    if (val < 0) {
        fprintf(stderr, "ADS1115 conversion read failed: %s\n", pigpio_error(val));
        return -1;
    }

    *raw = val;
    return 0;
}

/* --------------------------- Concentration calc -------------------------- */

/*
 * MICS-4514 dual-element MOS sensor: resistance (R) is proportional to
 * the logarithm of the CO concentration (ppm).  The curve is calibrated
 * from a known resistance and ppm value.
 *
 * ppm = 10^(R / R0)  where R0 is the calibration resistance in ohms.
 *
 * Returns 0.0 on success, -1.0 on invalid input.
 */
static float calculate_co_concentration(int16_t raw)
{
    if (raw == 0) {
        return -1.0f;
    }

    /*
     * Placeholder calibration: raw counts map linearly to ppm.
     * Replace with the actual calibration curve from the datasheet.
     */
    float ppm = (float)raw * 0.1f;

    /* Clamp to a physically meaningful range */
    if (ppm < 0.0f) {
        ppm = 0.0f;
    }
    if (ppm > 1000.0f) {
        ppm = 1000.0f;
    }

    return ppm;
}

/* ------------------------------- Logging --------------------------------- */

static int log_co_concentration(float ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f ppm\n", ts, ppm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C and ADS1115 */
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C/ADS1115 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MICS-4514 CO logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw = 0;

        if (read_ads1115_raw(&raw) != 0) {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (%d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors. "
                                "Sensor may be disconnected or bus fault.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        consecutive_errors = 0;

        float ppm = calculate_co_concentration(raw);

        if (log_co_concentration(ppm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("CO: %.2f ppm (raw=%d)\n", ppm, raw);

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

