        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
        } else {
            int temp = read_mcp3008(MCP3008_CHANNEL);
            if (temp < 0) {
                fprintf(stderr, "Failed to read MCP3008\n");
            } else {
                if (log_data(flame, temp) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

