#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0f
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *ox, uint16_t *red) {
    char buf[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
        if (bytes_read == 4) {
            *ox = (uint16_t)((buf[0] << 8) | (buf[1] & 0xFF));
            *red = (uint16_t)((buf[2] << 8) | (buf[3] & 0xFF));
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "I2C read failed (attempt %d/%d), retrying...\n", retries, MAX_RETRIES);
            gpioDelay(100000);
        }
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static float convert_ox_to_ppm(uint16_t ox) {
    /* Placeholder linear conversion; replace with calibrated formula from datasheet */
    return (float)ox * 0.1f;
}

static int log_co_value(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        perror("Error opening alert log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, ALERT: CO concentration %.2f ppm exceeds threshold %.2f ppm\n",
            timestamp, co_ppm, ALERT_THRESHOLD);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("CO monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ox = 0, red = 0;

        if (read_sensor_data(&ox, &red) == 0) {
            float co_ppm = convert_ox_to_ppm(ox);

            if (log_co_value(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO value\n");
            }

            if (co_ppm >= ALERT_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

