#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC1_GPIO 2
#define MIC2_GPIO 3
#define I2C_BUS 1
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic_level(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1;
    }
    return level;
}

static double process_mic_data(int level) {
    /* IMP23ABSU analog output: 0 = silence, 1 = full-scale.
     * Convert to dBFS (0 dB = full-scale, -96 dB = noise floor).
     * Assumes 16-bit resolution; adjust for different ADCs. */
    double dbfs = 96.0 - (level * 96.0 / 15);
    return dbfs;
}

static void log_data(double avg_dbfs) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, avg_dbfs);
    } else {
        fprintf(fp, "unknown,%.2f\n", avg_dbfs);
    }

