#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 27
#define THRESHOLD 0.5f
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_WINDOW_MS)
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / 1000)
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double s = (double)samples[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / num_samples);
}

static void log_data(float rms1, float rms2) {
    FILE *fp = fopen("audio_events.csv", "a");
    if (!fp) {
        perror("fopen audio_events.csv");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.3f,%.3f\n", ts, rms1, rms2);
    }
    fclose(fp);
}

static void control_led(float rms1, float rms2) {
    if (rms1 > THRESHOLD || rms2 > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000);
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int samples1[NUM_SAMPLES];
    int samples2[NUM_SAMPLES];

    while (running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            samples1[i] = read_mcp3008(ADC_CHANNEL_1);
            samples2[i] = read_mcp3008(ADC_CHANNEL_2);
            if (samples1[i] < 0 || samples2[i] < 0) {
                fprintf(stderr, "ADC read error at sample %d\n", i);
                running = 0;
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!running) break;

        float rms1 = calculate_rms(samples1, NUM_SAMPLES);
        float rms2 = calculate_rms(samples2, NUM_SAMPLES);

        log_data(rms1, rms2);
        control_led(rms1, rms2);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

