static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 initialization ----------------------- */
static int ads1115_init(void)
{
    /*
     * Write the config register (big-endian 16-bit value).
     * pigpio's i2cWriteWordData sends the register address as the
     * low byte, followed by the high byte, so the ADS1115 receives
     * the config word correctly.
     */
    if (i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG,
                         ADS1115_CONFIG_BASE) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register: %s\n",
                strerror(errno));
        return -1;
    }

    /* Allow the first conversion to complete */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* --------------------------- ADS1115 read --------------------------------- */
static int ads1115_read_raw(int16_t *raw)
{
    if (raw == NULL) {
        return -1;
    }

    /*
     * Trigger a new single-shot conversion by writing the config
     * register with OS=1.
     */
    if (i2cWriteWordData(g_i2c_handle, ADS1115_REG_CONFIG,
                         ADS1115_CONFIG_BASE | 0x8000) < 0) {
        fprintf(stderr, "Error: failed to trigger ADS1115 conversion: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (poll OS bit) */
    for (int i = 0; i < 100; i++) {
        int cfg = i2cReadWordData(g_i2c_handle, ADS1115_REG_CONFIG);
        if (cfg < 0) {
            fprintf(stderr, "Error: failed to read ADS1115 config: %s\n",
                    strerror(errno));
            return -1;
        }
        if (cfg & 0x8000) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    /* Read the conversion result (2 bytes, big-endian) */
    int hi = i2cReadByteData(g_i2c_handle, ADS1115_REG_CONVERSION);
    if (hi < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion MSB: %s\n",
                strerror(errno));
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, ADS1115_REG_CONVERSION + 1);
    if (lo < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion LSB: %s\n",
                strerror(errno));
        return -1;
    }

    *raw = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

/* --------------------------- Raw -> current ------------------------------- */
static float raw_to_current(int16_t raw)
{
    /*
     * ADS1115 in single-ended mode, MUX=100 (A0):
     *   ±4.096 V range  -> 1 bit = 125 µV
     *   16-bit signed   -> 0x8000 = -32768 (full negative)
     *   0x7FFF = +32767  (full positive)
     *   Full-scale code = 32767
     *   Full-scale voltage = 32767 * 125 µV = 4.095625 V
     *   Current = voltage / 0.1 A/turn
     */
    const float full_scale_volts = 4.095625f;
    const float full_scale_code  = 32767.0f;
    const float current_per_turn = 0.1f;

    float voltage = ((float)raw / full_scale_code) * full_scale_volts;
    return voltage / current_per_turn;
}

/* --------------------------- Circular buffer ------------------------------ */
static void buffer_add(float current)
{
    g_buffer[g_buf_idx] = current;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) {
        g_buf_count++;
    }
}

static float buffer_average(void)
{
    if (g_buf_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++) {
        sum += g_buffer[i];
    }
    return sum / (float)g_buf_count;
}

/* ------------------------------- LED control ------------------------------ */
static void led_set(bool on)
{
    if (gpioWrite(LED_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to write LED GPIO %d: %s\n",
                LED_GPIO, strerror(errno));
    }
}

/* ------------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    led_set(false);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADS1115 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed (sensor absent?)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_set(false);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("MLX91204 current monitor started. Sampling at 10 Hz.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(&raw) < 0) {
            fprintf(stderr, "Error: ADC read failed; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);
        buffer_add(current);

        float avg = buffer_average();
        led_set(avg > CURRENT_THRESHOLD);

        printf("Raw: %6d  Current: %7.3f A  Avg: %7.3f A  LED: %s\n",
               raw, current, avg, avg > CURRENT_THRESHOLD ? "ON" : "OFF");

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

