#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define LOG_FILE       "color_log.csv"
#define READ_INTERVAL  1.0
#define MAX_CONSEC_FAILS 3

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_CDATAH  0x15
#define TCS34725_RDATAL  0x16
#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ID_VALUE    0x44

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int initialize_sensor(int handle)
{
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    time_sleep(0.002); /* power-on delay */

    if (i2c_write_byte(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    int id = i2cReadByteData(handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected ID register value: 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, uint16_t *clear, uint16_t *red,
                            uint16_t *green, uint16_t *blue)
{
    if (i2c_read_word(handle, TCS34725_CDATAL, clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATAL, red)   < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATAL, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATAL, blue) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    int consecutive_failures = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (read_sensor_data(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            if (log_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Sensor read failed (%d consecutive)\n",
                    consecutive_failures);
            if (consecutive_failures >= MAX_CONSEC_FAILS) {
                fprintf(stderr, "Too many consecutive failures; aborting\n");
                break;
            }
        }

        /* Sleep for the remainder of the one-second interval.
         * gpioSleep is non-blocking and returns early if a signal arrives. */
        gpioSleep(PI_TIME_RELATIVE, (int)READ_INTERVAL, 0);
    }

    cleanup();
    return EXIT_SUCCESS;
}

