#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define GPIO_CHIP       "gpiochip4"
#define MOTOR_SHUTDOWN  17
#define OVERCURRENT_THRESHOLD 10.0f

#define LOG_FILE        "current_log.csv"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES) {
            usleep(10000);
        }
    }
    return -1;
}

static float adc_to_amperes(int adc_value) {
    /* Placeholder linear conversion; replace with MLX91211 calibration curve */
    return (float)adc_value * 0.01f;
}

static void log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, current);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN);
    if (!shutdown_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(shutdown_line, "motor-shutdown", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        gpiod_line_release(shutdown_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Current(A)\n");
        fflush(fp);
    }

    printf("Monitoring current on MCP3008 channel 0. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries; skipping sample.\n", MAX_RETRIES);
        } else {
            float current = adc_to_amperes(adc_value);
            log_current(fp, current);

            if (current > OVERCURRENT_THRESHOLD) {
                printf("Overcurrent detected! Current: %.3f A\n", current);
                if (gpiod_line_set_value(shutdown_line, 0) < 0) {
                    perror("gpiod_line_set_value(0)");
                }
                sleep(1);
                if (gpiod_line_set_value(shutdown_line, 1) < 0) {
                    perror("gpiod_line_set_value(1)");
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(shutdown_line, 1);
    gpiod_line_release(shutdown_line);
    gpiod_chip_close(chip);
    fclose(fp);
    close(spi_fd);
    return EXIT_SUCCESS;
}

