static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read pressure from MLX90817                                         */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure_kPa)
{
    char buf[2];
    int  rc;
    int  retries = 0;

    while (retries < MAX_READ_RETRIES) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) |
                           ((uint16_t)(uint8_t)buf[1]);
            /* 16-bit big-endian, 0.01 kPa resolution */
            *pressure_kPa = (float)raw / 100.0f;
            return 0;
        }
        retries++;
        if (retries < MAX_READ_RETRIES)
            gpioDelay(100000); /* 100 ms back-off */
    }

    fprintf(stderr,
            "I2C read failed after %d retries (rc=%d)\n",
            MAX_READ_RETRIES, rc);
    return -1;
