    while (g_running) {
        float pressure;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            if (log_data(g_log_file, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Pressure: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
