code:
/*
 * Raspberry Pi 4 Model B — MLX90834 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX90834 SDA  -> I2C bus 1 SDA (GPIO2 / pin 3)
 *   MLX90834 SCL  -> I2C bus 1 SCL (GPIO3 / pin 5)
 *   MLX90834 VDD  -> 3.3 V
 *   MLX90834 GND  -> GND
 *   ADS1115 SDA   -> I2C bus 1 SDA (GPIO2 / pin 3)
 *   ADS1115 SCL   -> I2C bus 1 SCL (GPIO3 / pin 5)
 *   ADS1115 ADDR  -> GND (I2C address 0x48)
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   LED anode     -> GPIO17 (pin 11) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90834_app mlx90834_app.c -lpigpio -lrt
 * Run:    sudo ./mlx90834_app
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits 14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA     = 001 (±4.096 V)
 *   Bit  8     MODE    = 1  (single-shot)
 *   Bits 7:5   DR      = 100 (128 SPS)
 *   Bit  4     COMP_MODE= 0
 *   Bit  3     COMP_POL= 0
 *   Bit  2     COMP_LAT= 0
 *   Bits 1:0   COMP_QUE= 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE  0xC083

#define PRESSURE_CHANNEL     0
#define TEMPERATURE_CHANNEL  1

#define PRESSURE_THRESHOLD_KPA 105.0f
#define LED_GPIO              17
#define SAMPLE_PERIOD_US      1000000  /* 1 s */
#define I2C_RETRIES           3
#define I2C_RETRY_DELAY_US    10000    /* 10 ms */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  ads1115_write_config(int handle, uint16_t config);
static int  ads1115_read_conversion(int handle, int16_t *raw);
static int  read_pressure(int handle, float *pressure_kpa);
static int  read_temperature(int handle, float *temp_c);
static void control_led(int gpio, float pressure);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers --------------------------- */
static int ads1115_write_config(int handle, uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (config) failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONVERSION;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (conversion) failed\n");
        return -1;
    }

    *raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ----------------------------- Sensor reads ------------------------------ */
static int read_pressure(int handle, float *pressure_kpa)
{
    int16_t raw;
    int attempt;

    for (attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (ads1115_write_config(handle, ADS1115_CONFIG_BASE) != 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        gpioDelay(10000);

        if (ads1115_read_conversion(handle, &raw) != 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        /* ±4.096 V range: 1 bit = 125 µV */
        float voltage = (float)raw * 0.000125f;
        *pressure_kpa = voltage * 25.0f;   /* MLX90834: 25 kPa full-scale */
        return 0;
    }

    fprintf(stderr, "[ERROR] Pressure read failed after %d retries\n", I2C_RETRIES);
    return -1;
}

static int read_temperature(int handle, float *temp_c)
{
    int16_t raw;
    int attempt;

    for (attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (ads1115_write_config(handle, ADS1115_CONFIG_BASE) != 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        gpioDelay(10000);

        if (ads1115_read_conversion(handle, &raw) != 0) {
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        /* ±4.096 V range: 1 bit = 125 µV */
        float voltage = (float)raw * 0.000125f;
        *temp_c = voltage * 100.0f;   /* NTC: 100 °C full-scale */
        return 0;
    }

    fprintf(stderr, "[ERROR] Temperature read failed after %d retries\n", I2C_RETRIES);
    return -1;
}

/* ----------------------------- LED control ------------------------------- */
static void control_led(int gpio, float pressure)
{
    int level = (pressure > PRESSURE_THRESHOLD_KPA) ? 1 : 0;
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", gpio, level);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("MLX90834 pressure sensor via ADS1115 (I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_pressure(g_i2c_handle, &pressure) != 0) {
            fprintf(stderr, "[WARN] Pressure read failed; skipping cycle\n");
        } else if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "[WARN] Temperature read failed; skipping cycle\n");
        } else {
            printf("Pressure: %7.2f kPa  |  Temperature: %6.2f °C\n",
                   pressure, temperature);
            control_led(LED_GPIO, pressure);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

