#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define ADC_CHANNEL      0
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE         "current_log.txt"
#define GPIO_SHUTDOWN    27
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_adc(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     * Byte 2: 0x00 (don't care, clocks out low 2 bits)
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (value < 0 || value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

static double adc_to_current(int adc_value)
{
    /* Placeholder linear conversion; replace with sensor-specific calibration. */
    return (double)adc_value * 0.1;
}

static void log_event(FILE *fp, const char *event)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Reset shutdown GPIO to safe state. */
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO as output, initially LOW. */
    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SHUTDOWN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    /* Open SPI0 CE0 at 1 MHz, mode 0. */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring current on MCP3008 channel %d. Press Ctrl+C to exit.\n",
           ADC_CHANNEL);

    while (g_running) {
        int adc_value = read_adc(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            log_event(g_log_file, "ERROR: ADC read failure");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (current > CURRENT_THRESHOLD) {
            log_event(g_log_file, "OVERCURRENT: motor shutdown initiated");
            gpioWrite(GPIO_SHUTDOWN, 1);
            break;
        }

        char line[128];
        snprintf(line, sizeof(line), "Current: %.2f A", current);
        log_event(g_log_file, line);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

