/*
 * Raspberry Pi 4 Model B — MLX90830 pressure sensor reader
 *
 * Hardware:
 *   - Melexis MLX90830 analog pressure sensor (analog out -> ADS1115 AIN0)
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - MLX90830 VOUT wired to ADS1115 AIN0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48          /* ADDR pin tied to GND */

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits 14:12 MUX     = 100 (AIN0 vs GND)
 *   Bits 11:9  PGA     = 001 (±4.096 V range)
 *   Bit  8     MODE    = 1  (single-shot)
 *   Bits 7:5   DR      = 100 (128 SPS)
 *   Bit  4     COMP_MODE = 0
 *   Bit  3     COMP_POL  = 0
 *   Bit  2     COMP_LAT  = 0
 *   Bits 1:0   COMP_QUE  = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE  0xC083

#define PRESSURE_MIN_KPA     0.0f
#define PRESSURE_MAX_KPA     100.0f
#define SAMPLE_INTERVAL_US  1000000      /* 1 second */
#define LOG_FILE            "pressure_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  ads1115_init(int handle);
static int  ads1115_read(int handle, int16_t *raw);
static float raw_to_kpa(int16_t raw);
static int  log_pressure(float pressure);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 initialization ----------------------- */

static int ads1115_init(int handle)
{
    /*
     * Write the config register (2 bytes) with the big-endian value.
     * pigpio's i2cWriteWordData sends the low byte first, then the high byte,
     * which matches the ADS1115's 16-bit register format.
     */
    if (i2cWriteWordData(handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_BASE) < 0) {
        fprintf(stderr, "[ERROR] Failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

/* --------------------------- ADS1115 read --------------------------------- */

static int ads1115_read(int handle, int16_t *raw)
{
    int val = i2cReadWordData(handle, ADS1115_REG_CONVERSION);
    if (val < 0) {
        fprintf(stderr, "[ERROR] ADS1115 conversion read failed (pigpio error %d).\n", val);
        return -1;
    }

    /*
     * pigpio returns the raw 16-bit value as a signed int (two's complement).
     * The ADS1115 sends the MSB first, so we swap bytes to get the correct
     * big-endian value.
     */
    *raw = (int16_t)(((val & 0xFF) << 8) | ((val >> 8) & 0xFF));
    return 0;
}

/* --------------------------- Conversion ----------------------------------- */

static float raw_to_kpa(int16_t raw)
{
    /*
     * ADS1115 in single-shot mode, PGA = ±4.096 V.
     * 16-bit signed: 0x8000 = -32768, 0x7FFF = +32767.
     * Full-scale range = 4.096 V.
     * MLX90830 output is 0 V at 0 kPa and 4.096 V at 100 kPa.
     * So: kPa = raw * (100 kPa / 32767.0) = raw * (100000.0 / 32767.0)
     */
    return (float)raw * (100000.0f / 32767.0f);
}

/* --------------------------- Logging -------------------------------------- */

static int log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure) < 0) {
        perror("[ERROR] fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose");
        return -1;
    }

    return 0;
}

/* --------------------------- Cleanup -------------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed (pigpio error %d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADS1115 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MLX90830 pressure logger started. Sampling at 1 Hz. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw = 0;

        if (ads1115_read(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "[WARN] ADC read failed; skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = raw_to_kpa(raw);

        if (pressure < PRESSURE_MIN_KPA || pressure > PRESSURE_MAX_KPA) {
            fprintf(stderr, "[WARN] Pressure out of range: %.2f kPa (raw=%d).\n",
                    pressure, raw);
        } else {
            if (log_pressure(pressure) < 0) {
                fprintf(stderr, "[WARN] Failed to log pressure reading.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

