            if (log_pressure(pressure) < 0) {
                fprintf(stderr, "[WARN] Failed to log pressure reading.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
