#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_RECIPIENT_NAME "Recipient Name"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float convert_to_humidity(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        return -1.0;
    }
    return (float)adc_value / 4095.0 * 100.0;
}

static float convert_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        return -1.0;
    }
    return (float)adc_value / 4095.0 * 100.0 - 40.0;
}

static int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int send_email_alert(float humidity, float temperature) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp -t -a \"From: sender@example.com\" -a \"To: %s\" -a \"Cc: %s\"",
             humidity, temperature, EMAIL_RECIPIENT, EMAIL_RECIPIENT_NAME);

    int ret = system(command);
    if (ret == -1) {
        perror("Error executing ssmtp");
        return -1;
    }
    if (ret != 0) {
        fprintf(stderr, "ssmtp returned non-zero exit status: %d\n", ret);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = convert_to_humidity(adc_value);
        float temperature = convert_to_temperature(adc_value);

        if (humidity < 0 || temperature < -40.0 || temperature > 125.0) {
            fprintf(stderr, "Invalid sensor data: humidity=%.2f%%, temperature=%.2fC\n", humidity, temperature);
            sleep(1);
            continue;
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity, temperature) != 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        sleep(5);
    }

    printf("\nCleaning up...\n");
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

