#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define GPIO_CHIP        "gpiochip4"
#define CS_PIN           8
#define TMP36_CHANNEL    0

#define VREF             3.3f
#define ADC_MAX          4095.0f
#define TEMP_MIN_C       (-40.0f)
#define TEMP_MAX_C       (125.0f)

#define LOG_FILE         "temperature_log.csv"
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs   = NULL;
static FILE         *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs = gpiod_chip_get_line(g_chip, CS_PIN);
    if (!g_cs) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_cs, "mcp3208-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; g_cs = NULL; return -1;
    }

    return 0;
}

static int mcp3208_read(uint8_t channel, uint16_t *out)
{
    if (!g_cs || !g_chip || !out) return -1;

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(g_cs, 0) < 0) {
        fprintf(stderr, "CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs, 1); return -1;
    }

    if (gpiod_line_set_value(g_cs, 1) < 0) {
        fprintf(stderr, "CS high: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[1] & 0x0F) << 8) | rx[2];
    *out = raw;
    return 0;
}

static float adc_to_celsius(uint16_t adc)
{
    float voltage = ((float)adc / ADC_MAX) * VREF;
    return (voltage - 0.5f) * 100.0f;
}

static int log_open(void)
{
    int need_header = (access(LOG_FILE, F_OK) != 0);
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (need_header) {
        if (fprintf(g_log_fp, "timestamp,temperature_celsius\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
            fclose(g_log_fp); g_log_fp = NULL; return -1;
        }
        fflush(g_log_fp);
    }
    return 0;
}

static void log_sample(float temp)
{
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    if (localtime_r(&now, &tmv)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    }
    if (fprintf(g_log_fp, "%s,%.2f\n", ts, temp) < 0) {
        fprintf(stderr, "fprintf data: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_cs)     { gpiod_line_release(g_cs); g_cs = NULL; }
    if (g_chip)   { gpiod_chip_close(g_chip); g_chip = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) { cleanup(); return 1; }
    if (gpio_init() < 0) { cleanup(); return 1; }
    if (log_open()  < 0) { cleanup(); return 1; }

    printf("TMP36 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc = 0;
        if (mcp3208_read(TMP36_CHANNEL, &adc) < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float temp = adc_to_celsius(adc);

        if (temp < TEMP_MIN_C || temp > TEMP_MAX_C) {
            fprintf(stderr, "Warning: temperature out of range (%.2f C) — ADC=%u\n", temp, adc);
        }

        log_sample(temp);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return 0;
}

