/*
 * Raspberry Pi Zero W – Si1172-A30-GMR Heart Rate / SpO2 Logger
 *
 * Reads raw 16-bit IR and RED ADC samples from the Si1172 via I2C bus 1
 * and logs them to biometric_log.csv with a timestamp, HR (bpm), SpO2 (%),
 * and an error flag (0 = OK, 1 = read error, 2 = sensor absent/uninit).
 *
 * NOTE: The Si1172 is a proprietary GMR optical sensor that requires
 *       proprietary firmware / algorithm to convert raw PPG samples
 *       into meaningful HR and SpO2 values.  This program logs the
 *       raw 16-bit ADC values as proxy values; the HR and SpO2 fields
 *       are annotated with a comment indicating the data is synthetic.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c
 * Run:    ./si1172_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- Si1172 I2C address (7-bit) ---- */
#define SI1172_ADDR 0x60

/* ---- Si1172 register addresses ---- */
#define SI1172_REG_PART_ID      0x00
#define SI1172_REG_HW_KEY       0x07
#define SI1172_REG_MEAS_RATE0   0x08
#define SI1172_REG_MEAS_RATE1   0x09
#define SI1172_REG_ALS_IR_DATA0 0x22
#define SI1172_REG_ALS_IR_DATA1 0x23
#define SI1172_REG_ALS_RED_DATA0 0x24
#define SI1172_REG_ALS_RED_DATA1 0x25

/* ---- Expected PART_ID for Si1172-A30-GMR ---- */
#define SI1172_PART_ID_EXPECTED 0x72

/* ---- Error flags ---- */
#define ERR_OK          0
#define ERR_READ        1
#define ERR_SENSOR      2

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read word reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1172 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    uint8_t part_id = 0;

    /* Read PART_ID to confirm the sensor is present and responding. */
    if (i2c_read_byte(handle, SI1172_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[Si1172] cannot read PART_ID – sensor absent or bus error\n");
        return -1;
    }

    if (part_id != SI1172_PART_ID_EXPECTED) {
        fprintf(stderr, "[Si1172] unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1172_PART_ID_EXPECTED);
        return -1;
    }

    /*
     * Write the HW_KEY required by the Si1172 to enable proper
     * operation.  A value of 0x17 is a common default.
     */
    if (i2c_write_byte(handle, SI1172_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "[Si1172] failed to write HW_KEY\n");
        return -1;
    }

    /*
     * Set MEAS_RATE0 to 0x0A (10 ms) and MEAS_RATE1 to 0x00 (0 ms).
     * This starts the ALS measurement loop.
     */
    if (i2c_write_byte(handle, SI1172_REG_MEAS_RATE0, 0x0A) != 0) {
        fprintf(stderr, "[Si1172] failed to write MEAS_RATE0\n");
        return -1;
    }
    if (i2c_write_byte(handle, SI1172_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "[Si1172] failed to write MEAS_RATE1\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw ADC samples                                               */
/* ------------------------------------------------------------------ */
static int si1172_read_samples(int handle, uint16_t *ir, uint16_t *red)
{
    if (i2c_read_word(handle, SI1172_REG_ALS_IR_DATA0, ir) != 0)
        return -1;
    if (i2c_read_word(handle, SI1172_REG_ALS_RED_DATA0, red) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample                                                     */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, time_t ts, uint16_t ir, uint16_t red,
                       int hr, int spo2, int err)
{
    if (fprintf(fp, "%ld,%u,%u,%d,%d\n",
                (long)ts, ir, red, hr, spo2) < 0) {
        fprintf(stderr, "[LOG] write failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus 1 at Si1172 address ---- */
    g_i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file (append) ---- */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] cannot open biometric_log.csv: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,raw_ir,raw_red,hr_bpm,spo2_pct,error\n");
        fflush(g_log_file);
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* ---- initialize sensor ---- */
