#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define FLOW_MIN        0.0
#define FLOW_MAX        5.0
#define LOG_FILE        "flow_log.csv"
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device, uint32_t speed, uint8_t mode, uint8_t bits)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_flow(int adc_value)
{
    if (adc_value <= 0) return FLOW_MIN;
    if (adc_value >= ADC_MAX) return FLOW_MAX;
    return (double)adc_value / (double)ADC_MAX * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
}

static int log_flow_rate(FILE *fp, double flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS);
    if (spi_fd < 0) {
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC at extreme (%d). Sensor may be absent or disconnected.\n", adc_value);
        } else {
            double flow_rate = adc_to_flow(adc_value);
            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                fprintf(stderr, "Warning: Flow rate %.2f L/min out of range [%.1f, %.1f].\n", flow_rate, FLOW_MIN, FLOW_MAX);
            }
            if (log_flow_rate(log_fp, flow_rate) < 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    return 0;
}

