/*
 * Raspberry Pi 3 Model B+ - Dual MP23ABS1 Noise-Cancelled Audio Sampler
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (GPIO8), SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9
 *   - MP23ABS1 #1 on MCP3008 CH0, MP23ABS1 #2 on MCP3008 CH1
 *
 * Build: gcc -O2 -Wall -o audio_sampler audio_sampler.c -lm
 * Run:   ./audio_sampler gain1 gain2
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNELS    2
#define ADC_RESOLUTION  1024.0f
#define ADC_MAX         1023

#define SAMPLE_RATE_HZ  44100U
#define SAMPLE_PERIOD_NS (1000000000ULL / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Noise-cancelled sample                                              */
/* ------------------------------------------------------------------ */
static int32_t noise_cancel(int32_t s1, int32_t s2, float g1, float g2)
{
    float v1 = (float)s1 * g1 / ADC_RESOLUTION;
    float v2 = (float)s2 * g2 / ADC_RESOLUTION;

    /* Simple moving-average cancellation */
    static float prev1 = 0.0f, prev2 = 0.0f;
    float out = v1 - v2 + prev1 + prev2;
    prev1 = v1;
    prev2 = v2;
    return (int32_t)(out * ADC_RESOLUTION);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s gain1 gain2\n", argv[0]);
        return EXIT_FAILURE;
    }

    float gain1 = strtof(argv[1], NULL);
    float gain2 = strtof(argv[2], NULL);
    if (gain1 <= 0.0f || gain2 <= 0.0f) {
        fprintf(stderr, "Gain values must be positive\n");
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Sampling %u channels at %u Hz via MCP3008 on %s\n",
           ADC_CHANNELS, SAMPLE_RATE_HZ, SPI_DEVICE);
    printf("Gain1: %.2f  Gain2: %.2f\n", gain1, gain2);
    printf("Press Ctrl+C to stop.\n\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int32_t s1 = mcp3008_read(spi_fd, 0);
        int32_t s2 = mcp3008_read(spi_fd, 1);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "ADC read error — continuing\n");
            continue;
        }

        int32_t out = noise_cancel(s1, s2, gain1, gain2);

        printf("%d,%d,%d\n", s1, s2, out);
        fflush(stdout);

        /* Sleep to achieve the desired sample period */
        struct timespec ts = {
            .tv_sec  = (time_t)(SAMPLE_PERIOD_NS / 1000000000ULL),
            .tv_nsec = (long)(SAMPLE_PERIOD_NS % 1000000000ULL)
        };
        nanosleep(&ts, NULL);
    }

    /* ---- Cleanup ---- */
    close(spi_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

