/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO 8)                      */
#define SPI_BAUD         1000000    /* 1 MHz — well within MCP3008 spec        */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words     */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC full-scale                  */
#define SAMPLE_INTERVAL  60         /* seconds between readings               */

#define LOG_FILE         "moisture_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
