#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 500
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", AMBIENT_TEMP_FILE, strerror(errno));
        return 25.0f;
    }

    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", AMBIENT_TEMP_FILE);
        temp = 25.0f;
    }

    fclose(fp);
    return temp;
}

static float compensate_voltage(int adc_value, float ambient_temp) {
    if (ambient_temp <= 0.0f) return 0.0f;
    return (float)adc_value * (3.3f / 1024.0f) * (100.0f / ambient_temp);
}

static void log_data(int adc_value, float voltage, float compensated_voltage, float ambient_temp, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);
    fflush(log_fp);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_CHANGE, &(int){0}) < 0) {
        fprintf(stderr, "Warning: SPI chip select not supported\n");
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0 && adc_value <= 1023) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                usleep(10000);
            }
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Failed to read valid ADC value after %d retries.\n", MAX_RETRIES);
            log_data(-1, -1.0f, -1.0f, -1.0f, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float ambient_temp = read_ambient_temperature();
        float voltage = (float)adc_value * (3.3f / 1024.0f);
        float compensated_voltage = compensate_voltage(adc_value, ambient_temp);
        int flame_detected = (adc_value > FLAME_THRESHOLD) ? 1 : 0;

        log_data(adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        if (flame_detected) {
            if (ioctl(spi_fd, SPI_IOC_WR_CS_CHANGE, &(int){0}) < 0) {
                fprintf(stderr, "Warning: SPI chip select not supported\n");
            }
            if (ioctl(spi_fd, SPI_IOC_WR_CS_CHANGE, &(int){1}) < 0) {
                fprintf(stderr, "Warning: Failed to assert CS\n");
            }
            if (ioctl(spi_fd, SPI_IOC_WR_CS_CHANGE, &(int){0}) < 0) {
                fprintf(stderr, "Warning: Failed to deassert CS\n");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

