#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE_NAME "water_levels.json"
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double calculate_water_level_percentage(int adc_value) {
    if (adc_value < 0) return 0.0;
    if (adc_value > 1023) return 100.0;
    return ((double)adc_value / 1023.0) * 100.0;
}

static void control_led(double water_level_percentage) {
    int level = (water_level_percentage > WATER_LEVEL_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) != 0) {
        fprintf(stderr, "Failed to write LED GPIO %d\n", LED_GPIO);
    }
}

static void log_water_level(double water_level_percentage) {
    if (json_file == NULL) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed\n");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ldZ", ts.tv_nsec / 1000000);

    if (fprintf(json_file, "  {\"timestamp\": \"%s\", \"water_level_percentage\": %.2f},\n", timestamp, water_level_percentage) < 0) {
        fprintf(stderr, "Failed to write to JSON file\n");
    }
    fflush(json_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (json_file != NULL) {
        fseek(json_file, -2, SEEK_END);
        fprintf(json_file, "\n]");
        fclose(json_file);
        json_file = NULL;
    }
}

