/*
 * airflow_monitor.c — Raspberry Pi Zero W
 *
 * Reads a Honeywell AWM7300V mass airflow sensor via an MCP3008 10-bit ADC
 * on SPI0 (CE0 / physical pins 24, 23, 19, 21) and logs the reading to
 * airflow_log.csv every 100 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_monitor airflow_monitor.c -lpigpio -lrt
 * Run:    sudo ./airflow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (physical pin 24)            */
#define SPI_BAUD         1000000    /* 1 MHz — well within MCP3008 spec  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE             */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0    */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC full-scale              */

#define LOG_FILE         "airflow_log.csv"
#define SAMPLE_PERIOD_US 100000     /* 100 ms                            */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly            */
}

/* --------------------------- MCP3008 helpers ----------------------------- */

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0    -> 10-bit result
 */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* --------------------------- Logging helpers ----------------------------- */

static int log_file_open(void)
{
    int need_header = (access(LOG_FILE, F_OK) != 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (need_header) {
        if (fprintf(g_log_file, "timestamp,airflow_lpm\n") < 0) {
            perror("fprintf header");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        if (fflush(g_log_file) != 0) {
            perror("fflush header");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
    }

    return 0;
}

static int log_data(float airflow_lpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, airflow_lpm) < 0) {
        perror("fprintf data");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush data");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- pigpio init ----------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open -------------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file -------------------------------------------------------- */
    if (log_file_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --------------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop ------------------------------------------------------- */
    while (g_running) {
        int adc_value = mcp3008_read(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else {
            /* AWM7300V: ~0.01 LPM per LSB at 0–1000000 rpm */
            float airflow_lpm = (float)adc_value * 0.01f;
            if (log_data(airflow_lpm) != 0) {
                fprintf(stderr, "Logging error — continuing\n");
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

