    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return 0;
}

static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture(int adc_value)
{
    return (float)adc_value / 1023.0f * 100.0f;
}

static int log_data(FILE *fp, int adc_value, float moisture)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    spi_close();
}

int main(int argc, char *argv[])
{
    int interval = SAMPLE_INTERVAL;

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Warning: invalid interval '%s', using default %d seconds\n",
                    argv[1], interval);
            interval = SAMPLE_INTERVAL;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        spi_close();
        return 1;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, interval);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float moisture = calculate_moisture(adc_value);
            if (log_data(g_log_fp, adc_value, moisture) < 0) {
                fprintf(stderr, "Warning: log write failed\n");
            }
        }

        if (g_running) {
            sleep(interval);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

