/*
 * MLX90823 pressure sensor reader via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> MLX90823 analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90823_reader mlx90823_reader.c -lpigpio -lrt
 * Run:    sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (GPIO8) on SPI0 CE0 */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */
#define ADC_VREF         3.3        /* MCP3008 VREF tied to 3.3 V */

#define SAMPLE_PERIOD_S  1          /* Seconds between readings */
#define MAX_CONSECUTIVE_ERRORS 10   /* Abort after this many consecutive SPI failures */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static void cleanup(void);
static int  initialize(void);
static int  read_adc(int channel, int *out_value);
static float adc_to_voltage(int adc_value);
static float voltage_to_pressure(float voltage);
static void log_reading(float pressure, int adc_value);
static void log_error(const char *message);

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Initialization ---------------------------- */

static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d).\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        g_spi_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- MCP3008 read ----------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0    -> 10-bit result
 *
 * Returns 0 on success (value stored in *out_value), -1 on SPI error.
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ------------------------------- Conversion ------------------------------- */

static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
}

static float voltage_to_pressure(float voltage)
{
    /*
     * MLX90823 is a 0–3.3 V analog output.  At 0 V the sensor is
     * disconnected or absent; at 3.3 V the sensor is saturated.
     * A linear approximation is used here; for a production
     * deployment a calibrated transfer function should be employed.
     */
    if (voltage <= 0.0f) {
        return 0.0f;
    }
    if (voltage >= ADC_VREF) {
        return 3.3f;
    }
    return voltage;
}

/* ------------------------------- Logging ---------------------------------- */

static void log_reading(float pressure, int adc_value)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    printf("[%s] ADC=%4d  Pressure=%.2f V\n", ts, adc_value, pressure);
    fflush(stdout);
}

static void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(stderr, "[%s] ERROR: %s\n", ts, message);
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90823 pressure reader started.  SPI0 CE0 @ 1 MHz, ADC channel %d.\n",
           ADC_CHANNEL);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            log_error("SPI read failed; continuing.");
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("Max consecutive SPI errors reached. Aborting.");
                break;
            }
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        consecutive_errors = 0;

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        log_reading(pressure, adc_value);

        /*
         * Sensor-absent / saturation detection:
         *   0 V  -> sensor disconnected or not connected
         *   3.3 V -> sensor saturated (open circuit or short to VREF)
         */
        if (voltage <= 0.001f || voltage >= 3.299f) {
            log_error("Warning: ADC voltage at extreme (sensor absent or saturated).");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

