/*
 * Raspberry Pi Zero W – SEN0193 Capacitive Soil Moisture Sensor
 * via MCP3008 ADC on SPI0 (mode 0, 1 MHz).
 *
 * Wiring (BCM numbering):
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (Pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (Pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (Pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (Pin 24, SPI0 CE0)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CH0  -> SEN0193 analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 spec */
#define SPI_MODE        0
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define SAMPLE_INTERVAL 5          /* seconds between readings */

/* Fault thresholds: stuck at rail indicates a sensor-absent / wiring fault */
#define FAULT_LOW_VALUE  0
#define FAULT_HIGH_VALUE ADC_MAX_VALUE

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4       (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 Soil Moisture Sensor Reader\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("ADC channel: %u\n", ADC_CHANNEL);
    printf("Sample interval: %u s\n", SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "%s – SPI read error\n", ts);
        } else if (adc_value == FAULT_LOW_VALUE ||
                   adc_value == FAULT_HIGH_VALUE) {
            fprintf(stderr, "%s – ADC stuck at rail (value=%d) – sensor absent or wiring fault\n",
                    ts, adc_value);
        } else {
            printf("%s – ADC value: %d\n", ts, adc_value);
            fflush(stdout);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    if (close(spi_fd) < 0) {
        fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

