static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void add_to_buffer(int moisture_level, int pump_state) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               time_str,
               log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS) < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System\n");
    printf("MCP3008 on SPI0 CE0, VH400 on CH0, Pump on GPIO17\n");
    printf("Thresholds: LOW=%d, HIGH=%d, Sample=%d s\n",
           LOW_THRESHOLD, HIGH_THRESHOLD, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n\n");

    int pump_state = 0;

    while (running) {
        int moisture = read_mcp3008(MOISTURE_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "Error reading moisture level, retrying in %d s\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (moisture < LOW_THRESHOLD && pump_state == 0) {
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn pump ON\n");
            } else {
                pump_state = 1;
                printf("Pump ON (moisture=%d)\n", moisture);
            }
        } else if (moisture > HIGH_THRESHOLD && pump_state == 1) {
            if (gpioWrite(PUMP_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn pump OFF\n");
            } else {
                pump_state = 0;
                printf("Pump OFF (moisture=%d)\n", moisture);
            }
        }

        add_to_buffer(moisture, pump_state);
        print_buffer();

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

