#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x57
#define LOG_FILE "health_log.txt"
#define SAMPLE_INTERVAL_US 1000000

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fclose(fp);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(g_i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char wbuf[1] = {(char)reg};
    if (i2cWriteDevice(g_i2c_handle, wbuf, 1) < 0) return -1;
    char rbuf[1];
    if (i2cReadDevice(g_i2c_handle, rbuf, 1) != 1) return -1;
    *val = (uint8_t)rbuf[0];
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg(REG_PART_ID, &part_id) < 0) {
        log_error("Failed to read Part ID register");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID);
        log_error("MAX30102 Part ID mismatch");
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) < 0) {
        log_error("Failed to reset sensor");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) < 0) {
        log_error("Failed to clear interrupt enable");
        return -1;
    }
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) < 0) {
        log_error("Failed to clear FIFO write pointer");
        return -1;
    }
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) < 0) {
        log_error("Failed to clear overflow counter");
        return -1;
    }
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) < 0) {
        log_error("Failed to clear FIFO read pointer");
        return -1;
    }
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x0F) < 0) {
        log_error("Failed to configure FIFO");
        return -1;
    }
    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) < 0) {
        log_error("Failed to set mode config");
        return -1;
    }
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) < 0) {
        log_error("Failed to set SPO2 config");
        return -1;
    }
    if (i2c_write_reg(REG_LED1_PA, 0x24) < 0) {
        log_error("Failed to set LED1 current");
        return -1;
    }
    if (i2c_write_reg(REG_LED2_PA, 0x24) < 0) {
        log_error("Failed to set LED2 current");
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *spo2, float *heart_rate) {
    uint8_t status1 = 0, status2 = 0;
    if (i2c_read_reg(REG_INTR_STATUS_1, &status1) < 0) return -1;
    if (i2c_read_reg(REG_INTR_STATUS_2, &status2) < 0) return -1;

    if (status1 & 0x04) {
        uint8_t data[6];
        char wbuf[1] = {(char)REG_FIFO_DATA};
        if (i2cWriteDevice(g_i2c_handle, wbuf, 1) < 0) return -1;
        if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) return -1;

        uint32_t red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
        uint32_t ir = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

        if (red == 0 || ir == 0) return -1;

        int spo2_val = 0, heart_rate_val = 0;
        if (i2c_read_reg(REG_SPO2_CONFIG, &spo2_val) < 0) return -1;
        if (i2c_read_reg(REG_MODE_CONFIG, &heart_rate_val) < 0) return -1;

        *spo2 = (float)spo2_val / 2.0f;
        *heart_rate = (float)heart_rate_val / 100.0f;
        return 0;
    }
    return -1;
}

static void log_health_data(float spo2, float heart_rate) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d SpO2: %.2f%%, Heart Rate: %.2f BPM\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, spo2, heart_rate);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", g_i2c_handle);
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        log_error("MAX30102 initialization failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and Heart Rate...\n");

    while (g_running) {
        float spo2 = 0.0f, heart_rate = 0.0f;
        int ret = read_sensor_data(&spo2, &heart_rate);

        if (ret < 0) {
            fprintf(stderr, "Sensor read error\n");
            log_error("Sensor read error");
        } else {
            printf("SpO2: %.2f%%, Heart Rate: %.2f BPM\n", spo2, heart_rate);

            if (spo2 < 95.0f || heart_rate > 100.0f) {
                log_health_data(spo2, heart_rate);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

