#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define RELAY_PIN      17
#define REED_PIN       27
#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLE_DELAY_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define RELAY_PULSE_MS  3000
#define ADC_MAX         32767.0f
#define ADC_VREF        4.096f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = &reg },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = buf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_ads1115(int fd) {
    if (i2c_write_reg16(fd, 0x01, 0x8000) < 0) return -1;
    if (i2c_write_reg16(fd, 0x02, 0x0000) < 0) return -1;
    if (i2c_write_reg16(fd, 0x03, 0x0000) < 0) return -1;
    return 0;
}

static int read_adc(int fd, uint16_t *raw) {
    if (i2c_read_reg16(fd, 0x00, raw) < 0) return -1;
    return 0;
}

static float calibrate_ads1115(int fd) {
    float sum = 0.0f;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        uint16_t raw;
        if (read_adc(fd, &raw) < 0) {
            fprintf(stderr, "Calibration read %d failed, using 0\n", i);
            sum += 0.0f;
            usleep(CALIBRATION_DELAY_MS * 1000);
            continue;
        }
        float voltage = ((float)raw / ADC_MAX) * ADC_VREF;
        sum += voltage;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }
    return sum / CALIBRATION_SAMPLES;
}

static int read_reed_sensor(int pin) {
    return (digitalRead(pin) == 0) ? 1 : 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_ads1115(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        cleanup();
        return 1;
    }

    float calibration_voltage = calibrate_ads1115(g_i2c_fd);
    if (calibration_voltage <= 0.0f) {
        fprintf(stderr, "Calibration failed or sensor absent\n");
        cleanup();
        return 1;
    }
    float threshold_voltage = calibration_voltage * 0.8f;
    printf("Calibration complete. Threshold voltage: %.3f V\n", threshold_voltage);

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0 || gpioSetMode(REED_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_PIN, 0);

    while (g_running) {
        uint16_t raw;
        if (read_adc(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed, skipping cycle\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        float voltage = ((float)raw / ADC_MAX) * ADC_VREF;
        printf("Raw: %u, Voltage: %.3f V\n", raw, voltage);

        if (voltage < threshold_voltage) {
            printf("Distance below threshold, releasing door\n");
            gpioWrite(RELAY_PIN, 1);
            log_event("Door released");
            usleep(RELAY_PULSE_MS * 1000);
            gpioWrite(RELAY_PIN, 0);
            int reed = read_reed_sensor(REED_PIN);
            if (reed) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    cleanup();
    printf("Program terminated cleanly\n");
    return 0;
}

