#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <bcm2835.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE BCM2835_SPI_MODE0
#define SPI_BITS_PER_WORD 8

#define CS0_PIN RPI_GPIO_P1_24  /* GPIO8  */
#define CS1_PIN RPI_GPIO_P1_15  /* GPIO7  */
#define CS2_PIN RPI_GPIO_P1_22  /* GPIO25 */

#define NUM_SENSORS 3
#define LOG_INTERVAL_SEC 5
#define LOG_FILE "soil_moisture_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int cs_init(void)
{
    if (bcm2835_spi_chipSelect(BCM2835_SPI_CS_NONE) != BCM2835_SPI_OK) {
        fprintf(stderr, "Error setting SPI chip select to NONE: %s\n",
                bcm2835_error_string(bcm2835_spi_chipSelect(BCM2835_SPI_CS_NONE)));
        return -1;
    }

    if (bcm2835_gpio_fsel(CS0_PIN, BCM2835_GPIO_FSEL_OUTP) != BCM2835_GPIO_SUCCESS) {
        fprintf(stderr, "Error setting CS0 pin %d as output: %s\n",
                CS0_PIN, bcm2835_error_string(bcm2835_gpio_fsel(CS0_PIN, BCM2835_GPIO_FSEL_OUTP)));
        return -1;
    }
    if (bcm2835_gpio_fsel(CS1_PIN, BCM2835_GPIO_FSEL_OUTP) != BCM2835_GPIO_SUCCESS) {
        fprintf(stderr, "Error setting CS1 pin %d as output: %s\n",
                CS1_PIN, bcm2835_error_string(bcm2835_gpio_fsel(CS1_PIN, BCM2835_GPIO_FSEL_OUTP)));
        return -1;
    }
    if (bcm2835_gpio_fsel(CS2_PIN, BCM2835_GPIO_FSEL_OUTP) != BCM2835_GPIO_SUCCESS) {
        fprintf(stderr, "Error setting CS2 pin %d as output: %s\n",
                CS2_PIN, bcm2835_error_string(bcm2835_gpio_fsel(CS2_PIN, BCM2835_GPIO_FSEL_OUTP)));
        return -1;
    }

    /* Start with all CS lines high (deselected) */
    bcm2835_gpio_write(CS0_PIN, HIGH);
    bcm2835_gpio_write(CS1_PIN, HIGH);
    bcm2835_gpio_write(CS2_PIN, HIGH);

    return 0;
}

static int read_adc(int cs_pin, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    bcm2835_gpio_write(cs_pin, LOW);

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on CS%d: %s\n",
                cs_pin, strerror(errno));
        bcm2835_gpio_write(cs_pin, HIGH);
        return -1;
    }

    bcm2835_gpio_write(cs_pin, HIGH);

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static int log_data(int s1, int s2, int s3)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (g_log_fd < 0) {
        g_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (g_log_fd < 0) {
            fprintf(stderr, "Error opening log file %s: %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }

        /* Write header only if the file is newly created */
        if (fstat(g_log_fd, NULL) == 0) {
            char header[64];
            int len = snprintf(header, sizeof(header), "timestamp,sensor1,sensor2,sensor3\n");
            if (len > 0) {
                if (write(g_log_fd, header, (size_t)len) != len) {
                    fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
                    close(g_log_fd);
                    g_log_fd = -1;
                    return -1;
                }
            }
        }
    }

    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%d,%d,%d\n",
                       timestamp, s1, s2, s3);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "Error formatting log line\n");
        return -1;
    }

    if (write(g_log_fd, line, (size_t)len) != (ssize_t)len) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fd >= 0) {
        close(g_log_fd);
        g_log_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    bcm2835_spi_chipSelect(BCM2835_SPI_CS_NONE);
    bcm2835_spi_end();
    bcm2835_close();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (bcm2835_init() != BCM2835_SUCCESS) {
        fprintf(stderr, "Error initializing bcm2835: %s\n",
                bcm2835_error_string(bcm2835_init()));
        return 1;
    }

    if (spi_init() < 0) {
        bcm2835_close();
        return 1;
    }

    if (cs_init() < 0) {
        cleanup();
        return 1;
    }

    bcm2835_spi_chipSelect(BCM2835_SPI_CS_NONE);
    bcm2835_spi_setChipSelectPolarity(BCM2835_SPI_CS_NONE, LOW);

    printf("Soil Moisture Logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_adc(CS0_PIN, 0);
        int s2 = read_adc(CS1_PIN, 0);
        int s3 = read_adc(CS2_PIN, 0);

        if (log_data(s1, s2, s3) < 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        for (int i = 0; i < LOG_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

