/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E (linear)  -> ADS1115 AIN0 (single-ended)
 *   - ADS1115 on I2C bus 1, address 0x48
 *   - Motor shutdown relay / MOSFET on GPIO27 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:    sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config word: single-shot, AIN0 single-ended, PGA 4.096 V, 128 SPS, start */
#define ADS1115_CFG_BASE     0x8483  /* OS=1, MUX=100, PGA=001, MODE=1, DR=100, COMP_QUE=11 */

#define GPIO_SHUTDOWN        27
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     1000000  /* 1 second */
#define THRESHOLD_GAUSS      500.0f
#define VOLTAGE_MIN          0.0f
#define VOLTAGE_MAX          3.3f
#define PGA_FULL_SCALE       4.096f   /* Volts */
#define ADC_MAX              32767.0f /* 16-bit signed positive max */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_gpio_initialized = false;

/* Circular buffer for rolling average */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer g_buffer = { {0.0f}, 0, 0 };

/* --------------------------- Function prototypes -------------------------- */
static int  ads1115_init(int handle);
static int  ads1115_read(int handle, float *voltage);
static float voltage_to_gauss(float voltage);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);
static void shutdown_motor(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- ADS1115 --------------------------------- */
static int ads1115_init(int handle)
{
    /* Write config register (big-endian on the bus) */
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (char)((ADS1115_CFG_BASE >> 8) & 0xFF);
