#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define ADC_CHANNEL      0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO        18
#define WATERING_DURATION 10
#define POLL_INTERVAL    60
#define LOG_FILE         "watering_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel select)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(g_spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static int log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static int control_pump(int gpio_pin, int duration_seconds)
{
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate pump on GPIO %d\n", gpio_pin);
        return -1;
    }

    printf("Pump activated on GPIO %d for %d seconds\n", gpio_pin, duration_seconds);

    /*
     * gpioDelay is a busy-wait that is interrupted by signals, so we use
     * a loop with a small sleep to allow signal delivery promptly.
     */
    for (int i = 0; i < duration_seconds && g_running; i++) {
        sleep(1);
    }

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate pump on GPIO %d\n", gpio_pin);
        return -1;
    }
    printf("Pump deactivated on GPIO %d\n", gpio_pin);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output and ensure it starts OFF */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO %d to LOW\n", PUMP_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        control_pump(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        control_pump(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = read_mcp3008(ADC_CHANNEL);

        if (moisture_level < 0) {
            fprintf(stderr, "Error: failed to read ADC value\n");
        } else if (moisture_level < 0 || moisture_level > 1023) {
            fprintf(stderr, "Warning: ADC value out of range: %d\n", moisture_level);
        } else {
            printf("Moisture level: %d\n", moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Threshold exceeded! Activating pump.\n");
                if (control_pump(PUMP_GPIO, WATERING_DURATION) != 0) {
                    fprintf(stderr, "Error: pump control failed\n");
                }
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Graceful shutdown: ensure pump is off */
    printf("\nShutting down...\n");
    control_pump(PUMP_GPIO, 0);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

