/*
 * YL-83 rain sensor reader via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> YL-83 analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_sensor rain_sensor.c -lm
 * Run:    ./rain_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define SAMPLE_PERIOD_S 1

/* Rainfall intensity thresholds (raw ADC values) */
#define RAIN_INTENSITY_LOW   200
#define RAIN_INTENSITY_MED   400
#define RAIN_INTENSITY_HIGH  600

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Install SIGINT handler; returns 0 on success, -1 on failure.       */
static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* Open and configure the SPI device.                                  */
/* Returns a valid file descriptor on success, or -1 on failure.      */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                       */
/* Returns 0 on success (value stored in *out), -1 on error.           */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2].
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map raw ADC value to rainfall intensity level.                      */
static const char *rain_intensity_str(uint16_t raw)
{
    if (raw >= RAIN_INTENSITY_HIGH) return "HIGH";
    if (raw >= RAIN_INTENSITY_MED)  return "MED";
    if (raw >= RAIN_INTENSITY_LOW)  return "LOW";
    return "NONE";
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI on %s\n", SPI_DEVICE);
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on %s (SPI mode 0, %u Hz).\n",
           SPI_DEVICE, SPI_SPEED_HZ);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t raw = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &raw) != 0) {
            fprintf(stderr, "SPI read failed; skipping sample.\n");
        } else {
            const char *intensity = rain_intensity_str(raw);
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            } else {
                snprintf(ts, sizeof(ts), "UNKNOWN");
            }
            printf("[%s] ADC=%4u  Rain Intensity: %s\n", ts, raw, intensity);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
        }
    }
    rc = EXIT_SUCCESS;

    return rc;
}

