/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor
 *   - ADS1115 16-bit ADC on I2C bus 1, address 0x48
 *   - SS49E analog output -> ADS1115 AIN0 (single-ended)
 *   - LED + 330 Ω resistor on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:
 *   ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   OS=1 (start single conversion)
 *   MUX=100 (AIN0 single-ended)
 *   PGA=001 (4.096 V)
 *   MODE=1 (single-shot)
 *   DR=100 (128 SPS)
 *   COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11 (disable comparator)
 * => 0x8420
 */
#define ADS1115_CONFIG_BASE  0x8420

#define LED_GPIO             17
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define BLINK_DURATION_US    1000000 /* 1 s   */
#define BLINK_HALF_US        50000   /* 50 ms */

#define DEFAULT_THRESHOLD    100.0f

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */
static int ads1115_write_config(int handle, uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set conversion register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data.\n");
        return -1;
    }

    *raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and return the raw 16-bit value.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw)
{
    if (ads1115_write_config(handle, ADS1115_CONFIG_BASE) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS; poll up to 100 ms). */
    for (int i = 0; i < 10; i++) {
        gpioDelay(10000); /* 10 ms */
        int16_t v;
        if (ads1115_read_conversion(handle, &v) == 0)
            return 0;
    }

    fprintf(stderr, "Error: ADS1115 conversion timeout.\n");
    return -1;
}

/* --------------------------- Magnetic conversion ------------------------- */
/*
 * SS49E output voltage (V) = 0.025 × |field| (Gauss) × 4.096 V / 1000.
 * PGA gain = 4.096 V, so the raw ADC count is already in millivolts.
 * 1 LSB = 1 mV, so field (Gauss) = raw / 1000.
 */
static float raw_to_gauss(int16_t raw)
{
    return (float)raw / 1000.0f;
}

/* ------------------------------- LED blink -------------------------------- */
static void blink_led(int gpio_pin, int duration_us)
{
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Warning: failed to set LED GPIO high.\n");
        return;
    }
    gpioDelay(BLINK_HALF_US);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to set LED GPIO low.\n");
        return;
    }
    gpioDelay(BLINK_HALF_US);
}

/* --------------------------------- main ---------------------------------- */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        char *endptr;
        threshold = strtof(argv[1], &endptr);
        if (*endptr != '\0' || threshold <= 0.0f) {
            fprintf(stderr, "Error: invalid threshold '%s'.\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to ADS1115 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Hall-effect monitor started. Threshold: %.2f Gauss\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "Warning: ADC read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 s.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

