#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"

static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(m, NULL, MQTT_COMMAND_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_COMMAND_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *msg) {
    (void)m;
    (void)userdata;
    if (msg->payloadlen > 0) {
        char payload[16] = {0};
        int len = msg->payloadlen < (int)sizeof(payload) - 1 ? msg->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, msg->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "pump_on") == 0) {
            control_pump(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", payload);
        }
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mosquitto_loop_start(mosq) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Soil moisture monitor started");

    while (running) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            int moisture_percent = (int)(((float)moisture / 1023.0f) * 100.0f);
            syslog(LOG_INFO, "Moisture: %d%%", moisture_percent);

            if (moisture_percent < MOISTURE_THRESHOLD_LOW) {
                control_pump(1);
            } else if (moisture_percent > MOISTURE_THRESHOLD_HIGH) {
                control_pump(0);
            }

            char payload[32];
            snprintf(payload, sizeof(payload), "%d", moisture_percent);
            if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to publish moisture data");
            }
        }

        sleep(60);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

