#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define VREF        3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel, float *voltage) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *voltage = (adc_value / 1023.0f) * VREF;
    return 0;
}

static int log_data(const float voltages[NUM_CHANNELS]) {
    FILE *fp = fopen("sensor_data.csv", "a");
    if (!fp) {
        perror("fopen sensor_data.csv");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);

    if (fclose(fp) != 0) {
        perror("fclose sensor_data.csv");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    float voltages[NUM_CHANNELS];

    while (running) {
        int error = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (read_mcp3008(spi_handle, i, &voltages[i]) != 0) {
                error = 1;
                break;
            }
        }

        if (error) {
            fprintf(stderr, "Error reading one or more channels; aborting.\n");
            break;
        }

        if (log_data(voltages) != 0) {
            fprintf(stderr, "Error logging data; aborting.\n");
            break;
        }

        sleep(SAMPLE_INTERVAL);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

