    unsigned char cmd = 0x10;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("BH1750 write");
        return -1;
    }
    usleep(BH1750_PAUSE_MS * 1000);
    unsigned char buf[2] = {0};
    if (read(i2c_fd, buf, 2) != 2) {
        perror("BH1750 read");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

