    sigaction(SIGTERM, &sa, NULL);

    if (init_spi() != 0) return 1;
    if (init_i2c() != 0) { close(spi_fd); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(spi_fd); close(i2c_fd); return 1;
    }
    fprintf(log_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (running) {
        int sound = read_sound_level();
        int light = read_light_level();
        int err = 0;
        if (sound < 0) err |= 0x01;
        if (light < 0) err |= 0x02;
        log_data(sound, light, err);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_fp) fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

