#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define MCP3008_CHANNEL  0
#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30.0
#define SAMPLE_INTERVAL  60
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel select)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = spiXfer(handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES) {
            usleep(100000); /* 100 ms backoff */
        }
    }
    return -1;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_pump(int gpio_pin, bool on) {
    if (gpioWrite(gpio_pin, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d to %s\n",
                gpio_pin, on ? "ON" : "OFF");
    }
}

static void cleanup(void) {
    control_pump(PUMP_GPIO, false);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0); /* ensure pump is off at start */

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Sampling every %d s.\n",
           SAMPLE_INTERVAL);
    printf("MCP3008 channel %d, pump GPIO %d, threshold %.1f%%\n",
           MCP3008_CHANNEL, PUMP_GPIO, MOISTURE_THRESHOLD);
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008 after %d retries; skipping cycle\n",
                    MAX_RETRIES);
        } else {
            float moisture = calculate_moisture_percentage(adc_value);
            if (moisture < 0.0f) {
                fprintf(stderr, "Invalid moisture reading: %d\n", adc_value);
            } else {
                time_t now = time(NULL);
                struct tm tm_buf;
                struct tm *t = localtime_r(&now, &tm_buf);
                char ts[32];
                if (t) {
                    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
                } else {
                    snprintf(ts, sizeof(ts), "UNKNOWN");
                }
                printf("[%s] ADC=%4d  Moisture=%.1f%%  Pump=%s\n",
                       ts, adc_value, moisture,
                       moisture < MOISTURE_THRESHOLD ? "ON" : "OFF");
