    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double co2_ppm = calculate_co2_ppm(adc_value);
        if (co2_ppm < 0) {
            fprintf(stderr, "Error calculating CO2, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        control_fan(co2_ppm);
        log_data(co2_ppm, gpioRead(FAN_GPIO));

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, gpioRead(FAN_GPIO) ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

