    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float distance = adc_to_distance(adc);
        if (distance < 0) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance: %.2f cm - Opening door!\n", distance);
            gpioWrite(RELAY_GPIO, 1);
            log_event(distance);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            gpioWrite(RELAY_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

