#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>
#include <linux/pwmchip.h>
#include <errno.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"
#define TIMEOUT_US 30000
#define MAX_DISTANCE_CM 400.0f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pwm_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;
static float last_distance = 0.0f;
static int last_ldr_value = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int ret = write(fd, value, strlen(value));
    close(fd);
    return (ret < 0) ? -1 : 0;
}

static int read_file(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    int ret = read(fd, buf, len - 1);
    close(fd);
    if (ret < 0) return -1;
    buf[ret] = '\0';
    return 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    unsigned int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int pwm_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    if (write_file(path, "0") < 0 && errno != EBUSY) {
        fprintf(stderr, "Failed to export PWM channel: %s\n", strerror(errno));
        return -1;
    }
    pwm_exported = 1;
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "10000000") < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "0") < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    if (write_file(path, "1") < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        return -1;
    }
    pwm_enabled = 1;
    return 0;
}

static void pwm_set_duty(int duty_ns) {
    if (!pwm_enabled) return;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    char val[16];
    snprintf(val, sizeof(val), "%d", duty_ns);
    if (write_file(path, val) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

static void pwm_cleanup(void) {
    if (pwm_enabled) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        write_file(path, "0");
        pwm_enabled = 0;
    }
    if (pwm_exported) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        write_file(path, "0");
        pwm_exported = 0;
    }
    if (pwm_fd >= 0) close(pwm_fd);
}

static int read_ldr(void) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float get_distance(void) {
    char path[64];
    int trigger_fd = open("/sys/class/gpio/gpio23/value", O_WRONLY);
    if (trigger_fd < 0) {
        fprintf(stderr, "Failed to open trigger GPIO: %s\n", strerror(errno));
        return -1.0f;
    }
    int echo_fd = open("/sys/class/gpio/gpio24/value", O_RDONLY);
    if (echo_fd < 0) {
        fprintf(stderr, "Failed to open echo GPIO: %s\n", strerror(errno));
        close(trigger_fd); return -1.0f;
    }
    if (write(trigger_fd, "1", 1) < 0) {
        fprintf(stderr, "Failed to trigger: %s\n", strerror(errno));
        close(trigger_fd); close(echo_fd); return -1.0f;
    }
    usleep(10);
    if (write(trigger_fd, "0", 1) < 0) {
        fprintf(stderr, "Failed to reset trigger: %s\n", strerror(errno));
        close(trigger_fd); close(echo_fd); return -1.0f;
    }
    char buf[16];
    int timeout = 0;
    while (read(echo_fd, buf, 1) != 1) {
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Echo timeout\n");
            close(trigger_fd); close(echo_fd); return -1.0f;
        }
        usleep(100);
    }
    int start = 0;
    timeout = 0;
    while (read(echo_fd, buf, 1) == 1) {
        if (buf[0] == '1') break;
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Echo start timeout\n");
            close(trigger_fd); close(echo_fd); return -1.0f;
        }
    }
    if (timeout > TIMEOUT_US) { close(trigger_fd); close(echo_fd); return -1.0f; }
    int end = 0;
    timeout = 0;
    while (read(echo_fd, buf, 1) == 1) {
        if (buf[0] == '0') break;
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Echo end timeout\n");
            close(trigger_fd); close(echo_fd); return -1.0f;
        }
    }
