    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_mcp3008(0);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor after retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(1000000);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-initialization failed: %d\n", spi_handle);
                continue;
            }
            sensor_value = read_mcp3008(0);
            if (sensor_value < 0) {
                fprintf(stderr, "Failed to read sensor after re-initialization.\n");
                continue;
            }
        }

        int aqi = calculate_aqi(sensor_value);
        if (aqi < 0) {
            fprintf(stderr, "Invalid AQI calculation.\n");
            continue;
        }

        log_aqi(aqi);
        control_fan(aqi);

        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

