#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define ADC_MIN_VALUE   0
#define SAMPLE_INTERVAL 1
#define LOG_FILE        "alcohol_log.txt"
#define PPM_HIGH        50
#define PPM_LOW         20
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int mcp3008_read(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (g_cs_line) {
        if (gpiod_line_set_value(g_cs_line, 0) < 0) {
            fprintf(stderr, "Error: failed to assert CS: %s\n", strerror(errno));
            return -1;
        }
    }

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        if (g_cs_line) {
            gpiod_line_set_value(g_cs_line, 1);
        }
        return -1;
    }

    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int read_adc_with_retry(int channel) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int value = mcp3008_read(channel);
        if (value >= 0) {
            return value;
        }
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static void log_data(int adc_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: gmtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s, ADC: %d, %s\n", timestamp, adc_value, status);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, 8);
    if (!g_cs_line) {
        fprintf(stderr, "Error: cannot get GPIO8 line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mq3-spi-cs", 1) < 0) {
        fprintf(stderr, "Error: cannot request CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MQ-3 Alcohol Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc_with_retry(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed after %d retries\n", MAX_RETRIES);
            log_data(-1, "ERROR: ADC read failed");
        } else if (adc_value == ADC_MIN_VALUE || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC at rail (%d). Sensor absent or wiring fault?\n", adc_value);
            log_data(adc_value, "WARNING: sensor absent or wiring fault");
        } else {
            int ppm = (int)(((float)adc_value / ADC_MAX_VALUE) * 1000.0f);
            const char *status = "Alcohol level within acceptable range.";
            if (ppm > PPM_HIGH) {
                status = "Alcohol detected! Limit exceeded.";
            } else if (ppm < PPM_LOW) {
                status = "Sobriety confirmed.";
            }
            log_data(adc_value, status);
            printf("ADC: %d, PPM: %d, %s\n", adc_value, ppm, status);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

