#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* Motor 1 */
#define MOTOR1_DIR_PIN 23
#define MOTOR1_EN_PIN  18

/* Motor 2 */
#define MOTOR2_DIR_PIN 25
#define MOTOR2_EN_PIN  24

/* MCP3008 SPI */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Potentiometer channels on MCP3008 */
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

/* PWM range for motor enable pins */
#define PWM_RANGE 1000

/* Speed scaling factor (0..1000 -> 0..255) */
#define SPEED_SCALE 255.0f

/* Acceleration / deceleration time (seconds) */
#define ACCEL_TIME 2.0f
#define HOLD_TIME  2.0f
#define PAUSE_TIME 5.0f

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008                        */
/* Returns 0–1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Map potentiometer reading to a speed value (0–255)                 */
/* ------------------------------------------------------------------ */
static int map_pot_to_speed(int pot_value)
{
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    int speed = (int)((float)pot_value / 1023.0f * SPEED_SCALE);
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    return speed;
}

/* ------------------------------------------------------------------ */
/* Set motor direction and enable PWM                                    */
/* ------------------------------------------------------------------ */
static void set_motor_direction(int dir_pin, int direction)
{
    if (gpioWrite(dir_pin, direction) < 0) {
        fprintf(stderr, "Failed to write direction pin %d\n", dir_pin);
    }
}

static void set_motor_speed(int en_pin, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (gpioPWM(en_pin, speed) < 0) {
        fprintf(stderr, "Failed to set PWM on pin %d\n", en_pin);
    }
}

/* ------------------------------------------------------------------ */
/* Accelerate, hold, decelerate, pause, reverse, repeat                */
/* ------------------------------------------------------------------ */
static void run_cycle(int spi_handle)
{
    int pot1_value, pot2_value;
    int speed1, speed2;

    /* Acceleration phase */
    for (float t = 0.0f; t < ACCEL_TIME && g_running; t += 0.01f) {
        pot1_value = read_mcp3008(spi_handle, POT1_CHANNEL);
        pot2_value = read_mcp3008(spi_handle, POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometers during acceleration\n");
            return;
        }

        speed1 = map_pot_to_speed(pot1_value);
        speed2 = map_pot_to_speed(pot2_value);

        set_motor_speed(MOTOR1_EN_PIN, speed1);
        set_motor_speed(MOTOR2_EN_PIN, speed2);

        set_motor_direction(MOTOR1_DIR_PIN, 1);   /* forward */
        set_motor_direction(MOTOR2_DIR_PIN, 1);

        time_sleep(0.01);
    }

    /* Hold phase — keep speed constant */
    for (float t = 0.0f; t < HOLD_TIME && g_running; t += 0.01f) {
        time_sleep(0.01);
    }

    /* Deceleration phase */
    for (float t = 0.0f; t < ACCEL_TIME && g_running; t += 0.01f) {
        pot1_value = read_mcp3008(spi_handle, POT1_CHANNEL);
        pot2_value = read_mcp3008(spi_handle, POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometers during deceleration\n");
            return;
        }

        speed1 = map_pot_to_speed(pot1_value);
        speed2 = map_pot_to_speed(pot2_value);

        set_motor_speed(MOTOR1_EN_PIN, speed1);
        set_motor_speed(MOTOR2_EN_PIN, speed2);

        set_motor_direction(MOTOR1_DIR_PIN, 0);   /* reverse */
        set_motor_direction(MOTOR2_DIR_PIN, 0);

        time_sleep(0.01);
    }

    /* Pause */
    for (float t = 0.0f; t < PAUSE_TIME && g_running; t += 0.01f) {
        time_sleep(0.01);
    }

    /* Reverse direction */
    set_motor_direction(MOTOR1_DIR_PIN, 0);
    set_motor_direction(MOTOR2_DIR_PIN, 1);

    /* Re-accelerate in reverse direction */
    for (float t = 0.0f; t < ACCEL_TIME && g_running; t += 0.01f) {
        pot1_value = read_mcp3008(spi_handle, POT1_CHANNEL);
        pot2_value = read_mcp3008(spi_handle, POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometers during reverse acceleration\n");
            return;
        }

        speed1 = map_pot_to_speed(pot1_value);
        speed2 = map_pot_to_speed(pot2_value);

        set_motor_speed(MOTOR1_EN_PIN, speed1);
        set_motor_speed(MOTOR2_EN_PIN, speed2);

        set_motor_direction(MOTOR1_DIR_PIN, 0);   /* reverse */
        set_motor_direction(MOTOR2_DIR_PIN, 1);

        time_sleep(0.01);
    }

    /* Hold phase in reverse */
    for (float t = 0.0f; t < HOLD_TIME && g_running; t += 0.01f) {
        time_sleep(0.01);
    }

    /* Decelerate in reverse */
    for (float t = 0.0f; t < ACCEL_TIME && g_running; t += 0.01f) {
        pot1_value = read_mcp3008(spi_handle, POT1_CHANNEL);
        pot2_value = read_mcp3008(spi_handle, POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometers during reverse deceleration\n");
            return;
        }

        speed1 = map_pot_to_speed(pot1_value);
        speed2 = map_pot_to_speed(pot2_value);

        set_motor_speed(MOTOR1_EN_PIN, speed1);
        set_motor_speed(MOTOR2_EN_PIN, speed2);

        set_motor_direction(MOTOR1_DIR_PIN, 0);   /* reverse */
        set_motor_direction(MOTOR2_DIR_PIN, 1);

        time_sleep(0.01);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motors */
    gpioPWM(MOTOR1_EN_PIN, 0);
    gpioPWM(MOTOR2_EN_PIN, 0);

    /* Set direction pins low */
    gpioWrite(MOTOR1_DIR_PIN, 0);
    gpioWrite(MOTOR2_DIR_PIN, 0);

    /* Release GPIO pins */
    gpioSetMode(MOTOR1_DIR_PIN, PI_INPUT);
    gpioSetMode(MOTOR1_EN_PIN,  PI_INPUT);
    gpioSetMode(MOTOR2_DIR_PIN, PI_INPUT);
    gpioSetMode(MOTOR2_EN_PIN,  PI_INPUT);

    /* Close SPI */
    spiClose(g_spi_handle);

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins as outputs */
    if (gpioSetMode(MOTOR1_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_EN_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_EN_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range for enable pins */
    if (gpioSetPWMrange(MOTOR1_EN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_EN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    int g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        run_cycle(g_spi_handle);
    }

    /* Graceful cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

