                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_CS_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        uint32_t now_ns;
        clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);
        now_ns = (uint32_t)(next_deadline.tv_sec * 1000000000ULL +
                            next_deadline.tv_nsec);

        int adc_value = read_mcp3008(spi_fd, cs_line, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        if (log_sample(log_fp, now_ns, adc_value) != 0) {
            break;
        }

        next_deadline.tv_sec += next_deadline.tv_nsec / 1000000000ULL;
        next_deadline.tv_nsec %= 1000000000ULL;

        struct timespec req = { .tv_sec = next_deadline.tv_sec,
                                .tv_nsec = next_deadline.tv_nsec };
        struct timespec rem;
        while (nanosleep(&req, &rem) == -1 && errno == EINTR && g_running) {
            req = rem;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return ret;
}

