#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define ADC_CHANNEL 0
#define LOG_FILE    "gas_log.txt"
#define SAMPLE_US   1000000
#define RETRY_US    100000

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_voltage(int adc_value)
{
    return (adc_value / 1023.0f) * 3.3f;
}

static void log_data(float voltage, float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Voltage: %.3f V, PPM: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, voltage, ppm);
    } else {
        fprintf(fp, "Timestamp error, Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Propane leak detector started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in 100 ms...\n");
            gpioDelay(RETRY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm = 0.0f; /* Placeholder PPM value */

        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);
        log_data(voltage, ppm);

        gpioDelay(SAMPLE_US);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

