#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define CS_PIN 8
#define ADC_CHANNELS 3

#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2

#define ADXL335_VREF 3.3f
#define ADXL335_MAX_VOLTAGE 3.3f
#define ADXL335_MIN_VOLTAGE 0.0f

#define G_PER_COUNT 0.000244f
#define G_PER_COUNT_SQ 0.000000596f

#define KALMAN_ALPHA 0.9
#define KALMAN_BETA 0.001f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to assert CS pin\n");
        return -1;
    }

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS pin\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float kalman_filter(float raw, float *estimate, float *variance) {
    float new_variance = KALMAN_ALPHA * (*variance) + KALMAN_BETA;
    if (new_variance < 0.0f) new_variance = 0.0f;

    float new_estimate = (*estimate) + (raw - (*estimate)) * new_variance;
    *estimate = new_estimate;
    *variance = new_variance;

    return (*estimate) * G_PER_COUNT;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(CS_PIN, 1);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x_est = 0.0f, y_est = 0.0f, z_est = 0.0f;
    float x_var = 1.0f, y_var = 1.0f, z_var = 1.0f;

    while (running) {
        int x_raw = read_mcp3008(ADXL335_X_CHANNEL);
        int y_raw = read_mcp3008(ADXL335_Y_CHANNEL);
        int z_raw = read_mcp3008(ADXL335_Z_CHANNEL);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        float x_g = (float)x_raw * (ADXL335_MAX_VOLTAGE - ADXL335_MIN_VOLTAGE) / 1023.0f * G_PER_COUNT;
        float y_g = (float)y_raw * (ADXL335_MAX_VOLTAGE - ADXL335_MIN_VOLTAGE) / 1023.0f * G_PER_COUNT;
        float z_g = (float)z_raw * (ADXL335_MAX_VOLTAGE - ADXL335_MIN_VOLTAGE) / 1023.0f * G_PER_COUNT;

        float fx = kalman_filter(x_g, &x_est, &x_var);
        float fy = kalman_filter(y_g, &y_est, &y_var);
        float fz = kalman_filter(z_g, &z_est, &z_var);

        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", fx, fy, fz);
        fflush(stdout);

        gpioDelay(100000);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

