    if (fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Error reading one or more sensors, skipping logging.\n");
        } else {
            double m1 = convert_to_millitesla(s1);
            double m2 = convert_to_millitesla(s2);
            double m3 = convert_to_millitesla(s3);

            if (m1 < MIN_MILLITESLA || m1 > MAX_MILLITESLA ||
                m2 < MIN_MILLITESLA || m2 > MAX_MILLITESLA ||
                m3 < MIN_MILLITESLA || m3 > MAX_MILLITESLA) {
                fprintf(stderr, "Warning: Magnetic field out of range (sensor1: %.2f mT, sensor2: %.2f mT, sensor3: %.2f mT)\n",
                        m1, m2, m3);
            } else {
                if (log_data(m1, m2, m3) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

