#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define CSV_FILENAME    "sensor_data.csv"
#define NUM_CHANNELS    3
#define SAMPLE_DELAY_S  1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4       (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure SPI bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure SPI max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file for appending --- */
    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "Channel0,Channel1,Channel2\n");
    }

    printf("Logging MCP3008 channels 0-2 to %s. Press Ctrl+C to stop.\n",
           CSV_FILENAME);

    /* --- Main sampling loop --- */
    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = read_mcp3008(fd, (uint8_t)i);
            if (v < 0) {
                error = 1;
                break;
            }
            values[i] = v;
        }

        if (error) {
            fprintf(stderr, "SPI read error; aborting.\n");
            goto cleanup;
        }

        if (fprintf(fp, "%d,%d,%d\n", values[0], values[1], values[2]) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);

        sleep(SAMPLE_DELAY_S);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

