#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 0
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60
#define RECONNECT_BACKOFF_FACTOR 2
#define JSON_BUFFER_SIZE 512

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int led_state = 0;
static int pigpio_initialized = 0;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "MQTT connection error: %s", mosquitto_strerror(result));
        log_error(buf);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    if (result != MOSQ_ERR_SUCCESS) {
        log_error("Unexpected MQTT disconnect");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_error("Empty MQTT message received");
        return;
    }

    if (message->payloadlen > JSON_BUFFER_SIZE) {
        log_error("JSON payload too large");
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (!payload) {
        log_error("Memory allocation failed for JSON payload");
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);
    free(payload);

    if (!root) {
        char buf[256];
        snprintf(buf, sizeof(buf), "JSON parse error: %s at line %d, column %d",
