#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_INTERVAL_MS 100
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (GPIO17) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (sound_line == NULL) {
        perror("gpiod_chip_get_line(sound)");
        goto cleanup;
    }

    /* Request the sound sensor line as input */
    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        goto cleanup;
    }

    /* Get the alarm LED line (GPIO18) */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request the alarm LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Sound sensor monitoring started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("gpiod_line_get_value(sound)");
            goto cleanup;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* KY-038 DO goes LOW when sound exceeds threshold */
            printf("Sound event detected! Activating alarm LED.\n");
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led, on)");
                goto cleanup;
            }
            usleep(ALARM_DURATION_MS * 1000);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, off)");
                goto cleanup;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line != NULL) {
        gpiod_line_release(sound_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program terminated cleanly.\n");
    }
    return ret;
}

