/*
 * BMP280 barometric-altitude logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   BMP280 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   BMP280 VDD  -> 3.3 V
 *   BMP280 GND  -> GND
 *
 * The BMP280 is a 3.3 V logic device and must never be driven with 5 V.
 * This program uses pigpio for I2C and handles SIGINT/SIGTERM for clean
 * shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP280 register addresses ---- */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88

#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static bmp280_calib_t g_cal;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(g_i2c_handle, reg) < 0)
        return -1;
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    return (i2cWriteDevice(g_i2c_handle, buf, 2) == 0) ? 0 : -1;
}

/* ---- Read calibration coefficients ---- */
static int read_calibration(void)
{
    uint8_t cal[24];
    if (i2c_read_reg(BMP280_REG_CALIB, cal, sizeof(cal)) < 0) {
        fprintf(stderr, "Error: failed to read BMP280 calibration data\n");
        return -1;
    }

    g_cal.dig_T1 = (uint16_t)(cal[0]  | (cal[1]  << 8));
    g_cal.dig_T2 = (int16_t)(cal[2]  | (cal[3]  << 8));
    g_cal.dig_T3 = (int16_t)(cal[4]  | (cal[5]  << 8));
    g_cal.dig_P1 = (uint16_t)(cal[6]  | (cal[7]  << 8));
    g_cal.dig_P2 = (int16_t)(cal[8]  | (cal[9]  << 8));
    g_cal.dig_P3 = (int16_t)(cal[10] | (cal[11] << 8));
    g_cal.dig_P4 = (int16_t)(cal[12] | (cal[13] << 8));
    g_cal.dig_P5 = (int16_t)(cal[14] | (cal[15] << 8));
    g_cal.dig_P6 = (int16_t)(cal[16] | (cal[17] << 8));
    g_cal.dig_P7 = (int16_t)(cal[18] | (cal[19] << 8));
    g_cal.dig_P8 = (int16_t)(cal[20] | (cal[21] << 8));
    g_cal.dig_P9 = (int16_t)(cal[22] | (cal[23] << 8));
    return 0;
}

/* ---- Read raw temperature and pressure ---- */
static int read_raw(int32_t *raw_t, int32_t *raw_p)
{
    uint8_t data[6];
    if (i2c_read_reg(BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error: failed to read BMP280 data registers\n");
        return -1;
    }
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

/* ---- Temperature compensation (BMP280 datasheet, section 4.2) ---- */
static double compensate_temperature(int32_t raw_t)
{
    double var1 = ((double)raw_t / 16384.0 - (double)g_cal.dig_T1 / 1024.0) * (double)g_cal.dig_T2;
    double var2 = ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0) *
                  ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0) * (double)g_cal.dig_T3;
    return var1 + var2;
}

/* ---- Pressure compensation (BMP280 datasheet, section 4.3) ---- */
static double compensate_pressure(int32_t raw_p, double t_fine)
{
    double var1 = t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)g_cal.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)g_cal.dig_P5 * 2.0;
    var2 = var2 / 4.0 + (double)g_cal.dig_P4 * 65536.0;
    var1 = ((double)g_cal.dig_P3 * var1 * var1 / 524288.0 + (double)g_cal.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)g_cal.dig_P1;
    if (var1 < 1.0) var1 = 1.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = (double)g_cal.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)g_cal.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)g_cal.dig_P7) / 16.0;
    return p;
}

/* ---- Compute altitude from pressure (BMP280 datasheet, section 4.4) ---- */
static double compute_altitude(double pressure_pa)
{
    const double sea_level_pa = 101325.0;
    return 44330.0 * (1.0 - pow(pressure_pa / sea_level_pa, 0.1903));
}

/* ---- Log altitude with timestamp ---- */
static int log_altitude(double altitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (fprintf(g_log_file, "%s, %.2f\n", ts, altitude) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed on log file\n");
        return -1;
    }
    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at BMP280 default address 0x76 ---- */
    g_i2c_handle = i2cOpen(1, 0x76, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that i2c is enabled.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify chip ID ---- */
    uint8_t id;
    if (i2c_read_reg(BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: failed to read BMP280 chip ID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n", id, BMP280_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Read calibration ---- */
    if (read_calibration() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open altitude_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor: osrs_t=1 (x1), osrs_p=1 (x1), mode=normal ---- */
    if (i2c_write_reg(BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write BMP280 config register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write BMP280 ctrl_meas register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int32_t raw_t, raw_p;
        if (read_raw(&raw_t, &raw_p) < 0) {
            fprintf(stderr, "Warning: read_raw failed, retrying in 5 s\n");
            sleep(5);
            continue;
        }

        double t_fine = compensate_temperature(raw_t);
        double pressure_pa = compensate_pressure(raw_p, t_fine);
        double altitude = compute_altitude(pressure_pa);

        if (log_altitude(altitude) < 0) {
            fprintf(stderr, "Warning: log_altitude failed\n");
        }

        printf("Altitude: %.2f m\n", altitude);
        sleep(5);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

