    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that i2c is enabled.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify chip ID ---- */
    uint8_t id;
    if (i2c_read_reg(BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: failed to read BMP280 chip ID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n", id, BMP280_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Read calibration ---- */
    if (read_calibration() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open altitude_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor: osrs_t=1 (x1), osrs_p=1 (x1), mode=normal ---- */
    if (i2c_write_reg(BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write BMP280 config register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write BMP280 ctrl_meas register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int32_t raw_t, raw_p;
        if (read_raw(&raw_t, &raw_p) < 0) {
            fprintf(stderr, "Warning: read_raw failed, retrying in 5 s\n");
            sleep(5);
            continue;
        }

        double t_fine = compensate_temperature(raw_t);
        double pressure_pa = compensate_pressure(raw_p, t_fine);
        double altitude = compute_altitude(pressure_pa);

        if (log_altitude(altitude) < 0) {
            fprintf(stderr, "Warning: log_altitude failed\n");
        }

        printf("Altitude: %.2f m\n", altitude);
        sleep(5);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

