#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define BUFFER_SIZE     120
#define SAMPLE_INTERVAL 5
#define LOG_FILE        "temp_log.dat"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %d: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_celsius(int adc_value)
{
    return (float)adc_value * 0.01f;
}

static void store_temperature(float temperature, float buffer[], int *index)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(const float buffer[], const char *filename)
{
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n",
                filename, strerror(errno));
        return -1;
    }

    if (fwrite(buffer, sizeof(float), BUFFER_SIZE, fp) != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file %s: %s\n",
                filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking in file %s: %s\n",
                filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n",
                filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Skipping sample due to SPI read error.\n");
        } else {
            float temperature = adc_to_celsius(adc_value);
            store_temperature(temperature, temperature_buffer, &buffer_index);
            printf("Temperature: %.2f °C\n", temperature);
        }

        if (write_buffer_to_file(temperature_buffer, LOG_FILE) < 0) {
            fprintf(stderr, "Warning: failed to write to log file.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

