    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %.2f, Sound: %d\n", timestamp, lux, adc_value);
    fclose(fp);
