int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: Failed to set up signal handler");
        return 1;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error: Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }
    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Error: Failed to configure SPI");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (mcp3008_init(spi_fd) < 0) {
        fprintf(stderr, "Error: MCP3008 initialization failed.\n");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int adc_value = 0;
        int bh1750_ok = (bh1750_read_lux(i2c_fd, &lux) == 0);
        int mcp3008_ok = (mcp3008_read_adc(spi_fd, &adc_value) == 0);

        if (bh1750_ok && mcp3008_ok) {
            if (log_data(lux, adc_value) < 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed (BH1750: %s, MCP3008: %s).\n",
                    bh1750_ok ? "OK" : "FAIL",
                    mcp3008_ok ? "OK" : "FAIL");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(spi_fd);
    close(i2c_fd);
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

