#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x60
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL 0.5
#define MAX_RETRIES 3

static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int write_mcp4725(uint16_t value) {
    if (value > 4095) {
        fprintf(stderr, "Invalid DAC value: %u\n", value);
        return -1;
    }

    uint8_t buf[3] = {0x00, (uint8_t)((value >> 4) & 0xFF), (uint8_t)((value << 4) & 0xF0)};
    if (write(i2c_fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static float calculate_temperature(int adc_value) {
    return (adc_value * 1.0f) / 1023.0f * 3.3f * 100.0f / 1.0f;
}

static int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("temperature_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n",
            timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file);

    printf("%s, ADC: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n",
           timestamp, adc_value, temperature, dac_voltage);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (i2c_init() < 0) {
        cleanup();
        return 1;
    }

    printf("Temperature control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries. Skipping sample.\n", MAX_RETRIES);
            continue;
        }

        float temperature = calculate_temperature(adc_value);
        float dac_voltage = temperature;

        if (write_mcp4725((uint16_t)(dac_voltage * 10.0f)) < 0) {
            fprintf(stderr, "Failed to write DAC value.\n");
        }

        if (log_data(adc_value, temperature, dac_voltage) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

