#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d (state %d)\n", pin, state);
        return -1;
    }
    return 0;
}

static int activate_relay(int pin) {
    if (set_relay(pin, 1) != 0) return -1;
    printf("Relay on GPIO %d activated\n", pin);
    return 0;
}

static int deactivate_relay(int pin) {
    if (set_relay(pin, 0) != 0) return -1;
    printf("Relay on GPIO %d deactivated\n", pin);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set all relay pins as outputs and ensure they start LOW (inactive) */
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay(pins[i], 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    while (running) {
        int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (!running) break;
            if (activate_relay(pins[i]) != 0) {
                fprintf(stderr, "Error activating relay on GPIO %d, exiting\n", pins[i]);
                break;
            }
            sleep(1);
            if (!running) break;
            if (deactivate_relay(pins[i]) != 0) {
                fprintf(stderr, "Error deactivating relay on GPIO %d, exiting\n", pins[i]);
                break;
            }
            sleep(1);
        }
    }

    /* Clean shutdown: deactivate all relays and release GPIO */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        set_relay(pins[i], 0);
    }
    gpioTerminate();
    printf("Light sequencer stopped.\n");
    return EXIT_SUCCESS;
}

