#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CLAP_SENSOR_PIN 26
#define LED_PIN 16
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000
#define ADC_MAX 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] ", buf);
}

static void led_on(void) {
    gpioWrite(LED_PIN, 1);
}

static void led_off(void) {
    gpioWrite(LED_PIN, 0);
}

static bool read_adc(uint16_t *value) {
    uint32_t sum = 0;
    int valid_samples = 0;
    for (int i = 0; i < 10; i++) {
        int bit = gpioRead(CLAP_SENSOR_PIN);
        if (bit < 0) {
            return false;
        }
        sum += (uint32_t)bit;
        gpioDelay(SAMPLE_DELAY_US);
        valid_samples++;
    }
    *value = (uint16_t)(sum / valid_samples);
    return true;
}

static bool detect_clap(uint16_t adc_value) {
    return adc_value > (ADC_MAX / 2);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CLAP_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set CLAP_SENSOR_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    led_off();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_detection_time = 0;

    while (running) {
        uint16_t adc_value;
        if (!read_adc(&adc_value)) {
            fprintf(stderr, "ADC read error, continuing\n");
            gpioDelay(100000);
            continue;
        }

        if (detect_clap(adc_value)) {
            uint32_t now = gpioTick();
            if (now - last_detection_time >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                print_timestamp();
                printf("Clap detected!\n");
                fflush(stdout);
                led_on();
                gpioDelay(LED_ON_MS * 1000);
                led_off();
                last_detection_time = now;
            }
        }

        gpioDelay(10000);
    }

    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

