#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(void) {
    FILE *fp = fopen("/sys/class/gpio/gpio17/value", "r");
    if (!fp) {
        fprintf(stderr, "Error opening GPIO file: %s\n", strerror(errno));
        return -1;
    }

    int distance = -1;
    if (fscanf(fp, "%d", &distance) != 1) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return distance;
}

static void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "Timestamp error, Distance: %d mm\n", distance);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (chdir("/sys/class/gpio") != 0) {
        fprintf(stderr, "Failed to change directory to /sys/class/gpio: %s\n", strerror(errno));
        return 1;
    }

    FILE *export_fp = fopen("export", "w");
    if (!export_fp) {
        fprintf(stderr, "Failed to open export file: %s\n", strerror(errno));
        return 1;
    }

    if (fprintf(export_fp, "%d", GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to write to export file: %s\n", strerror(errno));
        fclose(export_fp);
        return 1;
    }

    fclose(export_fp);

    sleep(1);

    FILE *dir_fp = fopen("gpio17/direction", "w");
    if (!dir_fp) {
        fprintf(stderr, "Failed to open direction file: %s\n", strerror(errno));
        return 1;
    }

    if (fprintf(dir_fp, "in") < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        fclose(dir_fp);
        return 1;
    }

    fclose(dir_fp);

    printf("Distance sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying in 1 second...\n");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");

    FILE *unexport_fp = fopen("unexport", "w");
    if (unexport_fp) {
        fprintf(unexport_fp, "%d", GPIO_PIN);
        fclose(unexport_fp);
    }

    return 0;
}

