#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_magnetic_field(int adc_value)
{
    /* DRV5055-A1: VOUT = 0.01 * B_mt (mT) */
    return (float)adc_value * 0.01f;
}

static int log_data(FILE *fp, time_t timestamp, float magnetic_field)
{
    if (fprintf(fp, "%ld,%.2f\n", (long)timestamp, magnetic_field) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int ret_code = EXIT_SUCCESS;

    while (g_running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
        } else {
            float magnetic_field = convert_to_magnetic_field(adc_value);
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "time: %s\n", strerror(errno));
            } else {
                if (log_data(log_fp, now, magnetic_field) < 0) {
                    ret_code = EXIT_FAILURE;
                }
            }
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    if (log_fp) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log): %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            fprintf(stderr, "close(spi): %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }

    return ret_code;
}

