                fprintf(stderr, "time: %s\n", strerror(errno));
            } else {
                if (log_data(log_fp, now, magnetic_field) < 0) {
                    ret_code = EXIT_FAILURE;
                }
            }
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    if (log_fp) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log): %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            fprintf(stderr, "close(spi): %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }

    return ret_code;
}

