#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define ADC_CHANNEL 0
#define VREF        5.0
#define ADC_MAX     1023
#define SAMPLE_US   100000
#define LOG_FILE    "current_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    return voltage * 1000.0f;
}

static int log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf() failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen() failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }
        float current = adc_to_current(adc_value);
        if (current < 0.0f || current > 1000.0f) {
            fprintf(stderr, "Warning: current %.2f A out of range; skipping sample\n", current);
            gpioDelay(SAMPLE_US);
            continue;
        }
        if (log_current(fp, current) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

