#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_debounced_sensor(int gpio) {
    int high_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int level = gpioRead(gpio);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", gpio);
            return -1;
        }
        if (level == 1) high_count++;
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (high_count >= (DEBOUNCE_SAMPLES + 1) / 2) ? 1 : 0;
}

static void log_sensor_state(int s1, int s2) {
    printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);
    fflush(stdout);
}

static void check_alert(int s1, int s2) {
    if (s1 == 0 && s2 == 0) {
        printf("ALERT: Both sensors detect object\n");
        fflush(stdout);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    fflush(stdout);

    while (running) {
        int s1 = read_debounced_sensor(SENSOR_1_GPIO);
        int s2 = read_debounced_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failed, exiting\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        log_sensor_state(s1, s2);
        check_alert(s1, s2);

        sleep(POLL_INTERVAL_S);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

