    return ((rx[1] & 0x03) << 8) | rx[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int main() {
    spi_config_t config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD
    };

    if (spi_setup(config) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            fprintf(stderr, "Error calculating moisture level, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        printf("%s,%.2f\n", "soil_moisture_log.csv", moisture_level);
        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

