/*
 * Raspberry Pi 4 Model B – PIR-triggered security camera
 *
 * Hardware:
 *   - HC-SR501 PIR sensor
 *     VCC  -> 5V  (pin 2 or 4)
 *     GND  -> GND (pin 6)
 *     OUT  -> GPIO17 (BCM 17, pin 11)
 *
 *   - Camera module (CSI connector)
 *     (Pi 4 has a built-in CSI port; no external ribbon required.)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o security_cam security_cam.c \
 *       -lpigpio -lrt -lpthread
 *
 * Run:
 *   sudo ./security_cam
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <syslog.h>
#include <pigpio.h>

#define PIR_PIN            17          /* BCM 17 – HC-SR501 OUT */
#define POLL_INTERVAL_US   50000       /* 50 ms  */
#define DEBOUNCE_DELAY_US  200000      /* 200 ms */
#define CAPTURE_DIR        "/home/pi/security_cam"
#define CAPTURE_WIDTH      1280
#define CAPTURE_HEIGHT     720
#define CAPTURE_QUALITY    85
#define CAPTURE_TIMEOUT    10          /* seconds to wait for child */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %m");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %m");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Path construction                                                   */
/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s') failed: %m", path);
        return -1;
    }
    return 0;
}

static int construct_capture_path(char *buf, size_t buflen, int motion_id)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        syslog(LOG_ERR, "localtime_r failed");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return -1;
    }

    int n = snprintf(buf, buflen, "%s/motion_%d_%s.jpg",
                     CAPTURE_DIR, motion_id, ts);
    if (n < 0 || (size_t)n >= buflen) {
        syslog(LOG_ERR, "Path buffer too small");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Camera capture via fork/exec                                       */
/* ------------------------------------------------------------------ */
static int capture_image(const char *path)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null so libcamera output
         * does not clutter the pigpio log. */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);

        char *argv[] = {
            "libcamera-still",
            "-o", (char *)path,
            "--width", "1280",
            "--height", "720",
            "--quality", "85",
            "--nopreview",
            NULL
        };

        execvp("libcamera-still", argv);
        /* If execvp returns, it failed. */
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %m");
        _exit(127);
    }

    /* Parent: wait for child. */
    int status = 0;
    for (int waited = 0; waited == 0; ) {
        pid_t w = waitpid(pid, &status, 0);
        if (w < 0) {
            if (errno == EINTR)
                continue;
            syslog(LOG_ERR, "waitpid() failed: %m");
            return -1;
        }
        waited = w;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", path);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (status=%d)",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        syslog(LOG_ERR, "Cannot access capture directory '%s'", CAPTURE_DIR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring PIR on GPIO%d in %s", PIR_PIN, CAPTURE_DIR);

    int last_state = 0;
    int motion_id = 0;

    while (g_running) {
        int level = gpioRead(PIR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (level != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int confirmed = gpioRead(PIR_PIN);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_PIN);
                last_state = level;
                continue;
            }

            if (confirmed == level) {
                motion_id++;
                char path[256];
                if (construct_capture_path(path, sizeof(path), motion_id) == 0) {
                    syslog(LOG_INFO, "Motion detected – capturing image %d", motion_id);
                    if (capture_image(path) != 0) {
                        syslog(LOG_ERR, "Image capture failed for motion %d", motion_id);
                    }
                } else {
                    syslog(LOG_ERR, "Failed to construct capture path for motion %d", motion_id);
                }
            }
            last_state = level;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

