#include <linux/videodev2.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define MAX_BUFFERS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt, struct v4l2_requestbuffers *req, struct v4l2_buffer *buf, unsigned char ***buffers, size_t **buffer_sizes, int *num_buffers) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &fmt->capability) < 0) {
        perror("Error querying capabilities");
        goto fail;
    }

    if (!(fmt->capability & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }

    if (!(fmt->capability & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto fail;
    }

    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = 640;
    fmt->fmt.pix.height = 480;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("Error setting format");
        goto fail;
    }

    req->count = MAX_BUFFERS;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        perror("Error requesting buffers");
        goto fail;
    }

    if (req->count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    *buffers = malloc(req->count * sizeof(unsigned char *));
    *buffer_sizes = malloc(req->count * sizeof(size_t));
    if (!*buffers || !*buffer_sizes) {
        perror("Error allocating memory for buffers");
        goto fail;
    }

    for (int i = 0; i < req->count; i++) {
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;
        buf->index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
            perror("Error querying buffer");
            goto fail;
        }

        (*buffer_sizes)[i] = buf->length;
        (*buffers)[i] = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);

        if (*buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            goto fail;
        }
    }

    *num_buffers = req->count;
    return 0;

fail:
    close(*fd);
    *fd = -1;
    free(*buffers);
    free(*buffer_sizes);
    return -1;
}

static int start_streaming(int fd, struct v4l2_buffer *buf) {
    for (int i = 0; i < *num_buffers; i++) {
        buf->index = i;
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf, unsigned char ***buffers, size_t **buffer_sizes, int *num_buffers) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) return 0;
        perror("Error in select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        xioctl(fd, VIDIOC_QBUF, buf);
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);
    fclose(fp);

    xioctl(fd, VIDIOC_QBUF, buf);
    return 0;
}

static void cleanup(int fd, struct v4l2_buffer *buf, unsigned char ***buffers, size_t **buffer_sizes, int *num_buffers) {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < *num_buffers; i++) {
            if (*buffers[i] != MAP_FAILED) {
                munmap(*buffers[i], (*buffer_sizes)[i]);
            }
        }
        free(*buffers);
        free(*buffer_sizes);
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char **buffers = NULL;
    size_t *buffer_sizes = NULL;
    int num_buffers = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (init_camera(&fd, &fmt, &req, &buf, &buffers, &buffer_sizes, &num_buffers) < 0) {
        return 1;
    }

    if (start_streaming(fd, &buf) < 0) {
        cleanup(fd, &buf, &buffers, &buffer_sizes, &num_buffers);
        return 1;
    }

    while (running) {
        if (capture_frame(fd, &buf, &buffers, &buffer_sizes, &num_buffers) < 0) {
            break;
        }
    }

    cleanup(fd, &buf, &buffers, &buffer_sizes, &num_buffers);
    return 0;
}

