    while (running) {
        if (capture_frame(fd, &buf, &buffers, &buffer_sizes, &num_buffers) < 0) {
            break;
        }
    }

    cleanup(fd, &buf, &buffers, &buffer_sizes, &num_buffers);
    return 0;
}

