            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= MAX_BUFFERS) {
            fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        unsigned char *frame = (unsigned char *)buffers[buf.index].start;
        int frame_index = buf.index;
        int total_fragments = NUM_FRAGMENTS;
        int payload_size = FRAME_SIZE;

        for (int frag = 0; frag < total_fragments; frag++) {
            unsigned char *payload = frame + (frag * MAX_PAYLOAD_SIZE);
            int payload_len = (frag < total_fragments - 1) ? MAX_PAYLOAD_SIZE : (FRAME_SIZE - frag * MAX_PAYLOAD_SIZE);

            struct {
                unsigned int frame_index;
                unsigned int fragment_index;
                unsigned int total_fragments;
                unsigned int payload_size;
            } header;
            header.frame_index = frame_index;
            header.fragment_index = frag;
            header.total_fragments = total_fragments;
            header.payload_size = payload_len;

            unsigned char *datagram = malloc(sizeof(header) + payload_len);
            if (!datagram) {
                perror("malloc");
                break;
            }

            memcpy(datagram, &header, sizeof(header));
            memcpy(datagram + sizeof(header), payload, payload_len);

            if (sendto(sockfd, datagram, sizeof(header) + payload_len, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
                perror("sendto");
                free(datagram);
                break;
            }

            free(datagram);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);

    for (int i = 0; i < MAX_BUFFERS; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }

    close(sockfd);
    close(fd);

    return EXIT_SUCCESS;
}

