#define MJPEG_HEIGHT 144

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt,
                       struct v4l2_requestbuffers *req,
                       struct v4l2_buffer *buf, unsigned char ***buffers,
                       size_t *buffer_sizes) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &fmt->capability) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail_close;
    }

    if (!(fmt->capability & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail_close;
    }

    if (!(fmt->capability & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto fail_close;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = MJPEG_WIDTH;
    fmt->fmt.pix.height = MJPEG_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail_close;
    }

    if (xioctl(*fd, VIDIOC_G_FMT, fmt) < 0) {
        perror("VIDIOC_G_FMT");
        goto fail_close;
    }

    if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device did not accept MJPEG format\n");
        goto fail_close;
    }

    memset(req, 0, sizeof(*req));
    req->count = NUM_BUFFERS;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail_close;
    }

    if (req->count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail_close;
    }

    *buffers = calloc(req->count, sizeof(**buffers));
    if (!*buffers) {
        perror("calloc buffers");
        goto fail_close;
    }

    *buffer_sizes = 0;
    for (int i = 0; i < req->count; i++) {
