#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

#define SERVO_MIN_PULSE  1000   /* 1 ms  -> 50 % duty */
#define SERVO_MAX_PULSE  2000   /* 2 ms  -> 100 % duty */
#define SERVO_MID_PULSE  1500   /* 1.5 ms -> 75 % duty */
#define SERVO_MIN_POS    25
#define SERVO_MAX_POS    125
#define SERVO_RANGE      1000
#define SERVO_DUTY_STEP  5
#define POLL_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int position)
{
    if (position < SERVO_MIN_POS) position = SERVO_MIN_POS;
    if (position > SERVO_MAX_POS) position = SERVO_MAX_POS;

    int pulse = SERVO_MIN_PULSE +
                (position - SERVO_MIN_POS) *
                (SERVO_MAX_PULSE - SERVO_MIN_PULSE) /
                (SERVO_MAX_POS - SERVO_MIN_POS);

    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse);
        return -1;
    }
    return 0;
}

static int read_button(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(pin=%d) failed\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Pan servo */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PAN_SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo(PAN_SERVO_PIN, SERVO_MID_PULSE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Tilt servo */
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TILT_SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo(TILT_SERVO_PIN, SERVO_MID_PULSE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Button inputs with internal pull-ups */
    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) < 0 ||
        gpioSetMode(TILT_DOWN_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_LEFT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(button inputs) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_pos  = SERVO_MID_PULSE;
    int tilt_pos = SERVO_MID_PULSE;

    while (g_running) {
        int tilt_up   = read_button(TILT_UP_PIN);
        int tilt_down = read_button(TILT_DOWN_PIN);
        int pan_left  = read_button(PAN_LEFT_PIN);
        int pan_right = read_button(PAN_RIGHT_PIN);

        if (tilt_up >= 0) {
            if (tilt_pos < SERVO_MAX_POS) {
                tilt_pos += SERVO_DUTY_STEP;
                if (set_servo(TILT_SERVO_PIN, tilt_pos) < 0)
                    tilt_pos -= SERVO_DUTY_STEP;
            }
        }
        if (tilt_down >= 0) {
            if (tilt_pos > SERVO_MIN_POS) {
                tilt_pos -= SERVO_DUTY_STEP;
                if (set_servo(TILT_SERVO_PIN, tilt_pos) < 0)
                    tilt_pos += SERVO_DUTY_STEP;
            }
        }
        if (pan_left >= 0) {
            if (pan_pos > SERVO_MIN_POS) {
                pan_pos -= SERVO_DUTY_STEP;
                if (set_servo(PAN_SERVO_PIN, pan_pos) < 0)
                    pan_pos += SERVO_DUTY_STEP;
            }
        }
        if (pan_right >= 0) {
            if (pan_pos < SERVO_MAX_POS) {
                pan_pos += SERVO_DUTY_STEP;
                if (set_servo(PAN_SERVO_PIN, pan_pos) < 0)
                    pan_pos -= SERVO_DUTY_STEP;
            }
        }

        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

