    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Failed to allocate temporary buffer\n");
        return;
    }

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int idx = (i * width + j) * 3;
            temp[idx]     = rgb[idx];
            temp[idx + 1] = rgb[idx + 1];
            temp[idx + 2] = rgb[idx + 2];
        }
    }

    for (int i = 1; i < height - 1; i++) {
        for (int j = 1; j < width - 1; j++) {
            int idx = (i * width + j) * 3;
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int k = -1; k <= 1; k++) {
                for (int l = -1; l <= 1; l++) {
                    int temp_idx = ((i + k) * width + (j + l)) * 3;
                    sum_r += temp[temp_idx];
                    sum_g += temp[temp_idx + 1];
                    sum_b += temp[temp_idx + 2];
                }
            }
            rgb[idx]     = (sum_r + 1) / 9;
            rgb[idx + 1] = (sum_g + 1) / 9;
            rgb[idx + 2] = (sum_b + 1) / 9;
        }
    }

    free(temp);
}

static int save_jpeg(const char *filename, const unsigned char *rgb, int width, int height, int quality) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    unsigned char jpeg_header[8];
    jpeg_header[0] = 0xFF;
    jpeg_header[1] = 0xD8;
    jpeg_header[2] = 0xFF;
    jpeg_header[3] = 0xE0;
    jpeg_header[4] = 0x00;
    jpeg_header[5] = 0x10;
    jpeg_header[6] = 'J';
    jpeg_header[7] = 'F';

    if (fwrite(jpeg_header, 1, 8, fp) != 8) {
        fprintf(stderr, "Failed to write JPEG header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char app0_marker[12];
    app0_marker[0] = 0xFF;
    app0_marker[1] = 0xE1;
    app0_marker[2] = 0x00;
    app0_marker[3] = 0x1A;
    app0_marker[4] = 'J';
    app0_marker[5] = 'F';
    app0_marker[6] = 'I';
    app0_marker[7] = 'F';
    app0_marker[8] = 0x00;
    app0_marker[9] = 0x01;
    app0_marker[10] = 0x01;
    app0_marker[11] = 0x01;

    if (fwrite(app0_marker, 1, 12, fp) != 12) {
        fprintf(stderr, "Failed to write APP0 marker: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char quant_table[64];
    for (int i = 0; i < 64; i++) {
        quant_table[i] = 1 << (7 - (i % 8));
    }

    unsigned char quant_marker[13];
    quant_marker[0] = 0xFF;
    quant_marker[1] = 0xDB;
    quant_marker[2] = 0x00;
    quant_marker[3] = 0x43;
    for (int i = 0; i < 64; i++) {
        quant_marker[4 + i] = quant_table[i];
    }

    if (fwrite(quant_marker, 1, 13, fp) != 13) {
        fprintf(stderr, "Failed to write quantization table: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char huffman_dc[65];
    unsigned char huffman_ac[65];
    for (int i = 0; i < 65; i++) {
        huffman_dc[i] = 0;
        huffman_ac[i] = 0;
    }

    unsigned char dc_luminance = 0;
    unsigned char dc_chrominance = 0;

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int idx = (i * width + j) * 3;
            int dc = rgb[idx] - dc_luminance;
            if (dc < 0) dc = -dc;
            if (dc > 12) dc = 12;
            huffman_dc[dc]++;
            dc_luminance = rgb[idx];

            int ac[64];
            int ac_idx = 0;
            for (int k = 0; k < 64; k++) {
                ac[k] = 0;
            }

            for (int k = 1; k < 64; k++) {
                int idx2 = (i * width + j) * 3 + k * 3;
                int ac_val = rgb[idx2] - rgb[idx2 - 3];
                if (ac_val != 0) {
                    ac[ac_idx++] = ac_val;
                }
            }

            for (int k = 0; k < ac_idx; k++) {
                int ac_val = ac[k];
                if (ac_val < 0) ac_val = -ac_val;
                if (ac_val > 12) ac_val = 12;
                huffman_ac[ac_val]++;
            }
        }
    }

    unsigned char huffman_table[257];
    for (int i = 0; i < 257; i++) {
        huffman_table[i] = 0;
    }

    unsigned char huffman_dc_table[12];
    unsigned char huffman_ac_table[12];
    for (int i = 0; i < 12; i++) {
        huffman_dc_table[i] = 0;
        huffman_ac_table[i] = 0;
    }

    int dc_code_length = 0;
    int ac_code_length = 0;
    int dc_code_index = 0;
    int ac_code_index = 0;

    for (int i = 0; i < 65; i++) {
        if (huffman_dc[i] > 0) {
            huffman_dc_table[dc_code_length] = i;
            dc_code_length++;
            dc_code_index++;
        }
    }

    for (int i = 0; i < 65; i++) {
        if (huffman_ac[i] > 0) {
            huffman_ac_table[ac_code_length] = i;
            ac_code_length++;
            ac_code_index++;
        }
    }

    unsigned char dc_huffman_table[18];
    unsigned char ac_huffman_table[18];
    for (int i = 0; i < 18; i++) {
        dc_huffman_table[i] = 0;
        ac_huffman_table[i] = 0;
    }

    for (int i = 0; i < dc_code_index; i++) {
        dc_huffman_table[i] = huffman_dc_table[i];
    }

    for (int i = 0; i < ac_code_index; i++) {
        ac_huffman_table[i] = huffman_ac_table[i];
    }

    unsigned char dc_huffman_marker[13];
    dc_huffman_marker[0] = 0xFF;
    dc_huffman_marker[1] = 0xC4;
    dc_huffman_marker[2] = 0x00;
    dc_huffman_marker[3] = 0x08;
    for (int i = 0; i < dc_code_index; i++) {
        dc_huffman_marker[4 + i] = dc_huffman_table[i];
    }

    unsigned char ac_huffman_marker[13];
    ac_huffman_marker[0] = 0xFF;
    ac_huffman_marker[1] = 0xC4;
    ac_huffman_marker[2] = 0x00;
    ac_huffman_marker[3] = 0x08;
    for (int i = 0; i < ac_code_index; i++) {
        ac_huffman_marker[4 + i] = ac_huffman_table[i];
    }

    if (fwrite(dc_huffman_marker, 1, 13, fp) != 13) {
        fprintf(stderr, "Failed to write DC Huffman table: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fwrite(ac_huffman_marker, 1, 13, fp) != 13) {
        fprintf(stderr, "Failed to write AC Huffman table: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char quant_huffman_marker[13];
    quant_huffman_marker[0] = 0xFF;
    quant_huffman_marker[1] = 0xDB;
    quant_huffman_marker[2] = 0x00;
    quant_huffman_marker[3] = 0x43;
    for (int i = 0; i < 64; i++) {
        quant_huffman_marker[4 + i] = quant_table[i];
    }

    if (fwrite(quant_huffman_marker, 1, 13, fp) != 13) {
        fprintf(stderr, "Failed to write quantization table: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char start_of_frame[14];
    start_of_frame[0] = 0xFF;
    start_of_frame[1] = 0xC2;
    start_of_frame[2] = 0x00;
    start_of_frame[3] = 0x11;
    start_of_frame[4] = 0x08;
    start_of_frame[5] = 0x22;
    start_of_frame[6] = 0x01;
    start_of_frame[7] = 0x21;
    start_of_frame[8] = 0x00;
    start_of_frame[9] = 0x03;
    start_of_frame[10] = 0x01;
    start_of_frame[11] = 0x01;
    start_of_frame[12] = 0x01;
    start_of_frame[13] = 0x01;

    if (fwrite(start_of_frame, 1, 14, fp) != 14) {
        fprintf(stderr, "Failed to write start of frame: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    unsigned char end_of_frame[2];
    end_of_frame[0] = 0xFF;
    end_of_frame[1] = 0xD9;

    if (fwrite(end_of_frame, 1, 2, fp) != 2) {
        fprintf(stderr, "Failed to write end of frame: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    void *buffer = NULL;
    size_t buffer_size = 0;
    unsigned char *rgb = NULL;
    char filename[256];
    time_t rawtime;
    struct tm *timeinfo;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        close(fd);
        return 1;
    }

    rgb = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!rgb) {
        fprintf(stderr, "Failed to allocate RGB buffer\n");
        close(fd);
        return 1;
    }

    int ret = 0;
    if (capture_frame(fd, &buffer, &buffer_size) == 0) {
        convert_yuyv_to_rgb24((unsigned char *)buffer, rgb, IMAGE_WIDTH, IMAGE_HEIGHT);
        apply_blur_filter(rgb, IMAGE_WIDTH, IMAGE_HEIGHT);
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), CAPTURE_FILE, timeinfo);
        if (save_jpeg(filename, rgb, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_QUALITY) == 0) {
            printf("Image saved as %s\n", filename);
        } else {
            ret = 1;
        }
    } else {
        fprintf(stderr, "Failed to capture frame\n");
        ret = 1;
    }

    if (buffer) {
        munmap(buffer, buffer_size);
    }
    if (rgb) {
        free(rgb);
    }
    if (fd >= 0) {
        close(fd);
    }

    return ret;
}

