#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_resolution(const char *name, unsigned int width, unsigned int height)
{
    printf("  %s: %ux%u\n", name, width, height);
}

static void print_frame_interval(const char *name, unsigned int numerator, unsigned int denominator)
{
    printf("    %s: %u/%u (%.2f fps)\n", name, numerator, denominator,
           (float)numerator / (float)denominator);
}

static void print_autofocus_support(int supported, int auto_focus)
{
    if (supported) {
        printf("  Autofocus: %s\n", auto_focus ? "supported" : "not supported");
    } else {
        printf("  Autofocus: not supported (control not found)\n");
    }
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_FRAME_RATE)) {
        fprintf(stderr, "Device %s does not support frame rate enumeration\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    struct v4l2_fmtdesc fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    printf("\nSupported formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        printf("  %s\n", fmt.description);
        fmt.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating formats: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum fs;
    memset(&fs, 0, sizeof(fs));
    fs.pixel_format = V4L2_PIX_FMT_YUYV;

    printf("\nSupported frame sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs) == 0) {
        if (fs.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            print_resolution("Discrete", fs.discrete.width, fs.discrete.height);
        } else if (fs.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  Stepwise: min %ux%u, max %ux%u\n",
                   fs.stepwise.min_width, fs.stepwise.min_height,
                   fs.stepwise.max_width, fs.stepwise.max_height);
        } else if (fs.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  Continuous: min %ux%u, max %ux%u\n",
                   fs.stepwise.min_width, fs.stepwise.min_height,
                   fs.stepwise.max_width, fs.stepwise.max_height);
        }
        fs.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmivalenum iv;
    memset(&iv, 0, sizeof(iv));
    iv.pixel_format = V4L2_PIX_FMT_YUYV;
    iv.width = 640;
    iv.height = 480;

    printf("\nSupported frame intervals for %ux%u:\n", iv.width, iv.height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &iv) == 0) {
        print_frame_interval("Discrete", iv.discrete.numerator, iv.discrete.denominator);
        iv.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) < 0) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    print_autofocus_support(qc.flags & V4L2_CTRL_FLAG_DISABLED, qc.default_value);

    close(fd);
    return EXIT_SUCCESS;
}

