#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH  1000
#define MAX_PULSE_WIDTH  2000
#define CENTER_PULSE_WIDTH 1500
#define STEP_PULSE_WIDTH  10
#define LOOP_DELAY_US     50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp_pulse_width(int pw)
{
    if (pw < MIN_PULSE_WIDTH) return MIN_PULSE_WIDTH;
    if (pw > MAX_PULSE_WIDTH) return MAX_PULSE_WIDTH;
    return pw;
}

static void adjust_servo(int pin, int *current_pw, int step)
{
    *current_pw += step;
    *current_pw = clamp_pulse_width(*current_pw);
    if (gpioServo(pin, *current_pw) < 0) {
        fprintf(stderr, "Warning: gpioServo(pin=%d, pw=%d) failed\n", pin, *current_pw);
    }
}

int main(void)
{
    int pan_pw = CENTER_PULSE_WIDTH;
    int tilt_pw = CENTER_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
