#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_PIN 17
#define DEBOUNCE_TIME 2
#define POLL_INTERVAL 0.1
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LENGTH 256
#define MAX_PAYLOAD_LENGTH 512
#define MAX_URL_LENGTH 512

static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t motion_detected = 0;
static volatile sig_atomic_t motion_last_seen = 0;
static char server_ip[64] = {0};
static int server_port = 80;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int create_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        fprintf(stderr, "Error: '%s' exists but is not a directory.\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -o %s -q %d -t 100 -w 640 -h 480 -e jpg",
             filename, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspistill exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static int get_timestamp(char *timestamp, size_t len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }
    snprintf(timestamp + strlen(timestamp), len - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    char payload[MAX_PAYLOAD_LENGTH];
    int payload_len = snprintf(payload, sizeof(payload),
                               "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
                               filename, timestamp, motion_status, gpio_pin);
    if (payload_len < 0 || (size_t)payload_len >= sizeof(payload)) {
        fprintf(stderr, "Error: payload formatting failed\n");
        return -1;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    char url[MAX_URL_LENGTH];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)payload_len);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "Error: HTTP request returned status code %ld\n", http_code);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    strncpy(server_ip, argv[1], sizeof(server_ip) - 1);
    server_ip[sizeof(server_ip) - 1] = '\0';

    char port_str[8];
    snprintf(port_str, sizeof(port_str), "%s", argv[2]);
    server_port = atoi(port_str);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (create_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_PIN);

    while (program_running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error: gpioRead failed for pin %d\n", PIR_PIN);
            break;
        }

        if (pir_value == 1) {
            if (!motion_detected) {
                motion_detected = 1;
                motion_last_seen = 1;
                printf("Motion detected on GPIO%d\n", PIR_PIN);
            }
        } else {
            if (motion_detected) {
                motion_detected = 0;
            }
        }

        if (motion_detected) {
            if (motion_last_seen) {
                char filename[MAX_FILENAME_LENGTH];
                snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", CAPTURE_DIR, (long)time(NULL));

                if (capture_image(filename) == 0) {
                    char timestamp[64];
                    if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                        if (send_data(filename, timestamp, 1, PIR_PIN) == 0) {
                            printf("Data sent to server: %s\n", filename);
                        } else {
                            fprintf(stderr, "Error: Failed to send data to server\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to get timestamp\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to capture image\n");
                }
                motion_last_seen = 0;
            }
        }

        time_sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

