#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 50
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_TIMEOUT_MS 2000
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define TIMESTAMP_LEN 32
#define CMD_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[TIMESTAMP_LEN];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    }
    fclose(fp);
}

static int capture_image(const char *filename) {
    char cmd[CMD_LEN];
    snprintf(cmd, sizeof(cmd),
             "raspistill -o %s -w %d -h %d -q %d -t %d -nopreview",
             filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY,
             CAPTURE_TIMEOUT_MS);
    int rc = system(cmd);
    if (rc == -1) {
        log_event("system() failed");
        return -1;
    }
    if (!WIFEXITED(rc) || WEXITSTATUS(rc) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "raspistill failed (rc=%d)", rc);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int wait_for_falling_edge(int fd, int timeout_ms) {
    struct timespec ts = {0, timeout_ms * 1000000L};
    struct gpiod_line_event ev;
    while (running) {
        int rc = gpiod_line_event_wait(fd, &ts);
        if (rc < 0) {
            if (errno == EINTR) continue;
            log_event("gpiod_line_event_wait error");
            return -1;
        }
        if (rc == 0) return 0; /* timeout */
        if (gpiod_line_event_read(fd, &ev) < 0) {
            if (errno == EINTR) continue;
            log_event("gpiod_line_event_read error");
            return -1;
        }
        if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) return 1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(pir, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (running) {
        int rc = wait_for_falling_edge(gpiod_line_fd(pir), DEBOUNCE_MS);
        if (rc < 0) {
            /* Error already logged */
            break;
        }
        if (rc == 0) {
            /* Timeout — loop and re-check running */
            continue;
        }

        time_t t = time(NULL);
        struct tm tm;
        if (!localtime_r(&t, &tm)) {
            log_event("localtime_r failed");
            continue;
        }
        char ts[TIMESTAMP_LEN];
        strftime(ts, sizeof(ts), "%Y%m%d_%H%M%S", &tm);

        char filename[128];
        snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg", IMAGE_DIR, ts);

        if (capture_image(filename) == 0) {
            printf("Image captured: %s\n", filename);
        } else {
            log_event("Image capture failed");
        }
    }

    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return 0;
}

