#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH  200
#define HEIGHT 150
#define FILENAME "cropped.yuv"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int setup_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    int ret = -1;

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: driver did not accept %dx%d, got %dx%d\n",
                WIDTH, HEIGHT, fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    ret = 0;
cleanup:
    if (ret == 0) {
        printf("Camera configured and streaming started\n");
    } else {
        if (buffer != NULL) {
            munmap(buffer, buf.length);
        }
    }
    return ret;
}

static int capture_frame(int fd, unsigned char *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index != 0) {
        fprintf(stderr, "warning: unexpected buffer index %u\n", buf.index);
    }

    if (buf.bytesused < buffer_size) {
        fprintf(stderr, "warning: frame too small (%u bytes, expected %zu)\n",
                buf.bytesused, buffer_size);
    }

    memcpy(buffer, buffer, buf.bytesused);
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int crop_and_write(const unsigned char *buffer, size_t buffer_size,
                          const unsigned char *crop, size_t crop_size,
                          const char *filename) {
    size_t crop_bytes = (size_t)WIDTH * HEIGHT * 2;
    if (crop_bytes != crop_size) {
        fprintf(stderr, "crop buffer size mismatch: %zu != %zu\n", crop_bytes, crop_size);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t written = fwrite(crop, 1, crop_bytes, fp);
    if (written != crop_bytes) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    printf("Wrote %zu bytes to %s\n", crop_bytes, filename);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *buffer = NULL;
    unsigned char *crop = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (setup_camera(fd) < 0) {
        goto cleanup;
    }

    buffer = malloc(WIDTH * HEIGHT * 2);
    if (!buffer) {
        perror("malloc");
        goto cleanup;
    }

    crop = malloc(WIDTH * HEIGHT * 2);
    if (!crop) {
        perror("malloc");
        goto cleanup;
    }

    while (!g_stop) {
        if (capture_frame(fd, buffer, WIDTH * HEIGHT * 2) < 0) {
            if (g_stop) {
                break;
            }
            continue;
        }

        /* YUYV: Y0 U Y1 V */
        for (int i = 0; i < HEIGHT; i++) {
            for (int j = 0; j < WIDTH; j++) {
                int idx = (i * WIDTH + j) * 2;
                crop[idx] = buffer[idx];          /* Y0 */
                crop[idx + 1] = buffer[idx + 1];  /* U */
            }
        }

        if (crop_and_write(buffer, WIDTH * HEIGHT * 2, crop, WIDTH * HEIGHT * 2,
                           FILENAME) < 0) {
            goto cleanup;
        }
        break;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buffer) free(buffer);
    if (crop) free(crop);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        if (munmap(buffer, WIDTH * HEIGHT * 2) < 0) {
            perror("munmap");
        }
        close(fd);
    }
    return ret;
}

