    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index != 0) {
        fprintf(stderr, "warning: unexpected buffer index %u\n", buf.index);
    }

    if (buf.bytesused < buffer_size) {
        fprintf(stderr, "warning: frame too small (%u bytes, expected %zu)\n",
                buf.bytesused, buffer_size);
    }

    memcpy(buffer, buffer, buf.bytesused);
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int crop_and_write(const unsigned char *buffer, size_t buffer_size,
                          const unsigned char *crop, size_t crop_size,
                          const char *filename) {
    size_t crop_bytes = (size_t)WIDTH * HEIGHT * 2;
    if (crop_bytes != crop_size) {
        fprintf(stderr, "crop buffer size mismatch: %zu != %zu\n", crop_bytes, crop_size);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t written = fwrite(crop, 1, crop_bytes, fp);
    if (written != crop_bytes) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    printf("Wrote %zu bytes to %s\n", crop_bytes, filename);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *buffer = NULL;
    unsigned char *crop = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (setup_camera(fd) < 0) {
        goto cleanup;
    }

    buffer = malloc(WIDTH * HEIGHT * 2);
    if (!buffer) {
        perror("malloc");
        goto cleanup;
    }

    crop = malloc(WIDTH * HEIGHT * 2);
    if (!crop) {
        perror("malloc");
        goto cleanup;
    }

    while (!g_stop) {
        if (capture_frame(fd, buffer, WIDTH * HEIGHT * 2) < 0) {
            if (g_stop) {
                break;
            }
            continue;
        }

        /* YUYV: Y0 U Y1 V */
        for (int i = 0; i < HEIGHT; i++) {
            for (int j = 0; j < WIDTH; j++) {
                int idx = (i * WIDTH + j) * 2;
                crop[idx] = buffer[idx];          /* Y0 */
                crop[idx + 1] = buffer[idx + 1];  /* U */
            }
        }

        if (crop_and_write(buffer, WIDTH * HEIGHT * 2, crop, WIDTH * HEIGHT * 2,
                           FILENAME) < 0) {
            goto cleanup;
        }
        break;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buffer) free(buffer);
    if (crop) free(crop);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        if (munmap(buffer, WIDTH * HEIGHT * 2) < 0) {
            perror("munmap");
        }
        close(fd);
    }
    return ret;
}

