#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define SERVO_FREQUENCY 50
#define SERVO_RANGE 180
#define NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Error: Angle %d out of range (0-%d).\n", angle, SERVO_RANGE);
        return -1;
    }
    int pulse_width = (angle * 1000) / SERVO_RANGE;
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, SERVO_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, SERVO_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, SERVO_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, SERVO_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) < 0) {
        fprintf(stderr, "Error: Failed to initialize servos to neutral position.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        cleanup();
        return 1;
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Servo control started. Press arrow keys to move, 'q' to quit.\n");
    printf("Pan: GPIO%d | Tilt: GPIO%d | Neutral: %d degrees\n", PAN_SERVO_PIN, TILT_SERVO_PIN, NEUTRAL_ANGLE);
    printf("Arrow keys: UP/DOWN = tilt, LEFT/RIGHT = pan\n");

    while (running) {
        int c = getchar();
        if (c == 'q' || c == 'Q') {
            break;
        } else if (c == '\n' || c == '\r') {
            continue;
        }

        switch (c) {
            case 'w':
            case 'W':
                tilt_angle += STEP_SIZE;
                if (tilt_angle > SERVO_RANGE) tilt_angle = SERVO_RANGE;
                break;
            case 's':
            case 'S':
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < 0) tilt_angle = 0;
                break;
            case 'a':
            case 'A':
                pan_angle -= STEP_SIZE;
                if (pan_angle < 0) pan_angle = 0;
                break;
            case 'd':
            case 'D':
                pan_angle += STEP_SIZE;
                if (pan_angle > SERVO_RANGE) pan_angle = SERVO_RANGE;
                break;
            default:
                continue;
        }

        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0 ||
            set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
            fprintf(stderr, "Error: Failed to set servo angle.\n");
        } else {
            printf("Pan: %d, Tilt: %d\n", pan_angle, tilt_angle);
        }

        usleep(DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

