#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define E_PULSE_US 500
#define E_DELAY_US 500

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static double total_volume = 0.0;
static double flow_rate = 0.0;
static double last_volume = 0.0;
static time_t last_log_time = 0;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        pulse_count++;
    }
}

static void lcd_pulse_enable(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) return;
    gpioDelay(E_PULSE_US);
    if (write(fd, &data & ~ENABLE, 1) != 1) return;
    gpioDelay(E_DELAY_US);
}

static void lcd_send_byte(int fd, uint8_t bits, int mode) {
    uint8_t high = (mode << 7) | (bits & 0xF0);
    uint8_t low = (mode << 7) | ((bits << 4) & 0xF0);
    lcd_pulse_enable(fd, high);
    lcd_pulse_enable(fd, low);
}

static void lcd_byte(int fd, uint8_t bits, int mode) {
    lcd_send_byte(fd, bits, mode);
    gpioDelay(2000);
}

static void lcd_string(int fd, const char *s) {
    while (*s) {
        lcd_byte(fd, (uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(int fd) {
    lcd_byte(fd, 0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(int fd) {
    gpioDelay(50000);
    lcd_byte(fd, 0x33, LCD_CMD);
    lcd_byte(fd, 0x32, LCD_CMD);
    lcd_byte(fd, 0x28, LCD_CMD);
    lcd_byte(fd, 0x0C, LCD_CMD);
    lcd_byte(fd, 0x06, LCD_CMD);
    lcd_byte(fd, 0x01, LCD_CMD);
    gpioDelay(2000);
}

static void log_data(double flow, double vol) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Flow: %.2f L/min, Volume: %.2f L\n", ts, flow, vol);
    fflush(stdout);
}

static void update_lcd(int fd, double flow, double vol) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", vol);
    lcd_clear(fd);
    lcd_byte(fd, LCD_LINE_1 | LCD_BACKLIGHT, LCD_CMD);
    lcd_string(fd, line1);
    lcd_byte(fd, LCD_LINE_2 | LCD_BACKLIGHT, LCD_CMD);
    lcd_string(fd, line2);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_fd);

    printf("Flow sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        if (difftime(now, last_log_time) >= 1.0) {
            double dt = difftime(now, last_log_time);
            if (dt > 0.0) {
                flow_rate = (double)pulse_count / dt / 60.0;
                total_volume += flow_rate * dt;
            }
            last_volume = total_volume;
            log_data(flow_rate, total_volume);
            last_log_time = now;
        }

        if (difftime(now, last_log_time) >= 10.0) {
            update_lcd(i2c_fd, flow_rate, total_volume);
            last_log_time = now;
        }

        pulse_count = 0;
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    lcd_clear(i2c_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

