            update_lcd(i2c_fd, flow_rate, total_volume);
            last_log_time = now;
        }

        pulse_count = 0;
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    lcd_clear(i2c_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

