#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define SPI_DEVICE      "/dev/spidev0.0"
#define I2C_DEVICE      "/dev/i2c-1"
#define LCD_ADDR        0x27
#define SAMPLE_MS       500
#define SAMPLE_COUNT    (SAMPLE_MS / 10)  /* 50 ms per count */

/* PCF8574 LCD backpack: bit assignments */
#define LCD_EN  0x04
#define LCD_RW  0x02
#define LCD_RS  0x01
#define LCD_BL  0x08

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t val)
{
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    return i2c_write_byte(fd, cmd);
}

static int i2c_write_data(int fd, uint8_t data)
{
    return i2c_write_byte(fd, data);
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = 1000000,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LCD (PCF8574)                                                        */
/* ------------------------------------------------------------------ */

static int lcd_init(int fd)
{
    if (i2c_write_byte(fd, 0x30) < 0) return -1;  /* force 4-bit mode */
    usleep(5000);
    if (i2c_write_byte(fd, 0x30) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x30) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x20) < 0) return -1;  /* 4-bit mode */
    usleep(1000);

    if (i2c_write_cmd(fd, 0x28) < 0) return -1;  /* 2 lines, 5x8 font */
    if (i2c_write_cmd(fd, 0x08) < 0) return -1;  /* display off */
    if (i2c_write_cmd(fd, 0x01) < 0) return -1;  /* clear */
    usleep(2000);
    if (i2c_write_cmd(fd, 0x06) < 0) return -1;  /* entry mode */
    if (i2c_write_cmd(fd, 0x0C) < 0) return -1;  /* display on, cursor off */
    return 0;
}

static int lcd_clear(int fd)
{
    return i2c_write_cmd(fd, 0x01);
}

static int lcd_set_cursor(int fd, uint8_t col, uint8_t row)
{
    uint8_t addr = (row == 0) ? 0x00 : 0x40;
    return i2c_write_cmd(fd, 0x80 | (col + addr));
