/* ------------------------------------------------------------------ */
/* Wind vane (MCP3008, single-ended channel 0)                         */
/* ------------------------------------------------------------------ */

static int read_mcp3008(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(spi_fd, tx, rx, 3) < 0)
        return -1;

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Wind direction                                                      */
/* ------------------------------------------------------------------ */

static const char *direction_str(int dir)
{
    switch (dir) {
        case 0: return "N";
        case 1: return "NNE";
        case 2: return "NE";
        case 3: return "ENE";
        case 4: return "E";
        case 5: return "ESE";
        case 6: return "SE";
        case 7: return "SSE";
        case 8: return "S";
        case 9: return "SSW";
        case 10: return "SW";
        case 11: return "WSW";
        case 12: return "W";
        case 13: return "WNW";
        case 14: return "NW";
        case 15: return "NNW";
        default: return "??";
    }
}

/* ------------------------------------------------------------------ */
/* Wind speed (anemometer)                                             */
/* ------------------------------------------------------------------ */

static float calculate_wind_speed(int pulse_count)
{
    static int last_count = 0;
    static struct timespec last_time = { 0, 0 };

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    float speed = 0.0f;
    if (last_time.tv_sec != 0 || last_time.tv_nsec != 0) {
        double dt = (now.tv_sec - last_time.tv_sec) +
                    (now.tv_nsec - last_time.tv_nsec) / 1e9;
        if (dt > 0.0) {
            speed = (float)((double)pulse_count - (double)last_count) / dt;
        }
    }
    last_count = pulse_count;
    last_time = now;
    return speed;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LCD_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize LCD */
    if (lcd_init(i2c_fd) < 0) {
        fprintf(stderr, "LCD initialization failed (sensor absent?)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure SPI mode 0 */
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI mode set failed: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI bits per word set failed: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI speed set failed: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input with pull-up (anemometer) */
    /* Note: pigpio is used for the GPIO; we use the kernel GPIO subsystem
       via /sys/class/gpio for the anemometer pin. */
    FILE *gpio_export = fopen("/sys/class/gpio/export", "w");
    if (gpio_export) {
        fprintf(gpio_export, "%d", ANEMOMETER_GPIO);
        fclose(gpio_export);
    } else {
        fprintf(stderr, "Warning: GPIO export failed: %s\n", strerror(errno));
    }

    FILE *gpio_direction = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (gpio_direction) {
        fprintf(gpio_direction, "input");
        fclose(gpio_direction);
    } else {
        fprintf(stderr, "Warning: GPIO direction failed: %s\n", strerror(errno));
    }

    FILE *gpio_pullup = fopen("/sys/class/gpio/gpio17/pullup_enable", "w");
    if (gpio_pullup) {
        fprintf(gpio_pullup, "1");
        fclose(gpio_pullup);
    } else {
        fprintf(stderr, "Warning: GPIO pullup failed: %s\n", strerror(errno));
    }

    /* Main loop */
    int pulse_count = 0;
    int adc_value = 0;
    int adc_stuck = 0;

    while (g_running) {
        /* Read anemometer pulse count */
        FILE *gpio_value = fopen("/sys/class/gpio/gpio17/value", "r");
        if (gpio_value) {
            if (fscanf(gpio_value, "%d", &pulse_count) == 1) {
                fclose(gpio_value);
            } else {
                fprintf(stderr, "Anemometer read error\n");
                pulse_count = 0;
            }
        } else {
            fprintf(stderr, "Cannot open anemometer value: %s\n", strerror(errno));
            pulse_count = 0;
        }

        /* Read MCP3008 channel 0 */
        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "MCP3008 read error\n");
            adc_value = 0;
        }

        /* Detect stuck ADC (sensor absent or wiring fault) */
        if (adc_value == 0 || adc_value == 1023) {
            if (!adc_stuck) {
                fprintf(stderr, "ADC stuck at %d - sensor absent or wiring fault\n",
                        adc_value);
                adc_stuck = 1;
            }
        } else {
            adc_stuck = 0;
        }

        /* Wind direction */
        int direction = (adc_value * 15) / 1023;  /* 0..15 */

        /* Wind speed */
        float speed = calculate_wind_speed(pulse_count);

        /* LCD */
        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Speed: %.1f m/s", speed);
        snprintf(line2, sizeof(line2), "Dir: %s", direction_str(direction));

        if (lcd_clear(i2c_fd) < 0) {
            fprintf(stderr, "LCD clear failed\n");
        }
        if (lcd_set_cursor(i2c_fd, 0, 0) < 0) {
            fprintf(stderr, "LCD set cursor 0 failed\n");
        }
        if (lcd_print(i2c_fd, line1) < 0) {
            fprintf(stderr, "LCD print line1 failed\n");
        }
        if (lcd_set_cursor(i2c_fd, 0, 1) < 0) {
            fprintf(stderr, "LCD set cursor 1 failed\n");
        }
        if (lcd_print(i2c_fd, line2) < 0) {
            fprintf(stderr, "LCD print line2 failed\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    /* Cleanup */
    lcd_clear(i2c_fd);
    close(spi_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

