    /* Main loop */
    int pulse_count = 0;
    int adc_value = 0;
    int adc_stuck = 0;

    while (g_running) {
        /* Read anemometer pulse count */
        FILE *gpio_value = fopen("/sys/class/gpio/gpio17/value", "r");
        if (gpio_value) {
            if (fscanf(gpio_value, "%d", &pulse_count) == 1) {
                fclose(gpio_value);
            } else {
                fprintf(stderr, "Anemometer read error\n");
                pulse_count = 0;
            }
        } else {
            fprintf(stderr, "Cannot open anemometer value: %s\n", strerror(errno));
            pulse_count = 0;
        }

        /* Read MCP3008 channel 0 */
        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "MCP3008 read error\n");
            adc_value = 0;
        }

        /* Detect stuck ADC (sensor absent or wiring fault) */
        if (adc_value == 0 || adc_value == 1023) {
            if (!adc_stuck) {
                fprintf(stderr, "ADC stuck at %d - sensor absent or wiring fault\n",
                        adc_value);
                adc_stuck = 1;
            }
        } else {
            adc_stuck = 0;
        }

        /* Wind direction */
        int direction = (adc_value * 15) / 1023;  /* 0..15 */

        /* Wind speed */
        float speed = calculate_wind_speed(pulse_count);

        /* LCD */
        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Speed: %.1f m/s", speed);
        snprintf(line2, sizeof(line2), "Dir: %s", direction_str(direction));

        if (lcd_clear(i2c_fd) < 0) {
            fprintf(stderr, "LCD clear failed\n");
        }
        if (lcd_set_cursor(i2c_fd, 0, 0) < 0) {
            fprintf(stderr, "LCD set cursor 0 failed\n");
        }
        if (lcd_print(i2c_fd, line1) < 0) {
            fprintf(stderr, "LCD print line1 failed\n");
        }
        if (lcd_set_cursor(i2c_fd, 0, 1) < 0) {
            fprintf(stderr, "LCD set cursor 1 failed\n");
        }
        if (lcd_print(i2c_fd, line2) < 0) {
            fprintf(stderr, "LCD print line2 failed\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    /* Cleanup */
    lcd_clear(i2c_fd);
    close(spi_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

