/*
 * Water Flow Monitor — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - YF-S201 water flow sensor  (pulse output) -> GPIO17 (BCM, physical pin 11)
 *   - LCD1602 (I2C)                          -> /dev/i2c-1, address 0x27
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLOW_SENSOR_GPIO      17          /* BCM pin connected to YF-S201 pulse out */
#define I2C_BUS               1           /* /dev/i2c-1 on Raspberry Pi 3 B+ */
#define LCD_I2C_ADDR          0x27        /* LCD1602 I2C address (4-bit mode) */
#define LCD_WIDTH             16          /* LCD1602 is 16 columns wide */

#define SAMPLE_INTERVAL_US    1000000     /* 1 second between flow-rate samples */
#define PULSE_TIMEOUT_S       10          /* No-pulse timeout → sensor-absent */
#define PULSE_THRESHOLD       1           /* Minimum pulses per second to count */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
