            gpioTerminate();
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to write row pin %d LOW\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set column pin %d as output\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
