#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_ALS_RATE     0x09
#define SI1145_REG_PS_RATE      0x0A
#define SI1145_REG_PS_LED21     0x0F
#define SI1145_REG_PS_LED3      0x10
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0    0x26
#define SI1145_REG_PS1_DATA1    0x27
#define SI1145_REG_COMMAND      0x30
#define SI1145_REG_RESPONSE     0x20

/* Command register values */
#define SI1145_CMD_RESET        0x01
#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_PS_FORCE     0x05
#define SI1145_CMD_PSALS_FORCE  0x07
#define SI1145_CMD_PSALS_AUTO   0x0F

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED 0x45

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level register helpers                                          */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

static int si1145_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read_word(uint8_t reg_low, uint16_t *value)
{
    uint8_t lo, hi;
    if (si1145_read_reg(reg_low, &lo) < 0) return -1;
    if (si1145_read_reg(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1145 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1145_init(void)
{
    uint8_t part_id;

    /* 1. Reset the device */
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* 2. Verify PART_ID */
    if (si1145_read_reg(SI1145_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }

    /* 3. Write HW_KEY (required for proper operation) */
    if (si1145_write_reg(SI1145_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* 4. Configure measurement rates (100 ms cadence) */
    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1145_write_reg(SI1145_REG_ALS_RATE, 0x00) < 0)
        return -1;
    if (si1145_write_reg(SI1145_REG_PS_RATE, 0x00) < 0)
        return -1;

    /* 5. Configure LED current for proximity (LED1 = 20 mA) */
    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x0F) < 0)
        return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED3, 0x00) < 0)
        return -1;

    /* 6. Start autonomous ALS + PS measurement */
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity and ambient light                                    */
/* ------------------------------------------------------------------ */
static int si1145_read_data(uint16_t *proximity, uint16_t *ambient)
{
    uint8_t response;

    /* Trigger a forced measurement */
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0)
        return -1;

    /* Poll the RESPONSE register for completion (bit 0 = data ready) */
    for (int i = 0; i < 10; i++) {
        if (si1145_read_reg(SI1145_REG_RESPONSE, &response) < 0)
            return -1;
        if (response & 0x01)
            break;
        gpioDelay(1000);  /* 1 ms */
    }
    if (!(response & 0x01)) {
        fprintf(stderr, "Error: Si1145 measurement timeout\n");
        return -1;
    }

    /* Read 16-bit proximity and ambient light values */
    if (si1145_read_word(SI1145_REG_PS1_DATA0, proximity) < 0)
        return -1;
    if (si1145_read_word(SI1145_REG_ALS_VIS_DATA0, ambient) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Proximity: %u, Ambient: %u\n",
            timestamp, proximity, ambient);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed\n",
                I2C_BUS, SI1145_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init() < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t proximity = 0, ambient = 0;

        if (si1145_read_data(&proximity, &ambient) == 0) {
            log_data(proximity, ambient);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

