static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        perror("fprintf log file");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

static int get_iso8601_utc(char *buf, size_t len) {
