#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_RESPONSE 0x20
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_PS_FORCE 0x07
#define SI1145_CMD_PSALS_AUTO 0x08
#define SI1145_PART_ID 0x45
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "biometric_data.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int si1145_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int si1145_read(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_wait_response(uint8_t expected) {
    uint8_t resp;
    for (int i = 0; i < 10; i++) {
        if (si1145_read(SI1145_REG_RESPONSE, &resp) < 0) return -1;
        if ((resp & 0x0F) == expected) return 0;
        gpioDelay(2000);
    }
    fprintf(stderr, "Timeout waiting for response 0x%02X\n", expected);
    return -1;
}

static int si1145_init(void) {
    uint8_t part_id;
    if (si1145_read(SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (si1145_write(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    if (si1145_write(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (si1145_write(SI1145_REG_MEAS_RATE, 0x00) < 0) return -1;
    if (si1145_write(SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) < 0) return -1;
    if (si1145_wait_response(0x00) < 0) return -1;
    return 0;
}

static int si1145_read_proximity(uint16_t *prox) {
    if (si1145_write(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    if (si1145_wait_response(0x00) < 0) return -1;
    uint8_t lo, hi;
    if (si1145_read(SI1145_REG_PS1_DATA0, &lo) < 0) return -1;
    if (si1145_read(SI1145_REG_PS1_DATA0 + 1, &hi) < 0) return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int si1145_read_als(uint16_t *als) {
    if (si1145_write(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (si1145_wait_response(0x00) < 0) return -1;
    uint8_t lo, hi;
    if (si1145_read(SI1145_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (si1145_read(SI1145_REG_ALS_VIS_DATA0 + 1, &hi) < 0) return -1;
    *als = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        si1145_write(SI1145_REG_COMMAND, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n", I2C_BUS, SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t prox = 0, als = 0;
        int prox_ok = si1145_read_proximity(&prox);
        int als_ok = si1145_read_als(&als);

        if (prox_ok == 0 && als_ok == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            fprintf(g_log_file, "%s,%u,%u\n", ts, prox, als);
            fflush(g_log_file);
            printf("%s  Proximity: %u  Ambient Light: %u\n", ts, prox, als);
        } else {
            fprintf(stderr, "Sensor read error (prox=%d, als=%d)\n", prox_ok, als_ok);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

