#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define POLL_INTERVAL_US 100000

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_CONFIG2 0x91
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C
#define APDS9960_CONFIG3 0xA0
#define APDS9960_GPENTH 0xA1
#define APDS9960_GEXTH 0xA2
#define APDS9960_PPENTH 0xAA
#define APDS9960_PEXTH 0xAB
#define APDS9960_EVEVENT 0xAE
#define APDS9960_EVDATA 0xAF
#define APDS9960_WTIME_DEFAULT 255
#define APDS9960_ATIME_DEFAULT 256
#define APDS9960_PPULSE_DEFAULT 0x87
#define APDS9960_CONTROL_DEFAULT 0x03
#define APDS9960_CONFIG1_DEFAULT 0x60
#define APDS9960_CONFIG2_DEFAULT 0x01
#define APDS9960_CONFIG3_DEFAULT 0x00
#define APDS9960_GPENTH_DEFAULT 0x00
#define APDS9960_GEXTH_DEFAULT 0x00
#define APDS9960_PPENTH_DEFAULT 0x00
#define APDS9960_PEXTH_DEFAULT 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_l, uint8_t reg_h, uint16_t *value) {
    uint8_t low, high;
    if (read_reg(reg_l, &low) < 0) return -1;
    if (read_reg(reg_h, &high) < 0) return -1;
    *value = ((uint16_t)high << 8) | low;
    return 0;
}

static int apds9960_init(void) {
    uint8_t id;
    if (read_reg(APDS9960_ID, &id) < 0) return -1;
    if (id != 0x92) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0x92)\n", id);
        return -1;
    }
    if (write_reg(APDS9960_ENABLE, 0x00) < 0) return -1;
    if (write_reg(APDS9960_ATIME, APDS9960_ATIME_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_WTIME, APDS9960_WTIME_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_PPULSE, APDS9960_PPULSE_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_CONTROL, APDS9960_CONTROL_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_CONFIG1, APDS9960_CONFIG1_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_CONFIG2, APDS9960_CONFIG2_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_CONFIG3, APDS9960_CONFIG3_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_GPENTH, APDS9960_GPENTH_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_GEXTH, APDS9960_GEXTH_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_PPENTH, APDS9960_PPENTH_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_PEXTH, APDS9960_PEXTH_DEFAULT) < 0) return -1;
    if (write_reg(APDS9960_ENABLE, 0x03) < 0) return -1;
    return 0;
}

static int read_proximity(uint8_t *proximity) {
    return read_reg(APDS9960_PDATA, proximity);
}

static int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(APDS9960_RDATAL, APDS9960_RDATAH, red) < 0) return -1;
    if (read_word(APDS9960_GDATAL, APDS9960_GDATAH, green) < 0) return -1;
    if (read_word(APDS9960_BDATAL, APDS9960_BDATAH, blue) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    fflush(log_file);
    printf("APDS9960 initialized. Logging proximity events to color_proximity_log.csv. Press Ctrl+C to exit.\n");
    while (running) {
        uint8_t proximity;
        if (read_proximity(&proximity) < 0) {
            fprintf(stderr, "Proximity read failed, re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                break;
            }
            if (apds9960_init() < 0) {
                fprintf(stderr, "APDS9960 re-initialization failed\n");
                break;
            }
            continue;
        }
        if (proximity > PROXIMITY_THRESHOLD) {
            uint16_t red, green, blue;
            if (read_rgb(&red, &green, &blue) < 0) {
                fprintf(stderr, "RGB read failed, re-initializing I2C...\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(1000000);
                i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                    break;
                }
                if (apds9960_init() < 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    break;
                }
                continue;
            }
            log_data(red, green, blue, proximity);
            printf("Proximity threshold exceeded! Proximity: %u, RGB: (%u, %u, %u)\n", proximity, red, green, blue);
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

