#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */

/* Si1182 proximity / heart-rate registers */
#define REG_PROX_DATA0 0x22
#define REG_PROX_DATA1 0x23
#define REG_HR_DATA0   0x24
#define REG_HR_DATA1   0x25

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_PROX_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_PROX_DATA1, &hi) < 0)
        return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int read_heart_rate(int fd, uint16_t *hr)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_HR_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_HR_DATA1, &hi) < 0)
        return -1;
    *hr = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int calculate_bpm(uint16_t proximity)
{
    /* Simplified linear conversion: higher proximity = higher HR.
     * In a real deployment a robust calibration curve would be used. */
    return (int)(proximity * 2);
}

static int write_to_csv(FILE *fp, const char *timestamp, int bpm)
{
    if (fprintf(fp, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (csv_fp) {
        fclose(csv_fp);
        csv_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* Probe the sensor by reading a register; if it responds we have a real
     * Si1182.  A real production deployment would use a proper driver or
     * verify the device ID register. */
    uint8_t probe;
    if (i2c_read_reg8(i2c_fd, REG_PROX_DATA0, &probe) < 0) {
        fprintf(stderr, "Si1182 not detected at 0x%02X on %s\n",
                SI1182_ADDR, I2C_BUS);
        cleanup();
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1182 heart-rate monitor started.  Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t prox = 0, hr = 0;
        int prox_ok = (read_proximity(i2c_fd, &prox) == 0);
        int hr_ok   = (read_heart_rate(i2c_fd, &hr)   == 0);

        if (!prox_ok || !hr_ok) {
            fprintf(stderr, "Warning: I2C read error (prox=%d, hr=%d)\n",
                    prox_ok ? 1 : 0, hr_ok ? 1 : 0);
            usleep(SAMPLE_PERIOD);
            continue;
        }

        int bpm = calculate_bpm(prox);
        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        if (write_to_csv(csv_fp, ts, bpm) < 0) {
            fprintf(stderr, "CSV write failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

