#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define LOG_FILE "distance_log.txt"
#define POLL_TIMEOUT_MS 100

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET 0x0003
#define REG_SYSTEM_MODE_START 0x0001
#define REG_RESULT_INTERRUPT_STATUS 0x0014
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t addr[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);

    /* Verify sensor presence by reading the model ID */
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, 0x010F, &model_id, 1) < 0) return -1;
    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L0X not detected (model ID = 0x%02X, expected 0xEA)\n", model_id);
        return -1;
    }

    /* Start continuous back-to-back ranging */
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

static int vl53l0x_read_distance(int fd, int *distance_mm) {
    uint8_t status = 0;
    int timeout = POLL_TIMEOUT_MS;

    /* Poll RESULT_INTERRUPT_STATUS for data-ready bit (bit 0) */
    while (timeout > 0) {
        if (i2c_read_reg16(fd, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) return -1;
        if (status & 0x01) break;
        usleep(1000);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "VL53L0X measurement timeout\n");
        return -1;
    }

    /* Read 2-byte distance (big-endian) */
    uint8_t dist_buf[2] = {0};
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;
    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt by writing to RESULT_INTERRUPT_STATUS */
    if (i2c_write_reg16(fd, REG_RESULT_INTERRUPT_STATUS, 0x01) < 0) return -1;

    return 0;
}

static void log_distance(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    /* Initialize sensor */
    if (vl53l0x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    /* Configure GPIO trigger as input with pull-up */
    if (gpio_set_mode(GPIO_TRIGGER, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_TRIGGER);
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }
    if (gpio_set_pull_mode(GPIO_TRIGGER, GPIO_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO %d pull-up\n", GPIO_TRIGGER);
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Wait for falling edge on GPIO 17 */
        int prev = gpio_read(GPIO_TRIGGER);
        if (prev < 0) {
            fprintf(stderr, "GPIO read failed\n");
            break;
        }
        while (running) {
            usleep(10000);
            int cur = gpio_read(GPIO_TRIGGER);
            if (cur < 0) break;
            if (cur == 0 && prev == 1) break;
            prev = cur;
        }

        if (!running) break;

        int distance = 0;
        if (vl53l0x_read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else {
            log_distance(log_fp, distance);
            printf("Distance: %d mm\n", distance);
        }
    }

    /* Cleanup */
    if (log_fp) {
        fflush(log_fp);
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

