#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x50
#define TRIGGER_REG    0x00
#define DISTANCE_REG   0x02
#define TRIGGER_DELAY_US 50000   /* 50 ms */
#define SAMPLE_DELAY_US  200000  /* 200 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (local buffer, no dynamic allocation)              */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm  tm_info;

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register                                   */
/* ------------------------------------------------------------------ */
static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian distance value from the CH101              */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, uint16_t *distance_mm)
{
    char reg = (char)DISTANCE_REG;
    char data[2];

    /* Point to the distance register */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set distance register pointer\n");
        return -1;
    }

    /* Read 2 bytes (MSB first) */
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed for distance register\n");
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char  timestamp[32];
    uint16_t distance_mm;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the CH101 address */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    /* Main sampling loop */
    while (g_running) {
        /* Trigger a measurement */
        if (write_reg(g_i2c_handle, TRIGGER_REG, 0x01) != 0) {
            fprintf(stderr, "Warning: trigger write failed, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Wait for the measurement to complete */
        gpioDelay(TRIGGER_DELAY_US);

        /* Read the distance */
        if (read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Warning: distance read failed, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Build timestamp and log to file */
        get_timestamp(timestamp, sizeof(timestamp));
        fprintf(g_log_file, "%s, %u\n", timestamp, distance_mm);
        fflush(g_log_file);

        /* Also print to stdout */
        printf("%s, %u mm\n", timestamp, distance_mm);
        fflush(stdout);

        /* Wait before next sample */
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Graceful cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

