#define I2C_BUS        1
#define I2C_ADDR       0x2A
#define GPIO_LED       17
#define DISTANCE_THRESHOLD 20.0f
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE       "distance_log.txt"

/* ICU-20201 register addresses (example; adjust per datasheet) */
#define REG_DISTANCE_MSB 0x04
#define REG_DISTANCE_LSB 0x05
#define REG_CONFIG       0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_sensor(void)
{
    /* Configure sensor: set measurement mode, range, etc. */
    if (i2cWriteByteData(g_i2c_handle, REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write config register\n");
        return -1;
    }
    return 0;
}

static int read_distance(float *distance)
{
    int msb, lsb;

    msb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error: failed to read distance MSB\n");
        return -1;
    }

    lsb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error: failed to read distance LSB\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    *distance = (float)raw * 0.1f;  /* placeholder conversion */
    return 0;
}

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f\n", ts, distance);
    } else {
        fprintf(fp, "(unknown time), %.2f\n", distance);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_LED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }

            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(GPIO_LED, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

