#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* Si1182 register addresses (example; adjust per datasheet) */
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_PS1_DATA0     0x24
#define SI1182_REG_PS1_DATA1     0x25

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    uint8_t lo, hi;
    if (read_register(handle, SI1182_REG_PS1_DATA0, &lo) < 0) return -1;
    if (read_register(handle, SI1182_REG_PS1_DATA1, &hi) < 0) return -1;
    *proximity = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int read_ambient_light(int handle, uint16_t *ambient_light) {
    uint8_t lo, hi;
    if (read_register(handle, SI1182_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (read_register(handle, SI1182_REG_ALS_VIS_DATA1, &hi) < 0) return -1;
    *ambient_light = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(FILE *file, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(file, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        return -1;
    }
    fflush(file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging Si1182 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t proximity = 0, ambient_light = 0;
        int prox_ok = 0, amb_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_proximity(g_i2c_handle, &proximity) == 0) {
                prox_ok = 1;
                break;
            }
            fprintf(stderr, "Proximity read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_ambient_light(g_i2c_handle, &ambient_light) == 0) {
                amb_ok = 1;
                break;
            }
            fprintf(stderr, "Ambient light read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }

        if (prox_ok && amb_ok) {
            if (log_data(g_log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; skipping sample\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

