/*
 * ICU-20201 ultrasonic ToF sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   ICU-20201 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode      -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_reader tof_reader.c -lpigpio -lrt
 * Run:    sudo ./tof_reader [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ICU-20201 constants (verified against datasheet / datasheet errata) ---- */
#define ICU20201_I2C_BUS        1
#define ICU20201_ADDR           0x50
#define ICU20201_REG_WHO_AM_I   0x00
#define ICU20201_REG_DISTANCE   0x04
#define ICU20201_REG_CONFIG     0x01
#define ICU20201_WHO_AM_I_VAL   0x20

#define LED_GPIO                17
#define LOG_FILE                "tof_log.txt"
#define POLL_INTERVAL_US        50000   /* 50 ms */
#define MAX_RETRIES             3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address.                  */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int icu_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)(value >> 8);
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address.                 */
/* Returns 0 on success and stores the value in *out, -1 on failure.   */
/* ------------------------------------------------------------------ */
static int icu_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (char)(reg >> 8);
    reg_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg addr 0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (reg 0x%04X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ICU-20201: verify WHO_AM_I, configure, and power on. */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int icu_init(int handle)
{
    uint16_t who_am_i = 0;

    if (icu_read_reg16(handle, ICU20201_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ICU20201_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure: 100 ms period, 100 samples, 100 µs per sample. */
    if (icu_write_reg16(handle, ICU20201_REG_CONFIG, 0x0001) != 0)
        return -1;

    /* Power on: set bit 0 of CONFIG register. */
    if (icu_write_reg16(handle, ICU20201_REG_CONFIG, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres. Returns -1 on error.                 */
/* ------------------------------------------------------------------ */
static int icu_read_distance(int handle)
{
    uint16_t distance = 0;
    if (icu_read_reg16(handle, ICU20201_REG_DISTANCE, &distance) != 0)
        return -1;
    return (int)distance;
}

/* ------------------------------------------------------------------ */
static void log_distance(int distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
