#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x28
#define CMD_FRAME_LEN  4
#define RESP_FRAME_LEN 15
#define INTRUSION_DIST 1000
#define SAMPLE_COUNT   10
#define SAMPLE_DELAY   100000   /* microseconds */
#define MEAS_DELAY     10000    /* microseconds */
#define LOG_FILE       "intrusion_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C write short: %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance)
{
    uint8_t cmd[CMD_FRAME_LEN] = {0x01, 0x00, 0x00, 0x00};
    uint8_t resp[RESP_FRAME_LEN];

    if (i2c_write(fd, cmd, CMD_FRAME_LEN) < 0)
        return -1;

    usleep(MEAS_DELAY);

    if (i2c_read(fd, resp, RESP_FRAME_LEN) < 0)
        return -1;

    if (resp[0] != 0x01) {
        fprintf(stderr, "Unexpected response header: 0x%02X\n", resp[0]);
        return -1;
    }

    *distance = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(FILE *fp, uint16_t avg_dist)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Average Distance: %u mm\n", ts, avg_dist);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                B5L_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Monitoring intrusion (1m <= distance <= 10m)...\n");

    while (g_running) {
        uint16_t sum = 0;
        int ok = 0;

        for (int i = 0; i < SAMPLE_COUNT && g_running; i++) {
            uint16_t dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                sum += dist;
                ok++;
            } else {
                fprintf(stderr, "Read error (attempt %d)\n", i + 1);
            }
            if (i < SAMPLE_COUNT - 1)
                usleep(SAMPLE_DELAY);
        }

        if (ok == 0) {
            fprintf(stderr, "No valid readings this cycle\n");
            continue;
        }

        uint16_t avg = sum / ok;
        if (avg < INTRUSION_DIST) {
            log_intrusion(fp, avg);
            printf("INTRUSION DETECTED: avg=%u mm\n", avg);
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    fclose(fp);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

