#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define REG_MODEL_ID   0x010F
#define EXPECTED_ID    0xEA
#define REG_SYSRANGE_START 0x0000
#define REG_RESULT_INT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_MS   500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l0x_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != EXPECTED_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X). Sensor not present or wrong device.\n", id, EXPECTED_ID);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    uint8_t dist_buf[2];
    int elapsed = 0;

    if (i2c_write_reg16(handle, REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging: %s\n", strerror(errno));
        return -1;
    }

    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, REG_RESULT_INT_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status: %s\n", strerror(errno));
