    g_running = 0;
}

static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int si1182_read_reg(int handle, uint8_t reg, uint8_t *value)
{
