        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1182_init(int handle)
{
    if (si1182_write_reg(handle, REG_HW_KEY, HW_KEY_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, REG_MEAS_RATE, MEAS_RATE_VAL) < 0)
        return -1;
    return 0;
}

static int si1182_read_proximity(int handle, uint16_t *proximity)
{
    uint8_t lo, hi;
    if (si1182_read_reg(handle, REG_ALS_VIS_DATA0, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, REG_ALS_VIS_DATA1, &hi) < 0)
        return -1;
    *proximity = ((uint16_t)hi << 8) | lo;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t proximity;
        if (si1182_read_proximity(g_i2c_handle, &proximity) == 0) {
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nExiting...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

