/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   OPT3101 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   OPT3101 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   OPT3101 VDD  -> 3.3 V
 *   OPT3101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101 opt3101.c -lpigpio -lrt
 * Run:    sudo ./opt3101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 I2C configuration ---- */
#define I2C_BUS        1
#define OPT3101_ADDR   0x48   /* OPT3101 default I2C address */

/* ---- OPT3101 register addresses ---- */
#define REG_CHIP_ID    0x00
#define REG_STATUS     0x01
#define REG_RANGE0     0x02   /* Channel 0 range result (16-bit) */
#define REG_ALS0       0x04   /* Channel 0 ambient light (16-bit) */
#define REG_ALS1       0x06   /* Channel 1 ambient light (16-bit) */
#define REG_ALS2       0x08   /* Channel 2 ambient light (16-bit) */
#define REG_ALS3       0x0A   /* Channel 3 ambient light (16-bit) */
#define REG_CONFIG     0x0F   /* Configuration register */

/* ---- Expected chip ID ---- */
#define OPT3101_CHIP_ID 0x3101

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

