#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms */
#define MAX_PULSE_US      38000    /* ~38 m round-trip */
#define SAMPLE_PERIOD_S   1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read distance from an HC-SR04 ultrasonic sensor.
 *
 * Returns:
 *   > 0 on success (distance in mm)
 *   -1 on timeout waiting for echo rising edge
 *   -2 on timeout waiting for echo falling edge
 *   -3 on invalid pulse duration (<= 0 or > 38 ms)
 */
static int read_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue a 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    timeout_tick = echo_start + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - echo_start;

    if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us (out of range)\n",
                pulse_us);
        return -3;
    }

    /* distance = (pulse_us / 1000000.0) * 34300.0 / 2.0 */
    return (int)((pulse_us * 34300) / 2000000);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init low) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = read_distance();

        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (distance > 0) {
            printf("%s - Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "%s - Error reading distance (code %d)\n",
                    timestamp, distance);
        }

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean up: issue a final trigger pulse to ensure the sensor is reset */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(1000);
    gpioWrite(TRIGGER_PIN, 0);

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

