#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_PROFILE_SIZE 128
#define MAGIC_WORD_SIZE 8
#define DATA_SIZE (RANGE_PROFILE_SIZE * sizeof(uint16_t))
#define LOG_FILE "intrusion_log.csv"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static int led_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_led(int gpio) {
    led_fd = open("/sys/class/gpio/gpio" INT_TO_PTR(gpio) "/value", O_WRONLY);
    if (led_fd < 0) {
        perror("open LED value");
        return -1;
    }
    if (write(led_fd, "1", 1) != 1) {
        perror("write LED init");
        close(led_fd);
        led_fd = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_fd >= 0) {
        write(led_fd, "0", 1);
        close(led_fd);
        led_fd = -1;
    }
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
}

static int log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance) < 0) {
        perror("fprintf log");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose log");
        return -1;
    }
    return 0;
}

static int detect_intrusion(const uint16_t *profile) {
    for (int i = 0; i < RANGE_PROFILE_SIZE; i++) {
        if (profile[i] > 0 && profile[i] < (uint16_t)(INTRUSION_THRESHOLD * 100.0f)) {
            return 1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    if (init_led(GPIO_LED) != 0) {
        cleanup();
        return 1;
    }

    uint8_t magic[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    uint8_t buffer[DATA_SIZE + MAGIC_WORD_SIZE];
    size_t buffer_len = 0;
    uint16_t range_profile[RANGE_PROFILE_SIZE];

    printf("Monitoring IWR1443 radar on %s... (Ctrl+C to exit)\n", UART_DEVICE);

    while (program_running) {
        ssize_t n = read(uart_fd, buffer + buffer_len, sizeof(buffer) - buffer_len);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read UART");
            break;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }

        buffer_len += n;

        while (buffer_len >= (ssize_t)(MAGIC_WORD_SIZE + DATA_SIZE)) {
            if (memcmp(buffer, magic, MAGIC_WORD_SIZE) == 0) {
                memcpy(range_profile, buffer + MAGIC_WORD_SIZE, DATA_SIZE);
                float distance = range_profile[0] / 100.0f;

                if (detect_intrusion(range_profile)) {
                    printf("Intrusion detected: %.2f m\n", distance);
                    if (log_intrusion(distance) == 0) {
                        printf("Intrusion logged.\n");
                    }
                    if (write(led_fd, "1", 1) != 1) {
                        perror("write LED on");
                    }
                    sleep(2);
                    if (write(led_fd, "0", 1) != 1) {
                        perror("write LED off");
                    }
                }
                memmove(buffer, buffer + MAGIC_WORD_SIZE + DATA_SIZE, buffer_len - (MAGIC_WORD_SIZE + DATA_SIZE));
                buffer_len -= MAGIC_WORD_SIZE + DATA_SIZE;
            } else {
                memmove(buffer, buffer + 1, buffer_len - 1);
                buffer_len--;
            }
        }
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

