#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", event);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_PIN %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* E18-D80NK is active-low: 0 = obstacle detected, 1 = clear */
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on SENSOR_PIN %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = -1;
    int first_read = 1;

    while (running) {
        int val = gpioRead(SENSOR_PIN);
        if (val < 0) {
            fprintf(stderr, "gpioRead failed on SENSOR_PIN %d\n", SENSOR_PIN);
            break;
        }

        if (first_read) {
            last_state = val;
            first_read = 0;
        } else if (val != last_state) {
            const char *event = (val == 0) ? "Obstacle detected" : "Obstacle cleared";
            if (gpioWrite(BUZZER_PIN, val) != 0) {
                fprintf(stderr, "gpioWrite failed on BUZZER_PIN %d\n", BUZZER_PIN);
                break;
            }
            if (log_event(event) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            last_state = val;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Ensure buzzer is off on exit */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

