/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance logger
 *
 * Wiring:
 *   ICU-20201 SDA  -> Pi GPIO2  (I2C bus 1, pin 3)
 *   ICU-20201 SCL  -> Pi GPIO3  (I2C bus 1, pin 5)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   Alert LED / buzzer on Pi GPIO17 (BCM 17, pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o distance_logger distance_logger.c -lpigpio -lrt
 * Run:    sudo ./distance_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define ICU20201_ADDR      0x28          /* default 7-bit I2C address */
#define ALERT_GPIO         17            /* BCM 17, physical pin 11 */
#define DISTANCE_THRESHOLD 10.0f        /* cm */
#define LOG_FILE           "distance_log.txt"
#define SAMPLE_PERIOD_US   100000        /* 100 ms */
#define MAX_RETRIES        3

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE_MSB   0x00
#define REG_DISTANCE_LSB   0x01
#define REG_CONFIG         0x02
#define REG_MEAS_START     0x03

/* Config: 1 MHz clock, 100 µs max range, 100 µs sample interval */
#define CONFIG_VALUE       0x000A

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  init_sensor(void);
static int  read_distance(float *distance_out);
static void log_distance(float distance);
static void trigger_alert(float distance);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------- GPIO ------------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor initialization ------------------------ */
static int init_sensor(void)
{
    /* Write 16-bit config value to CONFIG register */
    uint8_t buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF;
    buf[2] = CONFIG_VALUE & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 3) != 0) {
        fprintf(stderr, "[ERROR] Failed to write config register 0x%02X\n", REG_CONFIG);
        return -1;
    }

    /* Allow the first measurement to complete */
    gpioDelay(100000);  /* 100 ms */
    return 0;
}

/* ------------------------------- Read distance --------------------------- */
static int read_distance(float *distance_out)
{
    uint8_t reg = REG_DISTANCE_MSB;
    uint8_t data[2];

    /* Point to the distance register */
    if (i2cWriteDevice(g_i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to set distance register pointer\n");
        return -1;
    }

    /* Read 2 bytes (MSB first) */
    if (i2cReadDevice(g_i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to read distance data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *distance_out = (float)raw * 0.01f;  /* cm */
    return 0;
}

/* ------------------------------- Log distance ----------------------------- */
static void log_distance(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, %.2f\n", ts, distance);
    fflush(g_log_file);
