/*
 * Parking assistance system using STMicroelectronics VL53L1X ToF sensor.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: VL53L1X on 0x29
 * Log:    distance_log.csv
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assistance parking_assistance.c \
 *              -li2c -lpigpio -lrt
 * Run:    sudo ./parking_assistance
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants -------------------------------------------------- */
#define VL53L1X_DEFAULT_I2C_ADDR   0x29
#define VL53L1X_REG_SOFT_RESET     0x0000
#define VL53L1X_REG_SYSTEM_MODE    0x0001
#define VL53L1X_REG_SYSTEM_RANGE   0x0014
#define VL53L1X_REG_RESULT_RANGE   0x0096
#define VL53L1X_REG_RESULT_INT    0x0089
#define VL53L1X_REG_RESULT_INT_EN 0x0086
#define VL53L1X_REG_RESULT_INT_CLR 0x0087
#define VL53L1X_REG_RESULT_INT_STA 0x0088
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_SOFT_RESET_VAL    0x00
#define VL53L1X_SOFT_RESET_CMD    0x0003
#define VL53L1X_SOFT_RESET_WAIT_US 2000

#define VL53L1X_RANGE_START       0x0000
#define VL53L1X_RANGE_STOP        0x0001
#define VL53L1X_RANGE_MODE_SINGLE 0x0000
#define VL53L1X_RANGE_MODE_CONT   0x0001

#define VL53L1X_RANGE_STATUS_OK   0x00
#define VL53L1X_RANGE_STATUS_NO_DATA 0x01

#define POLL_INTERVAL_US          100000   /* 100 ms */
#define MAX_RANGE_MM              2000
#define MIN_RANGE_MM              0
#define STOP_THRESHOLD_MM         300
#define APPROACH_THRESHOLD_MM     600

/* ---- Globals ----------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Prototypes -------------------------------------------------------- */
static void signal_handler(int sig);
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t val);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void log_distance(FILE *fp, uint16_t distance_mm);
static void parking_guidance(uint16_t distance_mm);
static void cleanup(void);

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------- */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- VL53L1X driver ---------------------------------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t id_buf[2];
    uint8_t rev_buf[2];

    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(VL53L1X_SOFT_RESET_WAIT_US);

    /* Read firmware revision (bytes 0x01 and 0x02) */
    if (vl53l1x_read16(handle, 0x0100, id_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read firmware revision\n");
        return -1;
    }
    memcpy(rev_buf, id_buf, 2);
    printf("VL53L1X firmware revision: 0x%02X%02X\n", rev_buf[0], rev_buf[1]);

    /* Clear interrupt and set to single-shot mode */
    if (vl53l1x_write16(handle, VL53L1X_REG_RESULT_INT_EN, 0x00) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt\n");
        return -1;
    }
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_RANGE_MODE_SINGLE) < 0) {
        fprintf(stderr, "Error: failed to set single-shot mode\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status_buf[1];
    uint8_t int_buf[1];
    uint8_t dist_buf[2];

    /* Start a single-shot measurement */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_RANGE, VL53L1X_RANGE_START) < 0) {
        fprintf(stderr, "Error: failed to start range measurement\n");
        return -1;
    }

    /* Poll for completion (max ~50 ms) */
    for (int i = 0; i < 50; i++) {
        gpioDelay(1000);
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INT_STA, int_buf, 1) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status\n");
            return -1;
        }
        if (int_buf[0] & 0x01)
            break;
    }

    /* Read distance */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance\n");
        return -1;
    }
    *distance_mm = (uint16_t)((dist_buf[0] << 8) | dist_buf[1]);

    /* Read range status */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) < 0) {
        fprintf(stderr, "Error: failed to read range status\n");
        return -1;
    }

    if (status_buf[0] == VL53L1X_RANGE_STATUS_NO_DATA) {
        fprintf(stderr, "Warning: no data available (status 0x%02X)\n", status_buf[0]);
        return -1;
    }

    /* Clear interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_RESULT_INT_CLR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt\n");
        return -1;
    }

    return 0;
}

/* ---- Logging ----------------------------------------------------------- */
static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

static void parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < STOP_THRESHOLD_MM)
        printf("STOP - Object within %.0f mm\n", distance_mm);
    else if (distance_mm < APPROACH_THRESHOLD_MM)
        printf("APPROACH - Object %.0f mm - %.0f mm\n",
               STOP_THRESHOLD_MM, APPROACH_THRESHOLD_MM);
    else if (distance_mm < (MAX_RANGE_MM + 1))
        printf("SLOW - Object %.0f mm - %.0f mm\n",
               APPROACH_THRESHOLD_MM, MAX_RANGE_MM);
    else
        printf("CLEAR - Object %.0f mm - %.0f mm\n",
               MAX_RANGE_MM + 1, MAX_RANGE_MM + 1);
}

/* ---- Cleanup ----------------------------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at 0x29 */
    g_i2c_handle = i2cOpen(1, VL53L1X_DEFAULT_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error: failed to open distance_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            log_distance(g_log_file, distance_mm);
            parking_guidance(distance_mm);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping log entry\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

