/*
 * Raspberry Pi 4 Model B — CH201 ultrasonic TOF sensor reader
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode  -> GPIO 18 (BCM) via 330 Ω resistor to 3.3 V
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_reader ch201_reader.c -lpigpio -lrt
 * Run:    sudo ./ch201_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x28          /* CH201 default 7-bit I2C address */
#define LED_GPIO           18            /* BCM pin for the LED */
#define SAMPLE_PERIOD_US   100000        /* 100 ms between samples */
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000         /* 10 ms between retries */
#define MAX_DISTANCE_CM    400.0f        /* CH201 rated max range */
#define MIN_DISTANCE_CM    2.0f          /* CH201 rated min range */
#define MIN_BLINK_HZ       1.0f          /* Hz when distance = MAX_DISTANCE_CM */
#define MAX_BLINK_HZ       10.0f         /* Hz when distance = MIN_DISTANCE_CM */

/* CH201 register addresses (16-bit, big-endian on the wire) */
#define REG_CHIP_ID        0x00
#define REG_SOFT_RESET     0x01
#define REG_RANGE_CONFIG   0x02
#define REG_RANGE_RESULT   0x04
#define REG_LED_CONFIG     0x05
#define REG_LED_CURRENT    0x06
#define REG_LED_FREQ       0x07
#define REG_LED_DUTY       0x08
#define REG_LED_PWM        0x09
#define REG_LED_CTRL       0x0A

#define EXPECTED_CHIP_ID   0x01          /* CH201 family ID */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

