#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x60
#define MEASURE_CMD 0x01
#define MEASURE_DELAY_US 10000
#define READ_DELAY_US 10000
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, int *distance_cm) {
    char cmd = MEASURE_CMD;
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "Error: I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "Error: I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(100000);
            continue;
        }

        *distance_cm = (buf[0] << 8) | buf[1];
        return 0;
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries\n", RETRY_COUNT);
    return -1;
}

static int log_data(const char *filename, int distance_cm) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d\n", timestamp, distance_cm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d\n", MLX75030_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int distance_cm = -1;

        if (read_distance(i2c_handle, &distance_cm) == 0) {
            if (log_data(LOG_FILE, distance_cm) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

