#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000

/* MLX75030 register addresses (example; adjust per datasheet) */
#define REG_DISTANCE_MSB 0x01
#define REG_DISTANCE_LSB 0x02
#define REG_CONFIG       0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance)
{
    uint8_t msb, lsb;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_register(handle, REG_DISTANCE_MSB, &msb) == 0 &&
            read_register(handle, REG_DISTANCE_LSB, &lsb) == 0) {
            *distance = ((uint16_t)msb << 8) | lsb;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_data(uint16_t distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    printf("[%ld.%03ld] Distance: %u mm\n",
           (long)ts.tv_sec, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor (example; adjust per datasheet) */
    if (write_register(g_i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to configure sensor.\n");
    }

    while (g_running) {
        uint16_t distance;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

