#define I2C_BUS        1
#define VL53L4CX_ADDR  0x29

/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_SYSTEM_START            0x0000
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0001
#define REG_SYSTEM_INTERRUPT_STATUS 0x0001
#define REG_RESULT_RANGE_STATUS     0x0008
#define REG_RESULT_DISTANCE         0x0096

#define POLL_DELAY_US   500000   /* 500 ms */
#define MAX_RETRIES     10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L4CX driver                                                     */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Start ranging (bit 0 = 1) */
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int rc = -1;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(handle, REG_SYSTEM_INTERRUPT_STATUS, &status, 1) != 0)
            return -1;

        if (status & 0x01) {
            uint8_t dist_buf[2];
            if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) != 0)
                return -1;

            *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
            rc = 0;
            break;
        }

        gpioDelay(1000); /* 1 ms */
    }

    if (rc == 0) {
        /* Clear the interrupt so the next measurement can be read */
        if (i2c_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
            return -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers early */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L4CX initialized. Polling every 500 ms. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance = 0;
        char ts[40];

        if (vl53l4cx_read_distance(g_i2c_handle, &distance) == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("Timestamp: %s, Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance after %d attempts.\n",
                    MAX_RETRIES);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        /* Stop ranging */
        (void)i2c_write_reg16(g_i2c_handle, REG_SYSTEM_START, 0x00);
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
