        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to clear soft reset register.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_START, 0x01);
