#define MAX_ANGLE        (90.0f)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static float calculate_angle(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;
    return MIN_ANGLE + (distance_cm - MIN_DISTANCE_CM) *
           (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

static int log_data(float distance_cm, int angle)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("fopen(sensor_data.log)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm, angle);
    } else {
        fprintf(fp, "(time error), Distance: %.2f cm, Angle: %d\n", distance_cm, angle);
    }

    if (fclose(fp) != 0) {
        perror("fclose(sensor_data.log)");
        return -1;
    }
    return 0;
}

static int read_distance_cm(float *distance_cm)
{
    if (!distance_cm) return -1;

    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    gpioDelay(5);

    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) return -1;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    *distance_cm = (pulse_us * 0.0343f) / 2.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

