        float distance_cm;
        if (read_distance_cm(&distance_cm) == 0) {
            int angle = (int)calculate_angle(distance_cm);
            if (gpioServo(SERVO_PIN, angle) < 0) {
                fprintf(stderr, "gpioServo failed\n");
            }
            if (log_data(distance_cm, angle) != 0) {
                fprintf(stderr, "log_data failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error (timeout or invalid pulse)\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

