#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define POLL_DELAY_MS 50
#define MSG_QUEUE_NAME "/vl53l1x_queue"

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int mq_id = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(fd, buf, 3) == 3) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(fd, reg_buf, 2) != 2) {
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance) {
    uint8_t status;
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if (status & 0x01) {
        uint8_t dist_buf[2];
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;
        *distance = (dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }
    return -1;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (mq_id >= 0) {
        msgctl(mq_id, IPC_RMID, NULL);
        mq_id = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    mq_id = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (mq_id < 0) {
        perror("Failed to create message queue");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring (threshold: %d mm)...\n", DISTANCE_THRESHOLD);

    while (running) {
        int distance;
        if (vl53l1x_read_distance(i2c_fd, &distance) == 0) {
            char msg[32];
            snprintf(msg, sizeof(msg), "%d", distance);
            if (msgsnd(mq_id, msg, strlen(msg), 0) < 0) {
                perror("Failed to send message to queue");
            }
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance from sensor\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    cleanup();
    return 0;
}

