/*
 * Parking sensor for Raspberry Pi 3 Model B+
 * HC-SR04 ultrasonic sensor on GPIO 17 (trigger), GPIO 27 (echo), buzzer on GPIO 22.
 * Uses the pigpio library for GPIO and interrupt-driven timing.
 *
 * Build: gcc -Wall -Wextra -O2 -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US  0.0343   /* cm/us at 20 °C */
#define MIN_DISTANCE_CM           2.0
#define MAX_DISTANCE_CM           400.0
#define BUZZER_THRESHOLD_CM       30.0
#define SAMPLE_PERIOD_US          100000    /* 100 ms */
#define TRIGGER_PULSE_US          10
#define ECHO_TIMEOUT_US           30000      /* 30 ms (~5 m round trip) */
#define ECHO_VALID_MIN_US         20         /* 2 cm round trip */
#define ECHO_VALID_MAX_US         38000      /* 400 cm round trip */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t start_tick = 0;
    static bool     echo_rising = false;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
        echo_rising = true;
    } else if (level == 0 && echo_rising) {
        /* Falling edge: echo pulse ends */
        uint32_t elapsed = tick - start_tick;   /* handles 32-bit wrap */
        double   distance = (elapsed * SPEED_OF_SOUND_CM_PER_US) / 2.0;

        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Invalid reading: %.2f cm (out of range)\n",
                    distance);
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ---------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register echo alert ---------------------------------------- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register echo alert on GPIO %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

