#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *val) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) return -1;
    *val = (uint8_t)data[0];
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *val) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *val = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int vl53l1x_reset(int handle) {
    if (i2c_write_byte(handle, 0x00, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_byte(handle, 0x00, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_boot(int handle) {
    uint8_t status;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_byte(handle, 0x01, &status) < 0) return -1;
        if ((status & 0x01) == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_reset(handle) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_boot(handle) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    return i2c_write_byte(handle, 0x00, 0x01);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_byte(handle, 0x00, &status) < 0) return -1;
        if ((status & 0x04) == 0) break;
        gpioDelay(10000);
    }
    if (i2c_read_word(handle, 0x00, distance) < 0) return -1;
    return 0;
}

static void servo_set_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = (angle * 1000) / 180 + 500;
    gpioServo(SERVO_PIN, pulse_width);
}

static void gate_open(void) {
    log_event("Gate opening");
    servo_set_angle(180);
    gpioDelay(1000000);
}

static void gate_close(void) {
    log_event("Gate closing");
    servo_set_angle(0);
    gpioDelay(1000000);
}

static void gate_control(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        log_event("Object detected, gate opening");
        gate_open();
    } else {
        log_event("Path clear, gate closing");
        gate_close();
    }
}

static void vl53l1x_callback(int handle, uint8_t status, uint16_t distance) {
    (void)handle;
    if (status == 0) {
        gate_control(distance);
    } else {
        log_event("VL53L1X ranging error");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        log_event("I2C initialization failed");
        cleanup();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_event("VL53L1X initialization failed");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        log_event("Failed to start ranging");
        cleanup();
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    servo_set_angle(0);

    log_event("Program started");

    while (running) {
        uint16_t distance;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(100000);
        }

        if (success) {
            vl53l1x_callback(i2c_handle, 0, distance);
        } else {
            log_event("Failed to read distance after retries");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

