/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO 23 (physical pin 16, output, 3.3 V)
 *   ECHO -> GPIO 24 (physical pin 18, input, 5 V, use a voltage divider
 *                 or level shifter to bring it within the Pi's 3.3 V
 *                 tolerance; the HC-SR04 ECHO is 5 V logic)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN      23
#define ECHO_PIN      24

#define TRIG_PULSE_US 10          /* 10 µs trigger pulse            */
#define SAMPLE_US     200000      /* 5 Hz sampling interval         */
#define TIMEOUT_US    60000       /* 60 ms timeout for echo         */
#define MIN_PULSE_US  100         /* reject < 100 µs (noise)        */
#define MAX_PULSE_US  30000       /* reject > 30 ms (out of range)  */
#define SOUND_US_CM   58          /* round-trip 2 cm / 0.02 s       */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void timestamp_iso(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */
static void echo_alert(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;

    static uint32_t rising_tick = 0;
    static bool     have_rising = false;

    if (level == 1) {
        /* Rising edge: echo starts */
        rising_tick = tick;
        have_rising = true;
    } else if (level == 0 && have_rising) {
        /* Falling edge: echo ends */
        uint32_t pulse_us = tick - rising_tick;   /* handles 32-bit wrap */
        have_rising = false;

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            char ts[32];
            timestamp_iso(ts, sizeof ts);
            fprintf(stderr,
                    "[WARN] %s  Echo pulse %u us out of range [%.0f, %.0f]\n",
                    ts, pulse_us, (double)MIN_PULSE_US, (double)MAX_PULSE_US);
            return;
        }

        double distance = (double)pulse_us / 2.0 / SOUND_US_CM;
        char ts[32];
        timestamp_iso(ts, sizeof ts);

        printf("%s  Distance: %.2f cm  (pulse %u us)\n", ts, distance, pulse_us);
        fflush(stdout);

        if (g_log) {
            fprintf(g_log, "%s,%.2f,%.0f\n", ts, distance, (double)pulse_us);
            fflush(g_log);
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen("distance_log.txt", "a");
    if (!g_log) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: cannot set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Error: cannot initialise TRIG_PIN %d LOW.\n", TRIG_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);  /* 50 ms settle */

    /* ---- register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) != 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG_PIN : GPIO %d\n", TRIG_PIN);
    printf("  ECHO_PIN : GPIO %d (5 V -> use divider / level shifter)\n", ECHO_PIN);
    printf("  Sample   : every %d µs (%.1f Hz)\n", SAMPLE_US, 1000000.0 / SAMPLE_US);
    printf("  Log file : distance_log.txt\n");
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed.\n");
            break;
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed.\n");
            break;
        }

        /* Wait for echo or timeout */
        uint32_t waited = 0;
        while (gpioRead(ECHO_PIN) == 0 && waited < TIMEOUT_US && g_running) {
            gpioDelay(100);  /* 100 µs granularity */
            waited += 100;
        }
        if (!g_running) break;
        if (waited >= TIMEOUT_US) {
            char ts[32];
            timestamp_iso(ts, sizeof ts);
            fprintf(stderr,
                    "[WARN] %s  Echo timeout: no rising edge within %d µs\n",
                    ts, TIMEOUT_US);
            continue;
        }

        /* Wait for falling edge (or timeout) */
        waited = 0;
        while (gpioRead(ECHO_PIN) == 1 && waited < TIMEOUT_US && g_running) {
            gpioDelay(100);
            waited += 100;
        }
        if (!g_running) break;
        if (waited >= TIMEOUT_US) {
            char ts[32];
            timestamp_iso(ts, sizeof ts);
            fprintf(stderr,
                    "[WARN] %s  Echo timeout: no falling edge within %d µs\n",
                    ts, TIMEOUT_US);
            continue;
        }
    }

    /* ---- cleanup ---- */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    gpioTerminate();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

