/*
 * Smart Parking Gate using VL53L1X ToF Sensor and Servo Motor
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 * Sensor: VL53L1X on 0x29, shutdown=GPIO23, interrupt=GPIO24
 * Servo:  Hardware PWM on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o parking_gate parking_gate.c -lpigpio -lrt
 * Run:    sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18          /* BCM 18 — hardware PWM0 */
#define SERVO_FREQ_HZ        50          /* 50 Hz hardware PWM */
#define SERVO_RANGE          2000        /* 0–2000 us pulse width range */

#define DISTANCE_THRESHOLD_OPEN  50      /* cm  — open gate below this */
#define DISTANCE_THRESHOLD_CLOSE 60      /* cm  — close gate above this */
#define LOG_FILE             "parking_log.txt"
#define POLL_DELAY_US        100000      /* 100 ms between readings */
#define SERVO_OPEN_US        1000        /* ~1.5 ms pulse width for open */
#define SERVO_CLOSED_US      1500        /* ~2.0 ms pulse width for closed */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID_EXPECTED           0xEA

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  vl53l1x_write16(int handle, uint16_t reg, uint16_t val);
static int  vl53l1x_read16(int handle, uint16_t reg, uint16_t *out);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void set_servo_angle(int angle);
static void log_event(const char *event, uint16_t distance_mm);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C Helpers ------------------------------- */
static int vl53l1x_write16(int handle, uint16_t reg, uint16_t val)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ----------------------------- VL53L1X Driver ---------------------------- */
static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Verify sensor identity */
    if (vl53l1x_read16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read VL53L1X model ID — sensor absent or bus error\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] VL53L1X detected (model ID 0x%04X)\n", model_id);

    /* Software reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) != 0) return -1;
    gpioDelay(1000);  /* 1 ms */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) != 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Start continuous ranging (mode 0x0001 = single shot, then start) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0001) != 0) return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;
    uint16_t dist   = 0;

    /* Check the data-ready bit (bit 0 of the range status) */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;
    if ((status & 0x0001) == 0) {
        /* No new data yet — return 0 so caller can poll */
        return 1;
    }

    /* Read the 16-bit distance in mm */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear the data-ready bit so the next poll can check again */
    if (vl53l1x_write16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0x0001) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ----------------------------- Servo Control ----------------------------- */
static void set_servo_angle(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    /* pigpio hardware PWM range is 0–2000 us; 0° = 1000 us, 180° = 1500 us */
    int pulse_us = SERVO_OPEN_US - (angle * (SERVO_OPEN_US - SERVO_CLOSED_US) / 180);
    if (pulse_us < SERVO_CLOSED_US) pulse_us = SERVO_CLOSED_US;
    if (pulse_us > SERVO_OPEN_US)   pulse_us = SERVO_OPEN_US;

    if (gpioHardwarePWM(SERVO_PIN, SERVO_FREQ_HZ, pulse_us * 1000) != 0) {
        fprintf(stderr, "[ERROR] gpioHardwarePWM failed on pin %d\n", SERVO_PIN);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (distance_mm == 0) {
        fprintf(g_log_file, "%s - %s - Distance: N/A\n", ts, event);
    } else {
        fprintf(g_log_file, "%s - %s - Distance: %u mm\n", ts, event, distance_mm);
    }
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure gate is closed */
    set_servo_angle(0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to VL53L1X */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d) — check wiring and I2C address\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Parking gate system started. Press Ctrl+C to exit.\n");

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = (int)(distance_mm / 10);

            if (distance_cm > 0) {
                printf("[INFO] Distance: %d cm\n", distance_cm);

                if (distance_cm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                    set_servo_angle(180);
                    gate_open = true;
                    log_event("Gate opened", distance_mm);
                    printf("[INFO] Gate opened\n");
                } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                    set_servo_angle(0);
                    gate_open = false;
                    log_event("Gate closed", distance_mm);
                    printf("[INFO] Gate closed\n");
                }
            } else {
                /* No object detected — keep current state */
                gpioDelay(POLL_DELAY_US);
                continue;
            }
        } else if (rc < 0) {
            /* I2C error — log and continue */
            log_event("Sensor read error", 0);
            fprintf(stderr, "[WARN] Sensor read error — continuing\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

