    return i2cWriteWordData(handle, reg, value);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) return -1;
    *value = (uint16_t)rc;
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "Error: soft reset clear failed\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
