    return vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0001);
}

static int vl53l1x_stop_ranging(int handle) {
    return vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0000);
