    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_start_ranging(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_GATE_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_GATE_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_GATE_OPEN, 0);
