    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);
        if (rc < 0) {
            log_event("Error: I2C read failure");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (rc == 1) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_MM) {
            gpioWrite(GPIO_GATE_OPEN, 1);
            gpioWrite(GPIO_GATE_CLOSE, 0);
            log_event("Gate opened");
        } else {
            gpioWrite(GPIO_GATE_OPEN, 0);
            gpioWrite(GPIO_GATE_CLOSE, 1);
            log_event("Gate closed");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

