#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_START            0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_SOFT_RESET_VALUE            0x00
#define VL53L1X_SOFT_RESET_DELAY_US         1000
#define VL53L1X_START_MEASUREMENT_VALUE     0x01
#define VL53L1X_DATA_READY_BIT             0x01
#define VL53L1X_MAX_RETRIES                5
#define VL53L1X_RETRY_DELAY_US             10000

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_distance_ready = 0;
static volatile int g_distance = -1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
}

static void motor_forward(void) {
    motor_stop();
    gpioWrite(MOTOR_FORWARD, 1);
}

static void motor_backward(void) {
    motor_stop();
    gpioWrite(MOTOR_BACKWARD, 1);
}

static void trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        g_distance_ready = 1;
    }
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(VL53L1X_SOFT_RESET_DELAY_US);

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_START, VL53L1X_START_MEASUREMENT_VALUE) != 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t status_buf[1];
    uint8_t dist_buf[2];
    int retries = 0;
    int delay = 1000;

    while (retries < VL53L1X_MAX_RETRIES) {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) != 0) {
            fprintf(stderr, "Error: Failed to read range status (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(delay);
            delay *= 2;
            continue;
        }

        if ((status_buf[0] & VL53L1X_DATA_READY_BIT) == 0) {
            gpioDelay(1000);
            continue;
        }

        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
            fprintf(stderr, "Error: Failed to read distance (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(delay);
            delay *= 2;
            continue;
        }

        *distance = (dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries.\n", VL53L1X_MAX_RETRIES);
    return -1;
}

static void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        motor_backward();
    } else {
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(MOTOR_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(TRIGGER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    motor_stop();

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed. Sensor may be absent or bus error.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (g_distance_ready) {
            int distance;
            if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
                g_distance = distance;
                printf("Distance: %d mm\n", distance);
                control_motor(distance);
            } else {
                fprintf(stderr, "Error: Failed to read distance.\n");
                motor_stop();
            }
            g_distance_ready = 0;
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

