/*
 * Proximity-based interactive art installation — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (GPIO 2/SDA, GPIO 3/SCL)
 *   - 4 LEDs on GPIO 17, 18, 27, 22 (BCM numbering)
 *
 * Behaviour:
 *   Polls the MPR121 every 50 ms, drives a 4-bit LED pattern when any
 *   electrode detects proximity, and logs every proximity event to
 *   stdout with a timestamp.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o proximity_art proximity_art.c -lpigpio -lrt
 * Run:
 *   sudo ./proximity_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x5E          /* MPR121 default I2C address */

#define LED_PIN_0        17            /* BCM 17 */
#define LED_PIN_1        18            /* BCM 18 */
#define LED_PIN_2        27            /* BCM 27 */
#define LED_PIN_3        22            /* BCM 22 */

#define POLL_DELAY_US    50000         /* 50 ms */
#define RESET_DELAY_US   100000        /* 100 ms after soft reset */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CFG  0x5E
#define MPR121_SOFTRESET      0x80

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_log_fd   = -1;
static int  g_led_pins[4] = {LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3};

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_byte(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_byte(int fd, uint8_t reg, uint8_t *val);
static int  mpr121_init(int fd);
static int  mpr121_read_touch(int fd, uint16_t *touch_status);
static void set_led_pattern(int pattern);
static void log_event(const char *msg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 driver ----------------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset: write 0x63 to register 0x80 */
    if (i2c_write_byte(fd, MPR121_SOFTRESET, 0x63) != 0)
        return -1;
    gpioDelay(RESET_DELAY_US);

    /* Verify sensor presence by reading back the soft-reset register */
    uint8_t reset_val = 0;
    if (i2c_read_byte(fd, MPR121_SOFTRESET, &reset_val) != 0)
        return -1;
    if (reset_val != 0x63) {
        fprintf(stderr, "MPR121 soft-reset verification failed (got 0x%02X, expected 0x63)\n",
                reset_val);
        return -1;
    }

    /* Configure electrode charge/discharge parameters (simplified defaults) */
    if (i2c_write_byte(fd, 0x5C, 0x01) != 0) return -1;  /* FFI=000, CDC=0x01 */
    if (i2c_write_byte(fd, 0x5D, 0x01) != 0) return -1;  /* CDT=0x01 */
    if (i2c_write_byte(fd, 0x5E, 0x0C) != 0) return -1;  /* ELE_CFG: 12 electrodes, baseline tracking */

    return 0;
}

static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_L, &lo) != 0)
        return -1;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_H, &hi) != 0)
        return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ----------------------------- LED control ------------------------------- */
static void set_led_pattern(int pattern)
{
    gpioWrite(g_led_pins[0], (pattern >> 0) & 1);
    gpioWrite(g_led_pins[1], (pattern >> 1) & 1);
    gpioWrite(g_led_pins[2], (pattern >> 2) & 1);
    gpioWrite(g_led_pins[3], (pattern >> 3) & 1);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (g_log_fd < 0)
        return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    dprintf(g_log_fd, "[%s] %s\n", ts, msg);
    fflush(g_log_fd);
}

/* ----------------------------- Signal / cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    for (int i = 0; i < 4; i++)
        gpioWrite(g_led_pins[i], 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fd >= 0) {
        close(g_log_fd);
        g_log_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(g_led_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", g_led_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(g_led_pins[i], 0);
    }

    /* --- I2C open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- MPR121 init --- */
    if (mpr121_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fd = open("proximity_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (g_log_fd < 0) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity art installation started. Press Ctrl+C to exit.\n");
    log_event("Installation started");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(g_i2c_fd, &touch_status) != 0) {
            log_event("Error reading touch status");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status != 0) {
            int pattern = 0;
            if (touch_status & 0x0001) pattern |= 0x01;  /* ELE0 */
            if (touch_status & 0x0002) pattern |= 0x02;  /* ELE1 */
            if (touch_status & 0x0004) pattern |= 0x04;  /* ELE2 */
            if (touch_status & 0x0008) pattern |= 0x08;  /* ELE3 */
            if (touch_status & 0x0010) pattern |= 0x10;  /* ELE4 */
            if (touch_status & 0x0020) pattern |= 0x20;  /* ELE5 */
            if (touch_status & 0x0040) pattern |= 0x40;  /* ELE6 */
            if (touch_status & 0x0080) pattern |= 0x80;  /* ELE7 */
            if (touch_status & 0x0100) pattern |= 0x01;  /* ELE8 */
            if (touch_status & 0x0200) pattern |= 0x02;  /* ELE9 */
            if (touch_status & 0x0400) pattern |= 0x04;  /* ELE10 */
            if (touch_status & 0x0800) pattern |= 0x08;  /* ELE11 */

            set_led_pattern(pattern);
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Proximity detected (0x%04X) -> LED pattern 0x%02X",
                     touch_status, pattern);
            log_event(msg);
            printf("%s\n", msg);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    log_event("Installation stopped");
    cleanup();
    return EXIT_SUCCESS;
}

