    if (mpr121_write_reg(handle, MPR121_FDL_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x01) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + (i * 2), 0x0C) < 0) return -1;
        if (mpr121_write_reg(handle, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* AFE: FFI=10 samples, CDT=0.5 us, SFI=4 samples, CDC=16 uA */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* ECR: 12 electrodes enabled, baseline tracking, baseline tracking enabled */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

/*
 * Read the 16-bit touch status register (0x00-0x01).
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_read_touch(int handle, uint16_t *touch_status)
{
    uint8_t lo = 0, hi = 0;

    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *touch_status = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */

static void log_proximity_event(void)
{
    FILE *fp = fopen(PROXIMITY_LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" PROXIMITY_LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Proximity event detected\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    } else {
        fprintf(fp, "[timestamp error] - Proximity event detected\n");
    }
    fclose(fp);
}

/* ----------------------------- Signal / cleanup --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to MPR121 */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detector running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch(g_i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "[WARN] Touch read failed; retrying next cycle\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Check if any electrode is touched (bit 0 = electrode 0) */
        if (touch_status & 0x0001) {
            printf("[PROXIMITY] Electrode 0 touched\n");
            log_proximity_event();

            /* Turn LED on for one second */
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

