#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define SAMPLE_PERIOD_US  1000000
#define MIN_PULSE_US      58
#define MAX_PULSE_US      25000
#define LOG_FILE_NAME     "distance_log.txt"

static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile bool     g_pulse_ready = false;
static volatile bool     g_running     = true;

static FILE *g_log_file = NULL;

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_pulse_start = tick;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_pulse_ready = true;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioSetISRFuncEx(TRIGGER_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioSetISRFuncEx(TRIGGER_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on TRIGGER_PIN %d.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE_NAME);
        gpioSetISRFuncEx(TRIGGER_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler.\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        g_pulse_ready = false;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
            break;
        }

        if (!g_pulse_ready) {
            fprintf(stderr, "Error: echo pulse not received within timeout.\n");
            continue;
        }

        uint32_t pulse_width = g_pulse_end - g_pulse_start;

        if (pulse_width == 0 || pulse_width < MIN_PULSE_US || pulse_width > MAX_PULSE_US) {
            fprintf(stderr, "Error: invalid pulse width %u us (out of range).\n", pulse_width);
            continue;
        }

        double distance_m = (double)pulse_width / 2.0 / 1000000.0;

        time_t now = time(NULL);
        struct tm tm_info;
        if (localtime_r(&now, &tm_info) == NULL) {
            fprintf(stderr, "Error: localtime_r failed.\n");
            continue;
        }

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        if (fprintf(g_log_file, "%s, %.2f m\n", timestamp, distance_m) < 0) {
            fprintf(stderr, "Error: failed to write to log file.\n");
            break;
        }
        fflush(g_log_file);

        printf("%s, %.2f m\n", timestamp, distance_m);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

