            continue;
        }

        double distance_m = (double)pulse_width / 2.0 / 1000000.0;

        time_t now = time(NULL);
        struct tm tm_info;
        if (localtime_r(&now, &tm_info) == NULL) {
            fprintf(stderr, "Error: localtime_r failed.\n");
            continue;
        }

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        if (fprintf(g_log_file, "%s, %.2f m\n", timestamp, distance_m) < 0) {
            fprintf(stderr, "Error: failed to write to log file.\n");
            break;
        }
        fflush(g_log_file);

        printf("%s, %.2f m\n", timestamp, distance_m);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

