#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define XSHUT_PIN      27
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x000B
#define REG_SYSTEM_MODE_START   0x0000
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE     0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle)
{
    /* Soft reset: write 0x00 to SOFT_RESET register */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        syslog(LOG_ERR, "VL53L1X soft reset write failed: %s", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Start ranging: write 0x01 to SYSTEM_MODE_START */
    if (i2c_write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        syslog(LOG_ERR, "VL53L1X start ranging failed: %s", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    /* Read range status register (0x0089) */
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, status_buf, 1) < 0) {
        syslog(LOG_ERR, "Failed to read range status: %s", strerror(errno));
        return -1;
    }

    /* Check bit 0 of the status byte; 0 = data ready */
    if (status_buf[0] & 0x01) {
        syslog(LOG_ERR, "VL53L1X data not ready (status=0x%02X)", status_buf[0]);
        return -1;
    }

    /* Read 2 bytes from distance register (0x0096) */
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return -1;
    }

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure XSHUT pin as output and drive low (sensor disabled) */
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 0);
    gpioDelay(10000); /* 10 ms settle */

    /* Enable sensor by pulling XSHUT high (active-low) */
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(10000); /* 10 ms for sensor to power up */

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device on bus %d addr 0x%02X: %s",
               I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X reader started (I2C bus %d, addr 0x%02X, XSHUT pin %d)",
           I2C_BUS, VL53L1X_ADDR, XSHUT_PIN);

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            syslog(LOG_INFO, "Distance: %u mm", distance);
        } else {
            syslog(LOG_ERR, "Read failed; continuing");
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

