#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_file);
    }
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        log_message("Error: Failed to write soft reset register.");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        log_message("Error: Failed to release soft reset.");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        log_message("Error: Failed to stop ranging.");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        log_message("Error: Failed to read range status.");
        return -1;
    }
    if (status & 0x01) {
        log_message("Error: Range measurement not ready.");
        return -1;
    }
    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        log_message("Error: Failed to read distance register.");
        return -1;
    }
    uint16_t distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    *distance_cm = (float)distance_mm / 10.0f;
    return 0;
}

static void control_gate(int gpio_pin, float distance_cm) {
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        if (!gate_open) {
            if (gpioWrite(gpio_pin, 1) == 0) {
                gate_open = 1;
                log_message("Gate opened.");
            } else {
                log_message("Error: Failed to set gate GPIO high.");
            }
        }
    } else {
        if (gate_open) {
            if (gpioWrite(gpio_pin, 0) == 0) {
                gate_open = 0;
                log_message("Gate closed.");
            } else {
                log_message("Error: Failed to set gate GPIO low.");
            }
        }
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_message("Program terminated.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        log_message("Error: Failed to open I2C bus.");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_message("Error: VL53L1X initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GATE_GPIO);
        log_message("Error: Failed to set gate GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    while (g_running) {
        float distance_cm = 0.0f;
        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_message(msg);
            control_gate(GATE_GPIO, distance_cm);
        } else {
            log_message("Error: Failed to read distance.");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

