        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        log_message("Error: Failed to open I2C bus.");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_message("Error: VL53L1X initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GATE_GPIO);
        log_message("Error: Failed to set gate GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
