    gpioWrite(GATE_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started.");

    while (g_running) {
        float distance_cm = 0.0f;
        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_message(msg);
            control_gate(GATE_GPIO, distance_cm);
        } else {
            log_message("Error: Failed to read distance.");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

