#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define ECHO_TIMEOUT_US 30000
#define SAMPLE_COUNT 5
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t program_running = 1;
static volatile uint32_t pulse_width = 0;
static volatile bool new_pulse = false;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    static uint32_t start_tick = 0;
    static bool echo_rising = false;

    if (level == 1) {
        start_tick = tick;
        echo_rising = true;
    } else if (level == 0 && echo_rising) {
        uint32_t diff = tick - start_tick;
        if (diff > 0 && diff < ECHO_TIMEOUT_US) {
            pulse_width = diff;
            new_pulse = true;
        }
        echo_rising = false;
    }
}

static float calculate_average_distance(void) {
    static float buffer[SAMPLE_COUNT] = {0.0f};
    static int index = 0;
    static int count = 0;
    float sum = 0.0f;
    int i;

    for (i = 0; i < SAMPLE_COUNT; i++) {
        sum += buffer[i];
    }
    if (count > 0) {
        return sum / (float)count;
    }
    return 0.0f;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d (must be 0-180)\n", angle);
        return -1;
    }
    if (gpioServo(SERVO_PIN, angle * 1000) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(fp);
}

int main(void) {
    FILE *fp = NULL;
    int ret = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set echo pin pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set echo alert function\n");
        gpioTerminate();
        return 1;
    }

    if (gpioServo(SERVO_PIN, 90000) < 0) {
        fprintf(stderr, "Error: Failed to initialize servo to 90 degrees\n");
        gpioTerminate();
        return 1;
    }

    fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open distance_log.csv for writing\n");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Distance (cm),Servo Angle (deg)\n");
        fflush(fp);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        fclose(fp);
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        pulse_width = 0;
        new_pulse = false;

        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error: Failed to set trigger high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to set trigger low\n");
            break;
        }

        if (new_pulse) {
            float distance = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: Distance out of range (%.2f cm). Setting servo to 90 degrees.\n", distance);
                distance = -1.0f;
                set_servo_angle(90);
            } else {
                set_servo_angle((int)(distance / 2.0f));
            }

            float avg = calculate_average_distance();
            buffer[index] = avg;
            index = (index + 1) % SAMPLE_COUNT;
            if (count < SAMPLE_COUNT) {
                count++;
            }

            log_data(fp, distance, 90);
        } else {
            fprintf(stderr, "Warning: No echo received. Setting servo to 90 degrees.\n");
            set_servo_angle(90);
            log_data(fp, -1.0f, 90);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nCleaning up...\n");
    set_servo_angle(0);
    gpioDelay(1000000);
    gpioServo(SERVO_PIN, 0);

    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return ret;
}

