#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LED_PIN        17
#define BUFFER_SIZE    10
#define THRESHOLD_MM   200
#define POLL_DELAY_US  50000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_SYSTEM_START            0x0000
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0014
#define REG_SYSTEM_INTERRUPT_CONFIG 0x0011
#define REG_SYSTEM_CONFIG           0x0010
#define REG_RANGE_CONFIG_A          0x001A
#define REG_RANGE_CONFIG_B          0x001B
#define REG_RANGE_CONFIG_C          0x001C
#define REG_RANGE_CONFIG_D          0x001D
#define REG_RANGE_CONFIG_E          0x001E
#define REG_RANGE_CONFIG_F          0x001F
#define REG_RANGE_CONFIG_G          0x0020
#define REG_RANGE_CONFIG_H          0x0021
#define REG_RANGE_CONFIG_I          0x0022
#define REG_RANGE_CONFIG_J          0x0023
#define REG_RANGE_CONFIG_K          0x0024
#define REG_RANGE_CONFIG_L          0x0025
#define REG_RANGE_CONFIG_M          0x0026
#define REG_RANGE_CONFIG_N          0x0027
#define REG_RANGE_CONFIG_O          0x0028
#define REG_RANGE_CONFIG_P          0x0029
#define REG_RANGE_CONFIG_Q          0x002A
#define REG_RANGE_CONFIG_R          0x002B
#define REG_RANGE_CONFIG_S          0x002C
#define REG_RANGE_CONFIG_T          0x002D
#define REG_RANGE_CONFIG_U          0x002E
#define REG_RANGE_CONFIG_V          0x002F
#define REG_RANGE_CONFIG_W          0x0030
#define REG_RANGE_CONFIG_X          0x0031
#define REG_RANGE_CONFIG_Y          0x0032
#define REG_RANGE_CONFIG_Z          0x0033
#define REG_RESULT_RANGE_STATUS     0x0014
#define REG_RESULT_FINAL_MM         0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    /* Set default configuration registers */
    uint8_t cfg[32] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };
    for (int i = 0; i < 32; i++) {
        if (i2c_write_reg16(handle, (uint16_t)(0x0010 + i), cfg[i]) < 0) return -1;
    }

    /* Enable signal rate checking */
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG_A, 0x01) < 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status;
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* data not ready */

    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_FINAL_MM, buf, 2) < 0) return -1;
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, REG_SYSTEM_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t buffer[BUFFER_SIZE];
    int head = 0;
    int count = 0;

    while (g_running) {
        uint16_t distance;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            buffer[head] = distance;
            head = (head + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            if (distance < THRESHOLD_MM) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

