    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    /* Set default configuration registers */
    uint8_t cfg[32] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };
    for (int i = 0; i < 32; i++) {
        if (i2c_write_reg16(handle, (uint16_t)(0x0010 + i), cfg[i]) < 0) return -1;
    }

    /* Enable signal rate checking */
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG_A, 0x01) < 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status;
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* data not ready */

    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_FINAL_MM, buf, 2) < 0) return -1;
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2c_write_reg16(g_i2c_handle, REG_SYSTEM_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t buffer[BUFFER_SIZE];
    int head = 0;
    int count = 0;

    while (g_running) {
        uint16_t distance;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            buffer[head] = distance;
            head = (head + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            if (distance < THRESHOLD_MM) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

