/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a 50% duty-cycle
 * PWM speaker on GPIO18 (BCM) on a Raspberry Pi Zero W.
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23          /* HC-SR04 trigger  */
#define ECHO_PIN     24          /* HC-SR04 echo     */
#define PWM_PIN      18          /* 50% duty-cycle speaker */

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_S  34300.0   /* cm/s at 20 °C */
#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      200.0
#define MIN_FREQUENCY_HZ     200.0
#define MAX_FREQUENCY_HZ     2000.0
#define PWM_RANGE            1000     /* 0–1000 duty steps */
#define PWM_DUTY_50          500      /* 50% duty cycle */
#define ECHO_TIMEOUT_US      200000   /* 200 ms */
#define TRIGGER_PULSE_US     10
#define SAMPLE_PERIOD_US     20000    /* 20 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_last_tick = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0 on timeout / error.                */
static float read_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (!g_running) return -1.0f;
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (!g_running) return -1.0f;
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t elapsed = end_tick - start_tick;
    if (elapsed == 0) {
        fprintf(stderr, "Error: zero echo pulse width\n");
        return -1.0f;
    }

    /* distance = (elapsed_us * speed_cm_s) / 2 */
    return (float)elapsed * SPEED_OF_SOUND_CM_S / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Returns frequency in Hz, or -1.0 on out-of-range distance.          */
static float calculate_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }
    return MIN_FREQUENCY_HZ +
           (distance - MIN_DISTANCE_CM) *
           (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
           (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

/* ------------------------------------------------------------------ */
/* Returns duty-cycle steps (0–PWM_RANGE) for a given frequency.       */
static int calculate_duty(float frequency)
{
    if (frequency < MIN_FREQUENCY_HZ) frequency = MIN_FREQUENCY_HZ;
    if (frequency > MAX_FREQUENCY_HZ) frequency = MAX_FREQUENCY_HZ;

    /* Logarithmic mapping: lower frequencies have higher duty. */
    float normalized = (frequency - MIN_FREQUENCY_HZ) /
                       (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);
    float duty_float = MIN_FREQUENCY_HZ +
                       normalized * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);
    int duty = (int)(duty_float / (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) *
                     PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

/* ------------------------------------------------------------------ */
static void set_speaker_frequency(float frequency)
{
    int duty = calculate_duty(frequency);
    if (gpioPWM(PWM_PIN, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM first, then release pigpio. */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM range and start at 0 */
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Theremin ready.  Trigger=GPIO%d, Echo=GPIO%d, PWM=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, PWM_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            /* Error or timeout: keep previous frequency. */
            set_speaker_frequency(g_last_tick == 0 ? 440.0f : g_last_tick);
        } else {
            float freq = calculate_frequency(distance);
            if (freq < 0.0f) {
                /* Out of range: keep previous frequency. */
                set_speaker_frequency(g_last_tick == 0 ? 440.0f : g_last_tick);
            } else {
                set_speaker_frequency(freq);
                g_last_tick = (uint32_t)freq;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

