#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  5.0f
#define MAX_DISTANCE_CM  50.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

#define ECHO_TIMEOUT_US  100000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin %d\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    gpioDelay(5);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static long measure_echo_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    int level;

    /* Wait for echo rising edge */
    while (running) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) return -1;
        if (level == 1) {
            start_tick = gpioTick();
            break;
        }
        gpioDelay(1);
    }
    if (!running) return -1;

    /* Wait for echo falling edge */
    while (running) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) return -1;
        if (level == 0) {
            end_tick = gpioTick();
            break;
        }
        gpioDelay(1);
    }
    if (!running) return -1;

    if (start_tick == 0 || end_tick == 0) return -1;
    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_us) {
    if (pulse_us <= 0) return -1.0f;
    /* Speed of sound ~343 m/s => 0.0343 cm/µs; round trip => /2 */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static float map_distance_to_frequency(float distance_cm) {
    if (distance_cm < 0.0f) return 0.0f;
    if (distance_cm <= MIN_DISTANCE_CM) return MAX_FREQUENCY_HZ;
    if (distance_cm >= MAX_DISTANCE_CM) return MIN_FREQUENCY_HZ;
    return MAX_FREQUENCY_HZ - ((distance_cm - MIN_DISTANCE_CM) /
                               (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                               (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));
}

static int set_buzzer_frequency(float frequency_hz) {
    if (frequency_hz <= 0.0f) {
        if (gpioPWM(BUZZER_PIN, 0) < 0) return -1;
        return 0;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency_hz) < 0) return -1;
    if (gpioPWM(BUZZER_PIN, 128) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
