#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  5.0f
#define MAX_DISTANCE_CM  50.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

#define ECHO_TIMEOUT_US  100000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin %d\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    gpioDelay(5);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static long measure_echo_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    int level;

    /* Wait for echo rising edge */
    while (running) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) return -1;
        if (level == 1) {
            start_tick = gpioTick();
            break;
        }
        gpioDelay(1);
    }
    if (!running) return -1;

    /* Wait for echo falling edge */
    while (running) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) return -1;
        if (level == 0) {
            end_tick = gpioTick();
            break;
        }
        gpioDelay(1);
    }
    if (!running) return -1;

    if (start_tick == 0 || end_tick == 0) return -1;
    return (long)(end_tick - start_tick);
