#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms timeout for echo pulse */
#define LOOP_DELAY  500000  /* 500 ms between measurements */
#define MIN_DISTANCE 2.0f
#define MAX_DISTANCE 400.0f
#define TOO_CLOSE_THRESHOLD 10.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Measure the duration of the echo pulse in microseconds.
 * Returns the duration on success, or -1 on timeout.
 */
static int measure_echo(int trigger_pin, int echo_pin)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin low\n");
        return -1;
    }
    gpioDelay(5); /* settle */

    /* 10 us trigger pulse */
    if (gpioWrite(trigger_pin, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin high\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin low\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(echo_pin) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo pin timeout waiting for rising edge\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(echo_pin) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo pin timeout waiting for falling edge\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (int)(end_tick - start_tick);
}

static float calculate_distance(int pulse_duration_us)
{
    /* Speed of sound ~343 m/s => 0.0343 cm/us; round trip => divide by 2 */
    return (float)pulse_duration_us * 0.0343f / 2.0f;
}

int main(void)
{
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initially low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pulse_duration = measure_echo(TRIGGER_PIN, ECHO_PIN);

        if (pulse_duration < 0) {
            fprintf(stderr, "Error: echo measurement failed\n");
        } else {
            float distance = calculate_distance(pulse_duration);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading: %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < TOO_CLOSE_THRESHOLD) {
                    printf("Too close!\n");
                }
            }
        }

        /* Wait before next measurement (interruptible by signal) */
        for (int i = 0; i < 10 && program_running; i++) {
            gpioDelay(50000); /* 50 ms slices */
        }
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

