#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define CS_PIN      8
#define LOG_FILE    "distance_log.csv"
#define SAMPLE_US   100000
#define MAX_DISTANCE_MM 5000
#define MIN_DISTANCE_MM  200

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_mm)
{
    /*
     * Placeholder for the ICU-20201 SPI read sequence.
     * Replace the dummy byte sequence below with the actual
     * 16-bit big-endian distance read from the sensor.
     */
    char tx[2] = { 0x01, 0x02 };
    char rx[2] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 2).\n", ret);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

static int log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed on log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(CS_PIN) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(CS_PIN, 1);

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# ICU-20201 distance log started\n");
    fprintf(g_log_file, "# timestamp,distance_mm\n");
    fflush(g_log_file);

    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Warning: SPI read failed; skipping sample.\n");
        } else if (distance < MIN_DISTANCE_MM || distance > MAX_DISTANCE_MM) {
            fprintf(stderr, "Warning: distance out of range (%u mm); skipping.\n", distance);
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

