    fprintf(g_log_file, "# timestamp,distance_mm\n");
    fflush(g_log_file);

    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Warning: SPI read failed; skipping sample.\n");
        } else if (distance < MIN_DISTANCE_MM || distance > MAX_DISTANCE_MM) {
            fprintf(stderr, "Warning: distance out of range (%u mm); skipping.\n", distance);
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

