#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR             0x60
#define SI1120_REG_PART_ID      0x00
#define SI1120_REG_HW_KEY       0x07
#define SI1120_REG_COMMAND      0x08
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_PS1_DATA0    0x24
#define SI1120_CMD_RESET        0x01
#define SI1120_CMD_ALS_FORCE    0x06
#define SI1120_CMD_PS_FORCE     0x05
#define SI1120_PART_ID_EXPECTED 0x20
#define I2C_BUS                 1
#define SAMPLE_INTERVAL_US      500000
#define MAX_RETRIES             3
#define RETRY_DELAY_US          10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByteData(handle, reg, value) == 0)
            return 0;
        fprintf(stderr, "I2C write attempt %d failed (reg=0x%02X, val=0x%02X): %s\n",
                attempt + 1, reg, value, pigpio_error(i2cWriteByteData(handle, reg, value)));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_retry(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (reg=0x%02X): %s\n",
                attempt + 1, reg, pigpio_error(result));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int si1120_init(int handle)
{
    uint8_t part_id = 0;

    if (i2c_write_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_retry(handle, SI1120_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (i2c_read_retry(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }

    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }

    printf("Si1120 initialized (PART_ID=0x%02X)\n", part_id);
    return 0;
}

static int si1120_read_data(int handle, uint16_t *ambient_light, uint16_t *proximity)
{
    uint8_t als_vis_lo = 0, als_vis_hi = 0, ps1_lo = 0, ps1_hi = 0;

    if (i2c_write_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger ALS force\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_read_retry(handle, SI1120_REG_ALS_VIS_DATA0, &als_vis_lo) != 0) return -1;
    if (i2c_read_retry(handle, SI1120_REG_ALS_VIS_DATA0 + 1, &als_vis_hi) != 0) return -1;

    if (i2c_write_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger PS force\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_read_retry(handle, SI1120_REG_PS1_DATA0, &ps1_lo) != 0) return -1;
    if (i2c_read_retry(handle, SI1120_REG_PS1_DATA0 + 1, &ps1_hi) != 0) return -1;

    *ambient_light = (uint16_t)((als_vis_hi << 8) | als_vis_lo);
    *proximity     = (uint16_t)((ps1_hi << 8) | ps1_lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI1120_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1120_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging Si1120 data to si1120_log.txt. Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;

        if (si1120_read_data(g_i2c_handle, &ambient_light, &proximity) == 0) {
            log_data(g_log_file, ambient_light, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

