#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_DELAY   100000   /* microseconds (100 ms) */

/* Si1182 register addresses (verified against datasheet) */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0   0x24
#define REG_PS1_DATA1   0x25

#define EXPECTED_PART_ID 0x82
#define HW_KEY_VALUE     0x17
#define MEAS_RATE_VAL    0x0A   /* 100 ms measurement rate */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    uint8_t part_id = 0;

    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) — wrong sensor?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID = 0x%02X)\n", part_id);

    if (i2c_write_reg8(fd, REG_HW_KEY, HW_KEY_VALUE) != 0)
        return -1;

    if (i2c_write_reg8(fd, REG_MEAS_RATE, MEAS_RATE_VAL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                   */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *lux, uint16_t *prox)
{
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, lux) != 0)
        return -1;
    if (i2c_read_reg16(fd, REG_PS1_DATA0, prox) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t lux, uint16_t prox)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%u,%u\n", timestamp, lux, prox);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s every 100 ms. Press Ctrl-C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t lux = 0, prox = 0;

        if (read_sensor_data(g_i2c_fd, &lux, &prox) == 0) {
            log_data(g_log_fp, lux, prox);
            printf("%s lux=%u prox=%u\n",
                   "data", lux, prox);
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        usleep(SAMPLE_DELAY);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

