#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM          200.0
#define MIN_DISTANCE_CM          20.0
#define SERVO_MIN_PULSE_US       500
#define SERVO_MAX_PULSE_US       2500
#define SERVO_MID_ANGLE          90
#define SERVO_MIN_ANGLE          0
#define SERVO_MAX_ANGLE          180
#define ECHO_TIMEOUT_US          30000
#define LOOP_DELAY_US            100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    timeout_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    double distance = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    int pulse_us = SERVO_MIN_PULSE_US +
                   (int)((double)(angle - SERVO_MIN_ANGLE) *
                         (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
                         (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor read failed or out of range.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = SERVO_MID_ANGLE +
                    (int)((distance - MAX_DISTANCE_CM) *
                          (SERVO_MIN_ANGLE - SERVO_MID_ANGLE) /
                          (MAX_DISTANCE_CM - MIN_DISTANCE_CM));

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: failed to set servo angle.\n");
        }

        printf("Distance: %.2f cm, Servo Angle: %d°\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Stop servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

