#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE        0
#define MAX_ANGLE        180
#define MIN_PULSE_US     500
#define MAX_PULSE_US     2500
#define TIMEOUT_US       50000
#define CYCLE_DELAY_US   100000
#define TRIGGER_PULSE_US 10
#define INVALID_DISTANCE -1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin state.\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static float measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return INVALID_DISTANCE;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return INVALID_DISTANCE;
    }

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo start.\n");
            return INVALID_DISTANCE;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo end.\n");
            return INVALID_DISTANCE;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 58.0f;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d].\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = MIN_PULSE_US + (int)((float)angle / (float)MAX_ANGLE * (float)(MAX_PULSE_US - MIN_PULSE_US));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d.\n", angle);
        return -1;
    }
    return 0;
}

static int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    float angle = (distance - MIN_DISTANCE_CM) * (float)(MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_ANGLE;
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return (int)angle;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        float distance = measure_distance();
        if (distance == INVALID_DISTANCE) {
            fprintf(stderr, "Warning: invalid distance, skipping cycle.\n");
            gpioDelay(CYCLE_DELAY_US);
            continue;
        }
        int angle = map_distance_to_angle(distance);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Warning: failed to set servo angle.\n");
        }
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        gpioDelay(CYCLE_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

