#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x00
#define SI7005_REG_HUM  0x01
#define SI7005_REG_CONFIG 0x08
#define SI7005_CONFIG_RESET 0x80
#define SI7005_CONFIG_POWER_ON 0x03

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si7005_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si7005_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int si7005_init(int handle) {
    if (si7005_write_reg(handle, SI7005_REG_CONFIG, SI7005_CONFIG_RESET) != 0) {
        fprintf(stderr, "Error resetting sensor.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    if (si7005_write_reg(handle, SI7005_REG_CONFIG, SI7005_CONFIG_POWER_ON) != 0) {
        fprintf(stderr, "Error powering on sensor.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int read_sensor(int handle, float *temperature, float *humidity) {
    uint8_t temp_raw, hum_raw;

    if (si7005_write_reg(handle, SI7005_REG_CONFIG, SI7005_CONFIG_POWER_ON) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (si7005_read_reg(handle, SI7005_REG_TEMP, &temp_raw) != 0) {
        return -1;
    }
    if (si7005_read_reg(handle, SI7005_REG_HUM, &hum_raw) != 0) {
        return -1;
    }

    uint16_t temp_raw_val = (uint16_t)temp_raw;
    uint16_t hum_raw_val = (uint16_t)hum_raw;

    *temperature = -46.85 + (175.72 * (float)temp_raw_val / 65536.0);
    *humidity = -6.0 + (125.0 * (float)hum_raw_val / 65536.0);

    if (*humidity > 100.0) *humidity = 100.0;
    if (*humidity < 0.0) *humidity = 0.0;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (si7005_init(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    while (running) {
        if (read_sensor(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* 1 second delay before retry */
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                break;
            }
            if (si7005_init(i2c_handle) != 0) {
                fprintf(stderr, "Sensor re-initialization failed.\n");
                break;
            }
        }
        sleep(2);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

