#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define WHO_AM_I       0x75
#define WHO_AM_I_VAL   0x68
#define PWR_MGMT_1     0x6B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43
#define TEMP_OUT_H     0x41
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 register.\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */
    return 0;
}

static int mpu6050_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: failed to read 14-byte data block.\n");
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int who = i2cReadByteData(g_i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register.\n");
        goto cleanup;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, WHO_AM_I_VAL);
        goto cleanup;
    }

    if (mpu6050_init(g_i2c_handle) < 0) {
        goto cleanup;
    }

    printf("MPU-6050 initialized. Logging data every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d  Temp: %d\n",
                   ax, ay, az, gx, gy, gz, 0);
        } else {
            fprintf(stderr, "Warning: read failed, continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

