#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_I2C_ADDR 0x50
#define LOG_FILE "pressure_log.csv"
#define MEASUREMENT_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 2000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d).\n",
                SDP810_I2C_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int configure_sensor(void) {
    /*
     * SDP810-125Pa continuous measurement configuration (Command Set 0x36):
     *   0x36 0x08 0x00 0x00 0x00 0x00 0x00 0x00
     *   0x08 = continuous measurement mode, no averaging, no reset
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     *   0x00 = no clock stretching
     */
    uint8_t config_cmd[8] = {0x36, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)config_cmd, 8);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to configure sensor (pigpio error %d).\n", result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t read_cmd[2] = {0x36, 0x00};
    uint8_t data[9];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)read_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send measurement command (pigpio error %d).\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor (got %d bytes, pigpio error %d).\n",
                result, result);
        return -1;
    }

    /* CRC validation for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }

    /* CRC validation for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    /* CRC validation for scale factor (bytes 6-7, CRC at byte 8) */
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

static int log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Failed to close log file '%s'.\n", LOG_FILE);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int is_new_file = (fp == NULL);
    if (fp != NULL) {
        fclose(fp);
    }

    printf("SDP810-125Pa differential pressure sensor logging started.\n");
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float pressure, temperature;

        if (read_sensor_data(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed. Retrying in 1 second.\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

