#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x50
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, SDP31_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sdp31(float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[6];
    int retries = 0;
    int delay_us = 1000;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        uint8_t crc_p = (uint8_t)(0x03 - (buf[0] + buf[1]));
        uint8_t crc_t = (uint8_t)(0x03 - (buf[3] + buf[4]));
        if (crc_p != buf[2] || crc_t != buf[5]) {
            fprintf(stderr, "CRC mismatch (p=0x%02X lsb=0x%02X crc=0x%02X, t=0x%02X lsb=0x%02X crc=0x%02X)\n",
                    buf[0], buf[1], crc_p, buf[3], buf[4], crc_t);
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure = (float)raw_pressure / 100.0f;
        *temperature = (float)raw_temperature / 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SDP31 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    float pressure, temperature;

    while (running) {
        if (read_sdp31(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing to retry...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

