#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 27.0f
#define BUFFER_SIZE    60
#define POLL_INTERVAL  2
#define RETRY_COUNT    3
#define RETRY_DELAY_US 100000
#define FAN_ON_DELAY_US 10000
#define FAN_OFF_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

static TemperatureReading g_buffer[BUFFER_SIZE];
static int g_head = 0;
static int g_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void buffer_add(float temp) {
    time_t now = time(NULL);
    g_buffer[g_head].temperature = temp;
    g_buffer[g_head].timestamp = now;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE) g_count++;
}

static void buffer_print(void) {
    int start = (g_count == BUFFER_SIZE) ? g_head : 0;
    for (int i = 0; i < g_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&g_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("  [%s] Temp: %.2f C\n", ts, g_buffer[idx].temperature);
        }
