#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_INTERVAL_SEC 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_READ_MEASUREMENT           0xEC05
#define CMD_GET_DATA_READY             0x2002

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int write_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t *buf, int len) {
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != len) {
        fprintf(stderr, "Error: i2cReadDevice returned %d, expected %d\n", bytes, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, uint16_t *co2, float *temp, float *rh) {
    if (write_command(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;

    time_sleep(0.01);

    uint8_t buf[9];
    if (read_block(handle, buf, 9) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    *co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    int16_t t_raw = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t h_raw = (int16_t)((buf[6] << 8) | buf[7]);
    *temp = t_raw / 100.0f;
    *rh = h_raw / 100.0f;
    return 0;
}

static int data_ready(int handle) {
    if (write_command(handle, CMD_GET_DATA_READY) != 0)
        return -1;

    time_sleep(0.01);

    uint8_t buf[3];
    if (read_block(handle, buf, 3) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Data-ready CRC mismatch\n");
        return -1;
    }

    uint16_t val = (uint16_t)((buf[0] << 8) | buf[1]);
    return (val & 0x07FF) ? 1 : 0;
}

static void log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(g_log_file);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        write_command(g_i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        time_sleep(0.5);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (write_command(g_i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    time_sleep(MEASUREMENT_INTERVAL_SEC);

    while (g_running) {
        int ready = data_ready(g_i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Warning: data-ready check failed, retrying in %d s\n", POLL_INTERVAL_SEC);
            time_sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (ready) {
            uint16_t co2;
            float temp, rh;
            if (read_measurement(g_i2c_handle, &co2, &temp, &rh) == 0) {
                log_data(co2, temp, rh);
                printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);
            } else {
                fprintf(stderr, "Warning: read_measurement failed\n");
            }
        }

        time_sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

