/*
 * SCD40 CO2 monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode  -> GPIO17 (1 kΩ series resistor to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c \
 *               -lpigpio -lrt -lm
 * Run:    sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_ADDR           0x61          /* SCD40 default I2C address */
#define GPIO_LED             17            /* BCM pin for CO2 warning LED */
#define CO2_THRESHOLD_PPM    1000.0f
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_S    5
#define MAX_INIT_RETRIES     3
#define MAX_READ_RETRIES     3

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC   0x21B1
#define CMD_STOP_PERIODIC    0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY   0x2002
#define CMD_SET_MEAS_RATE    0x21B5
#define MEAS_RATE_5_S        0x0005

/* ----------------------------- Data structures ---------------------------- */
typedef struct {
    uint32_t co2;          /* ppm */
    float    temperature;  /* °C  */
    float    humidity;     /* %RH */
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ----------------------------- Globals ----------------------------------- */
static int           g_i2c_handle = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static uint8_t  crc8(const uint8_t *data, int len);
static int      init_scd40(void);
static int      read_scd40(sensor_data_t *out);
static void     buffer_add(circular_buffer_t *buf, sensor_data_t d);
static void     buffer_print(circular_buffer_t *buf);
static void     signal_handler(int sig);
static void     cleanup(void);

/* ----------------------------- CRC-8 (Sensirion polynomial 0x31) ---------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- SCD40 init --------------------------------- */
static int init_scd40(void)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_SET_MEAS_RATE >> 8),
                       (uint8_t)(CMD_SET_MEAS_RATE & 0xFF) };
    uint8_t rate[2] = { (uint8_t)(MEAS_RATE_5_S >> 8),
                        (uint8_t)(MEAS_RATE_5_S & 0xFF) };

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement rate.\n");
        return -1;
    }
    if (i2cWriteDevice(g_i2c_handle, (char *)rate, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement rate (2).\n");
        return -1;
    }

    cmd[0] = (uint8_t)(CMD_START_PERIODIC >> 8);
    cmd[1] = (uint8_t)(CMD_START_PERIODIC & 0xFF);
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to start periodic measurement.\n");
        return -1;
    }

    /* Allow the first measurement to be ready */
    sleep(5);
    return 0;
}

/* ----------------------------- Read one measurement ----------------------- */
static int read_scd40(sensor_data_t *out)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_READ_MEASUREMENT >> 8),
                       (uint8_t)(CMD_READ_MEASUREMENT & 0xFF) };
    uint8_t buf[9];   /* 3 words × (2 data + 1 CRC) */

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write (read measurement) failed.\n");
        return -1;
    }

    /* Small delay so the sensor can clock out the data */
    gpioDelay(10000);  /* 10 ms */

    int n = i2cReadDevice(g_i2c_handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read returned %d bytes (expected %zu).\n",
                n, sizeof(buf));
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d.\n", i);
            return -1;
        }
    }

    uint16_t co2_raw    = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temp_raw   = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t hum_raw    = (uint16_t)((buf[6] << 8) | buf[7]);

    out->co2        = (uint32_t)co2_raw;
    out->temperature = (float)temp_raw / 100.0f;
    out->humidity   = (float)hum_raw / 100.0f;

    return 0;
}

/* ----------------------------- Circular buffer ---------------------------- */
static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(circular_buffer_t *buf)
{
    printf("\n--- Last %d readings ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] CO2: %5u ppm  T: %6.2f C  RH: %5.2f %%\n",
               i, buf->data[idx].co2,
               buf->data[idx].temperature, buf->data[idx].humidity);
    }
    fflush(stdout);
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        uint8_t cmd[2] = { (uint8_t)(CMD_STOP_PERIODIC >> 8),
                           (uint8_t)(CMD_STOP_PERIODIC & 0xFF) };
        i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SCD40 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

