                attempt + 1, MAX_INIT_RETRIES);
        sleep(1);
    }
    if (!init_ok) {
        fprintf(stderr, "[FATAL] SCD40 initialization failed after %d attempts.\n",
                MAX_INIT_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD40 monitoring started (5 s interval). Press Ctrl-C to stop.\n");
    fflush(stdout);

