        for (int s = 0; s < SAMPLE_INTERVAL_S * 10 && !g_terminate; s++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

