#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_US 50000
#define MIN_TEMP -40.0f
#define MAX_TEMP 150.0f
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

static int log_message(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        fprintf(log_file, "%s: %s\n", ts, msg);
        fflush(log_file);
        return 0;
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
    return -1;
}

static int read_pulse_widths(unsigned int *high_us, unsigned int *total_us) {
    unsigned int start_tick, end_tick;
    int ret;

    start_tick = gpioTick();
    ret = gpioRead(GPIO_PIN);
    if (ret < 0) return -1;
    if (ret == 1) {
        /* Wait for falling edge */
        while (program_running) {
            end_tick = gpioTick();
            if (end_tick - start_tick > TIMEOUT_US) return -1;
            ret = gpioRead(GPIO_PIN);
            if (ret < 0) return -1;
            if (ret == 0) break;
        }
        if (!program_running) return -1;
        *high_us = end_tick - start_tick;
        start_tick = end_tick;
    } else {
        /* Wait for rising edge */
        while (program_running) {
            end_tick = gpioTick();
            if (end_tick - start_tick > TIMEOUT_US) return -1;
            ret = gpioRead(GPIO_PIN);
            if (ret < 0) return -1;
            if (ret == 1) break;
        }
        if (!program_running) return -1;
        *high_us = end_tick - start_tick;
    }

    *total_us = gpioTick() - start_tick;
    return 0;
}

static float calculate_temperature(unsigned int high_us, unsigned int total_us) {
    if (total_us == 0) return MIN_TEMP - 100.0f;
    float ratio = (float)high_us / (float)total_us;
    return MIN_TEMP + ratio * (MAX_TEMP - MIN_TEMP);
}

int main(void) {
    unsigned int high_us, total_us;
    float temperature;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_message("Failed to set GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to register signal handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    while (program_running) {
        if (read_pulse_widths(&high_us, &total_us) == 0) {
            temperature = calculate_temperature(high_us, total_us);
            if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
                log_message("Temperature out of valid range");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
                log_message(msg);
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program exiting");
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

