    *total_us = gpioTick() - start_tick;
    return 0;
}

static float calculate_temperature(unsigned int high_us, unsigned int total_us) {
    if (total_us == 0) return MIN_TEMP - 100.0f;
    float ratio = (float)high_us / (float)total_us;
    return MIN_TEMP + ratio * (MAX_TEMP - MIN_TEMP);
}

int main(void) {
    unsigned int high_us, total_us;
    float temperature;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_message("Failed to set GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to register signal handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    while (program_running) {
        if (read_pulse_widths(&high_us, &total_us) == 0) {
            temperature = calculate_temperature(high_us, total_us);
            if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
                log_message("Temperature out of valid range");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
                log_message(msg);
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program exiting");
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

