#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_CMD_HIGH_REP 0x2400
#define LOG_FILE "environmental_data.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000
#define MEASUREMENT_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD_HIGH_REP >> 8) & 0xFF, MEASUREMENT_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void simulate_environment(float *temperature, float *humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    double offset = (sin(2.0 * M_PI * (double)now / 3600.0) + 1.0) / 2.0 * 2.0 - 1.0;
    *temperature += offset;
    *humidity += offset;
    if (*temperature < -45.0f) *temperature = -45.0f;
    if (*temperature > 125.0f) *temperature = 125.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    while (running) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_environment(&temperature, &humidity);
            log_data(log_file, temperature, humidity);
        } else {
            log_data(log_file, NAN, NAN);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

