#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x36
#define CSV_FILE       "airflow.csv"
#define CONV_TIME_MS   45
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_block: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_block: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t buf[9];

    if (i2c_write_cmd(fd, 0x361F) < 0)
        return -1;

    usleep(CONV_TIME_MS * 1000);

    if (i2c_read_block(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error: pressure\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error: scale factor\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / (float)scale;

    return 0;
}

static int log_data(const char *filename, float pressure, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    printf("SDP810-125Pa sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(CSV_FILE, pressure, temperature) < 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read error or CRC mismatch\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nShutdown complete.\n");
    return 0;
}

