/*
 * SHT35 temperature & humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3 (pin 1)
 *   SHT35 GND  -> Pi GND (pin 6)
 *   SHT35 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c
 * Run:    ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44          /* SHT35 default I2C address (ADDR pin low) */
#define SHT35_CMD_MSB  0x2C          /* Single-shot, high repeatability, clock-stretching disabled */
#define SHT35_CMD_LSB  0x06          /* Clock stretching disabled, clock stretching disabled */
#define SAMPLE_PERIOD  5             /* seconds between readings */
#define MEAS_DELAY_US  15000         /* 15 ms measurement wait (datasheet: typ 12.5 ms) */
#define CSV_FILENAME   "environment.csv"

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handling ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CSV file helpers ---- */
static int ensure_csv_header(void)
{
    FILE *fp = fopen(CSV_FILENAME, "r");
    if (fp != NULL) {
        /* File exists; check if empty */
        if (fseek(fp, 0, SEEK_END) == 0) {
            long sz = ftell(fp);
            if (sz > 0) {
                fclose(fp);
                return 0;  /* file has content, keep it */
            }
            fclose(fp);
        } else {
            fclose(fp);
        }
    }
    /* File does not exist or is empty: write header */
    fp = fopen(CSV_FILENAME, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot create CSV file '%s': %s\n",
                CSV_FILENAME, strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

static int log_data(float temp_c, float rh)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open CSV file '%s' for append: %s\n",
                CSV_FILENAME, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh) < 0) {
        fprintf(stderr, "Error: writing to CSV file failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- SHT35 read ---- */
static int sht35_read(int handle, float *temp_c, float *rh)
{
    uint8_t cmd[2] = { SHT35_CMD_MSB, SHT35_CMD_LSB };
    uint8_t data[6];

    /* Issue single-shot measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%02X 0x%02X): %s\n",
                cmd[0], cmd[1], strerror(errno));
        return -1;
    }

    /* Wait for measurement to complete (datasheet: typ 12.5 ms) */
    gpioDelay(MEAS_DELAY_US);

    /* Read 6 bytes: T_MSB T_LSB T_CRC RH_MSB RH_LSB RH_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    /* CRC validation */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X got=0x%02X)\n",
                sht35_crc8(&data[0], 2), data[2]);
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X got=0x%02X)\n",
                sht35_crc8(&data[3], 2), data[5]);
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh    = 100.0f * (float)rh_raw / 65535.0f;

    /* Clamp humidity to valid range */
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure CSV file exists and has a header */
    if (ensure_csv_header() != 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started.  Bus=%d  Addr=0x%02X  Sample=%d s  CSV=%s\n",
           I2C_BUS, SHT35_ADDR, SAMPLE_PERIOD, CSV_FILENAME);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (sht35_read(handle, &temp_c, &rh) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temp_c, rh);
            if (log_data(temp_c, rh) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

