/*
 * Greenhouse monitor — Si7021 temperature & humidity logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * Sensor: Adafruit Si7021 (I2C address 0x40)
 * Log:    environment.log  (CSV: timestamp,temperature_C,humidity_percent)
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_S 5

/* Si7021 commands (MSB=0xFE for measurement, LSB=0x00 for RH, 0x01 for T) */
#define CMD_MEASURE_RH_NO_HOLD   0xE5
#define CMD_MEASURE_T_NO_HOLD    0xE3
#define CMD_RESET                0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00, no final XOR) — Si7021 datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t si7021_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    size_t got = 0;
    while (got < n) {
        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        got += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15 * 1000);  /* reset takes up to 15 ms */
    return 0;
}

/*
 * Poll until the Si7021 reports data-ready (MSB of RH or T result
 * is non-zero).  Returns 0 on success, -1 on timeout / error.
 */
static int si7021_wait_data_ready(int fd)
{
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t cmd = 0xE0;  /* measure RH, no hold, then T, no hold */
        if (i2c_write_cmd(fd, cmd) < 0)
            return -1;
        usleep(10 * 1000);

        uint8_t buf[3];
        if (i2c_read_n(fd, buf, 3) < 0)
            return -1;

        /* buf[0] = MSB of RH or T result, buf[1] = LSB, buf[2] = CRC */
        if (buf[0] != 0xFF)  /* non-zero => data ready */
            return 0;
    }
    fprintf(stderr, "Si7021 data-ready poll timeout\n");
    return -1;
}

static int si7021_read_measurement(int fd, uint8_t cmd, float *out)
{
    if (si7021_reset(fd) < 0)
        return -1;

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    if (si7021_wait_data_ready(fd) < 0)
        return -1;

    uint8_t buf[3];
    if (i2c_read_n(fd, buf, 3) < 0)
        return -1;

    /* CRC check */
    if (si7021_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Si7021 CRC mismatch (cmd 0x%02X)\n", cmd);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    if (cmd == CMD_MEASURE_RH_NO_HOLD)
        *out = (125.0f * raw) / 65536.0f - 6.0f;
    else if (cmd == CMD_MEASURE_T_NO_HOLD)
        *out = (175.72f * raw) / 65536.0f - 46.85f;
    else
        return -1;

    return 0;
}

static int read_sensor(int fd, float *temperature, float *humidity)
{
    if (si7021_reset(fd) < 0)
        return -1;

    if (si7021_read_measurement(fd, CMD_MEASURE_RH_NO_HOLD, humidity) < 0)
        return -1;

    if (si7021_read_measurement(fd, CMD_MEASURE_T_NO_HOLD, temperature) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
    fclose(fp);
    return 0;
}

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (log_open() < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started.  Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl-C to stop.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;

        if (read_sensor(g_i2c_fd, &temperature, &humidity) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; resetting and retrying...\n");
            /* On persistent failure, attempt a hard reset */
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "Hard reset failed; continuing to retry.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

