#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *pressure) {
    char buf[2];
    int ret = i2cReadDevice(handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", ret);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw * 0.01f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return pressure * 0.1f;
}

static void set_fan_speed(float flow_rate) {
    int duty = (int)(flow_rate * 100.0f);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", ts, pressure);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        cleanup();
        return 1;
    }

    while (running) {
        float pressure;
        if (read_sensor(i2c_handle, &pressure) == 0) {
            float flow = calculate_flow_rate(pressure);
            set_fan_speed(flow);
            log_data(pressure);
        } else {
            fprintf(stderr, "Sensor read failed; fan off\n");
            gpioPWM(FAN_GPIO, 0);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

