static int init_lps33hw(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset LPS33HW (CTRL_REG1 write).\n");
        return -1;
    }
    gpioDelay(50000);
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x84) < 0) {
        fprintf(stderr, "Error: Failed to configure LPS33HW (CTRL_REG1 write).\n");
        return -1;
    }
    return 0;
}

static int read_pressure(double *pressure) {
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read pressure data.\n");
        return -1;
