    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lps33hw() != 0) {
        fprintf(stderr, "Error: LPS33HW initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

