#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(float *temperature)
{
    char reg = 0x00;
    char data[2];

    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to write register address to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read 2 bytes from I2C device.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    *temperature = (float)raw / 16.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GPIO_LED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed; skipping iteration.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        buffer_add(&temp_buffer, temperature);
        float average = buffer_average(&temp_buffer);

        if (average > TEMP_THRESHOLD)
            gpioWrite(GPIO_LED, 1);
        else
            gpioWrite(GPIO_LED, 0);

        printf("Temperature: %.2f °C, Average: %.2f °C, LED: %s\n",
               temperature, average, gpioRead(GPIO_LED) ? "ON" : "OFF");

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

