/*
 * SCD30 Air Quality Monitor with Ventilation Control
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1 (GPIO2 = SDA, GPIO3 = SCL), address 0x61
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lscd30 -lm
 *
 * Logs CSV lines to air_quality.log every 5 s:
 *   2023-04-15T12:34:56+0000,405.0,23.5,45.2
 *
 * Ventilation state (per CO₂ ppm):
 *   < 800  -> OFF
 *   800–1199 -> LOW
 *   >= 1200 -> HIGH
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>

#include <pigpio.h>
#include <scd30.h>

#define I2C_BUS        1
#define SCD30_ADDR     0x61
#define LOG_FILE       "air_quality.log"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_INTERVAL  5          /* SCD30 measurement interval (~5 s) */
#define CO2_THRESHOLD  800.0f
#define CO2_HIGH       1200.0f

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float co2, float temp, float rh)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_utc);

    if (fprintf(g_log_file, "%s,%.1f,%.2f,%.2f\n",
                ts, co2, temp, rh) < 0)
        perror("warning: fprintf to log file");
    if (fflush(g_log_file) != 0)
        perror("warning: fflush log file");
}

static void log_error(const char *msg)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_utc);

    if (fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg) < 0)
        perror("warning: fprintf error to log file");
    if (fflush(g_log_file) != 0)
        perror("warning: fflush error log file");
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static const char *ventilation_state(float co2)
{
    if (co2 < CO2_THRESHOLD)
        return "OFF";
    if (co2 < (CO2_THRESHOLD + (CO2_HIGH - CO2_THRESHOLD) / 2.0f))
        return "LOW";
    return "HIGH";
}

/* ------------------------------------------------------------------ */
/* SCD30 helpers                                                       */
/* ------------------------------------------------------------------ */
static int scd30_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SCD30_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }

    if (scd30_start_periodic_measurement(g_i2c_handle) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int scd30_read_data(float *co2, float *temp, float *rh)
{
    uint8_t  buf[18];
    uint8_t  crc;
    uint16_t raw_co2, raw_temp, raw_rh;

    /* SCD30 data is ready when the 3 data registers are non-zero */
    if (scd30_data_ready(g_i2c_handle) != 0) {
        log_error("SCD30 data_ready failed");
        return -1;
    }

    if (i2cReadI2CBlockData(g_i2c_handle, 0x00, (char *)buf, 18) != 18) {
        log_error("SCD30 I2C read failed");
        return -1;
    }

    /* CRC-8 check (polynomial 0x31, init 0xFF) */
    crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= buf[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    if (crc != buf[2]) {
        log_error("SCD30 CO2 CRC mismatch");
        return -1;
    }

    crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= buf[3 + i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    if (crc != buf[5 + 2]) {
        log_error("SCD30 temperature CRC mismatch");
        return -1;
    }

    crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= buf[6 + i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    if (crc != buf[8 + 2]) {
        log_error("SCD30 humidity CRC mismatch");
        return -1;
    }

    raw_co2    = ((uint16_t)buf[0] << 8) | buf[1];
    raw_temp   = ((uint16_t)buf[3] << 8) | buf[4];
    raw_rh     = ((uint16_t)buf[6] << 8) | buf[7];

    *co2    = (float)raw_co2 / 1000.0f;
    *temp   = (float)raw_temp / 100.0f;
    *rh     = (float)raw_rh / 100.0f;

    return 0;
}

static void scd30_stop(void)
{
    if (g_i2c_handle >= 0) {
        scd30_stop_periodic_measurement(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float co2, temp, rh;

    install_signal_handlers();

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* If pigpio is not available (mocked environment) we cannot
       open the I2C bus and cannot run the SCD30 driver, but we
       still want to log the lack of sensor access and exit cleanly. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio not available — no SCD30 hardware detected.\n");
        log_error("pigpio not available");
        fclose(g_log_file);
        return EXIT_SUCCESS;
    }

    if (scd30_init() != 0) {
        fprintf(stderr, "SCD30 initialization failed — no sensor found at 0x%02X.\n",
                SCD30_ADDR);
        log_error("SCD30 init failed");
        scd30_stop();
        fclose(g_log_file);
        return EXIT_SUCCESS;
    }

    printf("SCD30 initialized. Logging to %s every %d s. Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        if (scd30_read_data(&co2, &temp, &rh) == 0) {
            printf("CO2: %.1f ppm | T: %.2f °C | RH: %.2f %%\n",
                   co2, temp, rh);
            log_data(co2, temp, rh);
            printf("Ventilation: %s\n", ventilation_state(co2));
        } else {
            fprintf(stderr, "Read failed — continuing.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    scd30_stop();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

