/*
 * Raspberry Pi 4 Model B – Sensirion SDP810-125Pa differential pressure sensor
 * I2C bus 1 (BCM GPIO2 = SDA, GPIO3 = SCL), periodic logging every 1 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -lpigpio -lrt
 * Run:    sudo ./sdp810
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define READ_LEN       9          /* 3 words × (2 data + 1 CRC) */
#define CONV_DELAY_US  45000      /* 45 ms conversion time */
#define SAMPLE_PERIOD  1          /* seconds between samples */

/* SDP810 command: continuous measurement, no averaging, no reset */
#define CMD_CONT_MEAS  0x361F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_ok(const uint8_t *data, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- start continuous measurement ------------------------------- */
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- wait for first conversion to complete ---------------------- */
    gpioDelay(CONV_DELAY_US);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint8_t buf[READ_LEN];
        int n = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
        if (n != READ_LEN) {
            fprintf(stderr, "Error: I2C read returned %d bytes (expected %d).\n",
                    n, READ_LEN);
            /* brief back-off before retrying */
            gpioDelay(100000);
            continue;
        }

        /* Validate CRC on each 3-byte word */
        for (int i = 0; i < 3; i++) {
            if (!crc8_ok(&buf[i * 3], buf[i * 3 + 2])) {
                fprintf(stderr, "Error: CRC mismatch on word %d.\n", i);
                continue;
            }
        }

        /* Assemble signed 16-bit values (big-endian) */
        int16_t dp_raw = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t t_raw  = (int16_t)((buf[3] << 8) | buf[4]);

        /* Scale factors are the next two bytes of each word */
        uint16_t dp_scale = (uint16_t)((buf[6] << 8) | buf[7]);
        uint16_t t_scale  = (uint16_t)((buf[6] << 8) | buf[8]);

        /* Sanity-check scale factors (typical: 1000–2000) */
        if (dp_scale == 0 || t_scale == 0) {
            fprintf(stderr, "Error: invalid scale factor (dp=%u, t=%u).\n",
                    dp_scale, t_scale);
            continue;
        }

        /* Convert to physical units */
        float dp = (float)dp_raw / (float)dp_scale;
        float t  = (float)t_raw  / (float)t_scale;

        printf("Differential Pressure: %.2f Pa, Temperature: %.2f °C\n",
               dp, t);
        fflush(stdout);

        /* Sleep for the remainder of the sample period */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            gpioDelay(1000000);   /* 1 s */
    }

    /* --- graceful shutdown ----------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

