#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40
#define REG_TEMP       0x00
#define REG_HUMID      0x01
#define REG_CONFIG     0x02
#define CONFIG_14BIT   0x1000  /* 14-bit temp + humidity, heater off */
#define CONV_DELAY_MS  20
#define POLL_DELAY_MS  5000

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read16(0x%02X): write reg failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read16(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write16(fd, REG_CONFIG, CONFIG_14BIT) != 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum)
{
    uint16_t raw_t, raw_h;
    if (i2c_read16(fd, REG_TEMP, &raw_t) != 0)
        return -1;
    if (i2c_read16(fd, REG_HUMID, &raw_h) != 0)
        return -1;
