/*
 * Si7051 Temperature Sensor Reader for Raspberry Pi 4 Model B
 * I2C bus 1 (SDA=GPIO2, SCL=GPIO3, BCM numbering)
 * Logs temperature every 5 seconds to the console.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7051_reader si7051_reader.c
 * Run:    sudo ./si7051_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7051_ADDR    0x40
#define TEMP_REG       0x00
#define MEAS_DELAY_MS  10
#define POLL_DELAY_MS  5000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a single byte to the sensor's register pointer.
 * Returns 0 on success, -1 on error.
 */
static int si7051_write_reg(uint8_t reg)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg pointer 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the current register pointer.
 * Returns 0 on success, -1 on error.
 */
static int si7051_read_bytes(uint8_t *buf, size_t len)
{
    ssize_t n = read(g_i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu bytes): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Trigger a temperature measurement and read the result.
 * Returns 0 on success and stores the temperature in *out_celsius.
 * Returns -1 on any I2C or protocol error.
 */
static int si7051_read_temperature(float *out_celsius)
{
    uint8_t buf[2];

    /* Trigger a temperature measurement (no hold, clock stretching) */
    if (si7051_write_reg(TEMP_REG) < 0)
        return -1;

    /* Wait for the conversion to complete */
    struct timespec ts = { 0, MEAS_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read the 2-byte result (MSB first) */
    if (si7051_read_bytes(buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    /* Clear the RH status bits (bits 0-1) and the T status bits (bits 2-3) */
    raw &= 0xFCFF;

    /* Assemble the 16-bit temperature value */
    uint16_t temp_raw = (raw >> 4) & 0x0FFF;
    *out_celsius = -46.85f + 175.72f * (float)temp_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SI7051_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("Si7051 temperature reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SI7051_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7051_read_temperature(&temperature) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                usleep(POLL_DELAY_MS * 1000);
        }

        if (success) {
            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_DELAY_MS / 100 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

