#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5C
#define READ_INTERVAL  0.5   /* seconds */
#define MAX_RETRIES    3

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE   0x0001
#define REG_CONFIG     0x0002

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address followed by a 16-bit value. */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian on the bus). */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    /* Configure: enable pressure measurement, default settings. */
    if (i2c_write_reg16(handle, REG_CONFIG, 0x0001) != 0)
        return -1;

    /* Allow the sensor to settle after configuration. */
    time_sleep(0.01);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure reading                                                    */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, uint16_t *pressure)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(handle, REG_PRESSURE, pressure) == 0)
            return 0;
        time_sleep(0.01);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90833 pressure logger started. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t pressure = 0;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Pressure: %u Pa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries\n", MAX_RETRIES);
        }

        time_sleep(READ_INTERVAL);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

