/*
 * Raspberry Pi Zero W – TDK ICP-10101 barometric pressure sensor reader
 *
 * Wiring:
 *   VDD  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10101_reader icp10101_reader.c
 *
 * The ICP-10101 defaults to a 7 ms measurement time; the loop below
 * polls every 5 s so the sensor is not starved.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x70
#define MEAS_DELAY_US  7000   /* 7 ms measurement time */
#define LOOP_DELAY_US  5000000 /* 5 s between readings */
#define MAX_RETRIES    3

/* ICP-10101 register addresses (16-bit, big-endian on the bus) */
#define REG_MEAS_CTRL  0x00
#define REG_TEMP_MSB   0x01
#define REG_TEMP_LSB   0x02
#define REG_PRESS_MSB  0x03
#define REG_PRESS_LSB  0x04

/* Measurement control: start a single-shot conversion */
#define MEAS_CTRL_START 0x01

/* Default value for the ICP-10101 when left floating */
#define ICP10101_DEFAULT_TEMP  25.0f
#define ICP10101_DEFAULT_PRESS 101325.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void timestamp_iso8601(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

static void log_error(const char *msg)
{
    char ts[32];
    timestamp_iso8601(ts, sizeof(ts));
    fprintf(stderr, "%s - ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit value to a 16-bit register address.
 * The ICP-10101 expects the address in big-endian form on the bus.
 */
static int icp_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/*
 * Read `len` bytes starting from a 16-bit register address.
 * The ICP-10101 expects the address in big-endian form on the bus.
 */
static int icp_read_reg16(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    char addr[2];
    addr[0] = (char)reg;
    addr[1] = 0x00; /* dummy – pigpio i2cWriteDevice sends the first byte */

    if (i2cWriteDevice(handle, addr, 1) < 0)
        return -1;

    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */

static int icp10101_start_measurement(int handle)
{
    return icp_write_reg16(handle, REG_MEAS_CTRL, MEAS_CTRL_START);
}

static int icp10101_read_temperature(int handle, float *temp_c)
{
    uint8_t buf[2];
    if (icp_read_reg16(handle, REG_TEMP_MSB, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (float)raw / 100.0f;
    return 0;
}

static int icp10101_read_pressure(int handle, float *press_pa)
{
    uint8_t buf[2];
    if (icp_read_reg16(handle, REG_PRESS_MSB, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *press_pa = (float)raw * 25.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ICP10101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICP-10101 reader started. Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (icp10101_start_measurement(g_i2c_handle) < 0) {
                log_error("Failed to send measurement command");
                gpioDelay(MEAS_DELAY_US);
                continue;
            }

            gpioDelay(MEAS_DELAY_US);

            float temp_c = ICP10101_DEFAULT_TEMP;
            float press_pa = ICP10101_DEFAULT_PRESS;

            if (icp10101_read_temperature(g_i2c_handle, &temp_c) < 0) {
                log_error("Failed to read temperature");
                continue;
            }
            if (icp10101_read_pressure(g_i2c_handle, &press_pa) < 0) {
                log_error("Failed to read pressure");
                continue;
            }

            ok = 1;
            break;
        }

        if (ok) {
            char ts[32];
            timestamp_iso8601(ts, sizeof(ts));
            printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                   ts, temp_c, press_pa);
            fflush(stdout);
        } else {
            log_error("Sensor read failed after multiple retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

