#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x36          /* SDP800-500Pa default I2C address */
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  45            /* ms between measurements */
#define MEAS_DELAY     10            /* ms measurement conversion time */
#define MAX_RETRIES    3

/* SDP800-500Pa command: continuous measurement, no averaging, no reset */
#define CMD_MEASURE    0x3608

/* CRC-8 parameters (Sensirion: poly 0x31, init 0xFF) */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF)                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the sensor                               */
/* ------------------------------------------------------------------ */
static int write_command(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor                           */
/* ------------------------------------------------------------------ */
static int read_bytes(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read 9 bytes with CRC validation         */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *pressure, float *temperature)
{
    uint8_t data[9];

    if (write_command(handle, CMD_MEASURE) != 0)
        return -1;

    gpioDelay(MEAS_DELAY * 1000);   /* 10 ms conversion time */

    if (read_bytes(handle, data, 9) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* SDP800-500Pa: 16-bit big-endian signed values */
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    /* SDP800-500Pa: 0.01 Pa per LSB, 0.01 °C per LSB */
    *pressure    = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temp     / 100.0f;

    return 0;
