    if (!fp) {
        perror("[ERROR] fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HVAC Airflow Monitor — SDP800-500Pa (I2C 0x%02X)\n", I2C_ADDR);
    printf("Logging to %s every %d ms. Press Ctrl-C to stop.\n", LOG_FILE, SAMPLE_PERIOD);

    /* --- Main loop --- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(g_i2c_handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100 * 1000);   /* 100 ms back-off before retry */
        }

        if (ok) {
            printf("Pressure: %.2f Pa  |  Temperature: %.2f °C\n", pressure, temperature);
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts — skipping sample\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD ms, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD && g_running; ms += 10) {
            gpioDelay(10 * 1000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

