code:
/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c
 * Run:    ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x50
#define TRIGGER_CMD    0x36
#define READ_LEN       3
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_MS      100
#define TRIGGER_MS     8

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the 3-byte response.
 * Returns 0 on success and fills *pressure_raw; returns -1 on error.
 */
static int read_sdp800(int fd, int16_t *pressure_raw)
{
    if (i2c_write_cmd(fd, TRIGGER_CMD) == -1)
        return -1;

    usleep(TRIGGER_MS * 1000);

    uint8_t buf[READ_LEN];
    if (i2c_read_bytes(fd, buf, READ_LEN) == -1)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    *pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static void log_data(const char *filename, int16_t pressure_raw)
{
    int file_exists = (access(filename, F_OK) == 0);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return;
    }

    if (!file_exists) {
        fprintf(fp, "Timestamp,Pressure_raw\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d\n", ts, pressure_raw);
    } else {
        fprintf(fp, "unknown,%d\n", pressure_raw);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
}

int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    int fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) == -1) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 logger started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t pressure_raw;
        if (read_sdp800(fd, &pressure_raw) == 0) {
            log_data(LOG_FILE, pressure_raw);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    if (close(fd) == -1)
        fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

