#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LOG_FILE       "pressure_log.csv"
#define PRESSURE_MIN   200.0f
#define PRESSURE_MAX   250.0f
#define SAMPLE_PERIOD  1.0
#define RETRY_DELAY    1.0
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }
    int raw = i2cReadWordData(g_i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *pressure = (float)raw / 100.0f;
    return 0;
}

static int log_pressure(float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void check_pressure(float pressure)
{
    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
        fprintf(stderr,
                "WARNING: Pressure %.2f kPa outside safe range [%.0f, %.0f] kPa\n",
                pressure, PRESSURE_MIN, PRESSURE_MAX);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    long file_size = ftell(g_log_file);
    if (file_size < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (file_size == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            consecutive_errors = 0;
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            check_pressure(pressure);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors reached; re-opening I2C\n");
                if (open_i2c() != 0) {
                    fprintf(stderr, "Re-open failed; exiting\n");
                    break;
                }
                consecutive_errors = 0;
            } else {
                time_sleep(RETRY_DELAY);
                continue;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

