/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_hih6130(int handle, float *temperature, float *humidity)
{
    uint8_t data[3] = {0};
    int rc;

    /* Trigger a measurement by writing a zero byte to the device */
    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", pigpio_error(rc));
        return -1;
    }

    /* Wait for the conversion to complete (datasheet: typ 35 ms, max 40 ms) */
    gpioDelay(TRIGGER_DELAY * 1000);  /* microseconds */

    /* Read 3 bytes: T_MSB, T_LSB, RH_MSB */
    rc = i2cReadDevice(handle, (char *)data, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading sensor data (rc=%d): %s\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* Status bits occupy the two LSBs of the first byte */
    uint8_t status = data[0] & 0x03;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", status);
        return -1;
    }

    /* Assemble raw temperature and humidity values */
    uint16_t raw_t = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_h = ((uint16_t)data[2] << 8) | data[1];

    *temperature = ((float)raw_t / 65535.0f) * 175.0f - 45.0f;
    *humidity    = ((float)raw_h / 65535.0f) * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log file size check and truncation                                  */
/* ------------------------------------------------------------------ */
static int check_and_truncate_log(void)
{
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        /* File does not exist yet; nothing to truncate */
        return 0;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    long size = ftell(fp);
    fclose(fp);

    if (size > LOG_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error truncating log file: %s\n", strerror(errno));
            return -1;
        }
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing truncated log file: %s\n",
                    strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to HIH6130 */
    g_i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, HIH6130_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("HIH6130 environmental monitor started. Logging to '%s'.\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_hih6130(g_i2c_handle, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000);  /* 100 ms backoff */
        }

        if (!success) {
            fprintf(stderr, "All %d read attempts failed; skipping log entry.\n",
                    MAX_RETRIES);
            /* Continue the loop to avoid flooding the log with errors */
            sleep(READ_INTERVAL);
            continue;
        }

        char timestamp[32];
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to generate timestamp; skipping log entry.\n");
            sleep(READ_INTERVAL);
            continue;
        }

        if (log_data(timestamp, temperature, humidity) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        if (check_and_truncate_log() != 0) {
            fprintf(stderr, "Warning: log file size check/truncation failed.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

