#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define SENT_TICK_US 3
#define SENT_SYNC_TICKS 56
#define SENT_MIN_TICKS 12
#define SENT_MAX_TICKS 271
#define SENT_NIBBLES 4
#define SENT_TIMEOUT_MS 1000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio, int *ticks) {
    int start_tick = gpioTick();
    int level = gpioRead(gpio);
    if (level < 0) return -1;

    int count = 0;
    while (running) {
        int now = gpioTick();
        if (now - start_tick > SENT_TIMEOUT_MS * 1000) return -1;
        if (gpioRead(gpio) != level) break;
        count++;
    }
    if (!running) return -1;

    *ticks = count;
    return 0;
}

static int read_sent_data(int gpio, unsigned char *data) {
    for (int i = 0; i < SENT_NIBBLES; i++) {
        int ticks;
        if (read_sent_nibble(gpio, &ticks) != 0) return -1;
        if (ticks < SENT_MIN_TICKS || ticks > SENT_MAX_TICKS) return -1;
        data[i] = (unsigned char)((ticks - 12) / 18);
    }
    return 0;
}

static int extract_pressure(const unsigned char *data, float *pressure) {
    unsigned int raw = ((unsigned int)data[0] << 12) |
                       ((unsigned int)data[1] << 6)  |
                       ((unsigned int)data[2]);
    *pressure = (float)raw * 0.5f;
    return 0;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    unsigned char data[SENT_NIBBLES];
    float pressure;

    while (running) {
        int sync_count = 0;
        int last_level = 1;
        int last_tick = gpioTick();

        while (running) {
            int now = gpioTick();
            if (now - last_tick > SENT_TIMEOUT_MS * 1000) {
                fprintf(stderr, "SENT timeout: no sync pulse detected\n");
                break;
            }
            int level = gpioRead(SENT_GPIO);
            if (level < 0) {
                fprintf(stderr, "GPIO read error\n");
                break;
            }
            if (level != last_level) {
                int diff = (now - last_tick) / SENT_TICK_US;
                if (diff >= SENT_SYNC_TICKS - 10 && diff <= SENT_SYNC_TICKS + 10) {
                    sync_count++;
                    if (sync_count >= 2) break;
                }
                last_level = level;
                last_tick = now;
            }
        }

        if (!running) break;

        if (read_sent_data(SENT_GPIO, data) != 0) {
            fprintf(stderr, "SENT data read error\n");
            continue;
        }

        unsigned char status = data[0];
        unsigned char status_nibble = (status >> 4) & 0x0F;
        if (status_nibble != 0) {
            fprintf(stderr, "SENT status error: status nibble = 0x%X\n", status_nibble);
            continue;
        }

        if (extract_pressure(data, &pressure) != 0) {
            fprintf(stderr, "SENT pressure extraction error\n");
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Failed to log pressure reading\n");
        } else {
            printf("Pressure: %.2f Pa\n", pressure);
        }
    }

    gpioTerminate();
    return 0;
}

