#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_ID   0x0C
#define TMP117_ID_VAL   0x117
#define LOG_FILE        "greenhouse_temps.dat"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val & 0xFF);
    buf[2] = (uint8_t)((val >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int verify_sensor_id(int fd) {
    uint16_t id;
    if (i2c_read_reg16(fd, TMP117_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read TMP117 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != TMP117_ID_VAL) {
        fprintf(stderr, "Error: TMP117 ID mismatch (got 0x%04X, expected 0x%04X)\n", id, TMP117_ID_VAL);
        return -1;
    }
    printf("TMP117 sensor verified (ID = 0x%04X)\n", id);
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (i2c_read_reg16(fd, TMP117_REG_TEMP, &raw) < 0) {
        fprintf(stderr, "Error: failed to read temperature register: %s\n", strerror(errno));
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temp = (float)signed_raw / 16.0f;
    return 0;
}

static int log_temperature(FILE *fp, float temp) {
    if (fwrite(&temp, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error: failed to write temperature to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Error: failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        goto cleanup;
    }

    if (verify_sensor_id(fd) < 0) {
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "ab");
    if (!fp) {
        fprintf(stderr, "Error: failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) < 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (log_temperature(fp, temp) < 0) {
            fprintf(stderr, "Warning: failed to log temperature, continuing...\n");
        }

        printf("Temperature: %.2f °C\n", temp);

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    printf("\nGreenhouse temperature monitoring stopped.\n");
    return rc;
}

