    }

    fp = fopen(LOG_FILE, "ab");
    if (!fp) {
        fprintf(stderr, "Error: failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) < 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (log_temperature(fp, temp) < 0) {
            fprintf(stderr, "Warning: failed to log temperature, continuing...\n");
        }

        printf("Temperature: %.2f °C\n", temp);

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    printf("\nGreenhouse temperature monitoring stopped.\n");
    return rc;
}

