#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define SAMPLE_INTERVAL_SEC 5
#define BUFFER_SIZE 10
#define LOG_FILE "temperature_log.dat"

/* TMP117 register addresses */
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01

/* TMP117 config: continuous conversion, 1 Hz, 12-bit */
#define TMP117_CONFIG_VAL 0x8000

typedef struct {
    float temperature[BUFFER_SIZE];
    time_t timestamp[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /* Write config register to start continuous conversions */
    char config_buf[3];
    config_buf[0] = TMP117_REG_CONFIG;
    config_buf[1] = (TMP117_CONFIG_VAL >> 8) & 0xFF;
    config_buf[2] = TMP117_CONFIG_VAL & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing TMP117 config register\n");
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    char reg = TMP117_REG_TEMP;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting TMP117 temperature register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading TMP117 temperature data\n");
        return -1;
    }

    /* TMP117 12-bit two's complement, left-justified in 16 bits */
    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    raw >>= 4;
    *temp = (float)raw * 0.0625f;
    return 0;
}

static void add_to_buffer(float temp, time_t ts) {
    buffer.temperature[buffer.head] = temp;
    buffer.timestamp[buffer.head] = ts;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    int start = (buffer.count == BUFFER_SIZE) ? buffer.head : 0;
    int written = 0;

    for (int i = 0; i < buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&buffer.timestamp[idx], sizeof(time_t), 1, fp) != 1) {
            fprintf(stderr, "Error writing timestamp to log file\n");
            fclose(fp);
            return -1;
        }
        if (fwrite(&buffer.temperature[idx], sizeof(float), 1, fp) != 1) {
            fprintf(stderr, "Error writing temperature to log file\n");
            fclose(fp);
            return -1;
        }
        written++;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return written;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMP117 temperature logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature;
        time_t current_time = time(NULL);

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature, current_time);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        /* Write buffer to file every SAMPLE_INTERVAL_SEC seconds */
        if (buffer.count > 0 && (time(NULL) - current_time) >= SAMPLE_INTERVAL_SEC) {
            if (write_buffer_to_file(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to write buffer to file.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Flush remaining samples on exit */
    if (buffer.count > 0) {
        if (write_buffer_to_file(LOG_FILE) != 0) {
            fprintf(stderr, "Failed to write buffer to file on exit.\n");
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("TMP117 temperature logger stopped.\n");
    return EXIT_SUCCESS;
}

