    while (running) {
        float temperature;
        time_t current_time = time(NULL);

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature, current_time);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        /* Write buffer to file every SAMPLE_INTERVAL_SEC seconds */
        if (buffer.count > 0 && (time(NULL) - current_time) >= SAMPLE_INTERVAL_SEC) {
            if (write_buffer_to_file(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to write buffer to file.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Flush remaining samples on exit */
    if (buffer.count > 0) {
        if (write_buffer_to_file(LOG_FILE) != 0) {
            fprintf(stderr, "Failed to write buffer to file on exit.\n");
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("TMP117 temperature logger stopped.\n");
    return EXIT_SUCCESS;
}

