#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHTC3_ADDR     0x60
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_DELAY_US  12400      /* 12.4 ms conversion time */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup: close I2C and release pigpio ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Read temperature and humidity from SHTC3 ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC error.
 * Temperature and humidity are written to *temp_c and *rh_pct.
 */
static int read_shtc3(float *temp_c, float *rh_pct)
{
    uint8_t cmd[2] = { 0x80, 0x06 };   /* measure T&RH, clock stretching disabled */
    uint8_t data[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] I2C read failed\n");
        return -1;
    }

    /* CRC checks */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh_pct = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Log a reading to file and stdout ---- */
static void log_reading(float temp_c, float rh_pct)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: ", LOG_FILE);
        perror("");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }

    printf("SHTC3 environmental monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh_pct;

        int rc = read_shtc3(&temp_c, &rh_pct);
        if (rc == 0) {
            if (temp_c < -40.0f || temp_c > 125.0f ||
                rh_pct < 0.0f   || rh_pct > 100.0f) {
                fprintf(stderr, "[WARN] Out-of-range reading: T=%.2f C, RH=%.2f %%\n",
                        temp_c, rh_pct);
            } else {
                log_reading(temp_c, rh_pct);
            }
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C communication error\n");
        } else {
            fprintf(stderr, "[WARN] CRC mismatch (sensor fault?)\n");
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

