#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x48
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

/* Si7202 register addresses */
#define SI7202_REG_TEMP 0x00
#define SI7202_REG_SPEED 0x02

/* Globals for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float rotational_speed;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed on bus %d addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, SI7202_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int rc;

    /* Read temperature (2 bytes, big-endian) */
    rc = i2cReadI2CBlockData(i2c_handle, SI7202_REG_TEMP, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read temperature failed (rc=%d)\n", rc);
        data->temperature = NAN;
    } else {
        int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
        data->temperature = (float)raw_temp / 100.0f;
    }

    /* Read rotational speed (2 bytes, big-endian) */
    rc = i2cReadI2CBlockData(i2c_handle, SI7202_REG_SPEED, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read rotational speed failed (rc=%d)\n", rc);
        data->rotational_speed = NAN;
    } else {
        int16_t raw_speed = (int16_t)((buf[0] << 8) | buf[1]);
        data->rotational_speed = (float)raw_speed / 100.0f;
    }

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (isnan(data->rotational_speed) || isnan(data->temperature)) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->rotational_speed, data->temperature);
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Rotational Speed (RPM),Temperature (C)\n");
        fflush(log_file);
    }

    sensor_data_t sensor_data;
    while (!terminate) {
        read_sensor_data(&sensor_data);
        log_data(&sensor_data);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

