#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_READ_INTERVAL_US 2000000  /* 2 seconds */
#define DHT11_START_LOW_US 18000        /* >= 18 ms low */
#define DHT11_START_HIGH_US 30          /* release line */
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_THRESHOLD_US 50       /* > 50 us high => '1' */
#define DHT11_MAX_RETRIES 5
#define DHT11_TIMEOUT_US 10000          /* 10 ms timeout for each stage */

#define DHT11_OK 0
#define DHT11_TIMEOUT -1
#define DHT11_CHECKSUM_ERROR -2
#define DHT11_NOT_PRESENT -3
#define DHT11_GPIO_ERROR -4

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *message, int status) {
    FILE *fp = fopen("dht11_errors.txt", "a");
    if (!fp) {
        perror("fopen(dht11_errors.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, %s, status: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message, status);
    } else {
        fprintf(fp, "<unknown time>, %s, status: %d\n", message, status);
    }
    fclose(fp);
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) {
            return DHT11_TIMEOUT;
        }
    }
    return DHT11_OK;
}

static int wait_for_level_timeout(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) {
            return DHT11_TIMEOUT;
        }
    }
    return DHT11_OK;
}

static int read_dht11(int gpio, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    /* Send start signal: pull low for >= 18 ms, then release */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        return DHT11_GPIO_ERROR;
    }
    if (gpioWrite(gpio, 0) < 0) {
        return DHT11_GPIO_ERROR;
    }
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(gpio, 1) < 0) {
        return DHT11_GPIO_ERROR;
    }
    gpioDelay(DHT11_START_HIGH_US);

    /* Switch to input and let sensor pull low for response */
    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        return DHT11_GPIO_ERROR;
    }

    /* Wait for sensor to pull low (response low pulse) */
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) != DHT11_OK) {
        return DHT11_TIMEOUT;
    }

    /* Wait for response high pulse */
    if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) != DHT11_OK) {
        return DHT11_TIMEOUT;
    }

    /* Wait for sensor to pull low again (response end) */
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) != DHT11_OK) {
        return DHT11_TIMEOUT;
    }

    /* Read 40 data bits */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of 50 us low period) */
        if (wait_for_level_timeout(gpio, 1, DHT11_TIMEOUT_US) != DHT11_OK) {
            return DHT11_TIMEOUT;
        }

        /* Measure high pulse duration */
        uint32_t high_start = gpioTick();
        if (wait_for_level_timeout(gpio, 0, DHT11_TIMEOUT_US) != DHT11_OK) {
            return DHT11_TIMEOUT;
        }
        uint32_t high_duration = gpioTick() - high_start;

        /* Determine bit value: > 50 us high => '1', else '0' */
        data[i / 8] <<= 1;
        if (high_duration > DHT11_BIT_THRESHOLD_US) {
            data[i / 8] |= 1;
        }
    }

    /* Verify checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        return DHT11_CHECKSUM_ERROR;
    }

    /* Convert data */
    *humidity = (float)data[0] + (float)data[1] / 10.0f;
    *temperature = (float)data[2] + (float)data[3] / 10.0f;

    return DHT11_OK;
}

static int write_to_file(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temperature: %.1f C, Humidity: %.1f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    } else {
        fprintf(fp, "<unknown time>, Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;
    int status;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    /* Main loop */
    while (g_running) {
        status = read_dht11(DHT11_GPIO, &temperature, &humidity);

        if (status == DHT11_OK) {
            if (write_to_file("dht11_readings.txt", temperature, humidity) != 0) {
                log_error("Failed to write to file", status);
            }
        } else {
            log_error("DHT11 read failed", status);
        }

        /* Sleep for the interval, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(DHT11_READ_INTERVAL_US / 10);
        }
    }

    /* Clean shutdown */
    gpioTerminate();
    return 0;
}

