    if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) != DHT11_OK) {
        return DHT11_TIMEOUT;
    }

    /* Wait for sensor to pull low again (response end) */
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) != DHT11_OK) {
        return DHT11_TIMEOUT;
    }

    /* Read 40 data bits */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of 50 us low period) */
        if (wait_for_level_timeout(gpio, 1, DHT11_TIMEOUT_US) != DHT11_OK) {
            return DHT11_TIMEOUT;
        }

        /* Measure high pulse duration */
        uint32_t high_start = gpioTick();
        if (wait_for_level_timeout(gpio, 0, DHT11_TIMEOUT_US) != DHT11_OK) {
            return DHT11_TIMEOUT;
        }
        uint32_t high_duration = gpioTick() - high_start;

        /* Determine bit value: > 50 us high => '1', else '0' */
        data[i / 8] <<= 1;
        if (high_duration > DHT11_BIT_THRESHOLD_US) {
            data[i / 8] |= 1;
        }
    }

    /* Verify checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        return DHT11_CHECKSUM_ERROR;
    }

    /* Convert data */
    *humidity = (float)data[0] + (float)data[1] / 10.0f;
    *temperature = (float)data[2] + (float)data[3] / 10.0f;

    return DHT11_OK;
}

static int write_to_file(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temperature: %.1f C, Humidity: %.1f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    } else {
        fprintf(fp, "<unknown time>, Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;
    int status;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    /* Main loop */
    while (g_running) {
        status = read_dht11(DHT11_GPIO, &temperature, &humidity);

        if (status == DHT11_OK) {
            if (write_to_file("dht11_readings.txt", temperature, humidity) != 0) {
                log_error("Failed to write to file", status);
            }
        } else {
            log_error("DHT11 read failed", status);
        }

        /* Sleep for the interval, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(DHT11_READ_INTERVAL_US / 10);
        }
    }

    /* Clean shutdown */
    gpioTerminate();
    return 0;
}

