#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define LOG_FILE "sht31d_data.log"
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 20000
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        if (crc8(&data[0], 2) != data[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        if (crc8(&data[3], 2) != data[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            usleep(10000);
            continue;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw = (data[3] << 8) | data[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "SHT31-D read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT31_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    while (running) {
        if (read_sht31d(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }
        usleep(LOOP_DELAY_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

