#define ADPD105_I2C_ADDR 0x18
#define ADPD105_REG_DATA 0x00
#define ADPD105_REG_CONFIG 0x01
#define ADPD105_REG_STATUS 0x02

#define I2C_BUS 1
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adpd105_read_reg(int handle, uint8_t reg, uint8_t *val) {
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    int b = i2cReadByte(handle);
    if (b < 0) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed\n", reg);
        return -1;
    }
    *val = (uint8_t)b;
    return 0;
}

static int adpd105_write_reg(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed\n", reg, val);
        return -1;
    }
    return 0;
}

static int adpd105_init(int handle) {
    uint8_t status;
    if (adpd105_read_reg(handle, ADPD105_REG_STATUS, &status) < 0) {
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "ADPD105 status not reset: 0x%02X\n", status);
        return -1;
    }
    if (adpd105_write_reg(handle, ADPD105_REG_CONFIG, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int adpd105_read_data(int handle, uint16_t *data) {
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, ADPD105_REG_DATA, (char *)buf, 2) != 2) {
        fprintf(stderr, "I2C block read of 2 bytes from reg 0x%02X failed\n", ADPD105_REG_DATA);
        return -1;
    }
    *data = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static float calculate_cct(uint16_t sensor_data) {
    /* Placeholder: replace with real ADPD105 CCT calculation */
    return (float)sensor_data * 100.0f;
}

static int log_cct(float cct) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, cct);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, ADPD105_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n", I2C_BUS, ADPD105_I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adpd105_init(handle) < 0) {
        fprintf(stderr, "ADPD105 initialization failed (sensor absent or bus error)\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);

    while (running) {
        uint16_t sensor_data1 = 0, sensor_data2 = 0;
        int ok1 = (adpd105_read_data(handle, &sensor_data1) == 0);
        int ok2 = (adpd105_read_data(handle, &sensor_data2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d); skipping cycle\n", ok1, ok2);
        } else {
            float cct = calculate_cct(sensor_data1);
            if (log_cct(cct) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(handle);
    gpioTerminate();
    if (need_header) {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "Timestamp,Average_CCT\n");
                fclose(fp);
            }
        }
    }
    return EXIT_SUCCESS;
}

