#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5C
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB    0x02
#define REG_TEMP_LSB    0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL || strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    return -1;
}

static int read_register16(int handle, uint8_t reg_msb, uint8_t reg_lsb, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg_msb, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_sensor(int handle, float *pressure, float *temperature)
{
    uint16_t raw_p, raw_t;

    if (read_register16(handle, REG_PRESSURE_MSB, REG_PRESSURE_LSB, &raw_p) != 0) {
        return -1;
    }
    if (read_register16(handle, REG_TEMP_MSB, REG_TEMP_LSB, &raw_t) != 0) {
        return -1;
    }

    /* Placeholder conversions (replace with actual MLX90824 scaling) */
    *pressure    = (float)raw_p * 0.1f;
    *temperature = (float)raw_t * 0.1f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL || strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    if (fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n", ts, pressure, temperature) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 pressure logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                log_error("Failed to write data to log file");
            }
        } else {
            log_error("Failed to read sensor data from I2C bus");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

