#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out)
{
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int n = i2cReadDevice(g_i2c_handle, buf, 2);
        if (n == 2) {
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *temp_out = (float)raw / 16.0f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Warning: I2C read returned %d, retrying (%d/%d)\n",
                    n, retries, MAX_RETRIES);
            time_sleep(0.1);
        }
    }
    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void control_fan(float avg_temp)
{
    static bool fan_on = false;
    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(1) failed\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(0) failed\n");
        }
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float buffer[BUFFER_SIZE];
    int   head = 0;
    int   count = 0;

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer[head] = temp;
            head = (head + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            float sum = 0.0f;
            for (int i = 0; i < count; i++) sum += buffer[i];
            float avg = (count > 0) ? (sum / (float)count) : 0.0f;

            printf("Temp: %.2f C  Avg: %.2f C\n", temp, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Error: temperature read failed, skipping cycle\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

