#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define POLL_INTERVAL_US     1000000
#define MAX_I2C_ERRORS       5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(float *temperature)
{
    char buf[2];
    int rc = i2cReadDevice(g_i2c_fd, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 100.0f;
    return 0;
}

static void control_led(float temperature)
{
    int level = (temperature > TEMP_THRESHOLD_HIGH) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Failed to write LED GPIO %d: %s\n", LED_GPIO, strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n", LED_GPIO, strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed: %s\n", LED_GPIO, strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            consecutive_errors = 0;
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);
            control_led(temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read error (%d/%d)\n",
                    consecutive_errors, MAX_I2C_ERRORS);
            if (consecutive_errors >= MAX_I2C_ERRORS) {
                fprintf(stderr, "Max I2C errors reached, exiting.\n");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

