#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3
#define MEASURE_RH_CMD 0xE5
#define MEASURE_TEMP_CMD 0xE3
#define READ_TEMP_CMD  0xE0
#define READ_ID_CMD    0xFA0F
#define READ_FW_REV_CMD 0x840F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) failed (rc=%d), attempt %d/%d\n",
                cmd, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "[WARN] i2cReadDevice failed (rc=%d), attempt %d/%d\n",
                rc, attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si7021 sensor operations                                            */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *temperature, float *humidity)
{
    uint8_t buf[2];

    /* 1. Measure Relative Humidity (No Master Hold) */
    if (i2c_write_cmd(handle, MEASURE_RH_CMD) != 0)
        return -1;
    gpioDelay(20000); /* 20 ms conversion time */

    /* 2. Read 2 bytes (RH MSB, RH LSB) */
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;
    uint16_t rh_raw = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity = (125.0f * rh_raw) / 65536.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    /* 3. Measure Temperature (No Master Hold) */
    if (i2c_write_cmd(handle, MEASURE_TEMP_CMD) != 0)
        return -1;
    gpioDelay(20000);

    /* 4. Read 2 bytes (Temp MSB, Temp LSB) */
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;
    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
