    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sts40_read_temperature(float *temperature) {
    uint8_t cmd = 0x36;
    uint8_t buf[3];

    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: failed to write trigger command to STS40\n");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    ssize_t n = read(i2c_fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error: failed to read 3 bytes from STS40 (got %zd)\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on STS40 data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 100.0f;
    return 0;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_fp) {
        fprintf(log_fp, "%s, %.2f\n", ts, temperature);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: failed to open I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STS40_I2C_ADDR) < 0) {
        perror("Error: failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error: failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("STS40 temperature logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature;
        if (sts40_read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

