#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x61
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "scd40_error.log"
#define CSV_FILE "scd40_data.csv"
#define START_PERIODIC_CMD {0x21, 0x10, 0x00, 0x00}
#define STOP_PERIODIC_CMD  {0x21, 0x26, 0x00, 0x00}
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

typedef struct {
    unsigned short co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t buffer;
static pthread_t logging_thread;
static FILE *error_log_fp = NULL;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_log_fp) {
        fprintf(error_log_fp, "%s: %s\n", timestamp, message);
        fflush(error_log_fp);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_circular_buffer(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
    if (pthread_mutex_init(&buf->mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        return -1;
    }
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_function(void *arg) {
    (void)arg;
    while (running) {
        sleep(60);
        if (!running) break;
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        pthread_mutex_unlock(&buffer.mutex);
        if (count > 0) {
            char csv_path[256];
            snprintf(csv_path, sizeof(csv_path), "%s/%s", LOG_DIR, CSV_FILE);
            FILE *fp = fopen(csv_path, "a");
            if (!fp) {
                log_error("Failed to open CSV file for logging");
                continue;
            }
            if (fseek(fp, 0, SEEK_END) == 0) {
                long fsize = ftell(fp);
                if (fsize == 0) {
                    fprintf(fp, "timestamp,co2_ppm,temperature_c,humidity_pct\n");
                }
            }
            pthread_mutex_lock(&buffer.mutex);
            for (int i = 0; i < count; i++) {
                int idx = (buffer.head - count + i + BUFFER_SIZE) % BUFFER_SIZE;
                sensor_data_t *d = &buffer.data[idx];
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
                fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, d->co2, d->temperature, d->humidity);
            }
            pthread_mutex_unlock(&buffer.mutex);
            if (fclose(fp) != 0) {
                log_error("Failed to close CSV file");
            }
        }
    }
    return NULL;
}

static int send_command(const unsigned char *cmd, int len) {
    unsigned char buf[len + 1];
    for (int i = 0; i < len; i++) buf[i] = cmd[i];
    buf[len] = crc8(buf, len);
    if (i2cWriteDevice(i2c_handle, (char *)buf, len + 1) != (len + 1)) {
        log_error("Failed to send command to SCD40");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    unsigned char buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Failed to read data from SCD40");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC check failed for CO2 value");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        log_error("CRC check failed for temperature value");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        log_error("CRC check failed for humidity value");
        return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(STOP_PERIODIC_CMD, 2);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (error_log_fp) {
        fclose(error_log_fp);
        error_log_fp = NULL;
    }
    pthread_mutex_destroy(&buffer.mutex);
    if (logging_thread) {
        pthread_join(logging_thread, NULL);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (init_circular_buffer(&buffer) != 0) {
        cleanup();
        return 1;
    }
    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        log_error("Failed to create log directory");
        cleanup();
        return 1;
    }
    error_log_fp = fopen("/var/log/scd40_error.log", "a");
    if (!error_log_fp) {
        log_error("Failed to open error log file");
        cleanup();
        return 1;
    }
    if (send_command(START_PERIODIC_CMD, 2) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 1;
    }
    sleep(1);
    if (pthread_create(&logging_thread, NULL, logging_thread_function, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            add_to_buffer(&buffer, sensor_data);
        }
        sleep(5);
    }
    cleanup();
    return 0;
}

