            FILE *fp = fopen(csv_path, "a");
            if (!fp) {
                log_error("Failed to open CSV file for logging");
                continue;
            }
            if (fseek(fp, 0, SEEK_END) == 0) {
                long fsize = ftell(fp);
                if (fsize == 0) {
                    fprintf(fp, "timestamp,co2_ppm,temperature_c,humidity_pct\n");
                }
            }
            pthread_mutex_lock(&buffer.mutex);
            for (int i = 0; i < count; i++) {
                int idx = (buffer.head - count + i + BUFFER_SIZE) % BUFFER_SIZE;
                sensor_data_t *d = &buffer.data[idx];
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
                fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, d->co2, d->temperature, d->humidity);
            }
            pthread_mutex_unlock(&buffer.mutex);
            if (fclose(fp) != 0) {
                log_error("Failed to close CSV file");
            }
        }
    }
    return NULL;
}

static int send_command(const unsigned char *cmd, int len) {
    unsigned char buf[len + 1];
    for (int i = 0; i < len; i++) buf[i] = cmd[i];
    buf[len] = crc8(buf, len);
    if (i2cWriteDevice(i2c_handle, (char *)buf, len + 1) != (len + 1)) {
        log_error("Failed to send command to SCD40");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    unsigned char buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Failed to read data from SCD40");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC check failed for CO2 value");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        log_error("CRC check failed for temperature value");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        log_error("CRC check failed for humidity value");
        return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(STOP_PERIODIC_CMD, 2);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (error_log_fp) {
        fclose(error_log_fp);
        error_log_fp = NULL;
    }
    pthread_mutex_destroy(&buffer.mutex);
    if (logging_thread) {
        pthread_join(logging_thread, NULL);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (init_circular_buffer(&buffer) != 0) {
        cleanup();
        return 1;
    }
    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        log_error("Failed to create log directory");
        cleanup();
        return 1;
    }
    error_log_fp = fopen("/var/log/scd40_error.log", "a");
    if (!error_log_fp) {
        log_error("Failed to open error log file");
        cleanup();
        return 1;
    }
    if (send_command(START_PERIODIC_CMD, 2) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return 1;
    }
    sleep(1);
    if (pthread_create(&logging_thread, NULL, logging_thread_function, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            add_to_buffer(&buffer, sensor_data);
        }
        sleep(5);
    }
    cleanup();
    return 0;
}

