#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1.0
#define MEAS_DELAY_US  45000
#define READ_LEN       9

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* CRC-8 polynomial 0x31, initial value 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd = 0x361F;  /* continuous measurement, mass flow mode */
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 2) != 0) {
        fprintf(stderr, "Error writing trigger command to I2C device\n");
        return -1;
    }

    time_sleep(MEAS_DELAY_US / 1e6);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error reading 9 bytes from I2C device\n");
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }
    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    /* Validate CRC for scale factor (bytes 6-7, CRC byte 8) */
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temp     / 100.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,pressure_Pa,temperature_C\n");
    fflush(g_log_file);

    float pressure, temperature;

    while (g_running) {
        if (read_sdp810(&pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data; continuing\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

