#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0x2C
#define MEASURE_CMD_ARG 0x0D
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 15000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd[2] = {MEASURE_CMD, MEASURE_CMD_ARG};
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        unsigned int temp_ticks = (data[0] << 8) | data[1];
        unsigned int hum_ticks = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)temp_ticks / 65535.0f;
        *humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "SHT40 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static int create_server_socket(int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }

    return fd;
}

static void handle_client(int client_fd) {
    float temperature, humidity;
    char html[256];

    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        snprintf(html, sizeof(html),
                 "<html><head><title>SHT40 Sensor</title></head>"
                 "<body><h1>SHT40 Sensor</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p></body></html>",
                 temperature, humidity);
    } else {
        snprintf(html, sizeof(html),
                 "<html><head><title>SHT40 Sensor</title></head>"
                 "<body><h1>SHT40 Sensor</h1>"
                 "<p>Failed to read sensor data.</p></body></html>");
    }

    char response[512];
    int len = snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\n"
            "Content-Type: text/html\r\n"
            "Content-Length: %zu\r\n"
            "Connection: close\r\n"
            "\r\n%s", strlen(html), html);

    if (len > 0) {
        if (send(client_fd, response, len, 0) < 0) {
            perror("send");
        }
    }
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = create_server_socket(SERVER_PORT);
    if (server_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT40 HTTP server started on port %d. Press Ctrl+C to exit.\n", SERVER_PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

