/*
 * Raspberry Pi Zero W – HDC2010 temperature & humidity sensor reader
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL), address 0x40
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -lpigpio -lrt
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define HDC2010_ADDR   0x40

/* HDC2010 register addresses */
#define REG_TEMP_LOW    0x00
#define REG_TEMP_HIGH   0x01
#define REG_HUM_LOW     0x02
#define REG_HUM_HIGH    0x03
#define REG_MEAS_CFG    0x0E
#define REG_INT_CFG     0x0F

/* MEASUREMENT_CONFIG bit field */
#define MEAS_CFG_START  0x01
#define MEAS_CFG_T_EN   0x02
#define MEAS_CFG_H_EN   0x04
#define MEAS_CFG_MODE   0x00   /* continuous mode (bit 0 = 0) */

#define POLL_TIMEOUT_MS 500
#define POLL_DELAY_US   1000   /* 1 ms */
#define MAX_RETRIES     10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/* Write a single byte to a register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* HDC2010 sensor operations                                           */
/* ------------------------------------------------------------------ */

/*
 * Trigger a single measurement and wait for completion.
 * Returns 0 on success, -1 on error.
 */
static int hdc2010_trigger_measurement(int handle)
{
    uint8_t cfg = MEAS_CFG_START | MEAS_CFG_T_EN | MEAS_CFG_H_EN;
    if (reg_write(handle, REG_MEAS_CFG, cfg) != 0)
        return -1;

    /* Poll bit 0 of MEASUREMENT_CONFIG until it reads 0 (measurement done). */
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 10) {
        uint8_t cfg_val;
        if (reg_read(handle, REG_MEAS_CFG, &cfg_val) != 0)
            return -1;
        if ((cfg_val & MEAS_CFG_START) == 0)
            return 0;
        gpioDelay(POLL_DELAY_US); /* 1 ms */
    }

    fprintf(stderr, "[ERROR] HDC2010 measurement timeout (sensor may be absent or bus error)\n");
    return -1;
}

/*
 * Read temperature and humidity from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int hdc2010_read(int handle, float *temperature, float *humidity)
{
    uint8_t t_low, t_high, h_low, h_high;

    if (hdc2010_trigger_measurement(handle) != 0)
        return -1;

    if (reg_read(handle, REG_TEMP_LOW, &t_low) != 0) return -1;
    if (reg_read(handle, REG_TEMP_HIGH, &t_high) != 0) return -1;
    if (reg_read(handle, REG_HUM_LOW, &h_low) != 0) return -1;
    if (reg_read(handle, REG_HUM_HIGH, &h_high) != 0) return -1;

    uint16_t temp_raw  = ((uint16_t)t_high << 8) | t_low;
    uint16_t hum_raw   = ((uint16_t)h_high << 8) | h_low;

    *temperature = ((float)temp_raw / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)hum_raw  / 65536.0f) * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC2010 reader started on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, HDC2010_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int retries = 0;

        while (g_running && retries < MAX_RETRIES) {
            if (hdc2010_read(g_i2c_handle, &temperature, &humidity) == 0)
                break;
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(100000); /* 100 ms back-off */
        }

        if (g_running) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "\n[INFO] Shutting down cleanly.\n");
        }
    }

    /* --- Cleanup --- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

