#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x50
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MEAS_DELAY_US  45000    /* microseconds (45 ms)  */
#define MAX_RETRIES    3

/* SDP800-500Pa: 16-bit differential pressure, 16-bit temperature */
#define SDP800_CMD_READ 0x3608  /* continuous measurement, no averaging */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == expected);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Sensor may be absent or bus unavailable.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* --- send measurement command ---------------------------------- */
    uint8_t cmd[2] = {
        (uint8_t)((SDP800_CMD_READ >> 8) & 0xFF),
        (uint8_t)(SDP800_CMD_READ & 0xFF)
    };

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- wait for first measurement to complete --------------------- */
    gpioDelay(MEAS_DELAY_US);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint8_t buf[6];
        int n = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
        if (n != 6) {
            fprintf(stderr, "Error: I2C read returned %d bytes (expected 6).\n", n);
            gpioDelay(READ_INTERVAL);
            continue;
        }

        /* CRC checks */
        if (!crc8_check(&buf[0], 2, buf[2])) {
            fprintf(stderr, "Error: pressure CRC mismatch.\n");
            gpioDelay(READ_INTERVAL);
            continue;
        }
        if (!crc8_check(&buf[3], 2, buf[5])) {
            fprintf(stderr, "Error: temperature CRC mismatch.\n");
            gpioDelay(READ_INTERVAL);
            continue;
        }

        /* Convert raw values */
        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

        printf("Pressure: %6d  |  Temperature: %6d\n",
               raw_pressure, raw_temp);
        fflush(stdout);

        gpioDelay(READ_INTERVAL);
    }

    /* --- graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

