#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define SSR_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static float Kp = 10.0f, Ki = 0.1f, Kd = 0.01f;
static float integral = 0.0f, previous_error = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_thermocouple(float *temp_c) {
    char tx[3] = {0x00, 0x00, 0x00};
    char rx[3] = {0, 0, 0};
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    int16_t raw = ((int16_t)(rx[0] & 0xFF) << 8) | (rx[1] & 0xFF);
    if (raw & 0x0001) {
        fprintf(stderr, "Thermocouple fault detected (SCV or short)\n");
        return -1;
    }
    *temp_c = (float)raw * 0.25f;
    return 0;
}

static int control_ssr(float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    if (gpioWrite(SSR_PIN, duty > 0.0f ? 1 : 0) < 0) {
        fprintf(stderr, "Error writing SSR pin %d\n", SSR_PIN);
        return -1;
    }
    return 0;
}

static float pid_calculate(float setpoint, float actual) {
    float error = setpoint - actual;
    integral += error;
    if (integral > 100.0f) integral = 100.0f;
    if (integral < -100.0f) integral = -100.0f;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static int log_temperature(float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", ts, temp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int load_profile(float *temps, int *times, int max_points) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open profile file %s\n", PROFILE_FILE);
        return -1;
    }
    int count = 0;
    while (count < max_points) {
        int t, s;
        if (fscanf(fp, "%d,%d", &t, &s) != 2) break;
        if (t <= 0) break;
        temps[count] = (float)s;
        times[count] = t;
        count++;
    }
    fclose(fp);
    return count;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SSR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting SSR pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SSR_PIN, 0);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    float temps[100], times[100];
    int n = load_profile(temps, times, sizeof(temps) / sizeof(temps[0]));
    if (n <= 0) {
        fprintf(stderr, "No valid profile loaded, using default PID\n");
    }
    float current_time = 0.0f;
    float target_temp = temps[0];
    int i = 0;
    while (running) {
        float temp;
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_thermocouple(&temp) == 0) break;
            retries++;
            gpioDelay(10000);
        }
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float pid_out = pid_calculate(target_temp, temp);
        float duty = pid_out;
        if (control_ssr(duty) != 0) {
            fprintf(stderr, "SSR control error, continuing\n");
        }
        if (log_temperature(temp) != 0) {
            fprintf(stderr, "Logging error, continuing\n");
        }
        current_time += SAMPLE_INTERVAL_US / 1000000.0f;
        while (i < n && current_time >= times[i]) {
            target_temp = temps[i];
            i++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(SSR_PIN, 0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

