#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>
#include <linux/pwmchip.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_BUS "/dev/w1-therm"
#define DS18B20_ID_PREFIX "28-"
#define DS18B20_TEMP_REG "temperature"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int w1_fd = -1;
static int pwm_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static int w1_read_temp(const char *id, float *temp) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/w1_slave", W1_DEVICES_DIR, id);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        log_message("Error opening DS18B20 w1_slave");
        return -1;
    }
    char buf[256];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n < 0) {
        log_message("Error reading DS18B20 w1_slave");
        return -1;
    }
    buf[n] = '\0';
    if (strstr(buf, "YES") == NULL) {
        log_message("DS18B20 CRC check failed");
        return -1;
    }
    char *t = strstr(buf, "t=");
    if (!t) {
        log_message("DS18B20 temperature not found");
        return -1;
    }
    long v = strtol(t + 2, NULL, 10);
    *temp = v / 1000.0f;
    return 0;
}

static int pwm_set_duty(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    unsigned int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    struct pwm_state state;
    state.duty_cycle = duty_ns;
    state.period = PWM_PERIOD_NS;
    state.enabled = 1;
    if (ioctl(pwm_fd, PWM_IOCTL_SETSTATE, &state) < 0) {
        log_message("Error setting PWM state");
        return -1;
    }
    return 0;
}

static int pwm_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/dev/pwmchip%d", PWM_CHIP);
    pwm_fd = open(path, O_RDWR);
    if (pwm_fd < 0) {
        log_message("Error opening PWM device");
        return -1;
    }
    struct pwm_device *pwm = pwm_get_device(pwm_fd, PWM_CHANNEL);
    if (!pwm) {
        log_message("Error getting PWM device");
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    if (pwm_init(pwm) < 0) {
        log_message("Error initializing PWM device");
        pwm_put_device(pwm);
        close(pwm_fd);
        pwm_fd = -1;
        return -1;
    }
    pwm_put_device(pwm);
    return 0;
}

static int spi_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/dev/spidev0.0");
    spi_fd = open(path, O_RDWR);
