static int w1_read_temp(const char *id, float *temp) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/w1_slave", W1_DEVICES_DIR, id);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        log_message("Error opening DS18B20 w1_slave");
        return -1;
    }
    char buf[256];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n < 0) {
        log_message("Error reading DS18B20 w1_slave");
        return -1;
    }
    buf[n] = '\0';
    if (strstr(buf, "YES") == NULL) {
        log_message("DS18B20 CRC check failed");
        return -1;
    }
