#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_DEHUMIDIFIER 17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MEAS_DELAY_US  80000
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int aht20_read(int fd, float *humidity) {
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, 0xAC) != 0) {
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_write_cmd(fd, 0x33) != 0) {
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEAS_DELAY_US);

        if (i2c_read_data(fd, buf, 6) != 0) {
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 busy or error status: 0x%02X\n", buf[0]);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4)  |
                       ((uint32_t)buf[3] >> 4);
        *humidity = (float)raw / 1048576.0f * 100.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH) {
        gpioWrite(GPIO_DEHUMIDIFIER, 1);
        printf("Humidity %.2f%% > %.1f%% -> dehumidifier ON\n", humidity, HUMIDITY_HIGH);
    } else if (humidity < HUMIDITY_LOW) {
        gpioWrite(GPIO_DEHUMIDIFIER, 0);
        printf("Humidity %.2f%% < %.1f%% -> dehumidifier OFF\n", humidity, HUMIDITY_LOW);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (aht20_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialisation failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_DEHUMIDIFIER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_DEHUMIDIFIER);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_DEHUMIDIFIER, 0);

    printf("AHT20 dehumidifier controller started. Polling every %d s.\n", POLL_INTERVAL);

    while (g_running) {
        float humidity;
        if (aht20_read(g_i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down cleanly...\n");
    gpioWrite(GPIO_DEHUMIDIFIER, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

