    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (aht20_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialisation failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_DEHUMIDIFIER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_DEHUMIDIFIER);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_DEHUMIDIFIER, 0);

    printf("AHT20 dehumidifier controller started. Polling every %d s.\n", POLL_INTERVAL);

    while (g_running) {
        float humidity;
        if (aht20_read(g_i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down cleanly...\n");
    gpioWrite(GPIO_DEHUMIDIFIER, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

