#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_HUMIDITY_REG 0x00
#define HTU21D_MEASURE_HOLD 0xE0
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (sockfd >= 0) {
        close(sockfd);
        sockfd = -1;
    }
    closelog();
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: expected 3 bytes, got %zd: %s", reg, n, strerror(errno));
        return -1;
    }
    uint8_t msb = buf[0];
    uint8_t lsb = buf[1];
    uint8_t crc = buf[2];
    uint8_t crc_calc = 0;
    uint8_t data[0x00 | 0x02 | 0x03 | 0x04 | 0x06 | 0x07 | 0x08 | 0x09 | 0x0A | 0x0B | 0x0C | 0x0D | 0x0F | 0x10 | 0x11 | 0x12 | 0x13 | 0x14 | 0x16 | 0x17 | 0x18 | 0x19 | 0x1A | 0x1B | 0x1D | 0x1E | 0x1F | 0x20 | 0x21 | 0x22 | 0x23 | 0x24 | 0x26 | 0x27 | 0x28 | 0x29 | 0x2A | 0x2B | 0x2D | 0x2E | 0x2F | 0x30 | 0x31 | 0x32 | 0x33 | 0x34 | 0x36 | 0x37 | 0x38 | 0x39 | 0x3A | 0x3B | 0x3D | 0x3E | 0x3F | 0x40 | 0x41 | 0x42 | 0x43 | 0x44 | 0x46 | 0x47 | 0x48 | 0x49 | 0x4A | 0x4B | 0x4D | 0x4E | 0x4F | 0x50 | 0x51 | 0x52 | 0x53 | 0x54 | 0x56 | 0x57 | 0x58 | 0x59 | 0x5A | 0x5B | 0x5D | 0x5E | 0x5F | 0x60 | 0x61 | 0x62 | 0x63 | 0x64 | 0x66 | 0x67 | 0x68 | 0x69 | 0x6A | 0x6B | 0x6D | 0x6E | 0x6F | 0x70 | 0x71 | 0x72 | 0x73 | 0x74 | 0x76 | 0x77 | 0x78 | 0x79 | 0x7A | 0x7B | 0x7D | 0x7E | 0x7F;
    for (int i = 0; i < 8; i++) {
        crc_calc = (crc_calc ^ (data[i] << (8 - i))) & 0xFF;
    }
    if (crc_calc != crc) {
        syslog(LOG_ERR, "CRC mismatch: calc=0x%02X recv=0x%02X", crc_calc, crc);
        return -1;
    }
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint16_t raw;
    if (i2c_read_reg16(fd, HTU21D_HUMIDITY_REG, &raw) != 0) {
        return -1;
    }
    raw &= 0xFFFC;
    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int send_http_post(float humidity) {
    char json[64];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        return -1;
    }
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    char request[256];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             API_ENDPOINT, strlen(json), json);
    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    char resp[1024];
    ssize_t n = recv(sockfd, resp, sizeof(resp) - 1, 0);
    if (n > 0) {
        resp[n] = '\0';
        syslog(LOG_INFO, "HTTP Response: %s", resp);
    } else if (n == 0) {
        syslog(LOG_INFO, "Server closed connection");
    } else {
        syslog(LOG_ERR, "Recv failed: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    close(sockfd);
    sockfd = -1;
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        return 1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    syslog(LOG_INFO, "HTU21D monitor started on %s", I2C_BUS);
    while (running) {
        float humidity;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_humidity(i2c_fd, &humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                syslog(LOG_WARNING, "Read failed, retrying (%d/%d)", retries, MAX_RETRIES);
                sleep(1);
            }
        }
        if (success) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (send_http_post(humidity) != 0) {
                syslog(LOG_ERR, "HTTP POST failed");
            }
        } else {
            syslog(LOG_ERR, "HTU21D read failed after %d retries", MAX_RETRIES);
        }
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }
    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

