#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID  0x58
#define BMP280_REG_ID   0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL  0xF4
#define BMP280_REG_DATA  0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB 0x88

#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t  t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data block.\n");
        return -1;
    }
    dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)dig_P6);
    var2 = var2 + ((var1 * ((int32_t)dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)dig_P4) << 16);
    var1 = (((((int32_t)dig_P3) * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) << 12) / (uint32_t)var1;
    var1 = (((int32_t)dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + dig_P7) >> 4));
    return p;
}

static int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_DATA, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data block.\n");
        return -1;
    }
    *raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static int log_pressure_data(float pressure_hpa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure_hpa);
    fclose(fp);
    return 0;
}

