#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR  0x38
#define PIR_LINE    17
#define I2C_DEV     "/dev/i2c-1"
#define LOG_DIR     "/var/log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int tmp117_init(int fd) {
    uint8_t id[2];
    if (i2c_read_reg(fd, 0x00, id, 2) < 0) return -1;
    if (id[0] != 0x11 || id[1] != 0x77) return -1;
    return 0;
}

static int tmp117_read_temp(int fd, float *temp) {
    uint8_t buf[2];
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg(fd, 0x00, buf, 2) == 0) {
            int16_t raw = (buf[0] << 8) | buf[1];
            *temp = raw * 0.0078125f;
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t buf[3];
    if (i2c_read_reg(fd, 0xAC, buf, 3) < 0) return -1;
    if (buf[0] & 0x01) return -1;
    if (i2c_write_reg(fd, 0xE5, 0x08) < 0) return -1;
    usleep(20000);
    return 0;
}

static int aht20_read_humidity(int fd, float *hum) {
    uint8_t buf[3];
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg(fd, 0xE5, buf, 3) == 0) {
            uint32_t raw = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | (buf[2] >> 4);
            *hum = (raw * 100.0f) / 1048576.0f;
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int pir_init(struct gpiod_line *line) {
    if (gpiod_line_request_input(line, "pir_sensor") < 0) return -1;
    return 0;
}

static int pir_read(struct gpiod_line *line) {
    int v = gpiod_line_get_value(line);
    if (v < 0) return -1;
    return v;
}

static void get_timestamp(char *ts, size_t len) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(ts, len, "%Y-%m-%d %H:%M:%S", tm);
}

static void get_filename(char *fn, size_t len) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(fn, len, "%Y-%m-%d.log", tm);
}

static int file_exists(const char *path) {
    return access(path, F_OK) == 0;
}

static void create_log_file(const char *fn) {
    FILE *fp = fopen(fn, "w");
    if (!fp) { perror("fopen"); return; }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("ioctl TMP117"); close(i2c_fd); return 1;
    }
    if (tmp117_init(i2c_fd) < 0) {
        fprintf(stderr, "TMP117 not detected\n");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl AHT20"); close(i2c_fd); return 1;
    }
    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 not detected\n");
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); close(i2c_fd); return 1; }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); close(i2c_fd); return 1; }
    if (pir_init(pir) < 0) {
        fprintf(stderr, "PIR not detected\n");
    }

    while (running) {
        char ts[32], fn[64];
        get_timestamp(ts, sizeof(ts));
        get_filename(fn, sizeof(fn));

        if (!file_exists(fn)) create_log_file(fn);

        float temp = 0.0f, hum = 0.0f, motion = 0.0f;
        int t_ok = tmp117_read_temp(i2c_fd, &temp);
        int h_ok = aht20_read_humidity(i2c_fd, &hum);
        int m_ok = (pir ? (pir_read(pir) ? 1.0f : 0.0f) : 0.0f);

        if (t_ok == 0 && h_ok == 0 && m_ok >= 0) {
            FILE *fp = fopen(fn, "a");
            if (fp) {
                fprintf(fp, "%s,%.2f,%.2f,%.0f\n", ts, temp, hum, m_ok);
                fclose(fp);
            }
        } else {
            fprintf(stderr, "Sensor read error: T=%d H=%d M=%d\n", t_ok, h_ok, m_ok);
        }

        sleep(1);
    }

    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

