#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, message);
    fflush(stdout);
}

static int set_motor(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int forward) {
    int ret;
    ret = gpiod_line_set_value(in1, forward ? 1 : 0);
    if (ret < 0) {
        log_event("Error: failed to set IN1");
        return -1;
    }
    ret = gpiod_line_set_value(in2, forward ? 0 : 1);
    if (ret < 0) {
        log_event("Error: failed to set IN2");
        return -1;
    }
    ret = gpiod_line_set_value(ena, 1);
    if (ret < 0) {
        log_event("Error: failed to set ENA high");
        return -1;
    }
    return 0;
}

static void stop_motor(struct gpiod_line *ena, struct gpiod_line *in1,
                       struct gpiod_line *in2) {
    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 0);
    gpiod_line_set_value(ena, 0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event("Error: cannot open gpiochip4");
        return EXIT_FAILURE;
    }

