    ena_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        log_event("Error: failed to get one or more GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain-sensor") < 0) {
        log_event("Error: failed to request rain sensor line as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(ena_line, "motor-ena", 0) < 0) {
        log_event("Error: failed to request ENA line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor-in1", 0) < 0) {
        log_event("Error: failed to request IN1 line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor-in2", 0) < 0) {
        log_event("Error: failed to request IN2 line as output");
        goto cleanup;
    }

