#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000

#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(long *user, long *nice, long *system,
                         long *idle, long *iowait, long *irq,
                         long *softirq, long *steal)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets /proc/stat");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    if (sscanf(line, "cpu  %ld %ld %ld %ld %ld %ld %ld %ld",
               user, nice, system, idle, iowait, irq, softirq, steal) != 8) {
        fprintf(stderr, "sscanf /proc/stat failed\n");
        return -1;
    }
    return 0;
}

static void set_led_color(int r, int g, int b)
{
    /* Common-anode LED: 0 = full on, 255 = full off */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void map_load_to_color(long prev_user, long prev_nice,
                              long prev_system, long prev_idle,
                              long prev_iowait, long prev_irq,
                              long prev_softirq, long prev_steal,
                              long curr_user, long curr_nice,
                              long curr_system, long curr_idle,
                              long curr_iowait, long curr_irq,
                              long curr_softirq, long curr_steal,
                              int *r, int *g, int *b)
{
    long prev_total = prev_user + prev_nice + prev_system + prev_idle +
                      prev_iowait + prev_irq + prev_softirq + prev_steal;
    long curr_total = curr_user + curr_nice + curr_system + curr_idle +
                      curr_iowait + curr_irq + curr_softirq + curr_steal;

    if (prev_total == 0) {
        *r = 0; *g = 0; *b = 0;
        return;
    }

    long delta_total = curr_total - prev_total;
    long delta_idle  = curr_idle  - prev_idle;

    double load = (double)delta_total / (double)prev_total;
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    if (load <= 0.5) {
        *r = 0;
        *g = (int)((load / 0.5) * 255.0);
        *b = 255 - (int)((load / 0.5) * 255.0);
    } else {
        *r = (int)(((load - 0.5) / 0.5) * 255.0);
        *g = 255 - (int)(((load - 0.5) / 0.5) * 255.0);
        *b = 0;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    set_led_color(0, 0, 0);

    long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0;
    long prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0;

    while (g_running) {
        long curr_user = 0, curr_nice = 0, curr_system = 0, curr_idle = 0;
        long curr_iowait = 0, curr_irq = 0, curr_softirq = 0, curr_steal = 0;

        if (read_cpu_load(&prev_user, &prev_nice, &prev_system,
                          &prev_idle, &prev_iowait, &prev_irq,
                          &prev_softirq, &prev_steal) != 0) {
            fprintf(stderr, "Failed to read CPU load; retrying next cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US);

        if (read_cpu_load(&curr_user, &curr_nice, &curr_system,
                          &curr_idle, &curr_iowait, &curr_irq,
                          &curr_softirq, &curr_steal) != 0) {
            fprintf(stderr, "Failed to read CPU load; retrying next cycle\n");
            continue;
        }

        int r, g, b;
        map_load_to_color(prev_user, prev_nice, prev_system, prev_idle,
                          prev_iowait, prev_irq, prev_softirq, prev_steal,
                          curr_user, curr_nice, curr_system, curr_idle,
                          curr_iowait, curr_irq, curr_softirq, curr_steal,
                          &r, &g, &b);

        set_led_color(r, g, b);
    }

    /* Graceful shutdown: turn LED off (all channels full off for common-anode) */
    set_led_color(255, 255, 255);
    gpioDelay(100000);
    set_led_color(255, 255, 255);

    gpioTerminate();
    return 0;
}

