#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD   1

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} FanData;

static FanData fan_buffer[BUFFER_SIZE];
static int     buffer_index = 0;
static int     buffer_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycle on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_max31855(uint8_t *data) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, handle);
        return -1;
    }

    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 4)\n", ret);
        spiClose(handle);
        return -1;
    }

    spiClose(handle);

    data[0] = (uint8_t)rx[0];
    data[1] = (uint8_t)rx[1];
    data[2] = (uint8_t)rx[2];
    data[3] = (uint8_t)rx[3];

    return 0;
}

static float process_temperature(const uint8_t *data) {
    if (data[3] & 0x01) {
        fprintf(stderr, "Warning: MAX31855 fault detected (bit 0 set)\n");
        return -273.15f;
    }

    int32_t raw = ((int32_t)data[0] << 16) |
                  ((int32_t)data[1] << 8)  |
                   (int32_t)data[2];

    raw >>= 4;

    if (raw & 0x00800000) {
        raw |= 0xFF000000;
    }

    int16_t thermocouple = (int16_t)(raw & 0x7FFF);
    int16_t cold_junction = (int16_t)((raw >> 15) & 0x7FFF);

    if (thermocouple & 0x8000) {
        thermocouple = (int16_t)(thermocouple & 0x7FFF);
    }

    float t = (float)thermocouple * 0.25f;
    if (cold_junction & 0x8000) {
        t += (float)cold_junction * 0.00390625f;
    }

    return t;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0f) {
        return 0;
    } else if (temperature < 40.0f) {
        return (int)((temperature - 25.0f) * 2.0f);
    } else if (temperature < 60.0f) {
        return (int)(50.0f + (temperature - 40.0f) * 10.0f);
    } else {
        return 255;
    }
}

static void update_fan(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty cycle %d\n", duty_cycle);
    }
}

static void store_data(float temperature, int duty_cycle) {
    fan_buffer[buffer_index].timestamp = time(NULL);
    fan_buffer[buffer_index].temperature = temperature;
    fan_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Fan Data Buffer (%d entries) ---\n", buffer_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&fan_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(ts, sizeof(ts), "INVALID");
        }
        printf("[%s] Temp: %.2f C, Duty: %d\n", ts, fan_buffer[idx].temperature, fan_buffer[idx].duty_cycle);
    }
    printf("-------------------------------------\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    uint8_t raw_data[4];
    float temperature;
    int duty_cycle;

    while (running) {
        if (read_max31855(raw_data) == 0) {
            temperature = process_temperature(raw_data);
            if (temperature > -273.0f) {
                duty_cycle = calculate_duty_cycle(temperature);
                update_fan(duty_cycle);
                store_data(temperature, duty_cycle);
            } else {
                fprintf(stderr, "Error: invalid temperature reading\n");
            }
        } else {
            fprintf(stderr, "Error: SPI read failed\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    update_fan(0);
    gpioTerminate();
    print_buffer();
    return 0;
}

