#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define GPIO_PIN 2
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    int v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC1); if (v < 0) return -1; c->ac1 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC2); if (v < 0) return -1; c->ac2 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC3); if (v < 0) return -1; c->ac3 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC4); if (v < 0) return -1; c->ac4 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC5); if (v < 0) return -1; c->ac5 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC6); if (v < 0) return -1; c->ac6 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_B1);  if (v < 0) return -1; c->b1  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_B2);  if (v < 0) return -1; c->b2  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MB);  if (v < 0) return -1; c->mb  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MC);  if (v < 0) return -1; c->mc  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MD);  if (v < 0) return -1; c->md  = (int16_t)v;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *ut = ((int32_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)};
    if (i2cWriteDevice(handle, cmd, 2) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *up = (((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (uint8_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int compute_b5(int32_t ut, const bmp180_cal_t *c, int32_t *b5) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    *b5 = x1 + x2;
    return 0;
}

static int compute_temperature(int32_t b5, const bmp180_cal_t *c, float *temp_c) {
    int32_t t = (b5 + 8) >> 4;
    *temp_c = (float)t / 10.0f;
    return 0;
}

static int compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c, float *pressure_pa) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)c->ac1 * 4 + x3) << BMP180_OSS + 2) >> 2;
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    *pressure_pa = (float)p;
    return 0;
}

static void log_data(float temp_c, float pressure_pa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp_c, pressure_pa);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) != 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL) != 0) {
        fprintf(stderr, "ISR setup failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log open failed\n");
        gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    int logging = 0;
    while (running) {
        if (logging) {
            int32_t ut, up, b5;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                if (compute_b5(ut, &cal, &b5) == 0) {
                    float temp_c, pressure_pa;
                    compute_temperature(b5, &cal, &temp_c);
                    compute_pressure(up, b5, &cal, &pressure_pa);
                    log_data(temp_c, pressure_pa);
                }
            }
            logging = 0;
        }
        gpioDelay(1000000);
    }
    gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

