        fprintf(stderr, "Log open failed\n");
        gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    int logging = 0;
    while (running) {
        if (logging) {
            int32_t ut, up, b5;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                if (compute_b5(ut, &cal, &b5) == 0) {
                    float temp_c, pressure_pa;
                    compute_temperature(b5, &cal, &temp_c);
                    compute_pressure(up, b5, &cal, &pressure_pa);
                    log_data(temp_c, pressure_pa);
                }
            }
            logging = 0;
        }
        gpioDelay(1000000);
    }
    gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

