#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR_DEFAULT  0x76
#define BMP280_I2C_ADDR_ALT      0x77
#define I2C_BUS                  "/dev/i2c-1"
#define LOG_FILE                 "weather_data.txt"
#define SAMPLE_INTERVAL_SEC      5

/* BMP280 registers */
#define BMP280_REG_ID            0xD0
#define BMP280_REG_RESET         0xE0
#define BMP280_REG_STATUS        0xF3
#define BMP280_REG_CTRL_MEAS     0xF4
#define BMP280_REG_CONFIG        0xF5
#define BMP280_REG_PRESS_MSB     0xF7
#define BMP280_REG_TEMP_MSB      0xFA
#define BMP280_REG_CALIB_00      0x88
#define BMP280_REG_CALIB_26      0xE1

#define BMP280_CHIP_ID           0x58
#define BMP280_RESET_CMD         0xB6

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_burst(fd, BMP280_REG_ID, &id, 1) < 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) return -1;
    usleep(2000);

    uint8_t cfg[2];
    if (i2c_read_burst(fd, BMP280_REG_CONFIG, cfg, 2) < 0) return -1;
    /* t_sb=0.5ms, filter=4, spi3w_en=0 -> 0x24 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x24) < 0) return -1;

    /* ctrl_meas: osrs_t=1 (0.5ms), osrs_p=1 (0.5ms), mode=forced (0x01) -> 0x25 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x25) < 0) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, struct bmp280_calib *c) {
    uint8_t d[24];
    if (i2c_read_burst(fd, BMP280_REG_CALIB_00, d, 24) < 0) return -1;

    c->dig_T1 = (uint16_t)(d[0]  | (d[1]  << 8));
    c->dig_T2 = (int16_t)(d[2]  | (d[3]  << 8));
    c->dig_T3 = (int16_t)(d[4]  | (d[5]  << 8));
    c->dig_P1 = (uint16_t)(d[6]  | (d[7]  << 8));
    c->dig_P2 = (int16_t)(d[8]  | (d[9]  << 8));
