                    BMP280_I2C_ADDR_DEFAULT, strerror(errno));
            close(fd);
            return 1;
        }
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }

    struct bmp280_calib cal;
    if (bmp280_read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "BMP280 calibration read failed\n");
        close(fd);
        return 1;
    }

    while (g_running) {
