        if (bmp280_read(fd, &temp_c, &press_hpa) < 0) {
            fprintf(stderr, "BMP280 read failed; will retry next cycle\n");
        } else {
            if (log_data(temp_c, press_hpa) < 0) {
                fprintf(stderr, "Logging failed; will retry next cycle\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(fd);
    return 0;
}

