                printf("Temperature alert %s\n", alert_state ? "ON" : "OFF");
            }
        }
        gpioDelay(100000);  /* 100 ms */
    }
    return NULL;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_alert_tid != 0) {
        pthread_join(g_alert_tid, NULL);
        g_alert_tid = 0;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
