/*
 * LM75 temperature monitor for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - LM75 temperature sensor on I2C bus 1, address 0x48 (ADDR pin tied to GND).
 *   - Alert LED on GPIO18 (BCM), active-high.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 *
 * Run:
 *   sudo ./lm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS              1
#define LM75_ADDR            0x48
#define LM75_TEMP_REG        0x00
#define LM75_CONFIG_REG      0x01
#define LM75_CONFIG_HYS      0x00
#define LM75_CONFIG_FAULT    0x00
#define LM75_CONFIG_OS       0x00
#define LM75_CONFIG_SD       0x00
#define LM75_CONFIG_DEFAULT  (LM75_CONFIG_HYS | LM75_CONFIG_FAULT | LM75_CONFIG_OS | LM75_CONFIG_SD)

#define BUFFER_SIZE          60
#define TEMPERATURE_THRESHOLD 28.0f
#define ALERT_GPIO           18
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */
#define MAX_REINIT_ATTEMPTS  3

/* ------------------------------------------------------------------ */
/* Shared state                                                        */
/* ------------------------------------------------------------------ */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static pthread_t g_alert_tid;
static CircularBuffer g_temp_buf;

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex_init failed\n");
        abort();
    }
}

static void buffer_add(CircularBuffer *cb, float temp)
{
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    pthread_mutex_lock(&cb->mutex);
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    float avg = sum / (float)cb->count;
    pthread_mutex_unlock(&cb->mutex);
    return avg;
}

static void buffer_destroy(CircularBuffer *cb)
{
    pthread_mutex_destroy(&cb->mutex);
}

/* ------------------------------------------------------------------ */
/* LM75 helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit value to an LM75 register.
 * Returns 0 on success, -1 on error.
 */
static int lm75_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (i2cWriteDevice(fd, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an LM75 register.
 * Returns 0 on success, -1 on error.
 */
static int lm75_read_reg(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (i2cWriteDevice(fd, (char *)&reg_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(fd, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/*
 * Read the LM75 temperature register (0x00).
 * Returns 0 on success, -1 on error.
 */
static int lm75_read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (lm75_read_reg(fd, LM75_TEMP_REG, &raw) != 0)
        return -1;

    /* LM75: 12-bit two's-complement, left-justified in 16 bits. */
    int16_t signed_raw = (int16_t)raw;
    signed_raw >>= 4;
    if (signed_raw & 0x0800) {
        signed_raw |= 0xF000;  /* sign-extend */
    }
    *temp_c = (float)signed_raw * 0.125f;
    return 0;
}

/*
 * Initialize the LM75: set operating mode, fault queue, and hysteresis.
 * Returns 0 on success, -1 on error.
 */
static int lm75_init(int fd)
{
    uint16_t config = LM75_CONFIG_DEFAULT;
    if (lm75_write_reg(fd, LM75_CONFIG_REG, config) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Alert thread                                                        */
/* ------------------------------------------------------------------ */

static void *alert_thread_fn(void *arg)
{
    (void)arg;
    int alert_state = 0;

    while (g_running) {
        float avg = buffer_average(&g_temp_buf);
        int new_state = (avg > TEMPERATURE_THRESHOLD) ? 1 : 0;

        if (new_state != alert_state) {
            if (gpioWrite(ALERT_GPIO, new_state) != 0) {
                fprintf(stderr, "Error: gpioWrite(%d) failed\n", ALERT_GPIO);
            } else {
                alert_state = new_state;
                printf("Temperature alert %s\n", alert_state ? "ON" : "OFF");
            }
        }
        gpioDelay(100000);  /* 100 ms */
    }
    return NULL;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_alert_tid != 0) {
        pthread_join(g_alert_tid, NULL);
        g_alert_tid = 0;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    buffer_destroy(&g_temp_buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LM75 init --- */
    if (lm75_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Error: LM75 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    buffer_init(&g_temp_buf);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Launch alert thread --- */
    if (pthread_create(&g_alert_tid, NULL, alert_thread_fn, NULL) != 0) {
        fprintf(stderr, "Error: pthread_create failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75 temperature monitor started. Sampling every 1 s. Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float temp;
        if (lm75_read_temperature(g_i2c_fd, &temp) == 0) {
            buffer_add(&g_temp_buf, temp);
            printf("Temperature: %.2f °C  (avg %.2f °C)\n",
                   temp, buffer_average(&g_temp_buf));
        } else {
            fprintf(stderr, "Error: temperature read failed; re-initialising I2C...\n");
            i2cClose(g_i2c_fd);
            g_i2c_fd = -1;
            int attempt;
            for (attempt = 0; attempt < MAX_REINIT_ATTEMPTS && g_running; attempt++) {
                gpioDelay(500000);  /* 0.5 s */
                g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
                if (g_i2c_fd >= 0) {
                    if (lm75_init(g_i2c_fd) == 0) {
                        printf("I2C re-initialised.\n");
                        break;
                    }
                    fprintf(stderr, "Error: LM75 re-init failed; will retry.\n");
                    i2cClose(g_i2c_fd);
                    g_i2c_fd = -1;
                } else {
                    fprintf(stderr, "Error: i2cOpen failed (attempt %d/%d): %s\n",
                            attempt + 1, MAX_REINIT_ATTEMPTS, strerror(errno));
                }
            }
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Error: I2C re-initialisation failed after %d attempts; exiting.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
