#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (write(fd, (uint8_t[]){BMP180_REG_CAL_AC1}, 1) != 1) return -1;
    if (read(fd, buf, 22) != 22) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    *b1  = (int16_t)((buf[12] << 8) | buf[13]);
    *b2  = (int16_t)((buf[14] << 8) | buf[15]);
    *mb  = (int16_t)((buf[16] << 8) | buf[17]);
    *mc  = (int16_t)((buf[18] << 8) | buf[19]);
    *md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (write(fd, (uint8_t[]){BMP180_REG_MSB}, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) < 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (write(fd, (uint8_t[]){BMP180_REG_MSB}, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int compute_b5(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md, int32_t *b5) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *b5 = x1 + x2;
    return 0;
}

static int compute_temperature(int32_t b5, int16_t *temp) {
    *temp = (int16_t)(((b5 + 8) >> 4) / 10);
    return 0;
}

static int compute_pressure(int32_t up, int32_t b5, int16_t ac1, int16_t ac2, int16_t ac3, uint16_t ac4, uint16_t ac5, uint16_t ac6, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md, int32_t *pressure) {
    int32_t x1 = ((b5 + 8) >> 4) - 4000;
    int32_t x2 = (x1 * x1 * (int32_t)ac2) >> 11;
    x2 = x2 + (x1 * (int32_t)ac1 * 2);
    x2 = (x2 >> 2) + ((int32_t)ac3 * 4096);
    int32_t b3 = (((int32_t)ac1 * 4 + x2) << 1) / 4;
    x1 = ((int32_t)ac4 * (b5 + 8)) >> 15;
    x2 = ((int32_t)mc * (b5 + 4000)) >> 11;
    int32_t b4 = (x1 + x2) >> 1;
    int32_t b7 = ((int32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    *pressure = p;
    return 0;
}

static int log_breach(float temp, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, pressure) < 0) return -1;
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration_data(i2c_fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen breach_log.txt");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 on /dev/i2c-1. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t ut, up, b5;
        int16_t temp;
        int32_t pressure;

        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_raw_temperature(i2c_fd, &ut) == 0 && read_raw_pressure(i2c_fd, &up) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "I2C read error (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            usleep(100000);
        }

        if (!ok) {
