#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS0   0x34

#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_US      500000

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t data_buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;

static int  i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Calibration coefficients */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t reg = BMP180_REG_CAL_AC1;
    uint8_t buf[22];

    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set calibration register pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22 bytes of calibration data\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    uint8_t cmd = BMP180_CMD_TEMP;
    uint8_t buf[2];

    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);

    if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESS_OSS0;
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *up >>= 8;
    return 0;
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;

    if (read_raw_temperature(&ut) != 0) {
        return;
    }
    if (read_raw_pressure(&up) != 0) {
        return;
    }

    float temperature = calculate_temperature(ut);
    float pressure    = calculate_pressure(up, ut);

    time_t now = time(NULL);
    data_buffer[buffer_index].timestamp  = now;
    data_buffer[buffer_index].temperature = temperature;
    data_buffer[buffer_index].pressure    = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
    fflush(stdout);

    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set timer function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        sleep(1);
    }

    gpioWrite(FAN_GPIO, 0);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

