#define PWM_RANGE   100
#define PWM_FREQ    1000
#define LOG_FILE    "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioPWM(RELAY_GPIO, 0);
        gpioTerminate();
    }
}

static int read_max31855(uint32_t *raw) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    *raw = ((uint32_t)(uint8_t)rx[0] << 24) |
           ((uint32_t)(uint8_t)rx[1] << 16) |
           ((uint32_t)(uint8_t)rx[2] << 8)  |
           ((uint32_t)(uint8_t)rx[3]);
    return 0;
}

static int check_fault(uint32_t raw) {
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        return -1;
    }
    if (raw & 0x00000004) {
        fprintf(stderr, "MAX31855 fault: short to GND\n");
        return -1;
    }
    if (raw & 0x00000002) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -1;
    }
    return 0;
}

static float raw_to_celsius(uint32_t raw) {
    int16_t temp = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp & 0x2000) {
        temp |= 0xC000;
    }
    return temp * 0.25f;
}

static int calculate_duty(float current_temp, float target_temp, float *duty) {
    float error = target_temp - current_temp;
    static float integral = 0.0f;
    static float prev_error = 0.0f;
    float derivative = error - prev_error;
    prev_error = error;
    integral += error;
    if (integral > MAX_DUTY) integral = MAX_DUTY;
    if (integral < 0.0f) integral = 0.0f;
    float p = 1.0f;
    float i = 0.1f;
    float d = 0.01f;
    *duty = p * error + i * integral + d * derivative;
    if (*duty > MAX_DUTY) *duty = MAX_DUTY;
    if (*duty < 0.0f) *duty = 0.0f;
    return 0;
}

static int log_data(float temp, float duty) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, duty);
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return 1;
    }
    gpioSetPWMrange(RELAY_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(RELAY_GPIO, PWM_FREQ);
    gpioPWM(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp,temperature_c,duty_percent\n");
    fflush(log_file);

    printf("Heater control started. Target: %.1f C, Max duty: %.0f%%\n", TARGET_TEMP, MAX_DUTY);

    while (running) {
        uint32_t raw = 0;
        if (read_max31855(&raw) != 0) {
            fprintf(stderr, "SPI read error, shutting down\n");
            break;
        }
        if (check_fault(raw) != 0) {
            fprintf(stderr, "MAX31855 fault, shutting down\n");
            break;
        }
        float temp = raw_to_celsius(raw);
        float duty = 0.0f;
        calculate_duty(temp, TARGET_TEMP, &duty);
        gpioPWM(RELAY_GPIO, (int)duty);
        log_data(temp, duty);
        printf("Temp: %.2f C, Duty: %.1f%%\n", temp, duty);
        time_sleep(1.0);
    }

    printf("\nShutting down...\n");
    gpioPWM(RELAY_GPIO, 0);
    cleanup();
    return 0;
}

