#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_temperature(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature");
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf temperature failed\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "fscanf temperature error\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose temperature");
        return -1;
    }

    return temp;
}

static void set_led_color(int r, int g, int b)
{
    set_pwm(RED_PIN,   r);
    set_pwm(GREEN_PIN, g);
    set_pwm(BLUE_PIN,  b);
}

static void cleanup(void)
{
    set_pwm(RED_PIN,   255);
    set_pwm(GREEN_PIN, 255);
    set_pwm(BLUE_PIN,  255);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int temp_milli = temp;
        int r, g, b;

        if (temp_milli < 40000) {
            r = 0;
            g = 0;
            b = 255;
        } else if (temp_milli < 60000) {
            r = 0;
            g = 255;
            b = 0;
        } else {
            r = 255;
            g = 0;
            b = 0;
        }

        set_led_color(r, g, b);
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_milli, r, g, b);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

