#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define MAX_JSON_LENGTH 256
#define MAX_RESPONSE_LENGTH 1024

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int timeout = 0;

    /* Send start signal: pull low for at least 1 ms, then high */
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); /* 2 ms low */
    gpioWrite(gpio, 1);
    gpioDelay(30);   /* 30 us high */

    /* Switch to input and wait for sensor response */
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);
    gpioDelay(40); /* Wait for sensor to pull low */

    /* Read 40 bits */
    while (bit_idx < 40) {
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            if (++timeout > 100) {
                return -1; /* Timeout waiting for low */
            }
            gpioDelay(1);
        }
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            if (++timeout > 100) {
                return -1; /* Timeout waiting for high */
            }
            gpioDelay(1);
        }
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            if (++timeout > 100) {
                return -1; /* Timeout waiting for low */
            }
            gpioDelay(1);
        }

        /* Determine bit value: high duration > low duration */
        if (timeout > 50) {
            data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
        }
        bit_idx++;
    }

    /* Validate checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2;
    }

    /* Convert data */
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    /* Validate ranges */
    if (*humidity < 0.0f || *humidity > 100.0f || *temperature < -40.0f || *temperature > 80.0f) {
        return -3;
    }

    return 0;
}

static int send_http_request(const char *url, const char *json_data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char response[MAX_RESPONSE_LENGTH];
    int ret = -1;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect failed");
        close(sockfd);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: yourserver.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        url, strlen(json_data), json_data);

    if (req_len < 0 || req_len >= (int)sizeof(request)) {
        fprintf(stderr, "Request buffer overflow\n");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, req_len) < 0) {
        perror("write failed");
        close(sockfd);
        return -1;
    }

    ssize_t total = 0;
    while ((total = read(sockfd, response + total, MAX_RESPONSE_LENGTH - total - 1)) > 0) {
        if (total == 0) break;
        if (total < 0) {
            perror("read failed");
            break;
        }
        total = total;
    }
    response[MAX_RESPONSE_LENGTH - 1] = '\0';

    if (total < 0) {
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    float temperature, humidity;
    char json_data[MAX_JSON_LENGTH];
    int retries = 0;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (!terminate) {
        int status = read_dht22(DHT22_GPIO, &temperature, &humidity);

        if (status == 0) {
            snprintf(json_data, sizeof(json_data),
                "{\"temperature\":%.1f,\"humidity\":%.1f}",
                temperature, humidity);

            for (retries = 0; retries < MAX_RETRIES && !terminate; retries++) {
                if (send_http_request(SERVER_URL, json_data) == 0) {
                    printf("Data sent successfully (attempt %d)\n", retries + 1);
                    break;
                }
                fprintf(stderr, "Failed to send data (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                if (retries < MAX_RETRIES - 1) {
                    sleep(1);
                }
            }

            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Failed to send data after %d attempts\n", MAX_RETRIES);
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor (code: %d)\n", status);
        }

        if (!terminate) {
            sleep(60);
        }
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return ret;
}

