#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE
#define BMP180_OSS              3
#define LOG_FILE                "pressure_log.txt"
#define BUTTON_GPIO             4
#define DEBOUNCE_US             200000
#define CONVERSION_DELAY_US     26000
#define POLL_INTERVAL_US        100000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_last_tick = 0;
static volatile int          g_logging_enabled = 0;
static int                   g_i2c_handle = -1;

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t g_cal;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t diff = tick - g_last_tick;
    if (diff < DEBOUNCE_US) return;
    g_last_tick = tick;
    g_logging_enabled = !g_logging_enabled;
    printf("Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
    fflush(stdout);
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    char buf[1];
    if (i2cReadDevice(handle, buf, 1) != 1) return -1;
    *out = (uint8_t)buf[0];
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd = 0x2E;
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2cReadByteData(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadByteData(handle, BMP180_REG_LSB) < 0) return -1;
    msb = (uint8_t)i2cReadByteData(handle, BMP180_REG_MSB);
    lsb = (uint8_t)i2cReadByteData(handle, BMP180_REG_LSB);
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    char cmd = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    uint8_t msb, lsb, xlsb;
    if (i2cReadByteData(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadByteData(handle, BMP180_REG_LSB) < 0) return -1;
    if (i2cReadByteData(handle, BMP180_REG_XLSB) < 0) return -1;
    msb = (uint8_t)i2cReadByteData(handle, BMP180_REG_MSB);
    lsb = (uint8_t)i2cReadByteData(handle, BMP180_REG_LSB);
    xlsb = (uint8_t)i2cReadByteData(handle, BMP180_REG_XLSB);
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else                 p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static int log_pressure(const char *filename, int32_t pressure) {
    FILE *fp = fopen(filename, "a");
    if (!fp) { perror("fopen"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) { perror("localtime_r"); fclose(fp); return -1; }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d Pa\n", ts, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (read_calibration(g_i2c_handle, &g_cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 logger started. Press button on GPIO 4 to toggle logging.\n");
    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(g_i2c_handle, &ut) < 0) {
                fprintf(stderr, "Temperature read failed\n");
            } else if (read_raw_pressure(g_i2c_handle, &up) < 0) {
                fprintf(stderr, "Pressure read failed\n");
            } else {
                int32_t p = compute_pressure(up, ut, &g_cal);
                if (log_pressure(LOG_FILE, p) < 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                } else {
                    printf("Logged: %d Pa\n", p);
                }
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

