#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <getopt.h>
#include <curl/curl.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 2000
#define READ_INTERVAL_S 10
#define DHT22_TIMEOUT_US 1000000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_RESP_LOW_US 80
#define DHT22_RESP_HIGH_US 80
#define DHT22_BIT_LOW_US 50
#define DHT22_BIT_HIGH_US 50
#define DHT22_TIMEOUT_COUNT 100

typedef struct {
    float humidity;
    float temperature;
    int error;
} DHT22Data;

static volatile sig_atomic_t program_running = 1;
static char *api_url = "http://your-the-librarys-API-call.com/api/humidity";
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void cleanup_resources(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    curl_global_cleanup();
}

static int read_dht22(struct gpiod_line *line, DHT22Data *data) {
    int i, j;
    int data_raw[5] = {0, 0, 0, 0, 0};
    struct timespec ts;
    long long start_time, end_time;
    long long elapsed_us;
    int timeout_count;

    memset(data, 0, sizeof(DHT22Data));

    if (gpiod_line_request_output(line, "dht22", 1) < 0) {
        log_message(LOG_ERR, "Failed to request line as output");
        return -1;
    }

    gpiod_line_set_value(line, 1);
    usleep(500000);

    gpiod_line_set_value(line, 0);
    usleep(DHT22_START_LOW_US);
    gpiod_line_set_value(line, 1);
    usleep(DHT22_START_HIGH_US);

    if (gpiod_line_request_input(line, "dht22") < 0) {
        log_message(LOG_ERR, "Failed to request line as input");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts);
    start_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;

    while (gpiod_line_get_value(line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            log_message(LOG_ERR, "clock_gettime failed");
            return -1;
        }
        end_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
        elapsed_us = end_time - start_time;
        if (elapsed_us > DHT22_TIMEOUT_US) {
            log_message(LOG_ERR, "DHT22 start signal low timeout");
            return -1;
        }
    }

    while (gpiod_line_get_value(line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            log_message(LOG_ERR, "clock_gettime failed");
            return -1;
        }
        end_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
        elapsed_us = end_time - start_time;
        if (elapsed_us > DHT22_TIMEOUT_US) {
            log_message(LOG_ERR, "DHT22 start signal high timeout");
            return -1;
        }
    }

    while (gpiod_line_get_value(line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            log_message(LOG_ERR, "clock_gettime failed");
            return -1;
        }
        end_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
        elapsed_us = end_time - start_time;
        if (elapsed_us > DHT22_TIMEOUT_US) {
            log_message(LOG_ERR, "DHT22 response low timeout");
            return -1;
        }
    }

    for (i = 0; i < 40; i++) {
        timeout_count = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                log_message(LOG_ERR, "clock_gettime failed");
                return -1;
            }
            end_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
            elapsed_us = end_time - start_time;
            if (elapsed_us > DHT22_TIMEOUT_US) {
                log_message(LOG_ERR, "DHT22 bit low timeout");
                return -1;
            }
            if (++timeout_count > DHT22_TIMEOUT_COUNT) {
                log_message(LOG_ERR, "DHT22 bit low timeout exceeded");
                return -1;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        start_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;

        timeout_count = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                log_message(LOG_ERR, "clock_gettime failed");
                return -1;
            }
            end_time = (long long)ts.tv_sec * 1000000LL + (long long)ts.tv_nsec / 1000LL;
            elapsed_us = end_time - start_time;
            if (elapsed_us > DHT22_TIMEOUT_US) {
                log_message(LOG_ERR, "DHT22 bit high timeout");
                return -1;
            }
            if (++timeout_count > DHT22_TIMEOUT_COUNT) {
                log_message(LOG_ERR, "DHT22 bit high timeout exceeded");
                return -1;
            }
        }

        if (end_time - start_time > DHT22_BIT_LOW_US) {
            data_raw[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if ((data_raw[0] + data_raw[1] + data_raw[2] + data_raw[3]) != data_raw[4]) {
        log_message(LOG_ERR, "DHT22 checksum failed");
        return -1;
    }

    data->humidity = (float)((data_raw[0] << 8) + data_raw[1]) / 10.0;
    data->temperature = (float)(((data_raw[2] & 0x7F) << 8) + data_raw[3]) / 10.0;
    if (data_raw[2] & 0x80) {
        data->temperature *= -1.0;
    }

    return 0;
}

static int post_data(const char *json_data) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        log_message(LOG_ERR, "Failed to initialize curl");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        log_message(LOG_ERR, "Failed to create curl headers");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, api_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;
    if (res != CURLE_OK) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        log_message(LOG_ERR, error_message);
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            ret = 0;
        } else {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "HTTP error: %ld", http_code);
            log_message(LOG_ERR, error_message);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

static int read_dht22_with_retry(struct gpiod_line *line, DHT22Data *data) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES && result != 0) {
        result = read_dht22(line, data);
        if (result != 0) {
            retries++;
            if (retries < MAX_RETRIES) {
                log_message(LOG_WARNING, "DHT22 read failed, retrying...");
                usleep(RETRY_DELAY_MS * 1000);
            }
        }
    }

    if (result == 0) {
        char json_data[128];
        snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f, \"temperature\": %.1f}", data->humidity, data->temperature);
        log_message(LOG_INFO, json_data);
        if (post_data(json_data) != 0) {
            log_message(LOG_ERR, "Failed to post data");
        }
    } else {
        log_message(LOG_ERR, "DHT22 read failed after all retries");
    }

    return result;
}

static void parse_arguments(int argc, char *argv[], char **api_url_ptr) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                *api_url_ptr = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    parse_arguments(argc, argv, &api_url);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        log_message(LOG_ERR, "curl_global_init failed");
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip0");
        cleanup_resources();
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        log_message(LOG_ERR, "Failed to get GPIO line 4");
        cleanup_resources();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "DHT22 monitor started");

    while (program_running) {
        DHT22Data data;
        if (read_dht22_with_retry(line, &data) != 0) {
            log_message(LOG_ERR, "Failed to read DHT22 sensor");
        }
        sleep(READ_INTERVAL_S);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup_resources();
    closelog();
    return EXIT_SUCCESS;
}

