    } else {
        log_message(LOG_ERR, "DHT22 read failed after all retries");
    }

    return result;
}

static void parse_arguments(int argc, char *argv[], char **api_url_ptr) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                *api_url_ptr = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    parse_arguments(argc, argv, &api_url);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        log_message(LOG_ERR, "curl_global_init failed");
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip0");
        cleanup_resources();
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        log_message(LOG_ERR, "Failed to get GPIO line 4");
        cleanup_resources();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "DHT22 monitor started");

    while (program_running) {
        DHT22Data data;
        if (read_dht22_with_retry(line, &data) != 0) {
            log_message(LOG_ERR, "Failed to read DHT22 sensor");
        }
        sleep(READ_INTERVAL_S);
    }

    log_message(LOG_INFO, "Shutting down");
    cleanup_resources();
    closelog();
    return EXIT_SUCCESS;
}

