#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_SPEED_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define TEMP_THRESHOLD_1 45
#define TEMP_THRESHOLD_2 55
#define TEMP_THRESHOLD_3 65

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_file(const char *path, char *buffer, size_t buffer_size) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        return -1;
    }
    size_t bytes_read = fread(buffer, 1, buffer_size - 1, fp);
    fclose(fp);
    if (ferror(stdin)) {
        return -1;
    }
    buffer[bytes_read] = '\0';
    return 0;
}

static int write_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        return -1;
    }
    if (fputs(value, fp) == EOF) {
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        return -1;
    }
    return 0;
}

static int get_cpu_temperature(void) {
    char buffer[16];
    if (read_file(CPU_TEMP_PATH, buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    return atoi(buffer);
}

static int get_fan_speed(void) {
    char buffer[16];
    if (read_file(FAN_STATE_PATH, buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    return atoi(buffer);
}

static int set_fan_speed(int speed) {
    char value[16];
    snprintf(value, sizeof(value), "%d", speed);
    return write_file(FAN_STATE_PATH, value);
}

static int get_max_fan_speed(void) {
    char buffer[16];
    if (read_file(MAX_FAN_SPEED_PATH, buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    return atoi(buffer);
}

static int calculate_fan_speed(int cpu_temp) {
    if (cpu_temp < TEMP_THRESHOLD_1) {
        return 0;
    } else if (cpu_temp < TEMP_THRESHOLD_2) {
        return 1;
    } else if (cpu_temp < TEMP_THRESHOLD_3) {
        return 2;
    } else {
        return 3;
    }
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int cpu_temp = get_cpu_temperature();
        if (cpu_temp < 0) {
            fprintf(stderr, "Error reading CPU temperature: %s\n", strerror(errno));
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int current_speed = get_fan_speed();
        if (current_speed < 0) {
            fprintf(stderr, "Error reading current fan speed: %s\n", strerror(errno));
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int max_speed = get_max_fan_speed();
        if (max_speed < 0) {
            fprintf(stderr, "Error reading max fan speed: %s\n", strerror(errno));
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (max_speed == 0) {
            fprintf(stderr, "Error: max_state is 0, fan control not supported.\n");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_speed = calculate_fan_speed(cpu_temp);

        if (new_speed != current_speed) {
            if (set_fan_speed(new_speed) != 0) {
                fprintf(stderr, "Error setting fan speed to %d: %s\n", new_speed, strerror(errno));
            } else {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d", new_speed);
                log_event(log_message);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    log_event("Fan control shutting down.");
    set_fan_speed(0);
    return 0;
}

