#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000

#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_TO_GND 0x02
#define MAX31855_FAULT_SHORT_TO_VCC 0x04

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double previous_error;
} PIDController;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

static int read_max31855(double *temperature) {
    char buffer[4];
    int bytes_read = spiRead(spi_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: SPI read returned %d bytes (expected 4)\n", bytes_read);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        uint8_t fault = raw & 0x07;
        if (fault & MAX31855_FAULT_OPEN_CIRCUIT) {
            fprintf(stderr, "Error: MAX31855 open circuit fault\n");
        }
        if (fault & MAX31855_FAULT_SHORT_TO_GND) {
            fprintf(stderr, "Error: MAX31855 short to GND fault\n");
        }
        if (fault & MAX31855_FAULT_SHORT_TO_VCC) {
            fprintf(stderr, "Error: MAX31855 short to VCC fault\n");
        }
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static double calculate_pid(PIDController *pid, double setpoint, double measured_value) {
    double error = setpoint - measured_value;
    pid->integral += error;
    double derivative = error - pid->previous_error;
    double output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

static void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    PIDController pid = {1.0, 0.1, 0.01, 0.0, 0.0};

    while (running) {
        double temperature;
        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Error: Failed to read temperature from MAX31855\n");
            gpioPWM(HEATER_GPIO, 0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            sleep(1);
            continue;
        }

        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            fprintf(stderr, "Error: Temperature out of range (%.2f C) - failsafe disabled heater\n", temperature);
            gpioPWM(HEATER_GPIO, 0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            sleep(1);
            continue;
        }

        double pid_output = calculate_pid(&pid, TARGET_TEMPERATURE, temperature);
        int duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        if (gpioPWM(HEATER_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d\n", HEATER_GPIO);
        }

        log_data(temperature, duty_cycle, pid_output);
        sleep(1);
    }

    cleanup();
    return 0;
}

