        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Error: Failed to read temperature from MAX31855\n");
            gpioPWM(HEATER_GPIO, 0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            sleep(1);
            continue;
        }

        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            fprintf(stderr, "Error: Temperature out of range (%.2f C) - failsafe disabled heater\n", temperature);
            gpioPWM(HEATER_GPIO, 0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            sleep(1);
            continue;
        }

        double pid_output = calculate_pid(&pid, TARGET_TEMPERATURE, temperature);
        int duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        if (gpioPWM(HEATER_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d\n", HEATER_GPIO);
        }

        log_data(temperature, duty_cycle, pid_output);
        sleep(1);
    }

    cleanup();
    return 0;
}

