#define PWM_RANGE 100
#define TEMP_LOW 40.0
#define TEMP_HIGH 70.0
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_data(const char *timestamp, float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int set_fan_speed(float temperature) {
    int duty_cycle;

    if (temperature <= TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_HIGH) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * 100.0f);
    }

    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }

    return duty_cycle;
}

static float read_cpu_temperature(void) {
    FILE *fp = popen("vcgencmd measure_temp", "r");
    if (fp == NULL) {
        perror("Error executing vcgencmd");
        return -1.0f;
    }

    char buffer[16];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature from vcgencmd\n");
        pclose(fp);
        return -1.0f;
    }

    pclose(fp);

    char *temp_str = strstr(buffer, ".");
    if (temp_str == NULL) {
        fprintf(stderr, "Error parsing temperature from output\n");
        return -1.0f;
    }

