    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CPU temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = read_cpu_temperature();

        if (temperature < 0.0f) {
            fprintf(stderr, "Error reading CPU temperature. Skipping this cycle.\n");
        } else {
            int duty_cycle = set_fan_speed(temperature);

            if (duty_cycle >= 0) {
                time_t rawtime;
                time(&rawtime);
                struct tm *timeinfo = localtime(&rawtime);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                if (log_data(timestamp, temperature, duty_cycle) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }

                printf("%s - CPU: %.2f°C, Fan: %d%%\n", timestamp, temperature, duty_cycle);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan stopped and resources released.\n");

    return EXIT_SUCCESS;
}

