#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REV 360.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_position(double position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f\n", ts, position);
    } else {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_A);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_B);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_a = gpioRead(GPIO_A);
    int last_b = gpioRead(GPIO_B);
    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Failed to read initial GPIO state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double position = 0.0;
    int last_state = (last_a << 1) | last_b;

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "GPIO read error\n");
            break;
        }

        int current_state = (a << 1) | b;

        if (current_state != last_state) {
            int delta = current_state - last_state;
            int direction = (delta == 3 || delta == -1) ? 1 : -1;
            position += (double)direction / 4.0 * PULSES_PER_REV;
            if (position >= PULSES_PER_REV) position -= PULSES_PER_REV;
            if (position < 0.0) position += PULSES_PER_REV;

            if (log_position(position) != 0) {
                fprintf(stderr, "Failed to log position\n");
            }

            last_state = current_state;
        }

        gpioDelay(10000);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

