        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_fp, "# timestamp,red,ir\n");
    fflush(log_fp);

    while (running) {
        uint16_t red = 0, ir = 0;
        if (read_sensor_data(i2c_fd, &red, &ir) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        log_data(log_fp, red, ir);
        control_led(LED_GPIO, (ir > IR_THRESHOLD) ? 1 : 0);

        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    gpioWrite(LED_GPIO, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

