    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(AUDIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GAIN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GAIN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    int first_read = 1;

    while (running) {
        int current_state = gpioRead(AUDIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", AUDIO_PIN);
            break;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else if (current_state == 1 && last_state == 0) {
            if (log_event(1) != 0) {
