    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *flow_rate = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a successful reading to the CSV file                            */
/* ------------------------------------------------------------------ */
static int log_flow_rate(uint16_t flow_rate)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%u\n", ts, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush log file failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file once in append mode --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Write CSV header if file is empty --- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_file);
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; Ctrl+C will not clean up\n");
    }

    /* --- Start continuous measurement --- */
    if (write_command(CMD_CONT_MEAS) != 0) {
        fprintf(stderr, "[FATAL] Failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- First measurement is available after ~45 ms --- */
    gpioDelay(50000);  /* 50 ms */

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t flow_rate = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(&flow_rate) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);  /* 10 ms backoff before retry */
        }

        if (ok) {
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "[WARN] Logging failed for reading %u\n", flow_rate);
            }
        } else {
            fprintf(stderr, "[WARN] All %d read attempts failed; will retry next cycle\n",
                    MAX_RETRIES);
        }

        /* Sleep 1 s (interruptible by signals) */
        if (g_running)
            gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown --- */
    fprintf(stderr, "\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

