/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register                                   */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte(reg 0x%02X) failed: %d\n", reg, rc);
        return -1;
    }

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "i2cReadDevice(reg 0x%02X) failed: got %d bytes\n", reg, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2)
{
    if (read_reg16(handle, REG_TVOC, tvoc) < 0)
        return -1;
    if (read_reg16(handle, REG_ECO2, eco2) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute IAQ index (placeholder: average of TVOC and eCO2)           */
/* ------------------------------------------------------------------ */
static int compute_iaq_index(uint16_t tvoc, uint16_t eco2)
{
