    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,iaq_index,tvoc_ppb,eco2_ppm\n");
        fflush(g_log_file);
    }

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MICS-VZ-89TE air quality logger started.  Bus=%d  Addr=0x%02X  Log=%s\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        rc = read_sensor_data(g_i2c_handle, &tvoc, &eco2);
        if (rc == 0) {
            int iaq = compute_iaq_index(tvoc, eco2);
            if (log_data(g_log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("TVOC=%u ppb  eCO2=%u ppm  IAQ=%d\n", tvoc, eco2, iaq);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep SAMPLE_INTERVAL_SEC, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

