#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        17
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define ALERT_THRESHOLD_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, NULL, "ttp223_tamper") != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", GPIO_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_PIN);
    fflush(stdout);

    int alert_active = 0;
    time_t alert_start = 0;

    while (g_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                    GPIO_PIN, strerror(errno));
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (level == 1) {
            if (!alert_active) {
                alert_active = 1;
                alert_start = time(NULL);
                printf("Intrusion detected!\n");
                fflush(stdout);
            }
        } else {
            if (alert_active) {
                alert_active = 0;
            }
        }

        if (alert_active && (time(NULL) - alert_start) >= ALERT_THRESHOLD_S) {
            alert_active = 0;
            printf("Intrusion confirmed after %d seconds!\n", ALERT_THRESHOLD_S);
            fflush(stdout);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

