/*
 * Raspberry Pi 4 Model B – INMP441 I2S MEMS Microphone Capture
 *
 * Captures 16-bit PCM samples from the INMP441 over the I2S bus using the
 * Linux ALSA subsystem (/dev/snd/pcmC0D0c) and writes them to a raw PCM file.
 * The L/R channel-select line (GPIO 17, BCM) is driven to select the left
 * channel.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_capture audio_capture.c
 * Run:    ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/soundcard.h>
#include <pigpio.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define PCM_FILE        "audio_capture.pcm"
#define GPIO_CHANNEL    17
#define SAMPLE_RATE     48000
#define BITS_PER_SAMPLE 16
#define CHANNELS        1
#define BUFFER_SIZE     4096
#define SAMPLES_PER_BUF (BUFFER_SIZE / (CHANNELS * (BITS_PER_SAMPLE / 8)))

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
