#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define TIMEOUT_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan PWM pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_event("System started");

    int last_flame_state = 1;
    uint32_t last_change_tick = 0;

    while (program_running) {
        int flame_value = gpioRead(FLAME_SENSOR_PIN);
        if (flame_value < 0) {
            fprintf(stderr, "Error reading flame sensor\n");
            log_event("Error reading flame sensor");
            break;
        }

        uint32_t now_tick = gpioTick();
        if (now_tick == 0) {
            fprintf(stderr, "gpioTick failed\n");
            log_event("Error reading time");
            break;
        }

        if (flame_value != last_flame_state) {
            if (now_tick - last_change_tick > DEBOUNCE_DELAY_US) {
                last_flame_state = flame_value;
                last_change_tick = now_tick;

                if (flame_value == 0) {
                    log_event("Flame detected");
                    if (gpioPWM(FAN_PWM_PIN, 100) != 0) {
                        fprintf(stderr, "Failed to start PWM\n");
                        log_event("Error starting PWM");
                        break;
                    }
                } else {
                    log_event("Flame ended");
                    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
                        fprintf(stderr, "Failed to stop PWM\n");
                        log_event("Error stopping PWM");
                        break;
                    }
                }
            }
        }

        usleep(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return EXIT_SUCCESS;
}

