#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define SPI_FRAME_SIZE 32768
#define LOG_FILE_NAME "radar_data.bin"
#define CONFIG_MAGIC 0x41444D52414D4544ULL
#define CONFIG_VERSION 1

typedef struct {
    uint64_t magic;
    uint32_t version;
    uint32_t frame_rate;
    uint32_t chirp_count;
    uint32_t sample_count;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_bars;
    uint32_t num_bins;
    uint32_t num_frames;
    uint32_t frame_size;
    uint32_t padding[2];
} __attribute__((packed)) radar_config_t;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
    uint32_t num_bars;
    uint32_t num_bins;
    uint32_t frame_size;
    uint32_t padding[3];
    uint8_t data[SPI_FRAME_SIZE];
} __attribute__((packed)) radar_frame_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_FRAME_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_FRAME_TRIGGER);
        return -1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_DATA_READY);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_DATA_READY);
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int initialize_log_file(void) {
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

static int configure_radar(void) {
    radar_config_t config;
    config.magic = CONFIG_MAGIC;
    config.version = CONFIG_VERSION;
    config.frame_rate = 100;
    config.chirp_count = 64;
    config.sample_count = 256;
    config.start_frequency = 77000;
    config.end_frequency = 79000;
    config.num_bars = 16;
    config.num_bins = 128;
    config.num_frames = 100;
    config.frame_size = SPI_FRAME_SIZE;
    memset(config.padding, 0, sizeof(config.padding));

    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
