    }

    if (initialize_spi() < 0) {
        cleanup();
        return 1;
    }

    if (initialize_log_file() < 0) {
        cleanup();
        return 1;
    }

    if (configure_radar() < 0) {
        cleanup();
        return 1;
    }

    uint8_t frame_data[SPI_FRAME_SIZE];
    radar_frame_t radar_frame;
    radar_frame.timestamp = 0;
    radar_frame.frame_number = 0;
    radar_frame.num_bars = 0;
    radar_frame.num_bins = 0;
    radar_frame.frame_size = SPI_FRAME_SIZE;

