/*
 * KY-026 Flame Sensor monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND   (Pin 9)
 *   KY-026 D0   -> GPIO20 (BCM 20, Pin 38)
 *
 * The KY-026 digital output (D0) is active-high: 1 = flame detected,
 * 0 = no flame.  We log only state transitions to flame_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 20          /* BCM 20 */
#define LOG_FILE         "flame_log.txt"
#define POLL_INTERVAL_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("gmtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", ts, state ? "FLAME_DETECTED" : "FLAME_CLEARED") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* Get the BCM 20 line */
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    if (gpiod_line_request_input(line, "ky026-flame") != 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int prev_state = -1;   /* unknown initial state */

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val != prev_state) {
            if (log_state(val) != 0) {
                fprintf(stderr, "Failed to log state transition.\n");
            }
            prev_state = val;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

