#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x04
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_MANUFACTURER_ID 0x7E
#define REG_DEVICE_ID 0x7F
#define EXPECTED_MANUFACTURER_ID 0x5449
#define EXPECTED_DEVICE_ID 0x3001
#define CONFIG_VALUE 0x0003
#define LUX_DATA_SIZE 2
#define RETRY_DELAY_US 100000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int write_register16(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int read_lux(int handle, float *lux_out) {
    uint16_t raw;
    if (read_register16(handle, REG_RESULT, &raw) < 0) {
        return -1;
    }
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * (1 << exponent);
    return 0;
}

static int log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        return -1;
    }
    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", OPT3001_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t manuf_id = 0, device_id = 0;
    if (read_register16(i2c_handle, REG_MANUFACTURER_ID, &manuf_id) < 0 ||
        read_register16(i2c_handle, REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Failed to read OPT3001 ID registers (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (manuf_id != EXPECTED_MANUFACTURER_ID || device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected OPT3001 ID: manuf=0x%04X dev=0x%04X (expected 0x5449 0x3001)\n",
                manuf_id, device_id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_register16(i2c_handle, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to write OPT3001 config register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open light_data.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging lux data to light_data.txt. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_lux(i2c_handle, &lux) < 0) {
            fprintf(stderr, "Error reading lux value. Retrying in 100ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (log_data(log_file, lux) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

