/*
 * Raspberry Pi 3 Model B+ — SainSmart IR Flame Detection Sensor Module
 *
 * Wiring:
 *   Sensor VCC  -> 3.3 V (Pin 1)
 *   Sensor GND  -> GND   (Pin 9)
 *   Sensor DOUT -> GPIO17 (BCM 17, Pin 11) — active-low, 0 = flame detected
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   sudo ./flame_detect   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    if (signum == SIGINT) {
        g_running = 0;
    }
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("%s", buf);
            return;
        }
    }
    /* Fallback: print seconds since epoch */
    printf("%ld", (long)rawtime);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install SIGINT handler for clean shutdown */
    if (install_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with pull-up bias (active-low sensor) */
    ret = gpiod_line_request_input_flags(line, "flame-sensor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        printf(" Flame Detected: %s\n",
               (value == 0) ? "YES" : "NO");
        fflush(stdout);

        /* Sleep for 1 second, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

