#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN   17
#define CENTER_PIN 18
#define RIGHT_PIN  27
#define POLL_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-downs so the pins read LOW when the sensor
     * output is idle (open-collector / open-drain). */
    if (gpioSetPullUpDown(LEFT_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(CENTER_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int left   = gpioRead(LEFT_PIN);
        int center = gpioRead(CENTER_PIN);
        int right  = gpioRead(RIGHT_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: gpioRead failed (left=%d, center=%d, right=%d).\n",
                    left, center, right);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

