#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void)
{
    struct gpio_chip *chip = NULL;
    struct gpio_line *lines[NUM_CHANNELS];
    int line_num;
    int ret;

    for (line_num = 0; line_num < NUM_CHANNELS; line_num++)
        lines[line_num] = NULL;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiochipOpen(0);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Request each GPIO line as input */
    for (line_num = 0; line_num < NUM_CHANNELS; line_num++) {
        lines[line_num] = gpioLineOpenInput(chip, gpio_pins[line_num]);
        if (lines[line_num] == NULL) {
            fprintf(stderr, "Error: failed to open GPIO line %u\n", gpio_pins[line_num]);
            goto cleanup;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (line_num = 0; line_num < NUM_CHANNELS; line_num++) {
            ret = gpioLineGetValue(lines[line_num]);
            if (ret < 0) {
                fprintf(stderr, "Error: failed to read GPIO line %u (channel %d)\n",
                        gpio_pins[line_num], line_num + 1);
                read_ok = 0;
                break;
            }
            values[line_num] = ret;
        }

        if (!read_ok) {
            gpiochipClose(chip);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        print_timestamp();
        printf("Channel 1: %d, Channel 2: %d, Channel 3: %d, Channel 4: %d, "
               "Channel 5: %d, Channel 6: %d, Channel 7: %d, Channel 8: %d\n",
               values[0], values[1], values[2], values[3], values[4],
               values[5], values[6], values[7]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release all line handles */
    for (line_num = 0; line_num < NUM_CHANNELS; line_num++) {
        if (lines[line_num] != NULL)
            gpioLineClose(lines[line_num]);
    }

    /* Close GPIO chip */
    if (chip != NULL)
        gpiochipClose(chip);

    /* Terminate pigpio library */
    gpioTerminate();

    return EXIT_SUCCESS;
}

