/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (TTP226 OUT -> Pi BCM pin):
 *   CH1 -> GPIO2  (pin 3)
 *   CH2 -> GPIO3  (pin 5)
 *   CH3 -> GPIO4  (pin 7)
 *   CH4 -> GPIO17 (pin 11)
 *   CH5 -> GPIO27 (pin 13)
 *   CH6 -> GPIO22 (pin 15)
 *   CH7 -> GPIO10 (pin 19)
 *   CH8 -> GPIO9  (pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lpigpio -lrt
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */

static const unsigned int sensor_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_pins[i] != 0) {
            gpioSetMode(sensor_pins[i], PI_INPUT);
        }
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure each sensor pin as an input with bias disabled. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr,
                    "Error: gpioSetMode failed for BCM pin %u.\n",
                    sensor_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr,
                    "Error: gpioSetPullUpDown failed for BCM pin %u.\n",
                    sensor_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(sensor_pins[i]);
            if (level < 0) {
                fprintf(stderr,
                        "Warning: gpioRead failed for BCM pin %u (ch %d).\n",
                        sensor_pins[i], i + 1);
                level = 0;  /* treat read error as 'not touched' */
            }
            printf("%s,%d", (i == 0) ? timestamp : "", level);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

