/*
 * Raspberry Pi Zero W — Omron D7E-1 tilt sensor reader
 *
 * Wiring:
 *   D7E-1 VCC  -> 3V3 (pin 1)
 *   D7E-1 GND  -> GND (pin 6)
 *   D7E-1 OUT  -> GPIO4 (BCM pin 7, physical pin 7)
 *
 * The internal pull-up is enabled so the pin reads HIGH when the
 * tilt switch is open (no tilt) and LOW when it is closed (tilted).
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt tilt.c -lpigpio -lrt
 * Run:    sudo ./tilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TILT_PIN 4          /* BCM pin 7, physical pin 7 */
#define POLL_US   100000    /* 100 ms between polls */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(TILT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                TILT_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(TILT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n",
                TILT_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int rc = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (setup_gpio() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Tilt sensor monitoring started on GPIO%d (BCM).\n", TILT_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    int prev_state = -1;   /* force initial print */

    while (g_running) {
        int level = gpioRead(TILT_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d).\n",
                    TILT_PIN, level);
            rc = EXIT_FAILURE;
            break;
        }

        int current_state = (level == 0) ? 0 : 1;   /* LOW = tilted */

        if (current_state != prev_state) {
            printf("Tilt %s\n", current_state ? "Not Tilted" : "Tilted");
            fflush(stdout);
            prev_state = current_state;
        }

        gpioDelay(POLL_US);   /* 100 ms */
    }

cleanup:
    gpioTerminate();
    return rc;
}

