/* ------------------------------------------------------------------ */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(TILT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                TILT_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(TILT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n",
                TILT_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int rc = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (setup_gpio() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Tilt sensor monitoring started on GPIO%d (BCM).\n", TILT_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    int prev_state = -1;   /* force initial print */

    while (g_running) {
        int level = gpioRead(TILT_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d).\n",
                    TILT_PIN, level);
            rc = EXIT_FAILURE;
            break;
        }

        int current_state = (level == 0) ? 0 : 1;   /* LOW = tilted */

        if (current_state != prev_state) {
            printf("Tilt %s\n", current_state ? "Not Tilted" : "Tilted");
            fflush(stdout);
            prev_state = current_state;
        }

        gpioDelay(POLL_US);   /* 100 ms */
    }

cleanup:
    gpioTerminate();
    return rc;
}

