#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_UV_INDEX0 0x2C

#define HW_KEY_VAL 0x17
#define MEAS_RATE_VAL 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_HW_KEY, HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, REG_MEAS_RATE0, MEAS_RATE_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }

    return 0;
}

static int read_uv_index(int fd, float *uv_index) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, REG_UV_INDEX0, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, REG_UV_INDEX0 + 1, &high) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)high << 8) | low;
    *uv_index = (float)raw / 100.0f;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0 + 1, &high) < 0) {
        return -1;
    }
    *als_visible = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error: Failed to read UV index.\n");
        } else if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error: Failed to read ALS visible light.\n");
        } else {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        }

        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

