#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x50
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1
#define START_DELAY_MS 100
#define MEAS_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int slf3s_start(int fd)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    return i2c_write_byte(fd, cmd[0]) && i2c_write_byte(fd, cmd[1]);
}

static int slf3s_read_flow(int fd, float *flow_out)
{
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) != 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 1000.0f;
    return 0;
}

static void log_flow(float avg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s,%.2f\n", ts, avg);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (slf3s_start(g_i2c_fd) != 0) {
        fprintf(stderr, "Failed to start SLF3S sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioDelay(START_DELAY_MS * 1000);

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = slf3s_read_flow(g_i2c_fd, &flow1);
        int ok2 = slf3s_read_flow(g_i2c_fd, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (flow1 + flow2) / 2.0f;
            log_flow(avg);
            gpioWrite(ALARM_GPIO, (avg < FLOW_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioWrite(ALARM_GPIO, 0);
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            gpioDelay(MEAS_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

