        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (slf3s_start(g_i2c_fd) != 0) {
        fprintf(stderr, "Failed to start SLF3S sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioDelay(START_DELAY_MS * 1000);

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = slf3s_read_flow(g_i2c_fd, &flow1);
        int ok2 = slf3s_read_flow(g_i2c_fd, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            float avg = (flow1 + flow2) / 2.0f;
            log_flow(avg);
            gpioWrite(ALARM_GPIO, (avg < FLOW_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioWrite(ALARM_GPIO, 0);
        }

        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            gpioDelay(MEAS_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

