#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int value;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_timestamp(time_t ts) {
    struct tm tm_info;
    char buf[32];
    localtime_r(&ts, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s", buf);
}

static void dump_buffer(void) {
    printf("\n--- Sensor Data Dump (Oldest First) ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        print_timestamp(sensor_buffer[idx].timestamp);
        printf(" - Value: %d\n", sensor_buffer[idx].value);
    }
    printf("--- End of Dump ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

