    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("KY-033 Obstacle Avoidance Sensor Monitor\n");
    printf("Polling GPIO%d every %d ms. Press Ctrl+C to exit.\n",
           SENSOR_PIN, POLL_DELAY_US / 1000);

    while (running) {
        int value = gpioRead(SENSOR_PIN);
        if (value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            break;
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error: time() failed.\n");
            break;
        }

        sensor_buffer[buffer_index].timestamp = now;
        sensor_buffer[buffer_index].value = value;

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (value == 0) {
            printf("Obstacle detected!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    dump_buffer();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

