#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define MODE_REG       0x00
#define X_REG          0x02
#define Y_REG          0x04
#define Z_REG          0x06
#define MODE_ACTIVE    0x01
#define POLL_DELAY_MS  500
#define MAX_POLLS      20
#define CSV_FILE       "fan_health.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int sensor_init(int fd) {
    if (i2c_write_reg8(fd, MODE_REG, MODE_ACTIVE) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, X_REG, x) < 0) return -1;
    if (i2c_read_reg16(fd, Y_REG, y) < 0) return -1;
    if (i2c_read_reg16(fd, Z_REG, z) < 0) return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static int write_csv_header(FILE *f) {
    long pos = ftell(f);
    if (pos == 0) {
        if (fprintf(f, "timestamp,x,y,z\n") < 0) return -1;
        fflush(f);
    }
    return 0;
}

static void cleanup(void) {
    if (g_csv) { fclose(g_csv); g_csv = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor init failed (sensor not responding or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_csv_header(g_csv) < 0) {
        fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring D7S vibration sensor on %s (addr 0x%02X)...\n", I2C_BUS, D7S_ADDR);

    int polls = 0;
    while (g_running) {
        int16_t x, y, z;
        if (read_sensor_data(g_i2c_fd, &x, &y, &z) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (fprintf(g_csv, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
                fprintf(stderr, "CSV write failed: %s\n", strerror(errno));
            } else {
                fflush(g_csv);
            }
            printf("%s  X=%d  Y=%d  Z=%d\n", ts, x, y, z);
            polls = 0;
        } else {
            fprintf(stderr, "Sensor read error (attempt %d/%d)\n", polls + 1, MAX_POLLS);
            if (++polls >= MAX_POLLS) {
                fprintf(stderr, "Sensor not active after %d polls; aborting.\n", MAX_POLLS);
                break;
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

