#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started.\n");
    printf("  Sensor 1: GPIO%d\n", SENSOR_1_PIN);
    printf("  Sensor 2: GPIO%d\n", SENSOR_2_PIN);
    printf("  LED:      GPIO%d\n", LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int exit_code = EXIT_SUCCESS;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d (code %d).\n",
                    SENSOR_1_PIN, s1);
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        if (s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d (code %d).\n",
                    SENSOR_2_PIN, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 OUT is active-LOW: 0 => obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, obstacle) != 0) {
            fprintf(stderr, "Warning: gpioWrite failed on GPIO%d (code %d).\n",
                    LED_PIN, obstacle);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: turn LED off and release pigpio resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nObstacle avoidance system stopped.\n");
    return exit_code;
}

