/*
 * TMAG5170-Q1 3D Hall-effect sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   TMAG5170 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   TMAG5170 VDD  -> 3.3 V
 *   TMAG5170 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_log mag_log.c -lpigpio -lrt
 * Run:    sudo ./mag_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170 register map (per TI datasheet) ---- */
#define TMAG5170_REG_DEVICE_CONFIG  0x00
#define TMAG5170_REG_DEVICE_ID     0x01
#define TMAG5170_REG_X_CH1_OUT     0x02
#define TMAG5170_REG_X_CH2_OUT     0x03
#define TMAG5170_REG_Y_CH1_OUT     0x04
#define TMAG5170_REG_Y_CH2_OUT     0x05
#define TMAG5170_REG_Z_CH1_OUT     0x06
#define TMAG5170_REG_Z_CH2_OUT     0x07

/* Device config: continuous conversion, all axes enabled, 50 mT range. */
#define TMAG5170_DEV_CONFIG_50MT   0x0000  /* bits[15:14]=00 (50 mT), bits[13:12]=00 (continuous), bits[11:8]=0000 (all axes) */

#define I2C_BUS        1
#define I2C_ADDR       0x0C              /* TMAG5170 default 7-bit I2C address */
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000            /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus unavailable.\n",
                g_i2c_handle);
        return -1;
    }

    /* Verify device identity by reading DEVICE_ID register (0x01).
     * Expected value: 0x51 for TMAG5170. */
    int16_t dev_id = 0;
    if (i2c_read_reg16(g_i2c_handle, TMAG5170_REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "Error: failed to read DEVICE_ID register.\n");
        return -1;
    }
    if (dev_id != 0x51) {
        fprintf(stderr, "Error: unexpected DEVICE_ID 0x%04X (expected 0x51). Wrong sensor or bus error.\n",
                (unsigned)dev_id);
        return -1;
    }

    /* Configure: continuous conversion, all axes, 50 mT range. */
    if (i2c_write_reg16(g_i2c_handle, TMAG5170_REG_DEVICE_CONFIG, TMAG5170_DEV_CONFIG_50MT) != 0) {
        fprintf(stderr, "Error: failed to write DEVICE_CONFIG register.\n");
        return -1;
    }

    /* Allow first conversion to complete (datasheet: typ 1 ms, max 10 ms). */
    gpioDelay(10000);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(g_i2c_handle, TMAG5170_REG_X_CH1_OUT, x) != 0) {
        fprintf(stderr, "Error: failed to read X axis.\n");
        return -1;
    }
    if (i2c_read_reg16(g_i2c_handle, TMAG5170_REG_Y_CH1_OUT, y) != 0) {
        fprintf(stderr, "Error: failed to read Y axis.\n");
        return -1;
    }
    if (i2c_read_reg16(g_i2c_handle, TMAG5170_REG_Z_CH1_OUT, z) != 0) {
        fprintf(stderr, "Error: failed to read Z axis.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0)
        fprintf(stderr, "Error: fprintf to log file failed.\n");
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty. */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z\n");
        fflush(g_log_file);
    }

    printf("TMAG5170 logging to %s. Press Ctrl-C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_sensor(&x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
            printf("X=%d Y=%d Z=%d\n", x, y, z);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

