#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */

/* Atomic pulse counter */
static volatile int32_t g_pulse_count = 0;

/* Flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* File pointer for logging (global so the signal handler can flush) */
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — called on every edge transition            */
/* ------------------------------------------------------------------ */
static void pulse_counter(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulse count in the last second                    */
/* ------------------------------------------------------------------ */
static float calculate_rpm(int32_t pulses)
{
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    int32_t diff = pulses - g_pulse_count;
    g_pulse_count = pulses;

    if (diff <= 0) {
        return 0.0f;
    }

    /* 1 second in microseconds */
    float elapsed_us = (float)SAMPLE_INTERVAL_US;
    float rpm = (float)diff * 60000.0f / elapsed_us;
    return rpm;
}

/* ------------------------------------------------------------------ */
/* Log RPM to file and stdout                                         */
/* ------------------------------------------------------------------ */
static void log_rpm(float rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm);
        fflush(g_log_fp);
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup — disable timer, release pigpio, close log file            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable the alert callback */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    /* Terminate pigpio */
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure GPIO pin as input with pull-up */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callback for rising edges */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on GPIO %d.\n",
                GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("RPM monitoring started on GPIO %d. Logging to '%s'.\n",
           GPIO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        int32_t pulses = g_pulse_count;
        float rpm = calculate_rpm(pulses);
        log_rpm(rpm);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

