#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"
#define POLL_DELAY_US 10000

typedef enum {
    QUAD_STATE_IDLE,
    QUAD_STATE_A_RISING,
    QUAD_STATE_B_RISING,
    QUAD_STATE_A_FALLING,
    QUAD_STATE_B_FALLING
} quad_state_t;

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cond = PTHREAD_COND_INITIALIZER;
static quad_state_t g_quad_state = QUAD_STATE_IDLE;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_rotation_event(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    pthread_mutex_lock(&g_mutex);
    if (g_log_file) {
        fprintf(g_log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, direction);
        fflush(g_log_file);
    }
    pthread_mutex_unlock(&g_mutex);
}

static void quad_callback(int a_value, int b_value) {
    quad_state_t new_state;
    static quad_state_t prev_state = QUAD_STATE_IDLE;

    if (a_value < 0 || b_value < 0) {
        fprintf(stderr, "Error: sensor read failed in callback (a=%d, b=%d)\n", a_value, b_value);
        return;
    }

    switch (prev_state) {
        case QUAD_STATE_IDLE:
            if (a_value == 1 && b_value == 0) new_state = QUAD_STATE_A_RISING;
            else if (a_value == 0 && b_value == 1) new_state = QUAD_STATE_B_RISING;
            else new_state = QUAD_STATE_IDLE;
            break;
        case QUAD_STATE_A_RISING:
            if (b_value == 1) new_state = QUAD_STATE_B_RISING;
            else if (b_value == 0) new_state = QUAD_STATE_A_RISING;
            else new_state = QUAD_STATE_IDLE;
            break;
        case QUAD_STATE_B_RISING:
            if (a_value == 0) new_state = QUAD_STATE_A_RISING;
            else if (a_value == 1) new_state = QUAD_STATE_B_RISING;
            else new_state = QUAD_STATE_IDLE;
            break;
        case QUAD_STATE_A_FALLING:
            if (b_value == 0) new_state = QUAD_STATE_A_FALLING;
            else if (b_value == 1) new_state = QUAD_STATE_B_FALLING;
            else new_state = QUAD_STATE_IDLE;
            break;
        case QUAD_STATE_B_FALLING:
            if (a_value == 1) new_state = QUAD_STATE_A_FALLING;
            else if (a_value == 0) new_state = QUAD_STATE_B_FALLING;
            else new_state = QUAD_STATE_IDLE;
            break;
        default:
            new_state = QUAD_STATE_IDLE;
            break;
    }

    prev_state = new_state;

    switch (new_state) {
        case QUAD_STATE_A_RISING:
            log_rotation_event("clockwise");
            break;
        case QUAD_STATE_B_RISING:
            log_rotation_event("clockwise");
            break;
        case QUAD_STATE_A_FALLING:
            log_rotation_event("counter-clockwise");
            break;
        case QUAD_STATE_B_FALLING:
            log_rotation_event("counter-clockwise");
            break;
        default:
            break;
    }
}

static void *sensor_thread(void *arg) {
    (void)arg;
    int a_value, b_value;

    while (g_running) {
        a_value = 0;
        b_value = 0;

        if (g_quad_state == QUAD_STATE_A_RISING || g_quad_state == QUAD_STATE_A_FALLING) {
            a_value = 1;
        } else if (g_quad_state == QUAD_STATE_B_RISING || g_quad_state == QUAD_STATE_B_FALLING) {
            b_value = 1;
        }

        quad_callback(a_value, b_value);

        pthread_mutex_lock(&g_mutex);
        g_quad_state = QUAD_STATE_IDLE;
        pthread_mutex_unlock(&g_mutex);

        usleep(POLL_DELAY_US);
    }

    return NULL;
}

int main(void) {
    pthread_t sensor_thread_id;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    ret = pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL);
    if (ret != 0) {
        fprintf(stderr, "pthread_create failed: %s\n", strerror(ret));
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    while (g_running) {
        pthread_mutex_lock(&g_mutex);
        while (g_quad_state == QUAD_STATE_IDLE && g_running) {
            pthread_cond_wait(&g_cond, &g_mutex);
        }
        pthread_mutex_unlock(&g_mutex);
    }

    pthread_join(sensor_thread_id, NULL);

    pthread_mutex_lock(&g_mutex);
    g_quad_state = QUAD_STATE_IDLE;
    pthread_mutex_unlock(&g_mutex);

    pthread_mutex_destroy(&g_mutex);
    pthread_cond_destroy(&g_cond);

    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    return EXIT_SUCCESS;
}

