#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define TOUCH_SENSOR_PIN 23
#define LED_PIN         18
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    openlog("touch_led_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers.");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started on %s GPIO%d, LED on GPIO%d.",
           GPIO_CHIP_NAME, TOUCH_SENSOR_PIN, LED_PIN);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip '%s': %s", GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get touch sensor line (GPIO%d): %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get LED line (GPIO%d): %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_output", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started. Press Ctrl+C to exit.");

    int led_state = 0;
    int last_touch_state = -1;

    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor value: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (touch_value != last_touch_state) {
            if (touch_value == 1) {
                syslog(LOG_INFO, "Touch detected on GPIO%d.", TOUCH_SENSOR_PIN);
            } else {
                syslog(LOG_INFO, "Touch released on GPIO%d.", TOUCH_SENSOR_PIN);
            }
            last_touch_state = touch_value;
        }

        led_state = touch_value;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            syslog(LOG_ERR, "Failed to set LED value: %s", strerror(errno));
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down touch sensor monitoring.");

    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn off LED during shutdown: %s", strerror(errno));
    }

    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Touch sensor monitoring stopped.");
    closelog();

    return EXIT_SUCCESS;
}

