/*
 * TTP223B capacitive touch sensor reader with LED toggle.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart TTP223B (OUT -> GPIO17, physical pin 11)
 * LED:    330 Ω resistor -> GPIO18 (physical pin 12)
 *
 * Behavior:
 *   - Waits for rising-edge events on GPIO17.
 *   - On each event, toggles the LED on GPIO18.
 *   - Debounces each touch event by sleeping 50 ms.
 *   - Prints clear error messages to stderr.
 *   - Gracefully exits on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lpigpio -lrt
 * Run:    sudo ./touch_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN  17          /* GPIO17, physical pin 11  */
#define LED_PIN    18          /* GPIO18, physical pin 12  */
#define DEBOUNCE_US 50000      /* 50 ms debounce            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure LED is off before releasing the line. */
    if (gpioInitialise() >= 0) {
        (void)gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts LOW. */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        goto cleanup_fail;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LED_PIN);
        goto cleanup_fail;
    }

    /* Configure touch pin as input. */
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_PIN);
        goto cleanup_fail;
    }

    /*
     * Open the GPIO chip for the BCM pin number so that we can use
     * the line event interface (gpioSetAlertFuncEx) rather than the
     * deprecated gpioSetWatchdog + gpioRead polling pattern.
     */
    if (gpioSetWatchdog(TOUCH_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to disable watchdog on GPIO%d.\n", TOUCH_PIN);
        goto cleanup_fail;
    }

    /*
     * Request rising-edge events on the touch pin.
     * gpioSetAlertFuncEx returns 0 on success, non-zero on error.
     */
    if (gpioSetAlertFuncEx(TOUCH_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Error: failed to request rising-edge events on GPIO%d.\n", TOUCH_PIN);
        goto cleanup_fail;
    }

    printf("TTP223B touch sensor ready.  Touch GPIO%d to toggle GPIO%d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main event loop: blocks until a rising edge or a signal arrives. */
    while (g_running) {
        int rc = gpioWaitForAlert(TOUCH_PIN, 1000);   /* 1 s timeout */
        if (rc < 0) {
            fprintf(stderr, "Error: gpioWaitForAlert failed (rc=%d).\n", rc);
            goto cleanup_fail;
        }
        if (rc == 0) {
            /* Timeout — loop back and check g_running. */
            continue;
        }

        /* Debounce: ignore events for 50 ms. */
        gpioDelay(DEBOUNCE_US);

        /* Toggle LED. */
        int level = gpioRead(LED_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", LED_PIN);
            goto cleanup_fail;
        }
        if (gpioWrite(LED_PIN, level ? 0 : 1) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", LED_PIN);
            goto cleanup_fail;
        }

        printf("Touch detected — LED %s.\n", level ? "OFF" : "ON");
        fflush(stdout);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup_fail:
    cleanup();
    return ret;
}

