#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define BUFFER_SIZE  100
#define POLL_DELAY_US 50000

typedef struct {
    int   sensor_pin;
    time_t timestamp;
    int   state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      overflow_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp  = now;
    log_buffer[buffer_index].state      = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

static void cleanup(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED1 state\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED2 state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev1 = gpioRead(SENSOR_1_PIN);
    int prev2 = gpioRead(SENSOR_2_PIN);
    if (prev1 < 0 || prev2 < 0) {
        fprintf(stderr, "Initial sensor read failed (s1=%d, s2=%d)\n", prev1, prev2);
        cleanup();
        return EXIT_FAILURE;
    }

    log_event(SENSOR_1_PIN, prev1);
    log_event(SENSOR_2_PIN, prev2);

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Sensor 1 read error\n");
        } else if (s1 != prev1) {
            if (gpioWrite(LED_1_PIN, s1) != 0) {
                fprintf(stderr, "Failed to write LED1\n");
            }
            log_event(SENSOR_1_PIN, s1);
            prev1 = s1;
        }

        if (s2 < 0) {
            fprintf(stderr, "Sensor 2 read error\n");
        } else if (s2 != prev2) {
            if (gpioWrite(LED_2_PIN, s2) != 0) {
                fprintf(stderr, "Failed to write LED2\n");
            }
            log_event(SENSOR_2_PIN, s2);
            prev2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    printf("Log buffer contents (%d entries, %d overflows):\n", buffer_index, overflow_count);
    for (int i = 0; i < buffer_index; i++) {
        int idx = (i + overflow_count) % BUFFER_SIZE;
        printf("  [%d] Sensor %d: %s (state=%d, ts=%ld)\n",
               i, log_buffer[idx].sensor_pin,
               log_buffer[idx].state ? "Touched" : "Released",
               log_buffer[idx].state, (long)log_buffer[idx].timestamp);
    }
    printf("Total overflows: %d\n", overflow_count);

    cleanup();
    return EXIT_SUCCESS;
}

