#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d\n", ts, s1, s2) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(fp, "timestamp,sensor1_state,sensor2_state\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_s1 = gpioRead(SENSOR_1_GPIO);
    int prev_s2 = gpioRead(SENSOR_2_GPIO);
    if (prev_s1 < 0 || prev_s2 < 0) {
        fprintf(stderr, "Initial GPIO read failed (s1=%d, s2=%d)\n", prev_s1, prev_s2);
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring shaft RPM on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n", SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "GPIO read error (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        if (s1 != prev_s1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int s1_recheck = gpioRead(SENSOR_1_GPIO);
            if (s1_recheck < 0) {
                fprintf(stderr, "GPIO read error during debounce (s1=%d)\n", s1_recheck);
                break;
            }
            if (s1_recheck == s1) {
                prev_s1 = s1;
                if (log_data(fp, s1, prev_s2) != 0) {
                    break;
                }
            }
        }

        if (s2 != prev_s2) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int s2_recheck = gpioRead(SENSOR_2_GPIO);
            if (s2_recheck < 0) {
                fprintf(stderr, "GPIO read error during debounce (s2=%d)\n", s2_recheck);
                break;
            }
            if (s2_recheck == s2) {
                prev_s2 = s2;
                if (log_data(fp, prev_s1, s2) != 0) {
                    break;
                }
            }
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

