        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting heart rate and SpO2 logging. Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t hr = 0, spo2 = 0;
        int hr_ok = read_heart_rate(&hr);
        int spo2_ok = read_spo2(&spo2);

        if (hr_ok == 0 && spo2_ok == 0) {
