#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x50
#define CTRL1_REG      0x20
#define CTRL2_REG      0x21
#define STATUS_REG     0x22
#define XOUT_L_REG     0x28
#define XOUT_H_REG     0x29
#define YOUT_L_REG     0x2A
#define YOUT_H_REG     0x2B
#define ZOUT_L_REG     0x2C
#define ZOUT_H_REG     0x2D
#define THRESHOLD      500
#define ALERT_PIN      17
#define POLL_MS        100
#define MAX_RETRIES    3
#define LOG_FILE       "seismic_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, uint8_t reg_h, int16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_h, &hi) < 0) return -1;
    *val = (int16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t ctrl1 = 0x00;
    if (i2c_write_reg8(i2c_fd, CTRL1_REG, ctrl1) < 0) {
        fprintf(stderr, "Failed to write CTRL1 (power-down mode).\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(10000);
    uint8_t status = 0;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg8(i2c_fd, STATUS_REG, &status) == 0) break;
        usleep(10000);
    }
    if (status == 0) {
        fprintf(stderr, "Sensor not responding (STATUS=0x00).\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg16(i2c_fd, XOUT_L_REG, XOUT_H_REG, x) == 0 &&
            i2c_read_reg16(i2c_fd, YOUT_L_REG, YOUT_H_REG, y) == 0 &&
            i2c_read_reg16(i2c_fd, ZOUT_L_REG, ZOUT_H_REG, z) == 0) {
            return 0;
        }
        usleep(10000);
    }
    return -1;
}

static double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;
    return sqrt(dx * dx + dy * dy + dz * dz);
}

static void log_event(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_fp, "%s, X=%d, Y=%d, Z=%d, Magnitude=%.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_fp);
}

static void trigger_alert(void) {
    if (i2c_fd >= 0) {
        if (i2c_write_reg8(i2c_fd, CTRL1_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to activate alert LED.\n");
        }
    }
    usleep(1000000);
    if (i2c_fd >= 0) {
        if (i2c_write_reg8(i2c_fd, CTRL1_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to deactivate alert LED.\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (init_sensor() < 0) {
        return 1;
    }
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int16_t x, y, z;
        if (read_sensor_data(&x, &y, &z) == 0) {
            double magnitude = calculate_magnitude(x, y, z);
            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
                log_event(x, y, z, magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }
        usleep(POLL_MS * 1000);
    }
    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, CTRL1_REG, 0x00);
        close(i2c_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return 0;
}

