#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN     18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    /* KY-032 OUT is active-low: 0 => object detected */
    return (v == 0) ? 1 : 0;
}

static void control_led(int state)
{
    int rc = gpioWrite(LED_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed on LED pin %d: %s\n",
                LED_PIN, pigpio_error(rc));
