/*
 * flame_monitor.c — Five KY-026 flame-sensor monitor for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 *
 * Wiring (BCM numbering):
 *   Sensor 1: GPIO 2  (physical pin 3)
 *   Sensor 2: GPIO 3  (physical pin 5)
 *   Sensor 3: GPIO 4  (physical pin 7)
 *   Sensor 4: GPIO 17 (physical pin 11)
 *   Sensor 5: GPIO 27 (physical pin 13)
 *
 * The KY-026 digital output is active-HIGH when a flame is detected.
 * On a confirmed HIGH->LOW transition we read the line again to debounce.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_S 1
#define LOG_FILE "/var/log/flame_events.log"
#define CHIP_NAME  "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int sensor_id, int pin, const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    char logline[256];
    int n = snprintf(logline, sizeof(logline),
                     "%s - Sensor ID: %d (GPIO %u) - %s",
                     ts, sensor_id, pin, msg);
    if (n < 0 || (size_t)n >= sizeof(logline)) {
        syslog(LOG_ERR, "log line truncated");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", logline) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    } else if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
    }

    syslog(LOG_INFO, "%s", logline);
}

static void log_error(int sensor_id, int pin, const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    syslog(LOG_ERR,
           "%s - Sensor ID: %d (GPIO %u) - ERROR: %s",
           ts, sensor_id, pin, msg);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (5 sensors on %s)",
           CHIP_NAME);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "initial gpiod_line_get_value(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = v;
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (prev_state[i] == 1 && v == 0) {
                /* Possible flame transition — debounce read */
                usleep(DEBOUNCE_MS * 1000);

                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "debounce read(%u) failed: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (debounced == 0) {
                    log_event(i + 1, sensor_pins[i], "Flame Detected");
                }
            }
            prev_state[i] = v;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame sensor monitoring stopped");

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

