/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT0-OUT7 -> Pi BCM GPIO):
 *   OUT0 -> GPIO5   (pin 29)
 *   OUT1 -> GPIO6   (pin 31)
 *   OUT2 -> GPIO13  (pin 33)
 *   OUT3 -> GPIO19  (pin 35)
 *   OUT4 -> GPIO26  (pin 37)
 *   OUT5 -> GPIO12  (pin 32)
 *   OUT6 -> GPIO16  (pin 36)
 *   OUT7 -> GPIO20  (pin 38)
 *
 * Build: gcc -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[timestamp-error] ");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[timestamp-error] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[timestamp-error] ");
        return;
    }
    fprintf(stderr, "[%s] ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_states, 0, sizeof(prev_states));

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line and verify it is in the correct consumer class */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
