#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VEML7700_ADDR 0x18
#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS 0x04
#define VEML7700_REG_INT 0x05

#define GPIO_PWM 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

#define LUX_LOW 100
#define LUX_MEDIUM 500
#define LUX_HIGH 1000

#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    uint8_t config[2] = {0x00, 0x00};
    if (i2cWriteI2CBlockData(handle, VEML7700_REG_CONFIG, (char *)config, 2) < 0) {
        fprintf(stderr, "Error: Failed to write VEML7700 config register.\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    uint8_t reg = VEML7700_REG_ALS;
    uint8_t buf[2];
    if (i2cWriteI2CBlockData(handle, reg, (char *)buf, 0) < 0) {
        fprintf(stderr, "Error: Failed to set ALS register pointer.\n");
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ALS data.\n");
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 100.0f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    if (gpioPWM(gpio, brightness) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
                timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(GPIO_PWM, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed (sensor may be absent).\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", GPIO_PWM);
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", GPIO_PWM);
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(GPIO_PWM, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", GPIO_PWM);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int lux_read = veml7700_read_lux(i2c_handle, &lux);

        if (lux_read == 0) {
            int brightness = 100;
            if (lux < LUX_LOW) {
                brightness = 100;
            } else if (lux < LUX_MEDIUM) {
                brightness = 75;
            } else if (lux < LUX_HIGH) {
                brightness = 50;
            } else {
                brightness = 25;
            }
            if (set_led_brightness(GPIO_PWM, brightness) != 0) {
                fprintf(stderr, "Error: Failed to set LED brightness.\n");
            }
            if (log_data(log_file, lux, brightness, 0) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read lux value.\n");
            if (log_data(log_file, 0.0f, 0, lux_read) != 0) {
                fprintf(stderr, "Error: Failed to log error.\n");
            }
        }

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

