code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN      17
#define POLL_DELAY_US 50000  /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening touch_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf() failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose() failed");
        return -1;
    }

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        last_state[i] = 0;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(sensor_pins[i]);
            if (level < 0) {
                fprintf(stderr, "gpioRead failed on GPIO %d\n", sensor_pins[i]);
                continue;
            }

            if (level == 1 && last_state[i] == 0) {
                if (log_touch_event(i + 1) == 0) {
                    printf("Touch detected on channel %d\n", i + 1);
                }
                if (gpioWrite(LED_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to turn LED on\n");
                }
            } else if (level == 0 && last_state[i] == 1) {
                if (gpioWrite(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to turn LED off\n");
                }
            }

            last_state[i] = level;
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

