#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x00
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUF_ID   0x7E
#define REG_DEVICE_ID  0x7F
#define MANUF_ID       0x5449
#define DEVICE_ID      0x3001
#define CONFIG_VALUE   0x0003  /* RN=100ms, CT=125ms, M=1, L=1 */
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1
#define CONFIG_DELAY   0.1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int opt3001_init(int fd)
{
    uint16_t manuf_id = 0, device_id = 0;

    if (i2c_read_reg16(fd, REG_MANUF_ID, &manuf_id) < 0)
        return -1;
    if (manuf_id != MANUF_ID) {
        fprintf(stderr, "Unexpected manufacturer ID: 0x%04X (expected 0x%04X)\n", manuf_id, MANUF_ID);
        return -1;
    }

    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) < 0)
        return -1;
    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID);
        return -1;
    }

    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) < 0)
        return -1;

    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw = 0;
    uint16_t exponent = 0, mantissa = 0;

    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0)
        return -1;

    /* OPT3001 returns data in big-endian format; swap bytes */
    exponent = (raw >> 8) & 0xFF;
    mantissa = raw & 0xFF;

    if (exponent == 0xFF && mantissa == 0xFF) {
        fprintf(stderr, "OPT3001 result saturated (0x%04X)\n", raw);
        return -1;
    }

    if (exponent == 0xFF && mantissa == 0x00) {
        *lux_out = 0.0f;
        return 0;
    }

    *lux_out = (float)mantissa * (1 << (exponent - 1));
    return 0;
}

static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting OPT3001 light data logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux value; retrying next cycle.\n");
        } else {
            if (log_data(g_log_fp, lux) < 0) {
                fprintf(stderr, "Failed to log data; continuing.\n");
            } else {
                printf("%s, %.2f lux\n", "timestamp", lux);
            }
        }

        /* Wait 100 ms after configuration before reading */
        usleep(CONFIG_DELAY * 1000000);
    }

    printf("\nShutting down gracefully...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) < 0) {
            fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
        }
        g_i2c_fd = -1;
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

