#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", FLAME_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", ALERT_PIN);
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d to LOW\n", ALERT_PIN);
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead() failed on GPIO%d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return value;
}

static int trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite() failed to set GPIO%d HIGH\n", ALERT_PIN);
        return -1;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite() failed to set GPIO%d LOW\n", ALERT_PIN);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            log_event("Error: failed to read flame sensor");
        } else if (flame_detected == 0) {
            if (log_event("Flame detected!") != 0) {
                fprintf(stderr, "Warning: failed to log flame event\n");
            }
            if (trigger_alert() != 0) {
                log_event("Error: failed to trigger alert");
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

