#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s: Touch %s\n", timestamp, state ? "Detected" : "Released") < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int last_state = 0;
    int current_state = 0;
    int ret = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    last_state = gpioRead(TOUCH_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Initial gpioRead failed on pin %d\n", TOUCH_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    while (running) {
        current_state = gpioRead(TOUCH_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", TOUCH_PIN);
            ret = EXIT_FAILURE;
            break;
        }

        if (current_state != last_state) {
            if (log_touch_event(current_state) != 0) {
                ret = EXIT_FAILURE;
                break;
            }
            last_state = current_state;
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(10000);  /* 10 ms poll interval */
    }

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return ret;
}

