#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x36
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_FLOW_RATE  100.0
#define MIN_FLOW_RATE  0.0
#define READ_DELAY_US  2000
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate, uint8_t *flags)
{
    uint8_t cmd = 0x36;
    uint8_t buf[3];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing command to I2C device\n");
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    int rd = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rd != 3) {
        fprintf(stderr, "Error reading from I2C device (got %d bytes)\n", rd);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flags = (uint8_t)raw;
    *flow_rate = (float)raw / 100.0f;

    if (*flow_rate < MIN_FLOW_RATE || *flow_rate > MAX_FLOW_RATE) {
        fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", *flow_rate);
        return -1;
    }

    return 0;
}

static void log_data(float flow_rate, uint8_t flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_file == NULL) {
        g_log_file = fopen(LOG_FILE, "a");
        if (g_log_file == NULL) {
            fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
            return;
        }
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }

    fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate = 0.0f;
        uint8_t flags = 0;
        const char *status = "OK";

        if (read_flow_rate(&flow_rate, &flags) != 0) {
            fprintf(stderr, "Read failed; attempting recovery...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Recovery failed; exiting.\n");
                break;
            }
            status = "RECOVERED";
        } else {
            if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
                status = "OUT_OF_RANGE";
            }
        }

        log_data(flow_rate, flags, status);
        printf("Flow Rate: %.2f ml/min, Status: %s\n", flow_rate, status);

        time_sleep(SAMPLE_PERIOD);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    printf("Coolant flow monitoring stopped.\n");
    return 0;
}

