/*
 * KY-033 Obstacle Avoidance Sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   Left  sensor  -> GPIO17 (physical pin 11)
 *   Middle sensor -> GPIO27 (physical pin 13)
 *   Right sensor  -> GPIO22 (physical pin 15)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033_log ky033_log.c -lgpiod
 *
 * The program polls each sensor every 50 ms, records a CSV row with an
 * ISO-8601 timestamp and one column per sensor, and flushes the log file
 * after each sample.  On SIGINT it cleans up all resources and exits.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define LEFT_SENSOR_PIN  17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE_NAME    "path_log.csv"
#define POLL_INTERVAL_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static int log_sensor_data(FILE *fp, const char *timestamp,
                           int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("fprintf()");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() != 0)
        goto cleanup;

    /* Open the GPIO chip */
