/*
 * KY-033 Obstacle Avoidance Sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   Left  sensor  -> GPIO17 (physical pin 11)
 *   Middle sensor -> GPIO27 (physical pin 13)
 *   Right sensor  -> GPIO22 (physical pin 15)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033_log ky033_log.c -lgpiod
 *
 * The program polls each sensor every 50 ms, records a CSV row with an
 * ISO-8601 timestamp and one column per sensor, and flushes the log file
 * after each sample.  On SIGINT it cleans up all resources and exits.
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define LEFT_SENSOR_PIN  17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE_NAME    "path_log.csv"
#define POLL_INTERVAL_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static int log_sensor_data(FILE *fp, const char *timestamp,
                           int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("fprintf()");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() != 0)
        goto cleanup;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* Get the three sensor lines */
    left_line   = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line  = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (left_line == NULL || middle_line == NULL || right_line == NULL) {
        fprintf(stderr, "Failed to get one or more GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request each line as an input */
    if (gpiod_line_request_input(left_line, "ky033-left") != 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n",
                LEFT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "ky033-middle") != 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n",
                MIDDLE_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "ky033-right") != 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n",
                RIGHT_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Open the log file in append mode */
    log_fp = fopen(LOG_FILE_NAME, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if the file is empty */
    if (ftell(log_fp) == 0) {
        if (fprintf(log_fp, "timestamp,left,middle,right\n") < 0) {
            perror("fprintf(header)");
            goto cleanup;
        }
        if (fflush(log_fp) != 0) {
            perror("fflush(header)");
            goto cleanup;
        }
    }

    printf("KY-033 obstacle avoidance logging started.\n");
    printf("Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    /* Main polling loop */
    while (g_running) {
        int left   = gpiod_line_get_value(left_line);
        int middle = gpiod_line_get_value(middle_line);
        int right  = gpiod_line_get_value(right_line);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n",
                    strerror(errno));
            break;
        }

        char timestamp[32];
        if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
            break;
        }

        if (log_sensor_data(log_fp, timestamp, left, middle, right) != 0) {
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (left_line)   gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line)  gpiod_line_release(right_line);
    if (chip)        gpiod_chip_close(chip);

    /* Close log file */
    if (log_fp) {
        if (fclose(log_fp) != 0) {
            perror("fclose()");
        }
    }

    if (ret == EXIT_SUCCESS)
        printf("\nLogging stopped.\n");

    return ret;
}

