#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_PATH "/dev/gpiochip4"
#define GPIO_TOUCH_PIN 23
#define GPIO_LED_PIN   24
#define LOG_FILE       "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;
static int  g_gpio_fd = -1;
static FILE *g_log_fp  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int gpio_export(unsigned pin)
{
    char buf[16];
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    int n = snprintf(buf, sizeof(buf), "%u", pin);
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed\n");
        close(fd);
        return -1;
    }
    if (write(fd, buf, (size_t)n) != n) {
        fprintf(stderr, "export pin %u: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(unsigned pin)
{
    char buf[16];
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    int n = snprintf(buf, sizeof(buf), "%u", pin);
    if (n < 0 || (size_t)n >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed\n");
        close(fd);
        return -1;
    }
    if (write(fd, buf, (size_t)n) != n) {
        fprintf(stderr, "unexport pin %u: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned pin, unsigned dir)
{
    struct gpio_v1_line_settings settings;
    struct gpio_v1_line_config config;
    struct gpio_v1_line_request request;
    struct gpio_v1_line_values values;
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    memset(&settings, 0, sizeof(settings));
    settings.direction = dir;
    settings.output_value = 0;
    settings.pull = GPIO_V1_LINE_PUD_OFF;
    settings.edge_detection = 0;
    memset(&config, 0, sizeof(config));
    config.flags = 0;
    config.num_settings = 1;
    config.settings = &settings;
    memset(&request, 0, sizeof(request));
    request.flags = 0;
    request.num_lines = 1;
    request.lines = &pin;
    request.config = &config;
    if (ioctl(fd, GPIO_V1_GET_LINE_REQUEST, &request) < 0) {
        fprintf(stderr, "ioctl GET_LINE_REQUEST: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    memset(&values, 0, sizeof(values));
    values.values[0] = 0;
    if (ioctl(fd, GPIO_V1_SET_LINE_VALUES, &values) < 0) {
        fprintf(stderr, "ioctl SET_LINE_VALUES: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(unsigned pin, unsigned value)
{
    struct gpio_v1_line_values values;
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    memset(&values, 0, sizeof(values));
    values.values[0] = value;
    if (ioctl(fd, GPIO_V1_SET_LINE_VALUES, &values) < 0) {
        fprintf(stderr, "ioctl SET_LINE_VALUES: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_get_value(unsigned pin)
{
    struct gpio_v1_line_values values;
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    memset(&values, 0, sizeof(values));
    if (ioctl(fd, GPIO_V1_GET_LINE_VALUES, &values) < 0) {
        fprintf(stderr, "ioctl GET_LINE_VALUES: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return values.values[0];
}

static int gpio_request_event(unsigned pin, unsigned edge)
{
    struct gpio_v1_line_config config;
    struct gpio_v1_line_request request;
    struct gpio_v1_line_event_config event_config;
    int fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_PATH, strerror(errno));
        return -1;
    }
    memset(&config, 0, sizeof(config));
    config.flags = 0;
    config.num_settings = 0;
    config.settings = NULL;
    memset(&request, 0, sizeof(request));
    request.flags = 0;
    request.num_lines = 1;
    request.lines = &pin;
    request.config = &config;
    if (ioctl(fd, GPIO_V1_GET_LINE_REQUEST, &request) < 0) {
        fprintf(stderr, "ioctl GET_LINE_REQUEST: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    memset(&event_config, 0, sizeof(event_config));
    event_config.edge_detection = edge;
    if (ioctl(fd, GPIO_V1_SET_LINE_EVENT_CONFIG, &event_config) < 0) {
        fprintf(stderr, "ioctl SET_LINE_EVENT_CONFIG: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int log_touch_event(int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    if (time(&rawtime) == (time_t)-1) {
