/*
 * Flame detection safety system for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - Keyes KY-026 Flame Sensor (digital output, active-low)
 *     DO  -> GPIO17 (BCM, physical pin 11)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   - Active buzzer
 *     +   -> GPIO18 (BCM, physical pin 12)
 *     -   -> GND
 *
 * Behavior:
 *   Polls the sensor every 500 ms.  On a HIGH-to-LOW transition (flame
 *   detected) logs a timestamped entry to alert_log.txt, drives the
 *   buzzer HIGH for 2 s, and repeats.  SIGINT / SIGTERM triggers a clean
 *   shutdown.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18   /* BCM 18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define CHIP_NAME         "gpiochip0"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_event(FILE *log_file, const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) == EOF) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */

static int buzzer_on(struct gpiod_line *buzzer_line)
{
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("gpiod_line_set_value(buzzer ON)");
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *buzzer_line)
{
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("gpiod_line_set_value(buzzer OFF)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* Get the flame sensor line */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    /* Get the buzzer line */
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* Request flame sensor line as input */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    /* Request buzzer line as output, initial value LOW */
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(log_file)");
        goto cleanup;
    }

    /* Write startup event */
    if (log_event(log_file, "System started") != 0) {
        fprintf(stderr, "Failed to log startup event\n");
        goto cleanup;
    }

    printf("Flame detection system started.  Press Ctrl+C to exit.\n");

    int last_flame_state = 1;   /* assume no flame at startup (HIGH) */

    while (g_running) {
        int flame_state = gpiod_line_get_value(flame_line);
        if (flame_state < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Detect HIGH-to-LOW transition (flame detected) */
        if (flame_state == 0 && last_flame_state == 1) {
            printf("Flame detected!\n");

            if (log_event(log_file, "FLAME DETECTED") != 0) {
                fprintf(stderr, "Failed to log flame event\n");
            }

            if (buzzer_on(buzzer_line) != 0) {
                break;
            }

            /* Drive buzzer for 2 seconds, checking for shutdown */
            for (int i = 0; i < BUZZER_DURATION_MS / 100 && g_running; i++) {
                usleep(100000); /* 100 ms */
            }

            if (buzzer_off(buzzer_line) != 0) {
                break;
            }
        }

        last_flame_state = flame_state;

        /* Sleep 500 ms, checking for shutdown */
        for (int i = 0; i < POLL_INTERVAL_MS / 100 && g_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure buzzer is off on every exit path */
    if (buzzer_line != NULL) {
        (void)gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        if (log_event(log_file, "System stopped") != 0) {
            fprintf(stderr, "Failed to log shutdown event\n");
        }
        if (fclose(log_file) == EOF) {
            perror("fclose");
        }
    }

    if (ret == EXIT_SUCCESS) {
        printf("Flame detection system stopped.\n");
    }
    return ret;
}

