/*
 * TMAG5110A1 Hall-effect latch sensor monitor for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 outputs an open-drain latch: the line is HIGH when no
 * magnet is present (no magnetic field, no south pole), and LOW when a
 * south-pole magnet is detected (magnet present, south pole present).
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_monitor mag_monitor.c -lpigpio -lrt
 * Run:    sudo ./mag_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    const int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, state ? "Magnet Present" : "Magnet Removed") < 0) {
        perror("Error writing to log file");
    }
    if (fflush(g_log_file) != 0) {
        perror("Error flushing log file");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int prev_state[3] = {-1, -1, -1};   /* -1 = unknown / first read */
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int level = gpioRead(pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed for pin %d.\n", pins[i]);
                continue;
            }

            if (prev_state[i] == -1) {
                /* Record initial state without logging a transition. */
                prev_state[i] = level;
            } else if (level != prev_state[i]) {
                log_event(i + 1, level);
                prev_state[i] = level;
            }
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            perror("Error closing log file");
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

