        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, state ? "Magnet Present" : "Magnet Removed") < 0) {
        perror("Error writing to log file");
    }
    if (fflush(g_log_file) != 0) {
        perror("Error flushing log file");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int prev_state[3] = {-1, -1, -1};   /* -1 = unknown / first read */
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d...\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int level = gpioRead(pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed for pin %d.\n", pins[i]);
                continue;
            }

            if (prev_state[i] == -1) {
                /* Record initial state without logging a transition. */
                prev_state[i] = level;
            } else if (level != prev_state[i]) {
                log_event(i + 1, level);
                prev_state[i] = level;
            }
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            perror("Error closing log file");
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

