#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define CSV_FILENAME "tracking_log.csv"

static volatile sig_atomic_t g_running = 1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Enable internal pull-up so the line is defined when no sensor is present */
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", pins[i]);
        }
    }
    return 0;
}

static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", pin);
        return -1;
    }
    /* Active-low: 0 = line detected, 1 = no line */
    return (value == 0) ? 1 : 0;
}

static int write_csv_header_if_needed(void)
{
    long pos = ftell(g_csv);
    if (pos == 0) {
        if (fprintf(g_csv, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header.\n");
            return -1;
        }
        fflush(g_csv);
    }
    return 0;
}

static int write_csv_row(int s1, int s2, int s3, int s4)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_csv, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: failed to write CSV row.\n");
        return -1;
    }
    if (fflush(g_csv) != 0) {
        fprintf(stderr, "Warning: fflush failed on CSV file.\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (g_csv == NULL) {
        perror("Error opening CSV file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_csv_header_if_needed() != 0) {
        fclose(g_csv);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tracking sensor data logged to %s. Press Ctrl+C to stop.\n", CSV_FILENAME);

    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Warning: sensor read error, skipping this cycle.\n");
        } else {
            if (write_csv_row(s1, s2, s3, s4) != 0) {
                fprintf(stderr, "Warning: failed to write CSV row.\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

