#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        return -1;
    }

    /* Enable internal pull-ups so the lines are defined when the sensor
       is disconnected (TCRT5000 modules drive active-low: 0 = obstacle). */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_2_PIN);
        return -1;
    }

    /* Start with LED off. */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d\n", LED_PIN);
        return -1;
    }

    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d\n", pin);
        return -1;
    }
    /* TCRT5000 is active-low: 0 = obstacle detected. */
    return (v == 0) ? 1 : 0;
}

static int control_led(int state)
{
    if (gpioWrite(LED_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite failed on LED GPIO%d\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int log_data(int s1, int s2, int led)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Best-effort LED off. */
    if (g_log != NULL) {
        gpioWrite(LED_PIN, 0);
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,sensor1,sensor2,led_state\n");
        fflush(g_log);
    }

    printf("Obstacle avoidance program started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(POLL_US);
            continue;
        }

        /* TCRT5000 active-low: 0 = obstacle. */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;
        int led = obstacle ? 1 : 0;

        if (control_led(led) != 0) {
            fprintf(stderr, "LED control error; continuing.\n");
        }

        if (log_data(s1, s2, led) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

