#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN      4   /* BCM GPIO4  - physical pin 7  */
#define LED_PIN      17  /* BCM GPIO17 - physical pin 11 */
#define SAMPLE_US    125 /* 8 kHz polling period        */
#define LED_ON_US    100000 /* 100 ms LED pulse           */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld\n", buf, ts.tv_nsec / 1000000L);
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN %d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d at ~8 kHz. Press Ctrl+C to exit.\n",
           MIC_PIN);
    fflush(stdout);

    while (g_running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on MIC_PIN %d\n", MIC_PIN);
            break;
        }

        if (level == 1) {
            print_timestamp_ms();
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
                break;
            }
            gpioDelay(LED_ON_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

