#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d.\n", pin);
        return -1;
    }
    /* SunFounder 3-Way Tracing Sensor: active-low; 0 = reflected light, 1 = dark */
    return (value == 0) ? 1 : 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("IR Sensor Data Acquisition (pigpio)\n");
    printf("Left: GPIO%d | Center: GPIO%d | Right: GPIO%d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: sensor read failure, exiting.\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

