/*
 * Si1175 Ambient Light Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads the visible ALS data from a Si1175 optical heart-rate sensor
 * over I2C bus 1 at 100 ms intervals, combines the LSB and MSB registers
 * into a single 16-bit raw value, and logs it to the console.
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1175 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1175 VDD  -> 3.3 V
 *   Si1175 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c -lpigpio -lrt
 * Run:    sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1175 register definitions (from Si1175 datasheet) ---- */
#define SI1175_I2C_BUS        1
#define SI1175_I2C_ADDR       0x49   /* 7-bit address, A0 tied to GND */

#define SI1175_REG_PART_ID    0x00
#define SI1175_REG_HW_KEY     0x07
#define SI1175_REG_ALS_VIS_LSB 0x22
#define SI1175_REG_ALS_VIS_MSB 0x23

#define SI1175_PART_ID_VAL    0x75   /* expected PART_ID value */

#define SI1175_HW_KEY_VAL     0x17

#define SAMPLE_PERIOD_US      100000 /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int si1175_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
static int si1175_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
static int si1175_init(int handle)
{
    int part_id = si1175_read_reg(handle, SI1175_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1175_PART_ID_VAL) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1175_PART_ID_VAL);
        return -1;
    }
    printf("[INFO] Si1175 detected (PART_ID = 0x%02X).\n", part_id);

    if (si1175_write_reg(handle, SI1175_REG_HW_KEY, SI1175_HW_KEY_VAL) < 0) {
        fprintf(stderr, "[ERROR] Failed to write HW_KEY.\n");
        return -1;
    }

    /* Allow the sensor to settle after configuration */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_als_raw(int handle, uint16_t *out)
{
    int lsb = si1175_read_reg(handle, SI1175_REG_ALS_VIS_LSB);
    if (lsb < 0) {
        return -1;
    }
    int msb = si1175_read_reg(handle, SI1175_REG_ALS_VIS_MSB);
    if (msb < 0) {
        return -1;
    }
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1175 address */
    g_i2c_handle = i2cOpen(SI1175_I2C_BUS, SI1175_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                SI1175_I2C_BUS, SI1175_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1175_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1175 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Starting ALS readings every 100 ms. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t als_raw;
        if (read_als_raw(g_i2c_handle, &als_raw) == 0) {
            printf("ALS (Visible): %u\n", als_raw);
        } else {
            fprintf(stderr, "[WARN] Failed to read ALS data.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

