#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DURATION 5.0
#define STEP_DELAY    (FADE_DURATION / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN, r) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN (BCM %d): %s", RED_PIN, pigpio_error(r));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN (BCM %d): %s", GREEN_PIN, pigpio_error(g));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN (BCM %d): %s", BLUE_PIN, pigpio_error(b));
        return -1;
    }
    return 0;
}

static void fade_to_color(int r, int g, int b) {
    for (int i = 0; i <= FADE_STEPS && g_running; i++) {
        int r_step = (r * i) / FADE_STEPS;
        int g_step = (g * i) / FADE_STEPS;
        int b_step = (b * i) / FADE_STEPS;
        if (set_led_color(r_step, g_step, b_step) < 0) {
            syslog(LOG_ERR, "Failed to set LED color during fade");
            return;
        }
        time_sleep(STEP_DELAY);
    }
}

static void random_color(int *r, int *g, int *b) {
    *r = (rand() % 256);
    *g = (rand() % 256);
    *b = (rand() % 256);
}

int main(void) {
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %m");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN (BCM %d) as output: %s", RED_PIN, pigpio_error(RED_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN (BCM %d) as output: %s", GREEN_PIN, pigpio_error(GREEN_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN (BCM %d) as output: %s", BLUE_PIN, pigpio_error(BLUE_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on RED_PIN (BCM %d): %s", RED_PIN, pigpio_error(RED_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GREEN_PIN (BCM %d): %s", GREEN_PIN, pigpio_error(GREEN_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on BLUE_PIN (BCM %d): %s", BLUE_PIN, pigpio_error(BLUE_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on RED_PIN (BCM %d): %s", RED_PIN, pigpio_error(RED_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GREEN_PIN (BCM %d): %s", GREEN_PIN, pigpio_error(GREEN_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on BLUE_PIN (BCM %d): %s", BLUE_PIN, pigpio_error(BLUE_PIN));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (set_led_color(0, 0, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize LED to off state");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));
    int r, g, b;

    while (g_running) {
        random_color(&r, &g, &b);
        fade_to_color(r, g, b);
    }

    if (set_led_color(0, 0, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn off LED on exit");
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

