/*
 * TCS34725 Color Sensor Reader with LED Threshold Indicator
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1 (BCM pins 2 = SDA, 3 = SCL)
 * Sensor: TCS34725 on 0x29
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725 tcs34725.c -lpigpio -lrt
 * Run:    sudo ./tcs34725
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- TCS34725 constants (datasheet) ---- */
#define TCS34725_I2C_ADDR      0x29
#define TCS34725_COMMAND_BIT   0x80
#define TCS34725_ENABLE        0x00
#define TCS34725_ATIME         0x01
#define TCS34725_CONTROL       0x0F
#define TCS34725_CDATA         0x14
#define TCS34725_RDATA         0x16
#define TCS34725_GDATA         0x18
#define TCS34725_BDATA         0x1A

#define TCS34725_ENABLE_PON    0x01
#define TCS34725_ENABLE_AEN    0x02
#define TCS34725_ATIME_154MS   0xC0   /* 154 ms integration time */
#define TCS34725_CONTROL_A1    0x01   /* gain 1x */

#define I2C_BUS        "/dev/i2c-1"
#define LED_GPIO       17
#define RED_THRESHOLD  200
#define POLL_MS        200

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register.                               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register.                              */
/* Returns 0 on success and stores the value in *out, -1 on error.    */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, enable RGBC, set integration     */
/* time, set gain, then wait for the first integration cycle.          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* power-on settling time */

    if (i2c_write_reg8(fd, TCS34725_ATIME, TCS34725_ATIME_154MS) != 0)
        return -1;

    if (i2c_write_reg8(fd, TCS34725_CONTROL, TCS34725_CONTROL_A1) != 0)
        return -1;

    if (i2c_write_reg8(fd, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    usleep(200000);  /* first integration cycle */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated RGBC values.                                        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_rgbc(int fd, uint16_t *r, uint16_t *g,
                              uint16_t *b, uint16_t *c)
{
    uint8_t rb, gr, bl, cl;

    if (i2c_read_reg8(fd, TCS34725_RDATA, &rb) != 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA, &gr) != 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA, &bl) != 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_CDATA, &cl) != 0) return -1;

    *r = (uint16_t)rb;
    *g = (uint16_t)gr;
    *b = (uint16_t)bl;
    *c = (uint16_t)cl;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg8(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TCS34725 ready. Polling every %d ms. Press Ctrl-C to exit.\n",
           POLL_MS);

    while (g_running) {
        uint16_t r, g, b, c;

        if (tcs34725_read_rgbc(g_i2c_fd, &r, &g, &b, &c) == 0) {
            printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);
            gpioWrite(LED_GPIO, (r > RED_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Read failed; re-initialising sensor...\n");
            if (tcs34725_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-initialisation failed; exiting.\n");
                break;
            }
        }

        usleep(POLL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

