/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (I2C bus 1, pin 3)
 *   BH1750 SCL  → GPIO3  (I2C bus 1, pin 5)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO10 (SPI0 MOSI, pin 19)
 *   APA102 CS   → GPIO8  (SPI0 CE0,  pin 24)
 *   APA102 VCC  → 5 V
 *   APA102 GND  → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_led light_led.c -lpigpio -lrt
 * Run:    sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_CONT    0x10   /* continuous H-Resolution mode */
#define BH1750_CONV_MS 120    /* conversion time for H-Resolution */
#define LED_COUNT      16
#define SPI_SPEED_HZ   1000000
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *bus)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    uint8_t  bits  = 8;
    uint8_t  mode  = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int spi_write(int fd, const uint8_t *data, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)data;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* APA102 helpers                                                      */
/* ------------------------------------------------------------------ */

static void apa102_frame(uint8_t *frame, int count)
{
    /* Start frame: 32 bits of 0 */
    memset(frame, 0x00, 4);
    /* LED frames: each LED has 4 bytes (B, G, R, B) */
    for (int i = 0; i < count; i++) {
        frame[4 + i * 4 + 0] = 0x00;   /* blue   */
        frame[4 + i * 4 + 1] = 0x00;   /* green  */
        frame[4 + i * 4 + 2] = 0x00;   /* red    */
        frame[4 + i * 4 + 3] = 0xFF;   /* brightness (255 = full) */
    }
    /* End frame: 32 bits of 0 */
    memset(frame + 4 + count * 4, 0x00, 4);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus and BH1750 */
    int i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

    /* Open SPI bus and APA102 */
    int spi_fd = spi_open(SPI_BUS);
    if (spi_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Power on BH1750 */
    if (i2c_write_byte(i2c_fd, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "BH1750 power-on failed (sensor may be absent)\n");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(10000);  /* 10 ms power-on delay */

    /* Main loop */
    while (g_running) {
        /* Trigger continuous H-Resolution conversion */
        if (i2c_write_byte(i2c_fd, BH1750_CONT) < 0) {
            fprintf(stderr, "BH1750 trigger failed\n");
            break;
        }
        usleep(BH1750_CONV_MS * 1000);

        uint16_t raw;
        if (i2c_read_word(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read failed\n");
            break;
        }

        /* Convert raw count to lux (1 lux = 1.2 raw units) */
        float lux = (float)raw / 1.2f;

        /* Scale brightness 0–255 */
        int brightness = (int)(lux / 100.0f * 255.0f);
        if (brightness < 0)   brightness = 0;
        if (brightness > 255) brightness = 255;

        /* Build APA102 frame */
        uint8_t *frame = malloc((size_t)LED_COUNT * 4 + 8);
        if (!frame) {
            fprintf(stderr, "malloc failed\n");
            break;
        }
        apa102_frame(frame, LED_COUNT);

        /* Turn off LEDs first to avoid ghosting */
        memset(frame, 0x00, (size_t)LED_COUNT * 4 + 8);
        if (spi_write(spi_fd, frame, (size_t)LED_COUNT * 4 + 8) < 0) {
            free(frame);
            break;
        }

        /* Set brightness for each LED */
        for (int i = 0; i < LED_COUNT; i++) {
            int b = (int)(brightness * (i + 1) / LED_COUNT);
            if (b < 0)   b = 0;
            if (b > 255) b = 255;
            frame[4 + i * 4 + 0] = (uint8_t)b;   /* blue   */
            frame[4 + i * 4 + 1] = (uint8_t)b;   /* green  */
            frame[4 + i * 4 + 2] = (uint8_t)b;   /* red    */
            frame[4 + i * 4 + 3] = 0xFF;         /* brightness */
        }

        if (spi_write(spi_fd, frame, (size_t)LED_COUNT * 4 + 8) < 0) {
            free(frame);
            break;
        }
        free(frame);

        usleep(SAMPLE_MS * 1000);
    }

    /* Graceful shutdown: turn off all LEDs */
    uint8_t off[LED_COUNT * 4 + 8];
    memset(off, 0x00, (size_t)LED_COUNT * 4 + 8);
    spi_write(spi_fd, off, (size_t)LED_COUNT * 4 + 8);

    close(spi_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

