#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <bcm2835.h>

#define NUM_SENSORS 3
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define FADE_MS 500
#define LOOP_DELAY_MS 100
#define BH1750_CONV_MS 180
#define BH1750_ADDR 0x29
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_POWER_DOWN 0x00
#define APA102_START 0x00
#define APA102_END 0xFF
#define APA102_FRAME_LEN 4
#define MAX_READ_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fds[NUM_SENSORS];
static int g_spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_DOWN) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    return 0;
}

static int bh1750_read(int fd, uint16_t *out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };
    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_write(int fd, uint8_t brightness) {
    uint8_t tx[APA102_FRAME_LEN * 4];
    uint8_t rx[APA102_FRAME_LEN * 4];
    size_t idx = 0;
    for (int i = 0; i < 4; i++) {
        tx[idx++] = APA102_START;
        tx[idx++] = 0;
        tx[idx++] = brightness;
        tx[idx++] = APA102_END;
    }
    return spi_transfer(tx, rx, idx);
}

static void fade_brightness(int target, int *current, int duration_ms) {
    int step = (target > *current) ? 1 : -1;
    int elapsed = 0;
    while (elapsed < duration_ms && g_running) {
        *current += step;
        if (apa102_write(g_spi_fd, (uint8_t)(*current)) < 0) break;
        usleep(1000);
        elapsed++;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        bcm2835_close();
        return 1;
    }

    uint8_t mode = BCM2835_SPI_MODE0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (bcm2835_spi_begin() != 0) {
        fprintf(stderr, "bcm2835_spi_begin failed\n");
        close(g_spi_fd);
        bcm2835_close();
        return 1;
    }
    bcm2835_spi_setBitOrder(bits);
    bcm2835_spi_setDataMode(mode);
    bcm2835_spi_setClockDivider(speed);

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (g_i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
            for (int j = 0; j < i; j++) close(g_i2c_fds[j]);
            close(g_spi_fd);
            bcm2835_close();
            return 1;
        }
        if (ioctl(g_i2c_fds[i], I2C_SLAVE, BH1750_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
            close(g_i2c_fds[i]);
            for (int j = 0; j < i; j++) close(g_i2c_fds[j]);
            close(g_spi_fd);
            bcm2835_close();
            return 1;
        }
        if (bh1750_init(g_i2c_fds[i]) < 0) {
            fprintf(stderr, "BH1750 init failed on sensor %d\n", i);
            close(g_i2c_fds[i]);
            for (int j = 0; j < i; j++) close(g_i2c_fds[j]);
            close(g_spi_fd);
            bcm2835_close();
            return 1;
        }
    }

    int current_brightness = 0;
    while (g_running) {
        uint16_t readings[NUM_SENSORS];
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_fds[i] < 0) continue;
            if (i2c_write_byte(g_i2c_fds[i], BH1750_CONT_HIGH_RES) < 0) {
                fprintf(stderr, "Sensor %d: failed to set high-res mode\n", i);
                continue;
            }
            usleep(BH1750_CONV_MS * 1000);
            uint16_t raw;
            int retries = 0;
            while (retries < MAX_READ_RETRIES) {
                if (bh1750_read(g_i2c_fds[i], &raw) == 0) {
                    readings[valid++] = raw;
                    break;
                }
                retries++;
                usleep(10000);
            }
            if (retries == MAX_READ_RETRIES) {
                fprintf(stderr, "Sensor %d: failed to read after %d retries\n", i, MAX_READ_RETRIES);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid sensor readings this cycle\n");
        } else {
            double sum = 0.0;
            for (int i = 0; i < valid; i++) sum += readings[i];
            double avg = sum / valid;
            int target = (int)(avg / 10.0);
            if (target < 0) target = 0;
            if (target > 255) target = 255;
            printf("Avg: %.2f  Target: %d\n", avg, target);
            fade_brightness(target, &current_brightness, FADE_MS);
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_fds[i] >= 0) {
            i2c_write_byte(g_i2c_fds[i], BH1750_POWER_DOWN);
            close(g_i2c_fds[i]);
        }
    }
    if (g_spi_fd >= 0) {
        apa102_write(g_spi_fd, 0);
        close(g_spi_fd);
    }
    bcm2835_spi_end();
    bcm2835_close();
    return 0;
}

