#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define VEML7700_ADDR 0x18
#define VEML7700_CONF 0x00
#define VEML7700_ALS 0x04
#define I2C_BUS "/dev/i2c-1"
#define LED_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define GAMMA 2.4

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int fd) {
    uint8_t config[2] = {0x00, 0x00};
    if (write(fd, config, 2) != 2) {
        perror("Failed to write VEML7700 config");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int fd, float *lux) {
    uint8_t reg = VEML7700_ALS;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to set ALS register");
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read ALS data");
        return -1;
    }
    uint16_t raw = (data[0] << 8) | data[1];
    *lux = (float)raw;
    return 0;
}

static int veml7700_read_lux_retry(int fd, float *lux) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (veml7700_read_lux(fd, lux) == 0) return 0;
        if (i < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static float gamma_correct(float lux) {
    return powf(lux, GAMMA);
}

static void ws2812b_set_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    uint8_t r = (uint8_t)brightness;
    uint8_t g = (uint8_t)brightness;
    uint8_t b = (uint8_t)brightness;
    uint8_t data[24] = {0};
