#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

#define TEST_SAMPLES     5
#define TEST_INTERVAL_US 100000   /* 100 ms */
#define TEST_BLINK_US    500000   /* 500 ms */
#define LOOP_DELAY_US    50000    /* 50 ms  */
#define BUZZER_SHORT_US  200000   /* 200 ms */
#define BUZZER_LONG_US   600000   /* 600 ms */
#define BUZZER_REPEAT    3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int self_test(void)
{
    log_event("Starting self-test...");

    /* Blink LED twice: 500 ms on / 500 ms off */
    for (int i = 0; i < 2; i++) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            log_event("Self-test failed: LED write on failed");
            return -1;
        }
        gpioDelay(TEST_BLINK_US);
        if (gpioWrite(LED_PIN, 0) < 0) {
            log_event("Self-test failed: LED write off failed");
            return -1;
        }
        gpioDelay(TEST_BLINK_US);
    }

    /* Read flame sensor TEST_SAMPLES times, expect HIGH (no flame) each time */
    int flame_ok = 1;
    for (int i = 0; i < TEST_SAMPLES; i++) {
        int v = gpioRead(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Self-test failed: flame sensor read error");
            return -1;
        }
        if (v == 0) {
            flame_ok = 0;
            log_event("Self-test failed: flame detected during self-test");
            break;
        }
        if (i < TEST_SAMPLES - 1) {
            gpioDelay(TEST_INTERVAL_US);
        }
    }

    if (!flame_ok) {
        log_event("Self-test failed: flame detected on sensor");
        return -1;
    }

    log_event("Self-test passed!");
    return 0;
}

static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure outputs start LOW */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (self_test() != 0) {
        fprintf(stderr, "Self-test failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Entering main loop...");

    while (g_running) {
        int v = gpioRead(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Error reading flame sensor");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (v == 0) {
            log_event("Flame detected!");
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                log_event("Error activating buzzer");
            }
            if (gpioWrite(LED_PIN, 1) < 0) {
                log_event("Error activating LED");
            }

            /* Keep outputs on until flame clears */
            while (g_running) {
                int r = gpioRead(FLAME_SENSOR_PIN);
                if (r < 0) {
                    log_event("Error reading flame sensor during loop");
                    break;
                }
                if (r == 1) {
                    if (gpioWrite(BUZZER_PIN, 0) < 0) {
                        log_event("Error deactivating buzzer");
                    }
                    if (gpioWrite(LED_PIN, 0) < 0) {
                        log_event("Error deactivating LED");
                    }
                    log_event("Flame cleared.");
                    break;
                }
                gpioDelay(LOOP_DELAY_US);
            }
        } else {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    log_event("Exiting...");
    cleanup();
    return EXIT_SUCCESS;
}

