#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CONT    0x10
#define LED_GPIO       17
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1
#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0
#define MIN_LUX        1000.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT) < 0) {
        return -1;
    }
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw / 1.2f;
    return 0;
}

static void buffer_add(float lux, float *buf, int *idx, int size) {
    buf[*idx] = lux;
    *idx = (*idx + 1) % size;
}

static float buffer_avg(const float *buf, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buf[i];
    }
    return sum / (float)size;
}

static void gpio_export(int pin) {
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (fp) {
        fprintf(fp, "%d", pin);
        fclose(fp);
    } else if (errno != EBUSY) {
        fprintf(stderr, "GPIO export failed: %s\n", strerror(errno));
    }
}

static void gpio_unexport(int pin) {
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp) {
        fprintf(fp, "%d", pin);
        fclose(fp);
    }
}

static void gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%s", dir);
        fclose(fp);
    }
}

static void gpio_set_value(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", val);
        fclose(fp);
    }
}

static void gpio_unexport_pin(int pin) {
    gpio_unexport(pin);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(g_i2c_fd);
        return 1;
    }

    gpio_export(LED_GPIO);
    gpio_set_direction(LED_GPIO, "out");
    gpio_set_value(LED_GPIO, 0);

    float lux_buffer[BUFFER_SIZE];
    int   buffer_index = 0;

    while (g_running) {
        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        buffer_add(lux, lux_buffer, &buffer_index, BUFFER_SIZE);

        float avg = buffer_avg(lux_buffer, BUFFER_SIZE);
        float freq = MIN_FREQ_HZ + (avg - MIN_LUX) * (MAX_FREQ_HZ - MIN_FREQ_HZ) / (1000.0f - MIN_LUX);

        int period_us = (int)(1000000.0f / freq);
        int half_us   = period_us / 2;

        gpio_set_value(LED_GPIO, 1);
        usleep(half_us);
        gpio_set_value(LED_GPIO, 0);
        usleep(half_us);

        printf("Lux: %.2f, Avg: %.2f, Freq: %.2f Hz\n", lux, avg, freq);
        sleep(SAMPLE_PERIOD);
    }

    gpio_set_value(LED_GPIO, 0);
    gpio_unexport_pin(LED_GPIO);
    close(g_i2c_fd);
    return 0;
}

