#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define BIT_DELAY_US 1
#define BLINK_DELAY_US 500000

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
}

int shift_out(int data_pin, int clock_pin, int latch_pin, unsigned char data) {
    for (int i = 0; i < 8; i++) {
        if (gpioWrite(data_pin, (data >> (7 - i)) & 1) < 0) {
            fprintf(stderr, "Error writing data pin\n");
            return -1;
        }
        gpioDelay(BIT_DELAY_US);
        if (gpioWrite(clock_pin, 1) < 0) {
            fprintf(stderr, "Error writing clock pin high\n");
            return -1;
        }
        gpioDelay(BIT_DELAY_US);
        if (gpioWrite(clock_pin, 0) < 0) {
            fprintf(stderr, "Error writing clock pin low\n");
            return -1;
        }
    }
    if (gpioWrite(latch_pin, 1) < 0) {
        fprintf(stderr, "Error writing latch pin high\n");
        return -1;
    }
    gpioDelay(BIT_DELAY_US);
    if (gpioWrite(latch_pin, 0) < 0) {
        fprintf(stderr, "Error writing latch pin low\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    unsigned char digit_pattern = 0b01101111; /* 5: a b c d e g */

    while (keep_running) {
        if (shift_out(DATA_PIN, CLOCK_PIN, LATCH_PIN, digit_pattern) < 0) {
            cleanup();
            return 1;
        }
        gpioDelay(BLINK_DELAY_US);
        if (!keep_running) break;
        if (shift_out(DATA_PIN, CLOCK_PIN, LATCH_PIN, 0x00) < 0) {
            cleanup();
            return 1;
        }
        gpioDelay(BLINK_DELAY_US);
    }

    cleanup();
    return 0;
}

