#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"
#define PERIOD_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request button line as input with pull-up and falling-edge event detection */
    ret = gpiod_line_request_falling_edge_events_flags(button_line, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d for %d seconds. Press the button (GPIO%d) to exit.\n",
           LED_PIN, PERIOD_SEC, BUTTON_PIN);
    fflush(stdout);

    /* Blink loop */
    while (keep_running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (on)");
            break;
        }

        /* Sleep for half the period (1 second) */
        sleep(PERIOD_SEC / 2);

        /* Check for button press event */
        ret = gpiod_line_event_wait(button_line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout — continue blinking */
            continue;
        }

        /* Read and discard event to clear it */
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        /* Turn LED off */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (off)");
            break;
        }

        printf("Button pressed! Exiting.\n");
        fflush(stdout);

        break;
    }

    /* Clean shutdown: turn LED off and release resources */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

