        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, "blink-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request button line as input with pull-down */
    if (gpiod_line_request_input_flags(button_line, "blink-button",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request button line as input with pull-down: %s\n", strerror(errno));
        goto cleanup;
    }

