            usleep(BLINK_DELAY_MS * 1000);
        } else {
            /* Button released: ensure LED is off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
                break;
            }
            usleep(10000); /* 10 ms poll interval */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (button_line != NULL) {
        gpiod_line_release(button_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

