#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_FREQ  100          /* Hz */
#define PWM_RANGE 100          /* 0..100 duty cycle */
#define PWM_PERIOD_US 10000    /* 10 ms -> 100 Hz */
#define STEP_US    1000        /* 1 ms sub-millisecond steps for PWM */
#define LOOP_DELAY_US 100000   /* 100 ms between colour changes */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000;
    ts.tv_nsec = (long)(us % 1000000) * 1000;
    clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
}

int main(void)
{
    srand((unsigned int)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all channels start off */
    set_pwm(RED_PIN, 0);
    set_pwm(GREEN_PIN, 0);
    set_pwm(BLUE_PIN, 0);

    while (g_running) {
        int red   = rand() % (PWM_RANGE + 1);
        int green = rand() % (PWM_RANGE + 1);
        int blue  = rand() % (PWM_RANGE + 1);

        /* Software PWM: drive each channel for PWM_PERIOD_US, updating duty cycle every STEP_US */
        for (int i = 0; i < PWM_PERIOD_US / STEP_US && g_running; i++) {
            if (set_pwm(RED_PIN,   red)   != 0) break;
            if (set_pwm(GREEN_PIN, green) != 0) break;
            if (set_pwm(BLUE_PIN,  blue)  != 0) break;
            sleep_us(STEP_US);
        }

        /* Wait 100 ms between colour changes */
        for (int i = 0; i < LOOP_DELAY_US / STEP_US && g_running; i++) {
            sleep_us(STEP_US);
        }
    }

    /* Clean shutdown: turn off all LEDs and release pigpio */
    set_pwm(RED_PIN,   0);
    set_pwm(GREEN_PIN, 0);
    set_pwm(BLUE_PIN,  0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

