#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- LSM303DLHC accelerometer I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19

/* ---- LSM303DLHC accelerometer registers ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

/* ---- Impact detection parameters ---- */
#define IMPACT_THRESHOLD_G 2.0f
#define IMPACT_GPIO        17
#define IMPACT_PULSE_US    50000   /* 50 ms in microseconds */
#define POLL_DELAY_US      100000  /* 100 ms = 10 Hz */
#define LOG_FILE           "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize the LSM303DLHC accelerometer                              */
/* ------------------------------------------------------------------ */
static int init_accelerometer(void)
{
    /* CTRL_REG1_A: enable accelerometer, 10 Hz ODR, all axes enabled */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1_A\n");
        return -1;
    }

    /* CTRL_REG4_A: full-scale range +/-2g (FS=00) */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit big-endian axis value from the accelerometer         */
/* ------------------------------------------------------------------ */
static int read_axis(int handle, uint8_t reg_l, uint8_t reg_h, int16_t *out)
{
    int lo = i2cReadByteData(handle, reg_l);
    if (lo < 0) {
        fprintf(stderr, "Error: I2C read failed at reg 0x%02X\n", reg_l);
        return -1;
    }
    int hi = i2cReadByteData(handle, reg_h);
    if (hi < 0) {
        fprintf(stderr, "Error: I2C read failed at reg 0x%02X\n", reg_h);
        return -1;
    }
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data and compute G-force magnitude               */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (read_axis(handle, LSM303_ACCEL_OUT_X_L_A, LSM303_ACCEL_OUT_X_H_A, &raw_x) < 0)
        return -1;
    if (read_axis(handle, LSM303_ACCEL_OUT_Y_L_A, LSM303_ACCEL_OUT_Y_H_A, &raw_y) < 0)
        return -1;
    if (read_axis(handle, LSM303_ACCEL_OUT_Z_L_A, LSM303_ACCEL_OUT_Z_H_A, &raw_z) < 0)
        return -1;

    /* Default ±2g range: 1 mg/LSB => 0.001 g/LSB */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the magnitude of the G-force vector                         */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log accelerometer data to file                                      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Trigger an impact interrupt on GPIO17                               */
/* ------------------------------------------------------------------ */
static void trigger_impact(void)
{
    if (gpioWrite(IMPACT_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite HIGH failed\n");
        return;
    }
    gpioDelay(IMPACT_PULSE_US);
    if (gpioWrite(IMPACT_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite LOW failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float impact_threshold = IMPACT_THRESHOLD_G;

    /* Parse command-line argument for impact threshold */
    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || val <= 0.0f) {
            fprintf(stderr, "Usage: %s [impact_threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
        impact_threshold = (float)val;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LSM303DLHC accelerometer address */
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Sensor may be absent or bus unavailable.\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the accelerometer */
    if (init_accelerometer() < 0) {
        fprintf(stderr, "Error: accelerometer initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as an output and ensure it starts LOW */
    if (gpioSetMode(IMPACT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", IMPACT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(IMPACT_GPIO, 0);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed; signals may not be caught\n");
    }

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           impact_threshold);

    /* Main polling loop */
    while (running) {
        float x, y, z;

        if (read_accelerometer(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed; "
                            "continuing after brief delay.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.3f G\n", magnitude);
            trigger_impact();
            log_data(log_file, x, y, z);
        } else {
            log_data(log_file, x, y, z);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

