#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x54
#define LED_GPIO 18
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

/* ADPD188BI register addresses */
#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADPD188BI_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_ALS_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)((buf[1] << 8) | buf[0]);

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_RED_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading RED data: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)((buf[1] << 8) | buf[0]);

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_GREEN_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading GREEN data: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)((buf[1] << 8) | buf[0]);

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_BLUE_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading BLUE data: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)((buf[1] << 8) | buf[0]);

    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led_brightness(uint16_t als) {
    /* Map ALS (0-65535) to PWM duty cycle (0-255) */
    int duty = (int)((float)als / 65535.0f) * 255;
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (gpioPWM(LED_GPIO, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", LED_GPIO);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t als, red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting ADPD188BI color logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led_brightness(als);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in 100 ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

