#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- FXOS8700CQ register definitions ---- */
#define FXOS8700_ADDRESS        0x1D
#define FXOS8700_WHO_AM_I       0x0D
#define FXOS8700_WHO_AM_I_VAL   0xC7
#define FXOS8700_CTRL_REG1      0x2A
#define FXOS8700_CTRL_REG2      0x2B
#define FXOS8700_M_CTRL_REG1    0x5B
#define FXOS8700_M_CTRL_REG2    0x5C
#define FXOS8700_OUT_X_MSB      0x01
#define FXOS8700_OUT_X_LSB      0x02
#define FXOS8700_OUT_Y_MSB      0x03
#define FXOS8700_OUT_Y_LSB      0x04
#define FXOS8700_OUT_Z_MSB      0x05
#define FXOS8700_OUT_Z_LSB      0x06

/* ---- Configuration ---- */
#define I2C_BUS                 1
#define IMPACT_THRESHOLD        1.0f
#define SAMPLE_INTERVAL_US      50000   /* 50 ms */
#define ACTIVATE_DELAY_US       10000   /* 10 ms  */
#define LOG_FILE                "impact_log.txt"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): pigpio error %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): pigpio error %d\n",
                reg, len, rc);
    }
    return rc;
}

/* ---- Sensor initialization ---- */
static int init_fxos8700(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: pigpio error %d\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (clear ACTIVE bit) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) < 0)
        return -1;

    /* ±2 g range, 200 Hz ODR (bits[3:0] = 0x0A) */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x0A) < 0)
        return -1;

    /* Auto-reset on magnetic sensor overflow */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, 0x01) < 0)
        return -1;

