#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define ALERT_THRESHOLD 50.0f
#define LOG_FILE       "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG2, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) != 0) return -1;
    return 0;
}

static int gyro_read(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L, raw, 6) != 0)
        return -1;
    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);
    *x = (float)rx;
    *y = (float)ry;
    *z = (float)rz;
    return 0;
}

static void log_alert(FILE *fp, float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s, ALERT: X=%.2f, Y=%.2f, Z=%.2f dps\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    int samples = 0;
    while (g_running && samples < 100) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration read error, continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x_off -= x; y_off -= y; z_off -= z;
        samples++;
        usleep(SAMPLE_PERIOD_US);
    }
    if (!g_running) goto cleanup;
    x_off /= (float)samples;
    y_off /= (float)samples;
    z_off /= (float)samples;
    printf("Calibration complete: offsets X=%.2f, Y=%.2f, Z=%.2f\n", x_off, y_off, z_off);

    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= x_off;
        y -= y_off;
        z -= z_off;
        time_t now = time(NULL);
        struct tm tmv;
        char ts[32];
        localtime_r(&now, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
        fprintf(g_log_fp, "%s, X=%.2f, Y=%.2f, Z=%.2f\n", ts, x, y, z);
        fflush(g_log_fp);
        if (fabsf(x) > ALERT_THRESHOLD || fabsf(y) > ALERT_THRESHOLD || fabsf(z) > ALERT_THRESHOLD) {
            log_alert(g_log_fp, x, y, z);
            fprintf(stderr, "ALERT: X=%.2f, Y=%.2f, Z=%.2f dps\n", x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

cleanup:
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

