#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATAX0      0x32
#define ADXL345_REG_DATA_FORMAT 0x31

/* Expected device ID */
#define ADXL345_DEVID_EXPECTED  0xE5

/* Full-resolution mode, ±2 g range */
#define ADXL345_DATA_FORMAT_CFG 0x08

/* Power-saving mode: standby */
#define ADXL345_POWER_CTL_STANDBY 0x00

/* Active-high LED on GPIO17 (BCM numbering) */
#define LED_GPIO 17

/* Acceleration threshold in g */
#define ACCEL_THRESHOLD 2.0f

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed (got %d bytes): %d\n", rc, rc);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n",
            timestamp, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

static void control_led(int gpio, bool on)
{
    gpioWrite(gpio, on ? 1 : 0);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345_ADDR */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t devid = 0;
    if (adxl345_read_reg(g_i2c_handle, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure data format: full resolution, ±2 g range */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_DATA_FORMAT,
                          ADXL345_DATA_FORMAT_CFG) != 0) {
        fprintf(stderr, "Failed to configure data format\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enter standby mode to allow configuration changes */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL,
                          ADXL345_POWER_CTL_STANDBY) != 0) {
        fprintf(stderr, "Failed to enter standby mode\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set sample rate to 10 Hz (ODR = 1000 Hz, power-saving mode 0) */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to set ODR\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it is off */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("ADXL345 logging started (10 Hz). Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;

        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            /* Convert raw 16-bit two's-complement to g units.
             * Full-resolution ±2 g range: 4 mg/LSB => 0.004 g/LSB.
             * Scale factor = 0.004 g/LSB. */
            float x_g = (float)x * 0.004f;
            float y_g = (float)y * 0.004f;
            float z_g = (float)z * 0.004f;

            log_data(g_log_file, x, y, z);

            bool exceed = (fabsf(x_g) > ACCEL_THRESHOLD ||
                           fabsf(y_g) > ACCEL_THRESHOLD ||
                           fabsf(z_g) > ACCEL_THRESHOLD);
            control_led(LED_GPIO, exceed);
        } else {
            /* On read failure, turn LED off and skip this sample to avoid
             * logging garbage. */
            control_led(LED_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    control_led(LED_GPIO, 0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

