#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_CTRL_REG1_M   0x50
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Globals for cleanup ---- */
static int accel_handle = -1;
static int mag_handle   = -1;
static FILE *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- Read a block of bytes from an I2C register ---- */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

/* ---- Read a signed 16-bit little-endian value from two consecutive registers ---- */
static int16_t read_s16(int handle, uint8_t reg) {
    uint8_t buf[2];
    if (read_block(handle, reg, buf, 2) < 0) return 0;
    return (int16_t)((buf[1] << 8) | buf[0]);
}

/* ---- Read a signed 16-bit big-endian value from two consecutive registers ---- */
static int16_t read_s16_be(int handle, uint8_t reg) {
    uint8_t buf[2];
    if (read_block(handle, reg, buf, 2) < 0) return 0;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

/* ---- Read a signed 8-bit value from a register ---- */
static int8_t read_s8(int handle, uint8_t reg) {
    uint8_t buf[1];
    if (read_block(handle, reg, buf, 1) < 0) return 0;
    return (int8_t)buf[0];
}

/* ---- Initialize the LSM303DLHC ---- */
static int init_lsm303(void) {
    /* Accelerometer: enable X/Y/Z axes, 50 Hz ODR */
    if (i2cWriteByteData(accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write accel CTRL_REG1_A\n");
        return -1;
    }
    /* Magnetometer: 80 Hz ODR, continuous conversion */
    if (i2cWriteByteData(mag_handle, LSM303_MAG_CTRL_REG1_M, 0x10) < 0) {
        fprintf(stderr, "Error: failed to write mag CTRL_REG1_M\n");
        return -1;
    }
    return 0;
}

/* ---- Read accelerometer data ---- */
static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    *x = read_s16(accel_handle, LSM303_ACCEL_OUT_X_L_A);
    *y = read_s16(accel_handle, LSM303_ACCEL_OUT_X_L_A + 2);
    *z = read_s16(accel_handle, LSM303_ACCEL_OUT_X_L_A + 4);
    return 0;
}

/* ---- Read magnetometer data ---- */
static int read_mag(int16_t *x, int16_t *y, int16_t *z) {
    *x = read_s16_be(mag_handle, LSM303_MAG_OUT_X_H_M);
    *y = read_s16_be(mag_handle, LSM303_MAG_OUT_X_H_M + 1);
    *z = read_s16_be(mag_handle, LSM303_MAG_OUT_X_H_M + 2);
    return 0;
}

/* ---- Tilt-compensated heading ---- */
static float calc_heading(int16_t ax, int16_t ay, int16_t az,
                          int16_t mx, int16_t my, int16_t mz) {
    float ax_g = (float)ax / 16384.0f;
    float ay_g = (float)ay / 16384.0f;
    float az_g = (float)az / 16384.0f;
    float mx_g = (float)mx / 10.0f;
    float my_g = (float)my / 10.0f;
    float mz_g = (float)mz / 10.0f;

    float roll  = atan2f(ay_g, az_g);
    float pitch = atan2f(-ax_g, sqrtf(ay_g * ay_g + az_g * az_g));

