#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_CTRL_REG1_M   0x50
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Globals for cleanup ---- */
static int accel_handle = -1;
static int mag_handle   = -1;
static FILE *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- Read a block of bytes from an I2C register ---- */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

/* ---- Read a signed 16-bit little-endian value from two consecutive registers ---- */
static int16_t read_s16(int handle, uint8_t reg) {
    uint8_t buf[2];
    if (read_block(handle, reg, buf, 2) < 0) return 0;
    return (int16_t)((buf[1] << 8) | buf[0]);
}

/* ---- Read a signed 16-bit big-endian value from two consecutive registers ---- */
static int16_t read_s16_be(int handle, uint8_t reg) {
    uint8_t buf[2];
    if (read_block(handle, reg, buf, 2) < 0) return 0;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

/* ---- Read a signed 8-bit value from a register ---- */
static int8_t read_s8(int handle, uint8_t reg) {
    uint8_t buf[1];
    if (read_block(handle, reg, buf, 1) < 0) return 0;
    return (int8_t)buf[0];
}

/* ---- Initialize the LSM303DLHC ---- */
static int init_lsm303(void) {
    /* Accelerometer: enable X/Y/Z axes, 50 Hz ODR */
    if (i2cWriteByteData(accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write accel CTRL_REG1_A\n");
        return -1;
