    /* Magnetometer: 80 Hz ODR, continuous conversion */
    if (i2cWriteByteData(mag_handle, LSM303_MAG_CTRL_REG1_M, 0x10) < 0) {
        fprintf(stderr, "Error: failed to write mag CTRL_REG1_M\n");
        return -1;
