#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x2A
#define SENSOR2_ADDR   0x2B
#define SAMPLE_PERIOD_US 10000
#define LOG_FILE       "audio_log.dat"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c_sensor(int bus, int addr)
{
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X on bus %d: %s\n",
                addr, bus, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_audio_sample(int handle, int16_t *sample)
{
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading from I2C handle %d: expected 2 bytes, got %d\n",
                handle, n);
        return -1;
    }
    *sample = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2)
{
    struct timespec ts1, ts2;
    clock_gettime(CLOCK_REALTIME, &ts1);
    clock_gettime(CLOCK_REALTIME, &ts2);
    return (double)(ts2.tv_sec - ts1.tv_sec) +
           (double)(ts2.tv_nsec - ts1.tv_nsec) / 1e9;
}

static int log_data(FILE *fp, double tdoa, int16_t s1, int16_t s2)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%ld,%ld,%d,%d,%.6f\n",
                (long)ts.tv_sec, (long)ts.tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = init_i2c_sensor(I2C_BUS, SENSOR1_ADDR);
    if (g_i2c_handle1 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = init_i2c_sensor(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c_handle2 < 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# timestamp_sec,timestamp_nsec,sensor1,sensor2,tdoa\n");
    fflush(g_log_fp);

    int16_t s1, s2;
    double tdoa;

    while (g_running) {
        if (read_audio_sample(g_i2c_handle1, &s1) != 0) {
            fprintf(stderr, "Sensor 1 read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_audio_sample(g_i2c_handle2, &s2) != 0) {
            fprintf(stderr, "Sensor 2 read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        tdoa = calculate_tdoa(s1, s2);

        if (log_data(g_log_fp, tdoa, s1, s2) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

