#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

#define ADIS16448_REG_GLOB_CMD 0x00
#define ADIS16448_REG_X_GYRO_OUT 0x04
#define ADIS16448_REG_Y_GYRO_OUT 0x06
#define ADIS16448_REG_Z_GYRO_OUT 0x08
#define ADIS16448_REG_X_ACCL_OUT 0x0A
#define ADIS16448_REG_Y_ACCL_OUT 0x0C
#define ADIS16448_REG_Z_ACCL_OUT 0x0E
#define ADIS16448_REG_SMPL_PRD 0x36
#define ADIS16448_REG_GLOB_CMD_RESET 0x0001

#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f
#define SAMPLE_PERIOD_MS 100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16448_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), (uint8_t)(value >> 8) };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int adis16448_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int adis16448_init(int fd) {
    if (adis16448_write_reg(fd, ADIS16448_REG_GLOB_CMD, ADIS16448_REG_GLOB_CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset ADIS16448\n");
        return -1;
    }
    usleep(100000);
    if (adis16448_write_reg(fd, ADIS16448_REG_SMPL_PRD, 0x000A) < 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    uint16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (adis16448_read_reg(fd, ADIS16448_REG_X_GYRO_OUT, &raw_gyro_x) < 0) return -1;
    if (adis16448_read_reg(fd, ADIS16448_REG_Y_GYRO_OUT, &raw_gyro_y) < 0) return -1;
    if (adis16448_read_reg(fd, ADIS16448_REG_Z_GYRO_OUT, &raw_gyro_z) < 0) return -1;
    if (adis16448_read_reg(fd, ADIS16448_REG_X_ACCL_OUT, &raw_accel_x) < 0) return -1;
    if (adis16448_read_reg(fd, ADIS16448_REG_Y_ACCL_OUT, &raw_accel_y) < 0) return -1;
    if (adis16448_read_reg(fd, ADIS16448_REG_Z_ACCL_OUT, &raw_accel_z) < 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

int main(void) {
    int fd = -1;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (adis16448_init(fd) < 0) {
        fprintf(stderr, "ADIS16448 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("ADIS16448 initialized. Logging data every %d ms...\n", SAMPLE_PERIOD_MS);

    while (g_running) {
        if (read_sensor_data(fd, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps | Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting cleanly...\n");
    close(fd);
    return 0;
}

