/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * I2C bus 1, address 0x68 (AD0 tied to GND)
 * Reads raw accelerometer and gyroscope data every 50 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6886 mpu6886.c
 * Run:    ./mpu6886   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6886 register map (verified against datasheet) ---- */
#define MPU6886_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define PWR_MGMT_2          0x6C
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43
#define WHO_AM_I            0x75
#define WHO_AM_I_VAL        0x34

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MPU-6886 initialization ---- */
static int mpu6886_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit, set DLPF_CFG = 3 (1 kHz internal, 98 Hz accel) */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilise */

    /* Disable sleep mode, enable all gyro axes, enable all accel axes */
    if (i2c_write_reg8(fd, PWR_MGMT_2, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Read one 16-bit big-endian sample with retry ---- */
static int read_sample(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                       int16_t *gx, int16_t *gy, int16_t *gz)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        uint8_t buf[14];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, sizeof(buf)) == 0) {
            *ax = (int16_t)((buf[0]  << 8) | buf[1]);
            *ay = (int16_t)((buf[2]  << 8) | buf[3]);
            *az = (int16_t)((buf[4]  << 8) | buf[5]);
            *gx = (int16_t)((buf[8]  << 8) | buf[9]);
            *gy = (int16_t)((buf[10] << 8) | buf[11]);
            *gz = (int16_t)((buf[12] << 8) | buf[13]);
            return 0;
        }
        usleep(10000);  /* 10 ms back-off before retry */
    }
    return -1;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    uint8_t who;
    if (i2c_read_reg8(g_i2c_fd, WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor may be absent or bus error\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu6886_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialisation failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialised. Reading every 50 ms. Press Ctrl-C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_sample(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }
        usleep(50000);  /* 50 ms */
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

