#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_BW_RATE     0x2C
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Expected device ID for ADXL345 */
#define ADXL345_DEVID_EXPECTED 0xE5

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 17

/* Impact threshold in g (2.5 g) */
#define IMPACT_THRESHOLD 2.5f

/* Scale factor for ±2 g full resolution: 256 LSB/g */
#define SCALE_FACTOR 256.0f

/* Polling interval in microseconds (10 ms) */
#define POLL_INTERVAL_US 10000

/* LED on-time in microseconds (500 ms) */
#define LED_ON_TIME_US 500000

/* Log file path */
#define LOG_FILE "impact_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register; abort on failure       */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%02X (value 0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register; abort on failure      */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian axis value from the ADXL345            */
/* ------------------------------------------------------------------ */
static int adxl_read_axis(int handle, uint8_t reg_x, int16_t *out)
{
    uint8_t lo, hi;
    if (adxl_read_reg(handle, reg_x, &lo) < 0)
        return -1;
    if (adxl_read_reg(handle, reg_x + 1, &hi) < 0)
        return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set full resolution mode  */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Read and verify device ID */
    if (adxl_read_reg(handle, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Error: ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Set data format: full resolution, ±2 g range (0x0B) */
    if (adxl_write_reg(handle, ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Set data rate to 100 Hz (0x0B) — oversampling by 4 */
    if (adxl_write_reg(handle, ADXL345_BW_RATE, 0x0B) < 0)
        return -1;

    /* Enable measurement mode (bit 3 = 1) */
    if (adxl_write_reg(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration in g from the ADXL345                            */
/* ------------------------------------------------------------------ */
static int adxl345_read_accel(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adxl_read_axis(handle, ADXL345_DATAX0, &raw_x) < 0)
        return -1;
    if (adxl_read_axis(handle, ADXL345_DATAY0, &raw_y) < 0)
        return -1;
    if (adxl_read_axis(handle, ADXL345_DATAZ0, &raw_z) < 0)
        return -1;

    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude of acceleration vector in g                     */
/* ------------------------------------------------------------------ */
static float magnitude_g(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to the log file                                */
/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp, float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Impact detected: magnitude = %.2f g (X=%.2f, Y=%.2f, Z=%.2f)\n",
            ts, mag, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z, mag;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at the ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the ADXL345 */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 impact monitor running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read error — continuing\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        mag = magnitude_g(x, y, z);

        if (mag > IMPACT_THRESHOLD) {
            printf("Impact detected: magnitude = %.2f g (X=%.2f, Y=%.2f, Z=%.2f)\n",
                   mag, x, y, z);

            /* Turn LED on for 500 ms */
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_PIN, 0);

            /* Log the event */
            log_impact(g_log_file, x, y, z, mag);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

