#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICM20602_ADDR 0x68

#define REG_SMPLRT_DIV   0x19
#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x2D
#define REG_GYRO_XOUT_H  0x33

#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int init_icm20602(void) {
    if (write_reg(REG_SMPLRT_DIV, 0x00) < 0) return -1;
    if (write_reg(REG_CONFIG, 0x00) < 0) return -1;
    if (write_reg(REG_GYRO_CONFIG, 0x00) < 0) return -1;
    if (write_reg(REG_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d)\n", len, reg, rc);
        return -1;
    }
    return 0;
}

static void log_data(const int16_t ax, const int16_t ay, const int16_t az,
                     const int16_t gx, const int16_t gy, const int16_t gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ICM20602_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_icm20602() < 0) {
        fprintf(stderr, "ICM-20602 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening imu_log.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
        fflush(log_file);
    }

    uint8_t accel_buf[6], gyro_buf[6];
    int16_t ax, ay, az, gx, gy, gz;

    while (running) {
        if (read_burst(REG_ACCEL_XOUT_H, accel_buf, 6) < 0) {
            running = 0;
            break;
        }
        if (read_burst(REG_GYRO_XOUT_H, gyro_buf, 6) < 0) {
            running = 0;
            break;
        }

        ax = (int16_t)((accel_buf[0] << 8) | accel_buf[1]);
        ay = (int16_t)((accel_buf[2] << 8) | accel_buf[3]);
        az = (int16_t)((accel_buf[4] << 8) | accel_buf[5]);
        gx = (int16_t)((gyro_buf[0] << 8) | gyro_buf[1]);
        gy = (int16_t)((gyro_buf[2] << 8) | gyro_buf[3]);
        gz = (int16_t)((gyro_buf[4] << 8) | gyro_buf[5]);

        log_data(ax, ay, az, gx, gy, gz);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

