#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define MMA8451_ADDR     0x1D
#define LED_GPIO         17
#define THRESHOLD_G      2.0f
#define POLL_DELAY_US    100000   /* 100 ms */
#define LED_ON_US        500000   /* 500 ms */
#define LOG_FILE         "impact_log.txt"

/* ---- MMA8451Q Registers ---- */
#define REG_STATUS       0x00
#define REG_OUT_X_MSB    0x01
#define REG_WHO_AM_I     0x0D
#define REG_CTRL_REG1    0x2A
#define REG_CTRL_REG2    0x2B
#define REG_CTRL_REG3    0x2C
#define REG_CTRL_REG4    0x2D
#define REG_CTRL_REG5    0x2E
#define REG_CTRL_REG6    0x2F

#define WHO_AM_I_VAL     0x2A
#define CTRL_REG1_WAKE   0x01
#define CTRL_REG2_STANDBY 0x00

/* ±2 g range: 1 g = 1024 counts */
#define COUNTS_PER_G     1024.0f

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, wbuf, 1) < 0)
        return -1;
    char rbuf[1];
    if (i2cReadDevice(i2c_handle, rbuf, 1) != 1)
        return -1;
    *val = (uint8_t)rbuf[0];
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, wbuf, 1) < 0)
        return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* ---- MMA8451Q init ---- */
static int init_mma8451q(void)
{
    uint8_t who;
    if (i2c_read_reg(REG_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg(REG_CTRL_REG2, CTRL_REG2_STANDBY) < 0) {
        fprintf(stderr, "Error: cannot set standby mode.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Default: 800 Hz ODR, normal mode */
    if (i2c_write_reg(REG_CTRL_REG1, CTRL_REG1_WAKE) < 0) {
        fprintf(stderr, "Error: cannot set wake mode.\n");
        return -1;
    }
    gpioDelay(1000);

    /* Enable XYZ axes, no high-rate, no anti-aliasing */
    if (i2c_write_reg(REG_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: cannot configure CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ---- Read acceleration (g) ---- */
static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(REG_OUT_X_MSB, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / COUNTS_PER_G;
    *y = (float)raw_y / COUNTS_PER_G;
    *z = (float)raw_z / COUNTS_PER_G;
    return 0;
}

/* ---- Impact detection ---- */
static bool detect_impact(float x, float y, float z)
{
    return (fabsf(x) > THRESHOLD_G ||
            fabsf(y) > THRESHOLD_G ||
            fabsf(z) > THRESHOLD_G);
}

/* ---- Logging ---- */
static void log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", ts, x, y, z);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2c_write_reg(REG_CTRL_REG2, CTRL_REG2_STANDBY);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at addr 0x%02X (err %d).\n",
                I2C_BUS, MMA8451_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mma8451q() < 0) {
        fprintf(stderr, "Error: MMA8451Q initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MMA8451Q impact monitor running. Threshold: %.1f g. Ctrl+C to exit.\n",
           THRESHOLD_G);

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_data(x, y, z);

        if (detect_impact(x, y, z)) {
            printf("Impact detected! X=%.2f Y=%.2f Z=%.2f g\n", x, y, z);
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

