        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ensure_csv_header(g_csv_fp) < 0) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_magnetic_field(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv_fp, x, y, z) < 0) {
