/*
 * LSM6DSR Fall Detection Logger for Raspberry Pi 3 Model B+
 * I2C bus 1 (SDA=GPIO2, SCL=GPIO3), 104 Hz ODR, ±2 g accel, ±250 dps gyro.
 * Logs timestamped readings to motion_log.txt; falls into FREEFALL then IMPACT
 * on acceleration magnitude < 0.2 g (IDLE) or > 2.5 g (FREEFALL).
 *
 * Build: gcc -O2 -Wall -o lsm6dsr_log lsm6dsr_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR constants ---- */
#define LSM6DSR_ADDR        0x6B
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x6A
#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define OUTX_L_G            0x22
#define OUTX_L_XL           0x28

#define ACCEL_SENSITIVITY   0.061f   /* mg/LSB at ±2 g */
#define GYRO_SENSITIVITY    8.75f    /* mdps/LSB at ±250 dps */
#define ACCEL_THRESHOLD     0.2f     /* g */
#define IMPACT_THRESHOLD    2.5f     /* g */
#define IMPACT_WINDOW_MS    1000     /* ms */
#define SAMPLE_PERIOD_US    968      /* 104 Hz */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_regs: write");
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        perror("i2c_read_regs: read");
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int fd)
{
    uint8_t who;
    if (i2c_read_regs(fd, WHO_AM_I, &who, 1) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* ±2 g accel, ±250 dps gyro, 104 Hz ODR */
    if (i2c_write_reg(fd, CTRL1_XL, 0x80) < 0) return -1;
    if (i2c_write_reg(fd, CTRL2_G, 0x80) < 0) return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_sample(int fd, float *ax, float *ay, float *az,
                       float *gx, float *gy, float *gz)
{
    uint8_t buf[12];
    if (i2c_read_regs(fd, OUTX_L_G, buf, 12) < 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *ax = (float)raw_ax * ACCEL_SENSITIVITY / 1000.0f;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY / 1000.0f;
    *az = (float)raw_az * ACCEL_SENSITIVITY / 1000.0f;
    *gx = (float)raw_gx * GYRO_SENSITIVITY / 1000.0f;
    *gy = (float)raw_gy * GYRO_SENSITIVITY / 1000.0f;
    *gz = (float)raw_gz * GYRO_SENSITIVITY / 1000.0f;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float ax, float ay, float az,
                     float gx, float gy, float gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tbuf, ts.tv_nsec / 1000000L, ax, ay, az, gx, gy, gz);
    fflush(fp);
}

/* ---- Fall detection ---- */
static void detect_fall(float ax, float ay, float az)
{
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static struct timespec ff_start = {0, 0};
    static bool in_impact_window = false;

    float mag = sqrtf(ax * ax + ay * ay + az * az);

    switch (state) {
    case IDLE:
        if (mag < ACCEL_THRESHOLD) {
            state = FREEFALL;
            ff_start = (struct timespec){0, 0};
            clock_gettime(CLOCK_REALTIME, &ff_start);
            printf("FREEFALL: |a|=%.3f g\n", mag);
        }
        break;

    case FREEFALL:
        if (mag > IMPACT_THRESHOLD) {
            state = IMPACT;
            in_impact_window = true;
            printf("IMPACT: |a|=%.3f g\n", mag);
        } else if (mag < ACCEL_THRESHOLD) {
            /* Re-enter IDLE if acceleration recovers below threshold */
            state = IDLE;
        }
        break;

    case IMPACT:
        if (!in_impact_window) {
            /* Outside the 1 s window — reset */
            state = IDLE;
            in_impact_window = false;
        }
        break;
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("motion_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen motion_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# LSM6DSR fall detection log started\n");
    fprintf(g_log_fp, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps\n");
    fflush(g_log_fp);

    printf("LSM6DSR ready. Logging to motion_log.txt (Ctrl+C to stop).\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_sample(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        log_data(g_log_fp, ax, ay, az, gx, gy, gz);
        detect_fall(ax, ay, az);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

