        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("motion_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen motion_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# LSM6DSR fall detection log started\n");
    fprintf(g_log_fp, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps\n");
    fflush(g_log_fp);

    printf("LSM6DSR ready. Logging to motion_log.txt (Ctrl+C to stop).\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_sample(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        log_data(g_log_fp, ax, ay, az, gx, gy, gz);
        detect_fall(ax, ay, az);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

