#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define L3G4200D_ADDR 0x6B

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28
#define OUT_X_H      0x29
#define OUT_Y_L      0x2A
#define OUT_Y_H      0x2B
#define OUT_Z_L      0x2C
#define OUT_Z_H      0x2D

/* Expected WHO_AM_I value for L3G4200D */
#define L3G4200D_WHO_AM_I 0xD3

/* Sensitivity: 8.75 mdps/LSB (114.285 LSB/deg/s) */
#define GYRO_SENSITIVITY 114.285f

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Retry parameters for I2C write operations */
#define I2C_WRITE_RETRIES 3
#define I2C_WRITE_RETRY_DELAY_US 1000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize the L3G4200D                                            */
/* ------------------------------------------------------------------ */
static int initialize_gyroscope(int handle)
{
    int result;

    /* Verify sensor identity */
    result = i2cReadByteData(handle, WHO_AM_I);
    if (result < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (result != L3G4200D_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                result, L3G4200D_WHO_AM_I);
        return -1;
    }

    /* Standby mode first (clear all bits in CTRL_REG1) */
    result = i2cWriteByteData(handle, CTRL_REG1, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    /* 100 Hz output data rate, 12.5 Hz cutoff, all axes enabled */
    result = i2cWriteByteData(handle, CTRL_REG1, 0x0F);
    if (result < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (100 Hz): %s\n", strerror(errno));
        return -1;
    }

    /* Block data update (BDU) enabled, full scale ±250 dps (default) */
    result = i2cWriteByteData(handle, CTRL_REG4, 0x80);
    if (result < 0) {
        fprintf(stderr, "Error writing CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read angular velocity (X, Y, Z) in degrees per second               */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int result;
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at OUT_X_L (auto-increment) */
    result = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyro data block: %s\n", strerror(errno));
        return -1;
    }

    /* Combine low and high bytes (little-endian) */
    raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    /* Convert to degrees per second */
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped record to the CSV file                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *file, float x, float y, float z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    if (fprintf(file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Retry wrapper for I2C write operations                              */
/* ------------------------------------------------------------------ */
static int i2c_write_with_retry(int handle, uint8_t reg, uint8_t value)
{
    int result;
    for (int attempt = 0; attempt < I2C_WRITE_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result >= 0) {
            return 0;
        }
        fprintf(stderr, "I2C write attempt %d failed: %s\n",
                attempt + 1, strerror(errno));
        if (attempt < I2C_WRITE_RETRIES - 1) {
            usleep(I2C_WRITE_RETRY_DELAY_US);
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_US};

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at L3G4200D address */
    g_i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, L3G4200D_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyroscope(g_i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_gyro_data(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data, continuing...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

