/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately      */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *message)
{
    if (fp == NULL)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s – %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0)
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor; returns 0 (flame), 1 (no flame), or -1 on     */
/* error.  The KY-026 DO is active-LOW: LOW => flame detected.         */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead(PI_BAD_GPIO) on pin %d\n", gpio_pin);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with pull-up --------------------- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode ------------------------------- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for clean shutdown ------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* --- Main polling loop ----------------------------------------- */
    while (g_running) {
        int level = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (level == 0) {
            /* Flame detected (active-LOW) */
            log_event(g_log_file, "Flame detected: YES");
            printf("FLAME DETECTED!\n");
        } else if (level == 1) {
            /* No flame (active-LOW) */
            log_event(g_log_file, "Flame detected: NO");
        } else {
            /* Error reading sensor */
            log_event(g_log_file, "Error reading flame sensor");
        }

        gpioDelay(POLL_INTERVAL_US);  /* 500 ms */
    }

    /* --- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0)
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

