#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define D7S_REG_X_LSB  0x00
#define D7S_REG_X_MSB  0x01
#define D7S_REG_Y_LSB  0x02
#define D7S_REG_Y_MSB  0x03
#define D7S_REG_Z_LSB  0x04
#define D7S_REG_Z_MSB  0x05
#define D7S_REG_STATUS 0x06
#define D7S_STATUS_BUSY 0x01
#define D7S_STATUS_ERR  0x02
#define D7S_STATUS_MASK 0x03
#define D7S_READ_DELAY_MS 100
#define CSV_FILENAME "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_d7s(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t status;
    int retries = 0;

    while (g_running) {
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0)
            return -1;

        if (status & D7S_STATUS_ERR) {
            fprintf(stderr, "D7S error status: 0x%02X\n", status);
            return -1;
        }
        if (status & D7S_STATUS_BUSY) {
            if (++retries > 10) {
                fprintf(stderr, "D7S busy timeout\n");
                return -1;
            }
            usleep(10000);
            continue;
        }

        if (i2c_read_reg16(fd, D7S_REG_X_LSB, x) < 0) return -1;
        if (i2c_read_reg16(fd, D7S_REG_Y_LSB, y) < 0) return -1;
        if (i2c_read_reg16(fd, D7S_REG_Z_LSB, z) < 0) return -1;

        return 0;
    }
    return -1;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

