{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "fopen %s failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    fflush(fp);

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_d7s(fd, &x, &y, &z) == 0) {
            get_timestamp(ts, sizeof(ts));
            fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(fp);
        } else {
            fprintf(stderr, "D7S read failed; skipping sample\n");
        }

        usleep(D7S_READ_DELAY_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

