#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_HALL1 17
#define GPIO_HALL2 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_sensor_state(int hall1, int hall2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Hall1: %d, Hall2: %d\n", timestamp, ts.tv_nsec / 1000000, hall1, hall2);
    fclose(fp);
    return 0;
}

static int read_hall_sensor(int gpio_pin) {
    int fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = gpio_pin;
    req.flags = GPIOHANDLE_REQUEST_INPUT | GPIOHANDLE_REQUEST_BIAS_PULL_UP;
    req.default_values = NULL;
    req.num_defaults = 0;

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return -1;
    }

    int value = -1;
    if (req.fd >= 0) {
        value = ioctl(req.fd, GPIO_GET_LINE_VALUE, NULL);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio_pin, strerror(errno));
        }
        close(req.fd);
    }

    close(fd);
    return value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Monitoring Hall sensors on GPIO17 and GPIO27. Press Ctrl+C to exit.\n");

    while (program_running) {
        int hall1 = read_hall_sensor(GPIO_HALL1);
        int hall2 = read_hall_sensor(GPIO_HALL2);

        if (hall1 < 0 || hall2 < 0) {
            fprintf(stderr, "Error reading Hall sensors, retrying...\n");
        } else {
            if (log_sensor_state(hall1, hall2) != 0) {
                fprintf(stderr, "Error logging sensor state.\n");
            }

            if (hall1 == 1 && hall2 == 1) {
                printf("HALT CONVEYOR!\n");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    return EXIT_SUCCESS;
}

