#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define CTRL_REG1      0x2A
#define XYZ_DATA_CFG   0x0E
#define OUT_X_MSB      0x01
#define TILT_THRESHOLD 45.0f
#define LOOP_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int verify_who_am_i(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, WHO_AM_I, &id) != 0)
        return -1;
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", id, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t ctrl;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl) != 0)
        return -1;
    if (ctrl & 0x01) {
        if (i2c_write_reg8(fd, CTRL_REG1, 0x00) != 0)
            return -1;
        usleep(10000);
    }
    if (i2c_write_reg8(fd, XYZ_DATA_CFG, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, CTRL_REG1, 0x01) != 0)
        return -1;
    usleep(10000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) != 0)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static float calc_tilt_deg(int16_t x, int16_t y, int16_t z)
{
    float xz = (float)x * (float)z;
    float xy = (float)x * (float)y;
    float mag = (float)x * (float)x + (float)y * (float)y + (float)z * (float)z;
    if (mag == 0.0f)
        return 0.0f;
    float cos_theta = xz / mag;
    if (cos_theta > 1.0f) cos_theta = 1.0f;
    if (cos_theta < -1.0f) cos_theta = -1.0f;
    float theta = acosf(cos_theta) * 180.0f / (float)M_PI;
    return theta;
}

static void log_fall(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void)
