#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

#define CTRL1_VAL      0x57
#define CTRL2_VAL      0x00
#define CTRL3_VAL      0x00

#define SCALE_FACTOR   0.146f
#define OFFSET_X       0.0f
#define OFFSET_Y       0.0f
#define OFFSET_Z       0.0f
#define THRESHOLD      800.0f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1, CTRL1_VAL) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG2, CTRL2_VAL) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, CTRL3_VAL) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x * SCALE_FACTOR + OFFSET_X;
    *y = (float)raw_y * SCALE_FACTOR + OFFSET_Y;
    *z = (float)raw_z * SCALE_FACTOR + OFFSET_Z;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        fprintf(stderr, "ALERT: Magnetic field magnitude exceeded %.1f mG at %04d-%02d-%02d %02d:%02d:%02d (X=%.2f, Y=%.2f, Z=%.2f, mag=%.2f)\n",
                THRESHOLD, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z, mag);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log_file = fopen("magnetic_log.txt", "a");
    if (!g_log_file) {
        perror("fopen: magnetic_log.txt");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open: " I2C_BUS);
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl: I2C_SLAVE");
        close(g_i2c_fd);
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (init_lis3mdl(g_i2c_fd) == 0) break;
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Retrying LIS3MDL init (%d/%d)...\n", retries, MAX_RETRIES);
            usleep(100000);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d retries.\n", MAX_RETRIES);
        close(g_i2c_fd);
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at %d Hz. Press Ctrl+C to stop.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying sensor initialization...\n");
            retries = 0;
            while (retries < MAX_RETRIES && g_running) {
                if (init_lis3mdl(g_i2c_fd) == 0) break;
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying sensor init (%d/%d)...\n", retries, MAX_RETRIES);
                    usleep(100000);
                }
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Failed to re-initialize LIS3MDL after %d retries.\n", MAX_RETRIES);
                break;
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_file) fclose(g_log_file);
    return EXIT_SUCCESS;
}

