#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define ADXL354B_REG_DEVID_AD 0x00
#define ADXL354B_REG_STATUS 0x02
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_XDATA_M 0x0A
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_YDATA_H 0x0C
#define ADXL354B_REG_YDATA_M 0x0D
#define ADXL354B_REG_ZDATA_L 0x0E
#define ADXL354B_REG_ZDATA_H 0x0F
#define ADXL354B_REG_ZDATA_M 0x10
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x1F

#define ADXL354B_DEVID_AD_VAL 0xAD
#define ADXL354B_RESET_VALUE 0x52
#define ADXL354B_RESET_DELAY_MS 1
#define ADXL354B_STABLE_DELAY_MS 10
#define ADXL354B_READ_DELAY_US 10
#define ADXL354B_RETRY_COUNT 3
#define ADXL354B_RETRY_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };
    return spi_transfer(tx, rx, 2);
}

static int spi_read_axis(uint8_t reg_l, uint8_t reg_h, uint8_t reg_m, int32_t *out) {
    uint8_t tx[3] = { (uint8_t)(reg_l | 0x80 | 0x40), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };
    if (spi_transfer(tx, rx, 3) < 0) return -1;
    uint32_t raw = ((uint32_t)rx[1] << 16) | ((uint32_t)rx[2] << 8) | (uint32_t)rx[0];
    raw >>= 8;
    if (raw & 0x00000080) raw |= 0xFFFFF000;
    *out = (int32_t)raw;
    return 0;
}

static int adxl354b_init(void) {
    uint8_t devid = 0;
    if (spi_read_register(ADXL354B_REG_DEVID_AD, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID_AD\n");
        return -1;
    }
    if (devid != ADXL354B_DEVID_AD_VAL) {
        fprintf(stderr, "Unexpected DEVID_AD: 0x%02X (expected 0x%02X)\n", devid, ADXL354B_DEVID_AD_VAL);
        return -1;
    }
    if (spi_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_VALUE) < 0) {
        fprintf(stderr, "Failed to write RESET register\n");
        return -1;
    }
    usleep(ADXL354B_RESET_DELAY_MS * 1000);
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Failed to clear POWER_CTL\n");
        return -1;
    }
    for (int i = 0; i < ADXL354B_STABLE_DELAY_MS; i++) {
        uint8_t status = 0;
        if (spi_read_register(ADXL354B_REG_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        usleep(1000);
    }
    if (!(spi_read_register(ADXL354B_REG_STATUS, &status) < 0 || (status & 0x01))) {
        fprintf(stderr, "Sensor not stable after reset\n");
        return -1;
    }
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set POWER_CTL RUN\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int32_t *x, int32_t *y, int32_t *z) {
    for (int attempt = 0; attempt < ADXL354B_RETRY_COUNT; attempt++) {
        if (spi_read_axis(ADXL354B_REG_XDATA_L, ADXL354B_REG_XDATA_H, ADXL354B_REG_XDATA_M, x) == 0 &&
            spi_read_axis(ADXL354B_REG_YDATA_L, ADXL354B_REG_YDATA_H, ADXL354B_REG_YDATA_M, y) == 0 &&
            spi_read_axis(ADXL354B_REG_ZDATA_L, ADXL354B_REG_ZDATA_H, ADXL354B_REG_ZDATA_M, z) == 0) {
            return 0;
        }
        usleep(ADXL354B_RETRY_DELAY_US);
    }
    return -1;
}

static void log_data(int32_t x, int32_t y, int32_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    if (adxl354b_init() < 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    printf("ADXL354B initialized. Logging to vibration_log.txt\n");

    while (running) {
        int32_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "SPI read error\n");
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

