#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_DELAY_US 10000
#define LOG_FILE        "imu_log.csv"

/* ADIS16362 16-bit register addresses (MSB = 1) */
#define REG_X_GYRO_OUT  0x04
#define REG_Y_GYRO_OUT  0x06
#define REG_Z_GYRO_OUT  0x08
#define REG_X_ACCEL_OUT 0x0A
#define REG_Y_ACCEL_OUT 0x0C
#define REG_Z_ACCEL_OUT 0x0E

/* Scaling factors from ADIS16362 datasheet */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI transfer helper                                                */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362                          */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t address, int16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(address | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    /* ADIS16362 returns data on the next 16-bit transfer */
    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *out = (int16_t)(((uint16_t)rx[1] << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six axes                                                  */
/* ------------------------------------------------------------------ */
static int read_imu_data(int16_t *gx, int16_t *gy, int16_t *gz,
                         int16_t *ax, int16_t *ay, int16_t *az)
{
    if (read_register(REG_X_GYRO_OUT,  gx) < 0) return -1;
    if (read_register(REG_Y_GYRO_OUT,  gy) < 0) return -1;
    if (read_register(REG_Z_GYRO_OUT,  gz) < 0) return -1;
    if (read_register(REG_X_ACCEL_OUT, ax) < 0) return -1;
    if (read_register(REG_Y_ACCEL_OUT, ay) < 0) return -1;
    if (read_register(REG_Z_ACCEL_OUT, az) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t gx, int16_t gy, int16_t gz,
                     int16_t ax, int16_t ay, int16_t az)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long long ns = ts.tv_nsec;

    float gx_d = gx * GYRO_SCALE;
    float gy_d = gy * GYRO_SCALE;
    float gz_d = gz * GYRO_SCALE;
    float ax_d = ax * ACCEL_SCALE;
    float ay_d = ay * ACCEL_SCALE;
    float az_d = az * ACCEL_SCALE;

    fprintf(fp, "%s.%09lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ns, gx_d, gy_d, gz_d, ax_d, ay_d, az_d);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
