/*
 * KY-032 IR Obstacle Avoidance Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Sensor 1: GPIO17 (physical pin 11)
 * Sensor 2: GPIO27 (physical pin 13)
 *
 * KY-032 output is active-low: 0 = obstacle detected, 1 = path clear.
 * Polls every 100 ms; logs to console on each iteration.
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * pigpio gpioRead returns 0, 1, or PI_BAD_GPIO on error.
 * We treat PI_BAD_GPIO as an error so the caller can distinguish
 * a read failure from a valid 0/1 reading.
 */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%d) failed (PI_BAD_GPIO).\n", pin);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    /* --- Initialise pigpio daemon/library --------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs ---------------------------- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", SENSOR_1_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", SENSOR_2_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* --- Install signal handlers ------------------------------------ */
    if (install_signal_handlers() != 0) {
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance monitor started.\n");
    printf("  Sensor 1: GPIO%d (physical pin 11)\n", SENSOR_1_PIN);
    printf("  Sensor 2: GPIO%d (physical pin 13)\n", SENSOR_2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Read failure — log and continue rather than abort. */
            fprintf(stderr, "%s - Read error (s1=%d, s2=%d)\n",
                    timestamp, s1, s2);
        } else {
            /* KY-032 is active-low: 0 = obstacle detected, 1 = clear. */
            printf("%s - Sensor 1: %s | Sensor 2: %s\n",
                   timestamp,
                   (s1 == 0) ? "OBSTACLE DETECTED" : "PATH CLEAR",
                   (s2 == 0) ? "OBSTACLE DETECTED" : "PATH CLEAR");
            fflush(stdout);
        }

        /* Sleep 100 ms; gpioDelay is interruptible by signals. */
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    gpioTerminate();
    return ret;
}

