#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_US 100000

#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_XGYRO_OUT_H 0x05
#define ADIS16266_YGYRO_OUT_H 0x07
#define ADIS16266_ZGYRO_OUT_H 0x09

#define ADIS16266_SCALE 0.02f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_read_axis(int fd, uint8_t addr, int16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(addr | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, 3) < 0)
        return -1;

    *out = (int16_t)(((uint16_t)rx[1] << 8) | rx[2]);
    return 0;
}

static int adis16266_read_gyro(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adis16266_read_axis(fd, ADIS16266_XGYRO_OUT, &raw_x) < 0) return -1;
    if (adis16266_read_axis(fd, ADIS16266_XGYRO_OUT_H, &raw_x) < 0) return -1;
    if (adis16266_read_axis(fd, ADIS16266_YGYRO_OUT, &raw_y) < 0) return -1;
    if (adis16266_read_axis(fd, ADIS16266_YGYRO_OUT_H, &raw_y) < 0) return -1;
    if (adis16266_read_axis(fd, ADIS16266_ZGYRO_OUT, &raw_z) < 0) return -1;
    if (adis16266_read_axis(fd, ADIS16266_ZGYRO_OUT_H, &raw_z) < 0) return -1;

    *x = (float)raw_x * ADIS16266_SCALE;
    *y = (float)raw_y * ADIS16266_SCALE;
    *z = (float)raw_z * ADIS16266_SCALE;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI: %s @ %d Hz, Mode %d, %d bits\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float x, y, z;
        if (adis16266_read_gyro(g_spi_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyroscope read error.\n");
        } else {
            printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

