#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define OUTX_L_XL    0x28

/* Expected device identifier */
#define LSM6DSR_WHO_AM_I 0x6A

/* Sensitivities (LSB per LSB) */
#define ACCEL_SENSITIVITY 0.061f   /* mg/LSB  */
#define GYRO_SENSITIVITY  0.061f   /* mdps/LSB */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed (reg=0x%02X, expected=%u, got=%d): %s\n",
                reg, len, rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (i2c_read_burst(handle, WHO_AM_I, &who_am_i, 1) < 0)
        return -1;

    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Accelerometer: 12-bit left-justified, 100 Hz ODR */
    if (i2c_write_byte(handle, CTRL1_XL, 0x84) < 0)
        return -1;

    /* Gyroscope: 12-bit left-justified, 100 Hz ODR */
    if (i2c_write_byte(handle, CTRL2_G, 0x84) < 0)
        return -1;

    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_burst(handle, OUTX_L_XL, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_gyroscope(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_burst(handle, OUTX_L_G, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * GYRO_SENSITIVITY;
    *y = (float)raw_y * GYRO_SENSITIVITY;
    *z = (float)raw_z * GYRO_SENSITIVITY;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device on bus 1, addr 0x%02X: %s\n",
                LSM6DSR_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialised. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_accelerometer(g_i2c_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accelerometer read error\n");
            break;
        }
        if (read_gyroscope(g_i2c_handle, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyroscope read error\n");
            break;
        }

        printf("%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        /* 100 ms delay (pigpio delay is in microseconds) */
        gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

