/*
 * Raspberry Pi 4 Model B — Adafruit FXOS8700 accelerometer/magnetometer reader
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2  (pin 3,  BCM 2)
 *   FXOS8700 SCL  -> GPIO3  (pin 5,  BCM 3)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * I2C bus 1 (BCM pins 2/3).
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 register definitions (datasheet rev 1.06) ---- */
#define FXOS8700_I2C_ADDR        0x1D
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_OUT_X_MSB   0x01
#define FXOS8700_REG_WHO_AM_I    0x0D
#define FXOS8700_REG_CTRL_REG1   0x2A
#define FXOS8700_REG_CTRL_REG2   0x2B
#define FXOS8700_REG_CTRL_REG3   0x2C
#define FXOS8700_REG_CTRL_REG4   0x2D
#define FXOS8700_REG_CTRL_REG5   0x2E
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C
#define FXOS8700_REG_M_CTRL_REG3 0x5D
#define FXOS8700_REG_M_CTRL_REG4 0x5E
#define FXOS8700_REG_M_CTRL_REG5 0x5F

#define FXOS8700_WHO_AM_I_VAL    0xC7

/* CTRL_REG1: active mode, 100 Hz ODR, 200 Hz accel cutoff */
#define FXOS8700_CTRL1_ACTIVE    0x01
#define FXOS8700_CTRL1_ODR_100   0x00
#define FXOS8700_CTRL1_ACCEL_200 0x00

/* CTRL_REG2: 14-bit accel, 2 G full-scale */
#define FXOS8700_CTRL2_ACCEL_14BIT 0x00
#define FXOS8700_CTRL2_ACCEL_FS_2G 0x00

/* CTRL_REG3: enable all axes */
#define FXOS8700_CTRL3_XYZ_EN    0x07

/* CTRL_REG4: 14-bit mag, 100 Hz ODR, 0.6 uT LSB */
#define FXOS8700_CTRL4_MAG_14BIT 0x00
#define FXOS8700_CTRL4_MAG_ODR_100 0x00

/* CTRL_REG5: mag active mode, 0.6 uT LSB */
#define FXOS8700_CTRL5_MAG_ACTIVE 0x00

#define I2C_BUS        "/dev/i2c-1"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed (got %zd of %zu): %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int fxos8700_init(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_reg(fd, FXOS8700_REG_WHO_AM_I, &whoami) != 0)
        return -1;
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "FXOS8700 not detected (WHO_AM_I=0x%02X, expected 0x%02X)\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg(fd, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* CTRL_REG2: 14-bit accel, 2 G full-scale */
    if (i2c_write_reg(fd, FXOS8700_REG_CTRL_REG2,
                      FXOS8700_CTRL2_ACCEL_14BIT |
                      FXOS8700_CTRL2_ACCEL_FS_2G) != 0)
        return -1;

    /* CTRL_REG3: enable all axes */
    if (i2c_write_reg(fd, FXOS8700_REG_CTRL_REG3, FXOS8700_CTRL3_XYZ_EN) != 0)
        return -1;

    /* CTRL_REG4: 14-bit mag, 100 Hz ODR, 0.6 uT LSB */
    if (i2c_write_reg(fd, FXOS8700_REG_CTRL_REG4,
                      FXOS8700_CTRL4_MAG_14BIT |
                      FXOS8700_CTRL4_MAG_ODR_100) != 0)
        return -1;

    /* M_CTRL_REG1: mag active mode, 0.6 uT LSB */
    if (i2c_write_reg(fd, FXOS8700_REG_M_CTRL_REG1, FXOS8700_CTRL5_MAG_ACTIVE) != 0)
        return -1;

    /* M_CTRL_REG2: 100 Hz ODR, 0.6 uT LSB */
    if (i2c_write_reg(fd, FXOS8700_REG_M_CTRL_REG2,
                      FXOS8700_CTRL4_MAG_ODR_100) != 0)
        return -1;

    /* M_CTRL_REG3: auto-reset on overflow */
    if (i2c_write_reg(fd, FXOS8700_REG_M_CTRL_REG3, 0x00) != 0)
        return -1;

    /* M_CTRL_REG4: continuous conversion mode */
    if (i2c_write_reg(fd, FXOS8700_REG_M_CTRL_REG4, 0x00) != 0)
        return -1;

    /* M_CTRL_REG5: 100 Hz ODR, 0.6 uT LSB */
    if (i2c_write_reg(fd, FXOS8700_REG_M_CTRL_REG5,
                      FXOS8700_CTRL4_MAG_ODR_100) != 0)
        return -1;

    /* CTRL_REG1: active mode, 100 Hz ODR, 200 Hz accel cutoff */
    if (i2c_write_reg(fd, FXOS8700_REG_CTRL_REG1,
                      FXOS8700_CTRL1_ACTIVE |
                      FXOS8700_CTRL1_ODR_100 |
                      FXOS8700_CTRL1_ACCEL_200) != 0)
        return -1;

    return 0;
}

static int fxos8700_read_xyz(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];

    if (i2c_read_block(fd, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* Accelerometer: 6 bytes, 14-bit left-aligned, LSB at buf[0] */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 6 bytes, 16-bit, LSB at buf[6] */
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                FXOS8700_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (fxos8700_init(fd) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Sampling every %d ms. Press Ctrl-C to stop.\n",
           SAMPLE_PERIOD_US / 1000);

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos8700_read_xyz(fd, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying in %d ms...\n",
                    SAMPLE_PERIOD_US / 1000);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

