/*
 * ADXL345 Tilt Monitor — Raspberry Pi 5 (pigpio)
 *
 * Reads acceleration data from an ADXL345 over I2C, evaluates the tilt
 * angle, and logs timestamped entries to /var/log/tilt_events.log whenever
 * the tilt exceeds 30.0 degrees.  The sampling interval is 100 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS            1          /* /dev/i2c-1 on RPi 5              */
#define ADXL345_ADDR       0x53       /* Default I2C address              */

#define REG_DEVID          0x00
#define REG_THRESH_TAP     0x1D
#define REG_OFSX           0x1E
#define REG_OFSY           0x1F
#define REG_OFSZ           0x20
#define REG_DUR            0x21
#define REG_LATENT         0x22
#define REG_WINDOW         0x23
#define REG_THRESH_ACT     0x24
#define REG_THRESH_INACT   0x28
#define REG_TIME_INACT     0x29
#define REG_ACT_INACT_CTL  0x62
#define REG_THRESH_FF      0x2A
#define REG_TIME_FF        0x2B
#define REG_TAP_AXES       0x2C
#define REG_ACT_TAP_STATUS 0x1D
#define REG_BW_RATE        0x2C
#define REG_POWER_CTL      0x2D
#define REG_INT_ENABLE     0x2E
#define REG_INT_MAP        0x2F
#define REG_INT_SOURCE     0x30
#define REG_DATA_FORMAT    0x31
#define REG_DATAX0         0x32
#define REG_DATAX1         0x33
#define REG_DATAY0         0x34
#define REG_DATAY1         0x35
#define REG_DATAZ0         0x36
#define REG_DATAZ1         0x37
#define REG_FIFO_CTL       0x38
#define REG_FIFO_STATUS    0x31

#define LOG_FILE           "/var/log/tilt_events.log"
#define TILT_THRESHOLD     30.0f      /* degrees                           */
#define SAMPLE_PERIOD_US   100000     /* 100 ms                           */
#define MAX_RETRIES        3

/* --------------------------- Global State ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------- Function Prototypes ------------------------- */

static int  i2c_read_reg(int handle, uint8_t reg, uint8_t *val);
static int  i2c_write_reg(int handle, uint8_t reg, uint8_t val);
static int  adxl345_init(int handle);
static int  adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z);
static float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
static bool is_tilt_exceeding_threshold(float angle);
static int  log_tilt_event(float angle);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Helpers ----------------------------- */

/*
 * Read a single byte from an ADXL345 register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/*
 * Write a single byte to an ADXL345 register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* --------------------------- ADXL345 Init ------------------------------ */

/*
 * Initialise the ADXL345 for measurement mode.
 * Returns 0 on success, -1 on failure.
 */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;
    if (i2c_read_reg(handle, REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0xE5.\n", devid);
        return -1;
    }

    /* Standby first so configuration writes take effect. */
    if (i2c_write_reg(handle, REG_POWER_CTL, 0x00) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Default data format: full resolution, +/-2 g, right-justified. */
    if (i2c_write_reg(handle, REG_DATA_FORMAT, 0x08) != 0)
        return -1;

    /* Default range: +/-2 g. */
    if (i2c_write_reg(handle, REG_THRESH_TAP, 0x00) != 0)
        return -1;

    /* Default ODR: 100 Hz (0x0A). */
    if (i2c_write_reg(handle, REG_BW_RATE, 0x0A) != 0)
        return -1;

    /* Default tap config: no double-tap, 1 ms latency, 2 ms window. */
    if (i2c_write_reg(handle, REG_DUR, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_LATENT, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_WINDOW, 0x00) != 0)
        return -1;

    /* Default activity/inactivity thresholds. */
    if (i2c_write_reg(handle, REG_THRESH_ACT, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_THRESH_INACT, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_TIME_INACT, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_ACT_INACT_CTL, 0x00) != 0)
        return -1;

    /* Free-fall: no threshold, 50 ms time limit. */
    if (i2c_write_reg(handle, REG_THRESH_FF, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, REG_TIME_FF, 0x00) != 0)
        return -1;

    /* Default tap axes: X, Y, Z enabled. */
    if (i2c_write_reg(handle, REG_TAP_AXES, 0x07) != 0)
        return -1;

    /* Disable all interrupts. */
    if (i2c_write_reg(handle, REG_INT_ENABLE, 0x00) != 0)
        return -1;

    /* Enable measurement mode. */
    if (i2c_write_reg(handle, REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------- Read Acceleration --------------------------- */

/*
 * Read 6 bytes of acceleration data (X, Y, Z) from the ADXL345.
 * Returns 0 on success, -1 on failure.
 */
static int adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  rc = i2cReadI2CBlockData(handle, REG_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: got %d bytes (expected 6).\n", rc);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

/* ------------------------- Tilt Calculation ---------------------------- */

/*
 * Calculate the tilt angle in degrees from the acceleration vector.
 * Returns the angle in degrees, or 0.0 on a pure gravity vector.
 */
static float calculate_tilt_angle(int16_t x, int16_t y, int16_t z)
{
    float mag = sqrtf((float)x * x + (float)y * y + (float)z * z);
    if (mag < 1.0f) {
        /* Avoid division by zero or near-zero; treat as gravity-only. */
        return 0.0f;
    }
    float tilt = atan2f((float)y, (float)x) * 180.0f / (float)M_PI;
    if (tilt < 0.0f) tilt += 180.0f;
    return tilt;
}

/* ----------------------- Threshold Check ------------------------------- */

static bool is_tilt_exceeding_threshold(float angle)
{
    return (angle > TILT_THRESHOLD);
}

/* --------------------------- Logging ----------------------------------- */

static int log_tilt_event(float angle)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, angle) < 0) {
        fprintf(stderr, "[ERROR] Failed to write to log file.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------- Signal Handler ------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_reg(g_i2c_handle, REG_POWER_CTL, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Tilt monitor started.  Threshold: %.1f degrees  Log: %s\n",
           TILT_THRESHOLD, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "[WARN] Acceleration read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float angle = calculate_tilt_angle(x, y, z);
        if (is_tilt_exceeding_threshold(angle)) {
            if (log_tilt_event(angle) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

