/*
 * door_access.c — Raspberry Pi 4 Model B door-access controller
 *
 * Drives two TIP120-driven 5 V relay modules on GPIO17 (Door A) and
 * GPIO27 (Door B) to unlock doors for 5 s, then lock them again.
 * A six-digit security code is generated and printed; the user is
 * prompted for input, and access is logged to access_log.txt on a
 * successful match.
 *
 * Build:  gcc -Wall -Wextra -O2 -o door_access door_access.c -lgpiod
 * Run:    sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN    17
#define DOOR_B_PIN    27
#define UNLOCK_SEC    5
#define CODE_LEN      6
#define LOG_FILE      "access_log.txt"
#define CHIP_NAME     "gpiochip4"   /* BCM GPIO bank on Pi 4 */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_output(struct gpiod_line *line, int val)
{
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d) failed: %s\n",
                val, strerror(errno));
        return -1;
    }
    return 0;
}

static int lock_doors(struct gpiod_line *a, struct gpiod_line *b)
{
    if (set_output(a, 0) != 0) return -1;
    if (set_output(b, 0) != 0) return -1;
    return 0;
}

static int unlock_doors(struct gpiod_line *a, struct gpiod_line *b)
{
    if (set_output(a, 1) != 0) return -1;
    if (set_output(b, 1) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Code generation                                                     */
/* ------------------------------------------------------------------ */
static void generate_code(char *buf, size_t len)
{
    for (size_t i = 0; i < len; i++)
        buf[i] = (char)('0' + (rand() % 10));
    buf[len] = '\0';
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a = NULL, *door_b = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* Get the two door lines */
    door_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    door_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, default LOW (locked) */
    if (gpiod_line_request_output(door_a, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(door_b, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* Seed PRNG */
    srand((unsigned)time(NULL));

    printf("Door access controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        char code[CODE_LEN + 1];
        char input[CODE_LEN + 10];

        generate_code(code, sizeof(code));
        printf("Security code: %s\n", code);
        fflush(stdout);

        printf("Enter the code: ");
        fflush(stdout);

        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("\nEOF received — exiting.\n");
                break;
            }
            if (errno == EINTR) {
                if (!g_running) break;
                continue;
            }
            fprintf(stderr, "fgets() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\r\n")] = '\0';

        if (strcmp(input, code) == 0) {
            printf("Access granted.\n");
            fflush(stdout);

            if (log_access(code) != 0)
                fprintf(stderr, "Failed to log access.\n");

            if (unlock_doors(door_a, door_b) != 0)
                fprintf(stderr, "Failed to unlock doors.\n");

            /* Hold doors open for UNLOCK_SEC seconds, checking for exit */
            for (int s = 0; s < UNLOCK_SEC && g_running; s++)
                sleep(1);

            if (lock_doors(door_a, door_b) != 0)
                fprintf(stderr, "Failed to lock doors.\n");
        } else {
            printf("Access denied.\n");
            fflush(stdout);
        }

        /* Wait 1 s before next cycle */
        for (int s = 0; s < 1 && g_running; s++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on every exit path */
    if (door_a) gpiod_line_set_value(door_a, 0);
    if (door_b) gpiod_line_set_value(door_b, 0);

    if (door_a) gpiod_line_release(door_a);
    if (door_b) gpiod_line_release(door_b);
    if (chip)   gpiod_chip_close(chip);

    return rc;
}

