static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }

    /* Send continuous high-resolution mode command */
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_TIME_MS * 1000);

    /* Read 2 bytes of data */
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device (read %d bytes)\n", bytes_read);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl-C to exit.\n");

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
