        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

