#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_ADDR    0x19
#define LSM303_REG_MAG 0x08
#define MAG_DATA_LEN   6
#define LED_PIN        17
#define PWM_FREQ       1000
#define PWM_RANGE      100
#define SAMPLE_US      100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_err = NULL;
static FILE *g_log_data = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_err(const char *msg) {
    if (g_log_err) {
        fprintf(g_log_err, "%ld: %s\n", (long)time(NULL), msg);
        fflush(g_log_err);
    }
    fprintf(stderr, "%ld: %s\n", (long)time(NULL), msg);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_err) { fclose(g_log_err); g_log_err = NULL; }
    if (g_log_data) { fclose(g_log_data); g_log_data = NULL; }
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log_err = fopen("error.log", "a");
    if (!g_log_err) {
        perror("fopen error.log");
        return EXIT_FAILURE;
    }
    g_log_data = fopen("data.log", "a");
    if (!g_log_data) {
        perror("fopen data.log");
        fclose(g_log_err);
        g_log_err = NULL;
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_err("pigpio initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_err("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        log_err("Failed to acquire I2C bus access");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        log_err("Failed to set LED pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_PIN, PWM_FREQ) < 0) {
        log_err("Failed to set PWM frequency");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_PIN, PWM_RANGE) != 0) {
        log_err("Failed to set PWM range");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_PIN, 0);

    uint8_t reg = LSM303_REG_MAG;
    if (write(g_i2c_fd, &reg, 1) != 1) {
        log_err("Failed to set magnetometer register pointer");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t buf[MAG_DATA_LEN];
        ssize_t n = read(g_i2c_fd, buf, MAG_DATA_LEN);
        if (n != MAG_DATA_LEN) {
            if (n < 0) {
                log_err("I2C read error");
            } else {
                log_err("Short I2C read");
            }
            usleep(SAMPLE_US);
            continue;
        }

        int16_t mag_z = (int16_t)((buf[2] << 8) | buf[1]);
        float mag_magnitude = sqrtf((float)mag_z * mag_z);

        int pwm_val = (int)(mag_magnitude * PWM_RANGE / 1000.0f);
        if (pwm_val < 0) pwm_val = 0;
        if (pwm_val > PWM_RANGE) pwm_val = PWM_RANGE;

        gpioPWM(LED_PIN, pwm_val);

        if (g_log_data) {
            fprintf(g_log_data, "%ld, %.2f, %d\n", (long)time(NULL), mag_magnitude, pwm_val);
            fflush(g_log_data);
        }

        usleep(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

