#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HMC5883L_ADDR  0x1E

/* HMC5883L register addresses */
#define REG_CONFIG_A   0x00
#define REG_CONFIG_B   0x01
#define REG_MODE       0x02
#define REG_DATA_X_MSB 0x03
#define REG_DATA_X_LSB 0x04
#define REG_DATA_Z_MSB 0x05
#define REG_DATA_Z_LSB 0x06
#define REG_DATA_Y_MSB 0x07
#define REG_DATA_Y_LSB 0x08
#define REG_STATUS     0x09

/* Config A: 8-average, 15 Hz, normal measurement */
#define CFG_A_8AVG_15HZ 0x70
/* Config B: gain 1.3 Ga */
#define CFG_B_GAIN_1_3  0x20
/* Mode: continuous */
#define MODE_CONTINUOUS 0x00

#define SAMPLE_COUNT 100
#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int hmc5883l_init(int fd)
{
    if (i2c_write_reg8(fd, REG_CONFIG_A, CFG_A_8AVG_15HZ) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG_B, CFG_B_GAIN_1_3)   < 0) return -1;
    if (i2c_write_reg8(fd, REG_MODE,       MODE_CONTINUOUS) < 0) return -1;
    return 0;
}

static int read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_DATA_X_MSB, buf, sizeof(buf)) < 0)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void print_data(int16_t x, int16_t y, int16_t z)
{
    printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                HMC5883L_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hmc5883l_init(fd) < 0) {
        fprintf(stderr, "HMC5883L initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    int16_t raw_x = 0, raw_y = 0, raw_z = 0;
    int16_t avg_x = 0, avg_y = 0, avg_z = 0;
    int count = 0;

    while (g_running) {
        if (read_raw(fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (count < SAMPLE_COUNT) {
            avg_x = (avg_x * count + raw_x) / (count + 1);
            avg_y = (avg_y * count + raw_y) / (count + 1);
            avg_z = (avg_z * count + raw_z) / (count + 1);
            count++;
        }

        int16_t dx = raw_x - avg_x;
        int16_t dy = raw_y - avg_y;
        int16_t dz = raw_z - avg_z;

        print_data(dx, dy, dz);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

