/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration at ~10 ms intervals, stores each sample in
 * a 64-sample circular buffer, and on a rising edge of INT1 dumps the last
 * 10 buffered samples to stdout with timestamps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    sudo ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- LSM303D register map (STM32F4 datasheet / datasheet errata) ---- */
#define LSM303D_ADDR             0x19
#define LSM303D_WHO_AM_I         0x0F
#define LSM303D_WHO_AM_I_VAL     0x49
#define LSM303D_CTRL_REG1_A      0x20
#define LSM303D_CTRL_REG4_A      0x23
#define LSM303D_OUT_X_L_A        0x28
#define LSM303D_INT1_CFG_A       0x30
#define LSM303D_INT1_SRC_A       0x31
#define LSM303D_INT1_THS_A       0x32
#define LSM303D_INT1_DURATION_A  0x33

/* ---- Configuration ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define INT1_GPIO                23          /* BCM 23, physical pin 16 */
#define BUFFER_SIZE              64
#define SAMPLE_PERIOD_MS         10
#define INTERRUPT_THRESHOLD_MG   2000
#define ACCEL_SENSITIVITY_MG_LSB 0.061f

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x[BUFFER_SIZE];
    int16_t y[BUFFER_SIZE];
    int16_t z[BUFFER_SIZE];
    int     head;
    int     count;
} accel_buffer_t;

static accel_buffer_t g_buf;

/* ---- Prototypes ---- */
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  init_lsm303d(void);
static int  read_accel(int16_t *x, int16_t *y, int16_t *z);
static void buffer_add(int16_t x, int16_t y, int16_t z);
static void dump_buffer(void);
static void signal_handler(int sig);

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int init_lsm303d(void)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1_A: 0x80 = ODR 100 Hz, all axes enabled */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x80) != 0)
        return -1;

    /* CTRL_REG4_A: 0x08 = high-resolution mode, +/-2g full scale */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4_A, 0x08) != 0)
        return -1;

    /* INT1_CFG_A: 0x40 = latch, rising edge, 16-bit */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_CFG_A, 0x40) != 0)
        return -1;

    /* INT1_THS_A: 2000 mg / 0.061 mg/LSB = 327.68 -> 0x0020 */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_THS_A, 0x20) != 0)
        return -1;

    /* INT1_DURATION_A: 0x00 = 0 ms */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_DURATION_A, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Read acceleration (16-bit, little-endian) ---- */
static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(g_i2c_fd, LSM303D_OUT_X_L_A, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    *y = (int16_t)((uint16_t)buf[3] << 8 | buf[2]);
    *z = (int16_t)((uint16_t)buf[5] << 8 | buf[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(int16_t x, int16_t y, int16_t z)
{
    g_buf.x[g_buf.head] = x;
    g_buf.y[g_buf.head] = y;
    g_buf.z[g_buf.head] = z;
    g_buf.head = (g_buf.head + 1) % BUFFER_SIZE;
    if (g_buf.count < BUFFER_SIZE)
        g_buf.count++;
}

static void dump_buffer(void)
{
    printf("--- Last %d samples ---\n", g_buf.count);
    for (int i = 0; i < g_buf.count; i++) {
        int idx = (g_buf.head - g_buf.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%4d] X=%6d Y=%6d Z=%6d\n",
               idx, g_buf.x[idx], g_buf.y[idx], g_buf.z[idx]);
    }
    fflush(stdout);
}

/* ---- Signal handling ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize buffer */
    memset(&g_buf, 0, sizeof(g_buf));

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure GPIO 23 as input with pull-up (INT1 is active-high) */
    if (gpiod_line_request_input_flags(INT1_GPIO, "lsm303d-mon",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Cannot request GPIO %d: %s\n",
                INT1_GPIO, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started. Press Ctrl-C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        if (read_accel(&x, &y, &z) == 0) {
            buffer_add(x, y, z);

            /* Check INT1_SRC_A bit 0 (or bit 0 of the 8-bit value) */
            uint8_t src = 0;
            if (i2c_read_reg8(g_i2c_fd, LSM303D_INT1_SRC_A, &src) == 0) {
                if (src & 0x01) {
                    dump_buffer();
                }
            }
        } else {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");

    /* Disable accelerometer (write documented value) */
    (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);

    /* Release GPIO line */
    gpiod_line_release(INT1_GPIO);

    /* Close I2C */
    close(g_i2c_fd);
    g_i2c_fd = -1;

    printf("Done.\n");
    return EXIT_SUCCESS;
}

