#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"
#define EXPECTED_CODE "123456"
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define BAUD_RATE 9600
#define READ_TIMEOUT_SEC 5
#define LOCK_HOLD_SEC 2
#define CODE_LENGTH 6
#define POLL_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_uart_handle_1 = -1;
static int g_uart_handle_2 = -1;
static int g_pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    g_pigpio_initialized = 1;

    if (gpioSetMode(LOCK_GPIO_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LOCK_GPIO_1);
        return -1;
    }
    if (gpioSetMode(LOCK_GPIO_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LOCK_GPIO_2);
        return -1;
    }

    if (gpioWrite(LOCK_GPIO_1, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW\n", LOCK_GPIO_1);
        return -1;
    }
    if (gpioWrite(LOCK_GPIO_2, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW\n", LOCK_GPIO_2);
        return -1;
    }

    return 0;
}

static int initialize_uart(const char *port, int *handle) {
    *handle = serOpen(port, BAUD_RATE, 0);
    if (*handle < 0) {
        fprintf(stderr, "Error: failed to open UART port %s: %s\n", port, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_pigpio_initialized) {
        gpioWrite(LOCK_GPIO_1, 0);
        gpioWrite(LOCK_GPIO_2, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
    if (g_uart_handle_1 >= 0) {
        serClose(g_uart_handle_1);
        g_uart_handle_1 = -1;
    }
    if (g_uart_handle_2 >= 0) {
        serClose(g_uart_handle_2);
        g_uart_handle_2 = -1;
    }
}

static int compare_codes(const char *code1, const char *code2) {
    if (code1 == NULL || code2 == NULL) return 0;
    if (strlen(code1) != CODE_LENGTH || strlen(code2) != CODE_LENGTH) return 0;
    return (strncmp(code1, code2, CODE_LENGTH) == 0);
}

static void lock_door(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", gpio);
        return;
    }
    time_sleep(LOCK_HOLD_SEC);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", gpio);
    }
}

static void process_code(const char *code) {
    if (code == NULL || strlen(code) != CODE_LENGTH) return;
    if (compare_codes(code, EXPECTED_CODE)) {
        printf("Code accepted: %s\n", code);
        lock_door(LOCK_GPIO_1);
        lock_door(LOCK_GPIO_2);
    } else {
        fprintf(stderr, "Code rejected: %s (expected: %s)\n", code, EXPECTED_CODE);
    }
}

int main(void) {
    char buffer[CODE_LENGTH + 1];
    int buffer_len = 0;
    int ret1 = 0, ret2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (initialize_uart(UART_PORT_1, &g_uart_handle_1) != 0) {
        cleanup();
        return 1;
    }
    if (initialize_uart(UART_PORT_2, &g_uart_handle_2) != 0) {
        cleanup();
        return 1;
    }

    printf("Door lock authentication system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (buffer_len > 0) {
            if (buffer[buffer_len - 1] == '\n' || buffer[buffer_len - 1] == '\r') {
                buffer[buffer_len - 1] = '\0';
                process_code(buffer);
                buffer_len = 0;
            }
        }

        ret1 = serDataAvailable(g_uart_handle_1);
        if (ret1 > 0) {
            char c;
            for (int i = 0; i < ret1; i++) {
                if (serReadChar(g_uart_handle_1) == 0xFF) {
                    if (buffer_len > 0) {
                        buffer[buffer_len] = '\0';
                        process_code(buffer);
                        buffer_len = 0;
                    }
                } else if (buffer_len < CODE_LENGTH) {
                    buffer[buffer_len++] = (char)serReadChar(g_uart_handle_1);
                }
            }
        } else if (ret1 < 0) {
            fprintf(stderr, "Error: UART1 read error: %s\n", strerror(errno));
        }

        ret2 = serDataAvailable(g_uart_handle_2);
        if (ret2 > 0) {
            char c;
            for (int i = 0; i < ret2; i++) {
                if (serReadChar(g_uart_handle_2) == 0xFF) {
                    if (buffer_len > 0) {
                        buffer[buffer_len] = '\0';
                        process_code(buffer);
                        buffer_len = 0;
                    }
                } else if (buffer_len < CODE_LENGTH) {
                    buffer[buffer_len++] = (char)serReadChar(g_uart_handle_2);
                }
            }
        } else if (ret2 < 0) {
            fprintf(stderr, "Error: UART2 read error: %s\n", strerror(errno));
        }

        time_sleep(POLL_DELAY_US / 1000000.0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

