/*
 * PIR-triggered door-strike monitor for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> physical GPIO4  (BCM 4)
 *   - Door-strike relay    -> physical GPIO17 (BCM 17)
 *
 * Behaviour:
 *   Polls the PIR every 50 ms.  On a HIGH event:
 *     1. Logs a motion event.
 *     2. Drives the relay HIGH for 1 s.
 *     3. Drives the relay LOW.
 *   If the PIR remains HIGH for > 10 s, logs a warning and shuts down.
 *   SIGINT / SIGTERM triggers a clean shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_door pir_door.c -lpigpio -lrt
 * Run:
 *   sudo ./pir_door
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN        4
#define RELAY_PIN      17
#define POLL_DELAY_US  50000          /* 50 ms */
#define RELAY_ON_US    1000000        /* 1 s   */
#define FAILSAFE_SEC   10             /* seconds */
#define LOG_FILE       "/var/log/pir_door.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    syslog(priority, "[%s] %s", ts, msg);
}

