    openlog("pir_door", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- signal handlers ---- */
    if (install_signal_handlers() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
