#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON  0
#define RELAY_OFF 1

#define ACTIVATION_TIME 300
#define PAUSE_TIME      60
#define TIMER_INTERVAL  60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    syslog(LOG_INFO, "[%s] irrigation_system: %s", timestamp, message);
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d to %d", pin, state);
        return -1;
    }
    return 0;
}

static void activate_relay(int pin, int duration_seconds) {
    if (set_relay(pin, RELAY_ON) != 0) return;
    log_event("Relay activated");
    sleep(duration_seconds);
    if (set_relay(pin, RELAY_OFF) != 0) return;
    log_event("Relay deactivated");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    log_event("Timer triggered");
    static int current_relay = 1;
    const int num_relays = 4;
    const int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    for (int i = 0; i < num_relays; i++) {
        if (current_relay > num_relays) current_relay = 1;
        int pin = pins[current_relay - 1];
        activate_relay(pin, ACTIVATION_TIME);
        if (i < num_relays - 1) {
            sleep(PAUSE_TIME);
        }
        current_relay++;
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], RELAY_OFF) != 0) {
            syslog(LOG_ERR, "Failed to initialize GPIO %d to OFF", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Irrigation system started");

    while (g_running) {
        sleep(1);
    }

    log_event("Shutting down irrigation system");
    for (int i = 0; i < 4; i++) {
        gpioWrite(pins[i], RELAY_OFF);
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

