#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_YOUT_H 0x3D
#define MPU6050_REG_ACCEL_ZOUT_H 0x3F

#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L  /* 10 ms -> 100 Hz */

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_driver_fd = -1;
static struct timespec g_start_time;
static circular_buffer_t g_buffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050 (sensor may be absent)\n");
        return -1;
    }
    usleep(100000);  /* allow oscillator to stabilize */
    return 0;
}

static int read_accel(int fd, accel_data_t *out) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_ACCEL_XOUT_H, buf, 6) < 0)
        return -1;
    out->x = (int16_t)((buf[0] << 8) | buf[1]);
    out->y = (int16_t)((buf[2] << 8) | buf[3]);
    out->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void buffer_add(circular_buffer_t *buf, accel_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_get_latest(circular_buffer_t *buf, accel_data_t *out) {
    if (buf->count == 0) {
        out->x = out->y = out->z = 0;
        return;
    }
    int idx = (buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *out = buf->data[idx];
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    accel_data_t d;
    if (read_accel(g_i2c_fd, &d) < 0) {
        fprintf(stderr, "Failed to read accel data; skipping sample\n");
        return;
    }
    buffer_add(&g_buffer, d);
    buffer_get_latest(&g_buffer, &d);
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double elapsed = (now.tv_sec - g_start_time.tv_sec) +
                     (now.tv_nsec - g_start_time.tv_nsec) / 1e9;
    printf("X: %6d  Y: %6d  Z: %6d  |  elapsed: %.3f s\n", d.x, d.y, d.z, elapsed);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed; sensor may be absent\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_buffer.head = 0;
    g_buffer.count = 0;

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    timer_t timer_id;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        perror("timer_create");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value = its.it_interval;
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        perror("timer_settime");
        timer_delete(timer_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct sigaction timer_sa;
    memset(&timer_sa, 0, sizeof(timer_sa));
    timer_sa.sa_sigaction = timer_handler;
    sigemptyset(&timer_sa.sa_mask);
    timer_sa.sa_flags = SA_RESTART | SA_SIGINFO;
    if (sigaction(SIGRTMIN, &timer_sa, NULL) < 0) {
        perror("sigaction (timer)");
        timer_delete(timer_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

