#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int relay_intervals[4] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(int seconds) {
    struct timespec ts = { .tv_sec = seconds, .tv_nsec = 0 };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!running) break;
    }
}

static void turn_off_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Warning: gpioWrite failed for pin %d\n", relay_pins[i]);
        }
    }
}

static void cleanup(void) {
    turn_off_all_relays();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < 4 && running; i++) {
            if (gpioWrite(relay_pins[i], 1) != 0) {
                fprintf(stderr, "Error: gpioWrite HIGH failed for pin %d\n", relay_pins[i]);
                break;
            }
            printf("Relay %d ON for %ds\n", i + 1, relay_intervals[i]);
            sleep_seconds(relay_intervals[i]);
            if (gpioWrite(relay_pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioWrite LOW failed for pin %d\n", relay_pins[i]);
                break;
            }
            printf("Relay %d OFF\n", i + 1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

