#include <math.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define PWR_MGMT_1     0x6B
#define GYRO_CONFIG    0x1B
#define GYRO_XOUT_H    0x43
#define GYRO_XOUT_L    0x44
#define GYRO_YOUT_H    0x45
#define GYRO_YOUT_L    0x46
#define GYRO_ZOUT_H    0x47
#define GYRO_ZOUT_L    0x48

#define BUFFER_SIZE    100
#define THRESHOLD      50.0f
#define SAMPLE_DELAY_US 10000

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ret = read(fd, value, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_h, uint8_t reg_l, int16_t *value) {
    uint8_t buf[2];
    ssize_t ret = write(fd, &reg_h, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg_h, strerror(errno));
        return -1;
    }
    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg_h, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, GYRO_XOUT_H, GYRO_XOUT_L, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_YOUT_H, GYRO_YOUT_L, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, GYRO_ZOUT_L, &raw_z) < 0) return -1;

    data->x = (float)raw_x;
    data->y = (float)raw_y;
    data->z = (float)raw_z;
    return 0;
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static bool buffer_check_threshold(circular_buffer_t *buf, float threshold) {
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->tail + i) % BUFFER_SIZE;
        float magnitude = sqrtf(buf->data[idx].x * buf->data[idx].x +
                                buf->data[idx].y * buf->data[idx].y +
                                buf->data[idx].z * buf->data[idx].z);
        if (magnitude > threshold) return true;
    }
    return false;
}

static void callback_function(void) {
    printf("Angular velocity threshold exceeded!\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050 (sensor may be absent or bus error).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    circular_buffer_t buffer = {0};
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    printf("MPU6050 initialized. Monitoring angular velocity (threshold: %.1f deg/s)...\n", THRESHOLD);

    while (g_running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(g_i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyro data. Continuing...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        buffer_add(&buffer, gyro_data);

        if (buffer_check_threshold(&buffer, THRESHOLD)) {
            callback_function();
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

