#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 10
#define RESPONSE_LEN 9
#define READ_TIMEOUT_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10; /* 1 second timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv;
        tv.tv_sec = 1;
        tv.tv_usec = 0;

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            perror("select");
            return -1;
        }
        if (rv == 0) {
            fprintf(stderr, "select timeout\n");
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read returned 0\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int send_command(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("write");
        return -1;
    }
    tcdrain(fd);
    return 0;
}

static int parse_response(const uint8_t *buf, int *co2_ppm) {
    if (buf[0] != 0xFF) return -1;
    if (buf[1] != 0x86) return -1;
    if (buf[2] != 0x00) return -1;
    if (buf[3] != 0x00) return -1;
    if (buf[4] != 0xFF) return -1;
    if (buf[5] != 0x00) return -1;
    if (buf[6] != 0x00) return -1;
    if (buf[7] != 0x00) return -1;

    uint16_t raw = ((uint16_t)buf[8] << 8) | buf[7];
    *co2_ppm = (int)raw;
    return 0;
}

static void log_error(const char *msg) {
    if (!g_err_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_err_fp, "%s.%06ld: %s\n", ts, tv.tv_usec, msg);
    fflush(g_err_fp);
}

static void log_data(int co2_ppm) {
    if (!g_log_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "{\"timestamp\":\"%s.%06ld\",\"co2_ppm\":%d,\"error\":false}\n",
            ts, tv.tv_usec, co2_ppm);
    fflush(g_log_fp);
    printf("{\"timestamp\":\"%s.%06ld\",\"co2_ppm\":%d,\"error\":false}\n",
           ts, tv.tv_usec, co2_ppm);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        close(g_uart_fd);
        return 1;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        close(g_uart_fd);
        return 1;
    }

    uint8_t cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0xFF};
    uint8_t resp[RESPONSE_LEN];

    while (g_running) {
        if (send_command(g_uart_fd, cmd, sizeof(cmd)) != 0) {
            log_error("Failed to send command");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        int retries = 0;
        int co2_ppm = -1;
        int ok = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_exact(g_uart_fd, resp, RESPONSE_LEN) != 0) {
                log_error("Failed to read response");
                break;
            }

            if (parse_response(resp, &co2_ppm) == 0) {
                ok = 1;
                break;
            }

            log_error("Checksum mismatch");
            retries++;
            if (retries < MAX_RETRIES) sleep(1);
        }

        if (ok) {
            log_data(co2_ppm);
        } else {
            fprintf(stderr, "Failed to read CO2 after %d retries\n", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_uart_fd >= 0) close(g_uart_fd);
    if (g_log_fp) fclose(g_log_fp);
    if (g_err_fp) fclose(g_err_fp);
    return 0;
}

