    if (buf[0] != 0xFF) return -1;
    if (buf[1] != 0x86) return -1;
    if (buf[2] != 0x00) return -1;
    if (buf[3] != 0x00) return -1;
    if (buf[4] != 0xFF) return -1;
    if (buf[5] != 0x00) return -1;
    if (buf[6] != 0x00) return -1;
    if (buf[7] != 0x00) return -1;

    uint16_t raw = ((uint16_t)buf[8] << 8) | buf[7];
    *co2_ppm = (int)raw;
    return 0;
}

static void log_error(const char *msg) {
    if (!g_err_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_err_fp, "%s.%06ld: %s\n", ts, tv.tv_usec, msg);
    fflush(g_err_fp);
}

static void log_data(int co2_ppm) {
    if (!g_log_fp) return;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "{\"timestamp\":\"%s.%06ld\",\"co2_ppm\":%d,\"error\":false}\n",
            ts, tv.tv_usec, co2_ppm);
    fflush(g_log_fp);
    printf("{\"timestamp\":\"%s.%06ld\",\"co2_ppm\":%d,\"error\":false}\n",
           ts, tv.tv_usec, co2_ppm);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        close(g_uart_fd);
        return 1;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        close(g_uart_fd);
        return 1;
    }

    uint8_t cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0xFF};
    uint8_t resp[RESPONSE_LEN];

    while (g_running) {
        if (send_command(g_uart_fd, cmd, sizeof(cmd)) != 0) {
            log_error("Failed to send command");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        int retries = 0;
        int co2_ppm = -1;
        int ok = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_exact(g_uart_fd, resp, RESPONSE_LEN) != 0) {
                log_error("Failed to read response");
                break;
            }

            if (parse_response(resp, &co2_ppm) == 0) {
                ok = 1;
                break;
            }

            log_error("Checksum mismatch");
            retries++;
            if (retries < MAX_RETRIES) sleep(1);
        }

        if (ok) {
            log_data(co2_ppm);
        } else {
            fprintf(stderr, "Failed to read CO2 after %d retries\n", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_uart_fd >= 0) close(g_uart_fd);
    if (g_log_fp) fclose(g_log_fp);
    if (g_err_fp) fclose(g_err_fp);
    return 0;
}

