#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define SAMPLE_INTERVAL_US 100000
#define HARD_IRON_X_OFFSET 100.0
#define HARD_IRON_Y_OFFSET -50.0

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t x_raw = (int16_t)((data[0] << 8) | data[1]);
    int16_t z_raw = (int16_t)((data[2] << 8) | data[3]);
    int16_t y_raw = (int16_t)((data[4] << 8) | data[5]);
    *x = (float)x_raw;
    *y = (float)y_raw;
    *z = (float)z_raw;
    return 0;
}

static float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

static float compensate_heading(float heading) {
    return heading - HARD_IRON_X_OFFSET - HARD_IRON_Y_OFFSET;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static bool is_heading_deviation(CircularBuffer *cb, float current_heading) {
    if (cb->count < 2) {
        return false;
    }
    float min_heading = cb->buffer[0];
    float max_heading = cb->buffer[0];
    for (int i = 1; i < cb->count; i++) {
        if (cb->buffer[i] < min_heading) {
            min_heading = cb->buffer[i];
        }
        if (cb->buffer[i] > max_heading) {
            max_heading = cb->buffer[i];
        }
    }
    float min_deviation = fabsf(current_heading - min_heading);
    float max_deviation = fabsf(current_heading - max_heading);
    return (min_deviation > HEADING_THRESHOLD || max_deviation > HEADING_THRESHOLD);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    CircularBuffer heading_buffer = {0};
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            float heading = calculate_heading(x, y);
            float compensated_heading = compensate_heading(heading);
            add_to_buffer(&heading_buffer, compensated_heading);
            bool deviation = is_heading_deviation(&heading_buffer, compensated_heading);
            gpioWrite(GPIO_PIN, deviation ? 1 : 0);
        } else {
            fprintf(stderr, "Error reading magnetometer, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

