/*
 * Raspberry Pi 5 – BH1750 ambient light sensor reader with RGB relay control.
 *
 * Hardware:
 *   - BH1750 ambient light sensor on I2C bus 1, address 0x23 (ADDR pin low).
 *   - RGB relay channels (BCM numbering):
 *       RED   on GPIO 17
 *       GREEN on GPIO 27
 *       BLUE  on GPIO 22
 *
 * Behaviour:
 *   - Continuously reads lux from the BH1750.
 *   - Maps lux to relay states: < 50 → RED, 50–150 → GREEN, 150–300 → BLUE,
 *     > 300 → all three.
 *   - Logs timestamp, lux, relay states to lighting_log.txt every second.
 *   - Handles I2C and file errors gracefully and cleans up on all exit paths.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lighting lighting.c -lpigpio -lrt
 * Run:    sudo ./lighting
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23          /* ADDR pin low */
#define BH1750_POWER_ON      0x01
#define BH1750_CONT_HIGH_RES 0x10          /* 1 lx resolution, ~120 ms */
#define BH1750_MEAS_MS       120           /* max conversion time */

#define RED_PIN              17
#define GREEN_PIN            27
#define BLUE_PIN             22

#define LUX_THRESHOLD_LOW    50.0f
#define LUX_THRESHOLD_MID    150.0f
#define LUX_THRESHOLD_HIGH   300.0f

#define LOG_FILE             "lighting_log.txt"
#define SAMPLE_INTERVAL_S    1

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  bh1750_init(int fd);
static int  bh1750_read_lux(int fd, float *lux_out);
static void set_relays(int red, int green, int blue);
static void log_data(FILE *fp, float lux, int red, int green, int blue);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- BH1750 ---------------------------------- */
static int bh1750_init(int fd)
{
    /* Power on */
    if (i2cWriteByte(fd, BH1750_POWER_ON) < 0) {
        fprintf(stderr, "BH1750 power-on write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (bh1750_init(fd) < 0)
        return -1;

    /* Trigger continuous high-resolution mode */
    if (i2cWriteByte(fd, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "BH1750 trigger write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_MEAS_MS * 1000); /* 120 ms conversion */

    /* Read 2 bytes (no register pointer needed for continuous mode) */
    char buf[2];
    int n = i2cReadDevice(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed: expected 2 bytes, got %d: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------- Relays ---------------------------------- */
static void set_relays(int red, int green, int blue)
{
    if (gpioWrite(RED_PIN,   red)   < 0)
        fprintf(stderr, "gpioWrite RED failed: %s\n", strerror(errno));
    if (gpioWrite(GREEN_PIN, green) < 0)
        fprintf(stderr, "gpioWrite GREEN failed: %s\n", strerror(errno));
    if (gpioWrite(BLUE_PIN,  blue)  < 0)
        fprintf(stderr, "gpioWrite BLUE failed: %s\n", strerror(errno));
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(FILE *fp, float lux, int red, int green, int blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, R: %d, G: %d, B: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, red, green, blue);
    fflush(fp);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure relays are off */
    gpioWrite(RED_PIN,   0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN,  0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup (BCM numbering) --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_relays(0, 0, 0);

    /* --- I2C open --- */
    g_i2c_fd = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Lighting monitor started. Logging to %s. Press Ctrl-C to exit.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        float lux = 0.0f;
        int   rc  = bh1750_read_lux(g_i2c_fd, &lux);

        if (rc == 0) {
            int red, green, blue;
            if (lux < LUX_THRESHOLD_LOW) {
                red   = 1;
                green = 0;
                blue  = 0;
            } else if (lux < LUX_THRESHOLD_MID) {
                red   = 0;
                green = 1;
                blue  = 0;
            } else if (lux < LUX_THRESHOLD_HIGH) {
                red   = 0;
                green = 0;
                blue  = 1;
            } else {
                red   = 1;
                green = 1;
                blue  = 1;
            }
            set_relays(red, green, blue);
            log_data(g_log_fp, lux, red, green, blue);
        } else {
            /* Sensor error: turn off relays for safety and log */
            set_relays(0, 0, 0);
            log_data(g_log_fp, -1.0f, 0, 0, 0);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

