#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100
#define MIN_DISTANCE_THRESHOLD 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int direction) {
    if (direction == 0) {
        if (gpioWrite(in1, 0) != 0) return -1;
        if (gpioWrite(in2, 0) != 0) return -1;
    } else if (direction == 1) {
        if (gpioWrite(in1, 1) != 0) return -1;
        if (gpioWrite(in2, 0) != 0) return -1;
    } else if (direction == -1) {
        if (gpioWrite(in1, 0) != 0) return -1;
        if (gpioWrite(in2, 1) != 0) return -1;
    } else {
        return -1;
    }
    return 0;
}

static int set_motor_pwm(int in2, int in4, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(in2, duty_cycle) != 0) return -1;
    if (gpioPWM(in4, duty_cycle) != 0) return -1;
    return 0;
}

static int control_motor(int in1, int in2, int in3, int in4, int distance, int target_distance) {
    int distance_diff = target_distance - distance;
    int duty_cycle = (distance_diff * PWM_RANGE) / (MAX_DISTANCE - MIN_DISTANCE);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (distance < MIN_DISTANCE_THRESHOLD) {
        if (set_motor_direction(in1, in2, 1) != 0) return -1;
        if (set_motor_pwm(in2, in4, duty_cycle) != 0) return -1;
    } else {
        if (set_motor_direction(in1, in2, -1) != 0) return -1;
        if (set_motor_pwm(in2, in4, duty_cycle) != 0) return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance> <motor_b_distance>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int motor_a_distance = atoi(argv[1]);
    int motor_b_distance = atoi(argv[2]);

    if (motor_a_distance < MIN_DISTANCE || motor_a_distance > MAX_DISTANCE ||
        motor_b_distance < MIN_DISTANCE || motor_b_distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm.\n", MIN_DISTANCE, MAX_DISTANCE);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor A distance: %d cm, Motor B distance: %d cm\n", motor_a_distance, motor_b_distance);
    printf("Starting control loop. Press Ctrl+C to exit.\n");

    while (running) {
        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, motor_a_distance, motor_a_distance) != 0) {
            fprintf(stderr, "Error: Failed to control motor A.\n");
            break;
        }
        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, motor_b_distance, motor_b_distance) != 0) {
            fprintf(stderr, "Error: Failed to control motor B.\n");
            break;
        }
        usleep(LOOP_DELAY_US);
    }

    printf("\nStopping motors and cleaning up...\n");
    set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, 0);
    set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

