#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
        usleep(RETRY_DELAY_MS * (1 << attempt) * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            usleep(RETRY_DELAY_MS * (1 << attempt) * 1000);
            continue;
        }
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
        usleep(RETRY_DELAY_MS * (1 << attempt) * 1000);
    }
    return -1;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050.\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
