/*
 * Theremin for Raspberry Pi Zero W
 * HC-SR04 ultrasonic distance sensor + pigpio PWM buzzer
 *
 * Wiring (BCM numbering):
 *   GPIO23 (trigger)  -> HC-SR04 TRIG
 *   GPIO24 (echo)     -> HC-SR04 ECHO
 *   GPIO18 (PWM)      -> Buzzer
 *
 * Build: gcc -Wall -Wextra -O2 -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_FREQUENCY    20.0             /* Hz */
#define MAX_FREQUENCY    2000.0           /* Hz */
#define MIN_DISTANCE     2.0              /* cm */
#define MAX_DISTANCE     400.0            /* cm */
#define LOOP_DELAY_US    20000            /* 50 Hz */
#define ECHO_TIMEOUT_US  30000            /* 30 ms */
#define TRIGGER_PULSE_US 10               /* 10 µs */
#define MEASURE_GAP_US   60000            /* 60 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns true on success, false on timeout or sensor-absent error.
 */
static bool measure_distance(double *distance_out)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return false;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return false;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout (sensor absent?)\n");
            return false;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return false;
        }
    }
    uint32_t echo_end = gpioTick();

    double pulse_us = (double)(echo_end - echo_start);
    *distance_out = (pulse_us * SPEED_OF_SOUND) / 2000000.0;
    return true;
}

/*
 * Map distance to frequency.
 * Returns false if the distance is out of range.
 */
static bool distance_to_frequency(double distance, double *frequency_out)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return false;
    }
    *frequency_out = MIN_FREQUENCY +
        (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) /
        (MAX_DISTANCE - MIN_DISTANCE);
    return true;
}

static void set_buzzer_frequency(double frequency)
{
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Warning: frequency %.2f Hz out of range [%.1f, %.1f]; clamping\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
        if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
    }
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low and buzzer is off */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    printf("Theremin ready. Move your hand between %.1f and %.1f cm.\n",
           MIN_DISTANCE, MAX_DISTANCE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = 0.0;
        double frequency = 0.0;

        if (!measure_distance(&distance)) {
            /* Sensor error: silence buzzer and wait before retrying */
            gpioPWM(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (!distance_to_frequency(distance, &frequency)) {
            /* Out-of-range: silence buzzer and wait */
            gpioPWM(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        set_buzzer_frequency(frequency);

        /* Enforce minimum measurement gap */
        gpioDelay(MEASURE_GAP_US);
    }

    /* Cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

