#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void set_rgb(float proximity) {
    int r = (int)(128.0 + 127.0 * (1.0 - proximity));
    int g = (int)(128.0 + 127.0 * proximity);
    int b = 0;
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;
    if (gpioPWM(RED_PIN,   r) != 0) fprintf(stderr, "PWM write failed on RED\n");
    if (gpioPWM(GREEN_PIN, g) != 0) fprintf(stderr, "PWM write failed on GREEN\n");
    if (gpioPWM(BLUE_PIN,  b) != 0) fprintf(stderr, "PWM write failed on BLUE\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN,   0) != 0 ||
        gpioPWM(GREEN_PIN, 0) != 0 ||
        gpioPWM(BLUE_PIN,  0) != 0) {
