        gpioPWM(BLUE_PIN,  0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity-aware RGB LED running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float proximity = (float)(sin((double)time(NULL) / 5.0) + 1.0) / 2.0;
        if (proximity < 0.0) proximity = 0.0;
        if (proximity > 1.0) proximity = 1.0;
        set_rgb(proximity);
        usleep(20000);
    }

    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

