#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define TONE_DURATION_US 500000
#define TONE_FREQ_HZ 440
#define TONE_DUTY 128

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_press_tick = 0;

static const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        uint32_t now = tick;
        if ((now - last_press_tick) > DEBOUNCE_US) {
            last_press_tick = now;
            button_pressed = 1;
        }
    }
}

static void play_tone(int freq_hz) {
    if (gpioHardwarePWM(BUZZER_PIN, freq_hz, TONE_DUTY) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %d Hz\n", freq_hz);
        return;
    }
    gpioDelay(TONE_DURATION_US);
    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM stop failed for frequency %d Hz\n", freq_hz);
    }
}

static void play_melody(void) {
    for (int i = 0; i < melody_len; i++) {
        if (!running) break;
        play_tone(melody[i]);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin %d\n", BUTTON_PIN);
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Doorbell monitor started. Press button on GPIO%d to play melody on GPIO%d.\n", BUTTON_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            play_melody();
            printf("Melody finished.\n");
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

