        fprintf(stderr, "Error: gpioHardwarePWM stop failed for frequency %d Hz\n", freq_hz);
    }
}

static void play_melody(void) {
    for (int i = 0; i < melody_len; i++) {
        if (!running) break;
        play_tone(melody[i]);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin %d\n", BUTTON_PIN);
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Doorbell monitor started. Press button on GPIO%d to play melody on GPIO%d.\n", BUTTON_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            play_melody();
            printf("Melody finished.\n");
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

