/*
 * SW-420 vibration sensor edge-triggered monitor for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   SW-420 VCC  -> 3V3 (pin 1)
 *   SW-420 GND  -> GND (pin 9)
 *   SW-420 OUT  -> GPIO17 (BCM, physical pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c -lpigpio -lrt
 * Run:
 *   ./vibration_monitor [timeout_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define WINDOW_SIZE       5
#define DEFAULT_TIMEOUT   1000   /* milliseconds */
#define LOG_FILE          "vibration_events.log"

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(FILE *fp, int value)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%d\n", ts, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Edge detection                                                     */
/* ------------------------------------------------------------------ */

/*
 * pigpio's gpioSetAlertFuncEx() is the best choice for edge-triggered
 * monitoring on the Raspberry Pi.  It fires on every edge and is
 * re-entrant (the callback runs in a pigpio thread).
 *
 * Returns 0 on success, -1 on failure.
 */
static int setup_edge_detection(void)
{
    if (gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for GPIO%d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

/*
 * pigpio's gpioRead() is the best choice for reading the current state
 * of a GPIO pin on the Raspberry Pi.
 *
 * Returns 0 or 1 on success, -1 on failure.
 */
static int read_sensor(void)
{
    int v = gpioRead(GPIO_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d: %s\n",
                GPIO_PIN, strerror(errno));
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int  timeout_ms = DEFAULT_TIMEOUT;
    int  window[WINDOW_SIZE];
    int  idx = 0;
    int  count = 0;
    int  ret = EXIT_SUCCESS;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout '%s' (must be positive)\n",
                    argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Edge detection ---- */
    if (setup_edge_detection() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0) {
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Vibration monitoring started on GPIO%d (timeout %d ms).\n",
           GPIO_PIN, timeout_ms);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int value = read_sensor();
        if (value < 0) {
            /* Sensor read error: keep running but do not log. */
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        /* Slide window */
        window[idx] = value;
        idx = (idx + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) {
            count++;
        }

        /* Earthquake detection */
        int earthquake = 0;
        for (int i = 0; i < count && !earthquake; i++) {
            earthquake = (window[(idx - 1 - i + WINDOW_SIZE) % WINDOW_SIZE] == 1);
        }

        if (earthquake) {
            time_t     rawtime;
            struct tm  tm_info;
            char       ts[32];

            time(&rawtime);
            localtime_r(&rawtime, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_info);

            printf("EARTHQUAKE ALERT at %s\n", ts);
            fflush(stdout);
        }

        log_event(g_log_fp, value);

        gpioDelay(timeout_ms * 1000); /* pigpio microseconds */
    }

    printf("\nShutting down...\n");

cleanup:
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }
    gpioTerminate();
    return ret;
}

