code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDRESS_MAG 0x1E
#define LSM303_REGISTER_MAG_X_H 0x03
#define LSM303_REGISTER_MAG_X_L 0x04
#define LSM303_REGISTER_MAG_Y_H 0x05
#define LSM303_REGISTER_MAG_Y_L 0x06
#define LSM303_REGISTER_MAG_Z_H 0x07
#define LSM303_REGISTER_MAG_Z_L 0x08
#define LSM303_REGISTER_CTRL_REG5 0x24
#define LSM303_REGISTER_CTRL_REG6 0x25

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int initialize_i2c(void) {
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1 failed");
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDRESS_MAG) < 0) {
        perror("ioctl I2C_SLAVE failed");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(g_i2c_fd, LSM303_REGISTER_CTRL_REG5, 0x00) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(g_i2c_fd, LSM303_REGISTER_CTRL_REG6, 0x00) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_h, x_l, y_h, y_l, z_h, z_l;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_X_H, &x_h) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_X_L, &x_l) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_Y_H, &y_h) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_Y_L, &y_l) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_Z_H, &z_h) < 0) return -1;
    if (i2c_read_reg8(g_i2c_fd, LSM303_REGISTER_MAG_Z_L, &z_l) < 0) return -1;
    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);
    return 0;
}

static void calibrate_data(int16_t x, int16_t y, int16_t z,
                            int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

static double calculate_heading(int16_t cx, int16_t cy) {
    double heading = atan2((double)cy, (double)cx) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static const char *determine_compass_direction(double heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading < 67.5) return "NE";
    if (heading < 112.5) return "E";
    if (heading < 157.5) return "SE";
    if (heading < 202.5) return "S";
    if (heading < 247.5) return "SW";
    if (heading < 292.5) return "W";
    return "NW";
}

static int log_data(FILE *fp, int16_t cx, int16_t cy, int16_t cz, double heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(fp, "%s, %d, %d, %d, %.2f\n", timestamp, cx, cy, cz, heading) < 0) {
        perror("fprintf failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT failed");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM failed");
        return 1;
    }
    if (initialize_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }
    g_log_file = fopen("mag_log.csv", "a");
    if (g_log_file == NULL) {
        perror("fopen mag_log.csv failed");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_log_file);
    }
    printf("Magnetometer data logging started. Press Ctrl+C to stop.\n");
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
            sleep(1);
            continue;
        }
        int16_t cal_x, cal_y, cal_z;
        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        double heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_compass_direction(heading);
        printf("Heading: %.2f degrees (%s)\n", heading, direction);
        if (log_data(g_log_file, cal_x, cal_y, cal_z, heading) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }
        sleep(1);
    }
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

