#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define IRRIGATION_GAP 1
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int relay, int moisture) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d: Moisture = %d\n", timestamp, relay, moisture) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static int activate_relay(int pin, int duration) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite(LOW) failed on pin %d\n", pin);
        return -1;
    }
    if (log_event(pin, -1) != 0) {
        fprintf(stderr, "Failed to log relay activation on pin %d\n", pin);
    }
    sleep(duration);
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "gpioWrite(HIGH) failed on pin %d\n", pin);
        return -1;
    }
    if (log_event(pin, -1) != 0) {
        fprintf(stderr, "Failed to log relay deactivation on pin %d\n", pin);
    }
    return 0;
}

static int read_soil_moisture(void) {
    return rand() % 101;
}

int main(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));
    int rc = 0;

    srand((unsigned int)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "gpioWrite(HIGH) failed for pin %d\n", pins[i]);
            rc = EXIT_FAILURE;
            goto cleanup;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_soil_moisture();

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level %d below threshold %d. Activating relays.\n", moisture, MOISTURE_THRESHOLD);

            for (int i = 0; i < num_pins; i++) {
                if (activate_relay(pins[i], IRRIGATION_DURATION) != 0) {
                    fprintf(stderr, "Relay activation failed on pin %d\n", pins[i]);
                    rc = EXIT_FAILURE;
                    goto cleanup;
                }
                if (i < num_pins - 1) {
                    sleep(IRRIGATION_GAP);
                }
            }
        } else {
            printf("Moisture level %d above threshold %d. No irrigation needed.\n", moisture, MOISTURE_THRESHOLD);
        }

        if (running) {
            sleep(10);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return rc;
}

