    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_soil_moisture();

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level %d below threshold %d. Activating relays.\n", moisture, MOISTURE_THRESHOLD);

            for (int i = 0; i < num_pins; i++) {
                if (activate_relay(pins[i], IRRIGATION_DURATION) != 0) {
                    fprintf(stderr, "Relay activation failed on pin %d\n", pins[i]);
                    rc = EXIT_FAILURE;
                    goto cleanup;
                }
                if (i < num_pins - 1) {
                    sleep(IRRIGATION_GAP);
                }
            }
        } else {
            printf("Moisture level %d above threshold %d. No irrigation needed.\n", moisture, MOISTURE_THRESHOLD);
        }

        if (running) {
            sleep(10);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return rc;
}

