#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEP_DELAY_US 3000
#define DEBOUNCE_DELAY_US 20000
#define STEPS_PER_ROTATION 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deenergize(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

static int step(int step) {
    switch (step) {
        case 0: gpioWrite(IN1, 1); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
        case 1: gpioWrite(IN1, 0); gpioWrite(IN2, 1); gpioWrite(IN3, 0); gpioWrite(IN4, 0); break;
        case 2: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 1); gpioWrite(IN4, 0); break;
        case 3: gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 1); break;
        default: return -1;
    }
    return 0;
}

static int rotate(int steps, int direction) {
    for (int i = 0; i < steps; i++) {
        if (!running) return -1;
        if (step(direction) != 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    if (rotate(STEPS_PER_ROTATION, 1) != 0) {
        fprintf(stderr, "Error: Failed to rotate motor for lock.\n");
        return -1;
    }
    printf("Door locked.\n");
    return 0;
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    if (rotate(STEPS_PER_ROTATION, -1) != 0) {
        fprintf(stderr, "Error: Failed to rotate motor for unlock.\n");
        return -1;
    }
    printf("Door unlocked.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Door lock/unlock system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON) == 0 && running) {
                if (lock_door() != 0) {
                    fprintf(stderr, "Error: Lock operation failed.\n");
                }
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                if (unlock_door() != 0) {
                    fprintf(stderr, "Error: Unlock operation failed.\n");
                }
            }
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("Door lock/unlock system stopped.\n");
    return EXIT_SUCCESS;
}

