#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define LOOP_DELAY_US    60000
#define SAMPLE_INTERVAL  1000000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin state\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static long measure_pulse_us(void) {
    uint32_t start_tick = 0, end_tick = 0;
    int timeout = ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if (--timeout == 0) return -1;
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (--timeout == 0) return -1;
        gpioDelay(1);
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static double calculate_distance(long pulse_us) {
    return (pulse_us * 34300.0) / 2000000.0;
}

static void log_distance(double distance) {
    if (log_fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    if (distance < 0) {
        fprintf(log_fp, "-1\n");
    } else {
        fprintf(log_fp, "%.2f\n", distance);
    }
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        trigger_sensor();
        long pulse_us = measure_pulse_us();
        double distance = -1.0;

        if (pulse_us < 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
        } else {
            distance = calculate_distance(pulse_us);
        }

        log_distance(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

