/*
 * Raspberry Pi 4 Model B — VL53L1X time-of-flight distance reader
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, default address 0x29
 *   - Relay on GPIO18 (BCM), active-high
 *
 * Behaviour:
 *   Polls distance every 100 ms, drives relay HIGH when distance <= 50 cm,
 *   LOW otherwise.  Logs I2C / sensor errors to stderr and exits cleanly on
 *   SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define RELAY_GPIO           18
#define DISTANCE_THRESHOLD   50          /* cm */
#define POLL_DELAY_US        100000      /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET       0x0003
#define REG_SYSTEM_MODE      0x0001
#define REG_SYSTEM_RANGE     0x0000
#define REG_RESULT_INT_STATUS 0x0014
#define REG_RESULT_DISTANCE  0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, cmd, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "VL53L1X soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);  /* 1 ms */

    /* Clear any pending interrupt */
    uint8_t int_status = 0;
    if (i2c_read_reg16(handle, REG_RESULT_INT_STATUS, &int_status, 1) < 0) {
        fprintf(stderr, "VL53L1X read interrupt status failed: %s\n", strerror(errno));
        return -1;
    }

    /* Start a single ranging measurement */
    if (i2c_write_reg16(handle, REG_SYSTEM_RANGE, 0x01) < 0) {
        fprintf(stderr, "VL53L1X start ranging failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg16(handle, REG_RESULT_INT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "VL53L1X read interrupt status failed: %s\n", strerror(errno));
        return -1;
    }

    /* Bit 0 of the status byte indicates data ready */
    if (!(status & 0x01))
        return 1;  /* not ready yet */

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        fprintf(stderr, "VL53L1X read distance failed: %s\n", strerror(errno));
        return -1;
    }

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void relay_set(int gpio, int state)
{
    if (gpioWrite(gpio, state) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed: %s\n",
                gpio, state, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    relay_set(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                RELAY_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_set(RELAY_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed — sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X ready on I2C bus %d, address 0x%02X.  Polling every %d ms.\n",
           I2C_BUS, VL53L1X_ADDR, POLL_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);
            relay_set(RELAY_GPIO, (distance_cm <= DISTANCE_THRESHOLD) ? 1 : 0);
        } else if (rc < 0) {
            /* I2C / sensor error — log and keep running */
            fprintf(stderr, "Sensor read error — continuing\n");
        }
        /* rc == 1 (data not ready) — just wait */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

