/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  (BCM GPIO2 = SDA, BCM GPIO3 = SCL)
 * Address: 0x68 (AD0 tied to GND)
 * Reads X/Y/Z angular velocity and logs to stdout.
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c -lm
 * Run:   sudo ./mpu6050_gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define GYRO_XOUT_H         0x43
#define GYRO_YOUT_H         0x45
#define GYRO_ZOUT_H         0x47
#define WHO_AM_I            0x75
#define WHO_AM_I_VAL        0x68

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read the data bytes */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int mpu6050_init(int fd)
{
    /* Verify device identity */
    uint8_t who = 0;
    if (i2c_read_burst(fd, WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0)
        return -1;

    /* Allow oscillator to stabilize */
    usleep(100000); /* 100 ms */
    return 0;
}

/* ---- Read gyro X/Y/Z ---- */
static int mpu6050_read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    uint8_t who = 0;
    if (i2c_read_burst(g_i2c_fd, WHO_AM_I, &who, 1) != 0) {
        fprintf(stderr, "MPU-6050 not responding on 0x%02X\n", MPU6050_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready. Logging X/Y/Z angular velocity (degrees/sec)...\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x_raw, y_raw, z_raw;

        if (mpu6050_read_gyro(g_i2c_fd, &x_raw, &y_raw, &z_raw) != 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(100000);
            continue;
        }

        /* Convert raw 16-bit signed values to degrees/sec.
         * Sensitivity: 131 LSB/deg/sec at default FS_SEL = 0.
         * Scale factor = 131 / 32768 ≈ 0.000409672 */
        float x_dps = (float)x_raw / 131.0f;
        float y_dps = (float)y_raw / 131.0f;
        float z_dps = (float)z_raw / 131.0f;

        printf("X: %+.4f  Y: %+.4f  Z: %+.4f  deg/s\n",
               x_dps, y_dps, z_dps);
        fflush(stdout);

        usleep(10000); /* 10 ms */
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

