#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "smart_lighting.log"
#define DURATION_SECONDS 1800

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error writing to GPIO %d", pin);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int set_pwm(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error setting PWM on GPIO %d", pin);
        log_event(msg);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Error setting GPIO %d as output", pins[i]);
            log_event(msg);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0) {
        log_event("Error setting PWM frequency");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) < 0) {
        log_event("Error setting PWM range");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    set_relay(RELAY1_PIN, 0);
    set_relay(RELAY2_PIN, 0);
    set_relay(RELAY3_PIN, 0);
    set_relay(RELAY4_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Smart lighting sunrise effect started");

    for (int i = 0; i <= 255 && running; i++) {
        set_pwm(RELAY1_PIN, i);
        set_pwm(RELAY2_PIN, i);
        set_pwm(RELAY3_PIN, i);
        set_pwm(RELAY4_PIN, i);
        log_event("Relay intensity increased");
        sleep(1);
    }

    log_event("Smart lighting sunrise effect ended");
    cleanup();
    return 0;
}

