#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define GYRO_XOUT_H         0x43
#define GYRO_YOUT_H         0x45
#define GYRO_ZOUT_H         0x47
#define LED_GPIO            17
#define BUFFER_SIZE         100
#define SAMPLE_PERIOD_US    50000
#define GYRO_THRESHOLD      250.0f
#define I2C_BUS             1
#define MAX_REINIT_ATTEMPTS 3

typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X on bus %d: %s\n",
                MPU6050_ADDR, I2C_BUS, strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > GYRO_THRESHOLD ||
        fabsf(y) > GYRO_THRESHOLD ||
        fabsf(z) > GYRO_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int reinit_attempts = 0;
    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) != 0) {
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            fprintf(stderr, "Attempting re-initialization (%d/%d)...\n",
                    reinit_attempts, MAX_REINIT_ATTEMPTS);
            gpioDelay(1000000);
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            reinit_attempts = 0;
            continue;
        }
        reinit_attempts = 0;
        add_to_buffer(x, y, z);
        check_threshold(x, y, z);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

