#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define CS_LINE_OFFSET 8
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int spi_fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_gyro_data(int spi_fd, struct gpiod_line *cs_line, float *x, float *y, float *z) {
    uint8_t tx[6] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[6] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }

        if (spi_transfer(spi_fd, tx, rx, 6) < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            gpiod_line_set_value(cs_line, 1);
            retries++;
            usleep(1000);
            continue;
        }

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Failed to de-assert CS: %s\n", strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }

        int16_t raw_x = (int16_t)((rx[2] << 8) | rx[1]);
        int16_t raw_y = (int16_t)((rx[4] << 8) | rx[3]);
        int16_t raw_z = (int16_t)((rx[5] << 8) | rx[0]);

        *x = (float)raw_x / 131.0f;
        *y = (float)raw_y / 131.0f;
        *z = (float)raw_z / 131.0f;
        return 0;
    }

    return -1;
}

static int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-gyro", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Logging gyro data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float x, y, z;
        if (read_gyro_data(spi_fd, cs_line, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data after %d retries.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

