    time_t timestamp;
    float  x;
    float  y;
    float  z;
} gyro_data_t;

static gyro_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }
    gpioWrite(LED_PIN, 0);
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char tx[6] = {0};
    char rx[6] = {0};

    tx[0] = GYRO_XOUT_H;
    if (spiXfer(spi_handle, tx, rx, 6) != 6) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    int16_t raw_y = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[3]);
    int16_t raw_z = (int16_t)(((uint8_t)rx[4] << 8) | (uint8_t)rx[5]);

    *x = (float)raw_x;
    *y = (float)raw_y;
    *z = (float)raw_z;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void blink_led(void) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(500000);
    gpioWrite(LED_PIN, 0);
    gpioDelay(500000);
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[idx].timestamp));
        printf("%s,%.2f,%.2f,%.2f\n", ts, circular_buffer[idx].x, circular_buffer[idx].y, circular_buffer[idx].z);
    }
    printf("--- End of Buffer ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (spiWrite(spi_handle, (char[]){PWR_MGMT_1, 0x00}, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(100000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;

    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (x > THRESHOLD || x < -THRESHOLD ||
                y > THRESHOLD || y < -THRESHOLD ||
                z > THRESHOLD || z < -THRESHOLD) {
                blink_led();
            }
            add_to_buffer(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, skipping sample\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    print_buffer();
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

