#include <math.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define LED_PIN      21
#define TILT_THRESHOLD 45.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(int handle) {
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Failed to write to PWR_MGMT_1 register.\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int read_accel_data(int handle, int16_t *ax, int16_t *ay, int16_t *az) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_tilt(int16_t ax, int16_t ay, int16_t az, float *roll, float *pitch) {
    float ax_g = (float)ax / 16384.0;
    float ay_g = (float)ay / 16384.0;
    float az_g = (float)az / 16384.0;
    *roll  = atan2(ay_g, az_g) * 180.0 / M_PI;
    *pitch = atan2(-ax_g, sqrt(ay_g * ay_g + az_g * az_g)) * 180.0 / M_PI;
}

static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open tilt_log.txt for appending.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

static void control_led(float roll, float pitch) {
    int state = (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_PIN, state) < 0) {
        fprintf(stderr, "Warning: Failed to write LED state.\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus 1 at address 0x%02X.\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU6050 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    int16_t ax, ay, az;
    float roll, pitch;

    while (running) {
        if (read_accel_data(i2c_handle, &ax, &ay, &az) == 0) {
            calculate_tilt(ax, ay, az, &roll, &pitch);
            log_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data. Continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

