#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define SAMPLE_RATE 100
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE)
#define MAX_RETRIES   3
#define GYRO_REG_XOUT 0x00
#define GYRO_REG_YOUT 0x02
#define GYRO_REG_TEMP 0x04
#define GYRO_REG_ID   0x00
#define GYRO_ID_VAL   0x00

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, int16_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    if (spi_read_register(GYRO_REG_XOUT, x_rate) != 0) return -1;
    if (spi_read_register(GYRO_REG_YOUT, y_rate) != 0) return -1;
    return 0;
}

static int log_data(FILE *fp, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(fp, "%ld.%06ld,%d,%d\n", (long)ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    if (fprintf(fp, "timestamp,x_rate,y_rate\n") < 0) {
        perror("fprintf header");
        cleanup();
        return 1;
    }
    fflush(fp);

    int retries = 0;
    while (running) {
        int16_t x_rate = 0, y_rate = 0;
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            if (log_data(fp, x_rate, y_rate) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            retries = 0;
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            if (spi_handle >= 0) {
                spiClose(spi_handle);
                spi_handle = -1;
            }
            if (spi_init() != 0) {
                fprintf(stderr, "SPI re-initialisation failed\n");
                retries++;
                if (retries >= MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached, exiting\n");
                    break;
                }
            }
        }
        if (running) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    cleanup();
    return 0;
}

