#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define LED_GPIO         17
#define THRESHOLD        20.0f
#define BUFFER_SIZE      100
#define SAMPLE_PERIOD_US 100000

/* ADXRS290 register addresses (MSB = 1 for read) */
#define REG_X_RATE_L     0x08
#define REG_X_RATE_H     0x09
#define REG_Y_RATE_L     0x0A
#define REG_Y_RATE_H     0x0B

typedef struct {
    struct timespec timestamp;
    float            x_rate;
} GyroData;

typedef struct {
    GyroData data[BUFFER_SIZE];
    int      head;
    int      tail;
    int      count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static bool g_led_state  = false;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *buf)
{
    memset(buf, 0, sizeof(*buf));
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(CircularBuffer *buf, GyroData d)
{
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_print(CircularBuffer *buf)
{
    pthread_mutex_lock(&buf->mutex);
    int start = (buf->count == BUFFER_SIZE) ? buf->tail : 0;
    int n = buf->count;
    printf("--- Circular Buffer (%d entries) ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("[%d] %ld.%09ld, X-rate: %.2f deg/s\n",
               i, buf->data[idx].timestamp.tv_sec,
               buf->data[idx].timestamp.tv_nsec,
               buf->data[idx].x_rate);
    }
    pthread_mutex_unlock(&buf->mutex);
}

/*
 * ADXRS290 SPI read: send 1-byte address (MSB = 1 for read), then
 * read 2 bytes of data (MSB first).
 * Returns 0 on success, -1 on error.
 */
static int adxrs290_read_axis(int handle, uint8_t reg_addr, float *out)
{
    char tx[2] = { (char)(reg_addr | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X: %s\n",
                reg_addr, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    *out = (float)raw / 16.0f;   /* 16-bit signed, 1/16 deg/s LSB */
    return 0;
}

static int read_gyro_data(int handle, float *x_rate)
{
    float x_l, x_h;
    if (adxrs290_read_axis(handle, REG_X_RATE_L, &x_l) != 0)
        return -1;
    if (adxrs290_read_axis(handle, REG_X_RATE_H, &x_h) != 0)
        return -1;
    *x_rate = x_l + (x_h * 256.0f);
    return 0;
}

static void control_led(float x_rate)
{
    bool warn = (x_rate > THRESHOLD);
    if (warn != g_led_state) {
        if (gpioWrite(LED_GPIO, warn ? 1 : 0) == 0) {
            g_led_state = warn;
        } else {
            fprintf(stderr, "Failed to write LED GPIO %d: %s\n",
                    LED_GPIO, strerror(errno));
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer gyro_buffer;
    buffer_init(&gyro_buffer);

    printf("ADXRS290 Gyroscope Monitor (SPI0 CE0, %d Hz)\n", SPI_SPEED);
    printf("Threshold: %.1f deg/s | LED on GPIO%d\n", THRESHOLD, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float x_rate;
        if (read_gyro_data(g_spi_handle, &x_rate) != 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        GyroData d = { ts, x_rate };
        buffer_add(&gyro_buffer, d);
        control_led(x_rate);

        printf("X-rate: %.2f deg/s | LED: %s\n",
               x_rate, g_led_state ? "ON" : "OFF");

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    buffer_print(&gyro_buffer);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

