#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define MAX_DUTY 255
#define MIN_DUTY 0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static void all_lamps_off(void) {
    set_lamp(LAMP1_PIN, 0);
    set_lamp(LAMP2_PIN, 0);
    set_lamp(LAMP3_PIN, 0);
}

static void cleanup(void) {
    all_lamps_off();
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  total_duration_seconds must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be an integer 1-3600.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
