#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define AMBER_PIN  24

#define RED_DURATION   10
#define YELLOW_DURATION 2
#define GREEN_DURATION 10
#define AMBER_DURATION  3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_relay(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d (state %d)\n", pin, state);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* De-energize all relays (active-low: HIGH = off) */
    gpioWrite(RED_PIN,   1);
    gpioWrite(YELLOW_PIN, 1);
    gpioWrite(GREEN_PIN,  1);
    gpioWrite(AMBER_PIN,  1);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Request each relay line as output, default HIGH (off) for active-low relays */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN,  PI_OUTPUT) != 0 ||
        gpioSetMode(AMBER_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure all relays start de-energized (HIGH = off) */
    if (set_relay(RED_PIN,   1) != 0 ||
        set_relay(YELLOW_PIN, 1) != 0 ||
        set_relay(GREEN_PIN,  1) != 0 ||
        set_relay(AMBER_PIN,  1) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Red + Yellow */
        if (set_relay(RED_PIN,   0) != 0 || set_relay(YELLOW_PIN, 0) != 0) break;
        printf("State: Red + Yellow\n");
        fflush(stdout);
        for (int i = 0; i < RED_DURATION + YELLOW_DURATION && g_running; i++)
            sleep(1);

        if (!g_running) break;
        if (set_relay(RED_PIN,   1) != 0 || set_relay(YELLOW_PIN, 1) != 0) break;
        printf("State: Red\n");
        fflush(stdout);
        for (int i = 0; i < RED_DURATION && g_running; i++)
            sleep(1);

        /* Green + Amber */
        if (set_relay(GREEN_PIN,  0) != 0 || set_relay(AMBER_PIN,  0) != 0) break;
        printf("State: Green + Amber\n");
        fflush(stdout);
        for (int i = 0; i < GREEN_DURATION + AMBER_DURATION && g_running; i++)
            sleep(1);

        if (!g_running) break;
        if (set_relay(GREEN_PIN,  1) != 0 || set_relay(AMBER_PIN,  1) != 0) break;
        printf("State: Green\n");
        fflush(stdout);
        for (int i = 0; i < GREEN_DURATION && g_running; i++)
            sleep(1);
    }

    cleanup();
    printf("Traffic light simulation stopped.\n");
    return EXIT_SUCCESS;
}

