static FILE *log_file = NULL;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_init(void) {
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus 1 at address 0x5A");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
