    }

    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);
    return 0;
}

static void set_motor_speed(int forward_pin, int backward_pin, int speed) {
    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
        gpioPWM(backward_pin, 0);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    }
}

static float generate_tilt_error(void) {
    return (float)(rand() % 201) - 100.0f;
}

static float generate_distance(void) {
    return (float)(rand() % 401) + 20.0f;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD_CM) {
        printf("Obstacle detected! Reversing...\n");
        set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, -OBSTACLE_REVERSE_SPEED);
        set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, -OBSTACLE_REVERSE_SPEED);

        gpioDelay(OBSTACLE_REVERSE_TIME_MS * 1000);

        set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, 0);
        set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, 0);
    }
}

int main(void) {
    srand(time(NULL));

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        stop_motors();
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        stop_motors();
        gpioTerminate();
        return 1;
    }

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    while (running) {
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        int motor_a_speed = (int)tilt_error;
        int motor_b_speed = (int)tilt_error;

        if (motor_a_speed > 255) motor_a_speed = 255;
        if (motor_a_speed < -255) motor_a_speed = -255;
        if (motor_b_speed > 255) motor_b_speed = 255;
        if (motor_b_speed < -255) motor_b_speed = -255;

        set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, motor_a_speed);
        set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        obstacle_avoidance(distance);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    stop_motors();
    fclose(log_file);
    gpioTerminate();
    return 0;
}

