/*
 * TTP223 Capacitive Touch Sensor -> Relay Control
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 on GPIO4  (BCM 4, physical pin 7)
 * Relay:  5 V relay on GPIO17 (BCM 17, physical pin 11)
 *
 * Behavior:
 *   - Polls GPIO4 for a rising edge (touch detected).
 *   - Toggles GPIO17 (relay) on each detection.
 *   - Debounce: 50 ms after each detection.
 *   - Active-high relay: GPIO17 HIGH = relay energized.
 *   - Graceful shutdown on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN    4   /* BCM 4  - TTP223 OUT  */
#define RELAY_PIN    17  /* BCM 17 - relay IN   */

#define DEBOUNCE_US  50000   /* 50 ms debounce window */
#define POLL_US      10000   /* 10 ms poll interval   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is OFF before releasing pigpio */
    if (RELAY_PIN != PI_BAD_GPIO)
        (void)gpioWrite(RELAY_PIN, 0);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    install_signal_handlers();

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF (active-high relay: LOW = de-energized) */
    if (safe_write(RELAY_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch relay control started.\n");
    printf("  Touch sensor : GPIO%d (BCM)\n", TOUCH_PIN);
    printf("  Relay        : GPIO%d (BCM, active-high)\n", RELAY_PIN);
    printf("  Debounce     : %d ms\n", DEBOUNCE_US / 1000);
    printf("Press Ctrl-C to exit.\n");

    bool relay_state = false;

    while (g_running) {
        int touch = safe_read(TOUCH_PIN);
        if (touch < 0) {
            /* Sensor read error — wait and retry */
            usleep(POLL_US);
            continue;
        }

        if (touch == 1) {
            /* Rising edge detected */
            relay_state = !relay_state;

            if (safe_write(RELAY_PIN, relay_state ? 1 : 0) != 0) {
                ret = EXIT_FAILURE;
                break;
            }

            printf("Touch detected -> relay %s\n",
                   relay_state ? "ON" : "OFF");

            /* Debounce: ignore further touches for 50 ms */
            usleep(DEBOUNCE_US);
        }

        usleep(POLL_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("\nExiting cleanly.\n");
    return ret;
}

