#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TCS34725_ADDR  0x29
#define CSV_FILE       "color_data.csv"
#define SAMPLE_US      500000   /* 500 ms */
#define INTEGRATION_MS 154

static volatile sig_atomic_t g_running = 1;
static int  g_i2c  = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int tcs_write(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(g_i2c, buf, 2) < 0) {
        fprintf(stderr, "tcs_write: i2cWriteDevice failed (reg=0x%02X, val=0x%02X)\n",
                reg, val);
        return -1;
    }
    return 0;
}

static int tcs_read(uint8_t reg, uint8_t *val)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c, wbuf, 1) < 0) {
        fprintf(stderr, "tcs_read: i2cWriteDevice (reg select) failed (reg=0x%02X)\n", reg);
        return -1;
    }
    char rbuf[1];
    if (i2cReadDevice(g_i2c, rbuf, 1) != 1) {
        fprintf(stderr, "tcs_read: i2cReadDevice failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *val = (uint8_t)rbuf[0];
    return 0;
}

static int tcs_init(void)
{
    /* Power on: PON = 1 */
    if (tcs_write(0x80, 0x01) < 0) return -1;
    gpioDelay(3000); /* 3 ms power-up delay */

    /* Set integration time: 154 ms (0x8B) */
    if (tcs_write(0x81, (uint8_t)INTEGRATION_MS) < 0) return -1;

    /* Set gain: 4x (0x8F) */
    if (tcs_write(0x8F, 0x00) < 0) return -1;

    /* Disable interrupts */
    if (tcs_write(0x86, 0x00) < 0) return -1;

    /* Set default command register (0x80) */
    if (tcs_write(0x80, 0x00) < 0) return -1;

    return 0;
}

static int tcs_read_raw(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b)
{
    uint8_t c_lo, c_hi, r_lo, r_hi, g_lo, g_hi, b_lo, b_hi;

    if (tcs_read(0x94, &c_lo) < 0) return -1;
    if (tcs_read(0x95, &c_hi) < 0) return -1;
    if (tcs_read(0x96, &r_lo) < 0) return -1;
    if (tcs_read(0x97, &r_hi) < 0) return -1;
    if (tcs_read(0x98, &g_lo) < 0) return -1;
    if (tcs_read(0x99, &g_hi) < 0) return -1;
    if (tcs_read(0x9A, &b_lo) < 0) return -1;
    if (tcs_read(0x9B, &b_hi) < 0) return -1;

    *c = (uint16_t)((c_hi << 8) | c_lo);
    *r = (uint16_t)((r_hi << 8) | r_lo);
    *g = (uint16_t)((g_hi << 8) | g_lo);
    *b = (uint16_t)((b_hi << 8) | b_lo);
    return 0;
}

static void cleanup(void)
{
    if (g_i2c >= 0) {
        i2cClose(g_i2c);
        g_i2c = -1;
    }
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "main: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "main: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, TCS34725_ADDR, g_i2c);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs_init() < 0) {
        fprintf(stderr, "main: TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILE, "w");
    if (!g_csv) {
        fprintf(stderr, "main: fopen(%s) failed\n", CSV_FILE);
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_csv, "timestamp,C,R,G,B\n");
    fflush(g_csv);

    printf("TCS34725 color sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs_read_raw(&c, &r, &g, &b) < 0) {
            fprintf(stderr, "main: sensor read error — logging zeros\n");
            c = r = g = b = 0;
        }

        time_t now = time(NULL);
        fprintf(g_csv, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
        fflush(g_csv);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

