#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioWrite(RELAY1, 1);
    gpioWrite(RELAY2, 1);
    gpioWrite(RELAY3, 1);
    gpioWrite(RELAY4, 1);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY2, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY3, PI_OUTPUT) != 0 ||
        gpioSetMode(RELAY4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY1, 1) != 0 ||
        gpioWrite(RELAY2, 1) != 0 ||
        gpioWrite(RELAY3, 1) != 0 ||
        gpioWrite(RELAY4, 1) != 0) {
        fprintf(stderr, "Error: failed to initialise relay states\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    const int num_relays = 4;
    const int *relays = (const int[]){RELAY1, RELAY2, RELAY3, RELAY4};
    const int num_phases = 4;
    const int phase_durations[] = {3600, 21600, 3600, 259200};
    const char *phase_names[] = {"Sunrise", "Daytime", "Sunset", "Nighttime"};

    while (running) {
        for (int p = 0; p < num_phases && running; p++) {
            int duration = phase_durations[p];
            int total_steps = duration * 10;
            int step_delay_us = (duration * 1000000) / total_steps;

            for (int s = 0; s < total_steps && running; s++) {
                int duty = s * 100 / total_steps;
                for (int i = 0; i < num_relays; i++) {
                    if (gpioWrite(relays[i], duty > 50 ? 0 : 1) != 0) {
                        fprintf(stderr, "Error: gpioWrite failed for relay %d\n", relays[i]);
                        cleanup();
                        return EXIT_FAILURE;
                    }
                }
                usleep(step_delay_us);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

