#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_MS 5000
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define TIMESTAMP_LEN 32
#define CMD_LEN 256

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename) {
    char command[CMD_LEN];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -w 640 -h 480 -fps 25",
             filename, VIDEO_DURATION_MS);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n",
                WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_fp == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }
    if (fprintf(log_fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(log_file)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", SENSOR_PIN);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                last_trigger_tick = now;

                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error: failed to generate timestamp.\n");
                    continue;
                }

                char filename[128];
                snprintf(filename, sizeof(filename), "%s%s.h264",
                         VIDEO_DIR, timestamp);

                if (capture_video(filename) == 0) {
                    printf("Motion detected at %s. Video saved to %s\n",
                           timestamp, filename);
                } else {
                    fprintf(stderr, "Error: video capture failed.\n");
                }

                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Error: failed to log motion event.\n");
                }
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

