#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MAX_DISTANCE_CM 4.0
#define TIMEOUT_US 100000
#define TRIG_PULSE_US 10
#define LOOP_DELAY_US 200000
#define MAX_PULSE_US 23200

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static volatile uint32_t tick_start = 0;
static volatile uint32_t tick_end = 0;
static volatile bool echo_rising = false;
static volatile bool echo_falling = false;
static volatile bool echo_ready = false;
static pthread_mutex_t echo_mutex;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&echo_mutex);
        tick_start = tick;
        echo_rising = true;
        echo_falling = false;
        echo_ready = false;
        pthread_mutex_unlock(&echo_mutex);
    } else if (level == 0 && echo_rising) {
        pthread_mutex_lock(&echo_mutex);
        tick_end = tick;
        echo_falling = true;
        echo_ready = true;
        pthread_mutex_unlock(&echo_mutex);
    }
}

static double calculate_distance(uint32_t pulse_us) {
    return (double)pulse_us / 58.0;
}

static void log_distance(double distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long nanos = ts.tv_nsec;
    fprintf(log_file, "%s.%09ld,%.2f\n", timestamp, nanos, distance);
    fflush(log_file);
}

static void log_error(const char *msg) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long nanos = ts.tv_nsec;
    fprintf(log_file, "%s.%09ld,ERROR,%s\n", timestamp, nanos, msg);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&echo_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write TRIG_PIN low\n");
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        pthread_mutex_destroy(&echo_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            log_error("Failed to trigger TRIG_PIN high");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            log_error("Failed to trigger TRIG_PIN low");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t start_tick = tick_start;
        uint32_t end_tick = tick_end;
        bool rising = echo_rising;
        bool falling = echo_falling;
        bool ready = echo_ready;

        pthread_mutex_lock(&echo_mutex);
        uint32_t pulse_us = 0;
        if (ready) {
            pulse_us = end_tick - start_tick;
        }
        echo_rising = false;
        echo_falling = false;
        echo_ready = false;
        pthread_mutex_unlock(&echo_mutex);

        if (pulse_us == 0) {
            log_error("No echo received");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (pulse_us > MAX_PULSE_US) {
            log_error("Echo pulse too long");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance = calculate_distance(pulse_us);
        if (distance > MAX_DISTANCE_CM) {
            log_error("Distance exceeds max range");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_distance(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    pthread_mutex_destroy(&echo_mutex);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

