#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LIS3DH_ADDR    0x19
#define BUZZER_PIN     17

#define REG_CTRL_REG1  0x20
#define REG_CTRL_REG4  0x23
#define REG_OUT_X_L    0x28
#define REG_OUT_X_H    0x29
#define REG_OUT_Y_L    0x2A
#define REG_OUT_Y_H    0x2B
#define REG_OUT_Z_L    0x2C
#define REG_OUT_Z_H    0x2D

#define DEFAULT_FREEFALL_THRESHOLD  0.2f
#define DEFAULT_IMPACT_THRESHOLD    1.5f
#define DEFAULT_I2C_RETRIES         3
#define DEFAULT_I2C_RETRY_DELAY_US  10000
#define DEFAULT_BUZZER_DURATION_US  1000000
#define DEFAULT_SAMPLE_DELAY_US     100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < DEFAULT_I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, DEFAULT_I2C_RETRIES, strerror(errno));
        if (DEFAULT_I2C_RETRY_DELAY_US > 0) usleep(DEFAULT_I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < DEFAULT_I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, DEFAULT_I2C_RETRIES, strerror(errno));
            if (DEFAULT_I2C_RETRY_DELAY_US > 0) usleep(DEFAULT_I2C_RETRY_DELAY_US);
            continue;
        }
        if (read(fd, value, 1) == 1) return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, DEFAULT_I2C_RETRIES, strerror(errno));
        if (DEFAULT_I2C_RETRY_DELAY_US > 0) usleep(DEFAULT_I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int lis3dh_init(int fd) {
    if (i2c_write_reg8(fd, REG_CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CTRL_REG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CTRL_REG1, 0x57) < 0) return -1;
    return 0;
}

static int lis3dh_read_accel(int fd, float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, REG_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(int pin, int duration_us) {
    gpioWrite(pin, 1);
    usleep(duration_us);
    gpioWrite(pin, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
    int buzzer_duration_us = DEFAULT_BUZZER_DURATION_US;
    int sample_delay_us = DEFAULT_SAMPLE_DELAY_US;

    if (argc > 1) freefall_threshold = strtof(argv[1], NULL);
    if (argc > 2) impact_threshold = strtof(argv[2], NULL);
    if (argc > 3) buzzer_duration_us = atoi(argv[3]);
    if (argc > 4) sample_delay_us = atoi(argv[4]);

    if (freefall_threshold <= 0.0f || impact_threshold <= 0.0f) {
        fprintf(stderr, "Error: Thresholds must be positive values.\n");
        return 1;
    }
    if (buzzer_duration_us <= 0) {
        fprintf(stderr, "Error: Buzzer duration must be positive.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    g_i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                LIS3DH_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (lis3dh_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LIS3DH sensor at 0x%02X\n", LIS3DH_ADDR);
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("LIS3DH initialized. Freefall threshold: %.2f g, Impact threshold: %.2f g, Buzzer duration: %d us, Sample delay: %d us\n",
           freefall_threshold, impact_threshold, buzzer_duration_us, sample_delay_us);

    while (g_running) {
        float x, y, z;
        if (lis3dh_read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
            usleep(sample_delay_us);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
        } else if (magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer(BUZZER_PIN, buzzer_duration_us);
        }

        usleep(sample_delay_us);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    return 0;
}

