        fprintf(stderr, "Error: failed to set Motor 1 pins as outputs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure Motor 2 pins as outputs. */
    if (gpioSetMode(MOTOR2_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set Motor 2 pins as outputs\n");
        gpioTerminate();
