    stop_motors(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4);

    printf("Tracing a %.1f mm square...\n", SQUARE_SIZE_MM);

    if (trace_square(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4,
                     MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4,
