#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D
#define LIS3DH_REG_STATUS 0x27
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int lis3dh_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_burst(fd, LIS3DH_REG_WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who_am_i, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_byte(fd, LIS3DH_REG_CTRL1, 0x57) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL1: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_byte(fd, LIS3DH_REG_CTRL4, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL4: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3dh_read_accel(int fd, float *x, float *y, float *z) {
    uint8_t status = 0;
    if (i2c_read_burst(fd, LIS3DH_REG_STATUS, &status, 1) < 0) {
        return -1;
    }
    if (!(status & 0x07)) {
        return 1;
    }
    uint8_t data[6];
    if (i2c_read_burst(fd, LIS3DH_REG_OUT_X_L, data, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((data[1] << 8) | data[0]);
    int16_t raw_y = (int16_t)((data[3] << 8) | data[2]);
    int16_t raw_z = (int16_t)((data[5] << 8) | data[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Threshold exceeded. Shutting down system...\n");
    fflush(stdout);
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Error: Invalid I2C address 0x%02X (must be 0x03-0x77)\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", i2c_address, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (lis3dh_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: LIS3DH initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3DH initialized at address 0x%02X. Monitoring for acceleration...\n", i2c_address);
    fflush(stdout);

    while (g_running) {
        float x, y, z;
        int ret = lis3dh_read_accel(g_i2c_fd, &x, &y, &z);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read acceleration data: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (ret == 1) {
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            log_acceleration(x, y, z);
            shutdown_system();
            break;
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

