        fprintf(stderr, "Error: Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", i2c_address, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (lis3dh_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: LIS3DH initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3DH initialized at address 0x%02X. Monitoring for acceleration...\n", i2c_address);
    fflush(stdout);

    while (g_running) {
        float x, y, z;
        int ret = lis3dh_read_accel(g_i2c_fd, &x, &y, &z);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read acceleration data: %s\n", strerror(errno));
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (ret == 1) {
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            log_acceleration(x, y, z);
            shutdown_system();
            break;
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

