/*
 * Autonomous line-following robot for Raspberry Pi 5.
 *
 * Hardware:
 *   - SunFounder 3-Way Tracking Sensor (IR reflectance, digital)
 *     Left  sensor -> GPIO4  (BCM)
 *     Center sensor -> GPIO17 (BCM)
 *     Right sensor -> GPIO27 (BCM)
 *   - Active-high alert LED/buzzer -> GPIO22 (BCM)
 *
 * Behavior:
 *   - Polls the three sensor pins every 10 ms.
 *   - Logs each reading into a circular buffer of size 5.
 *   - Drives the alert pin HIGH for 2 s when the center sensor
 *     reports "no line" (logic 1) for five consecutive readings.
 *   - Moves forward when the center sensor detects a line (logic 0).
 *   - Turns left when the left sensor detects a line.
 *   - Turns right when the right sensor detects a line.
 *   - Stops when all sensors read "no line".
 *   - Releases all resources on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_LED_PIN      22

#define BUFFER_SIZE        5
#define POLL_DELAY_US      10000   /* 10 ms */
#define ALERT_DURATION_S   2
#define CONSECUTIVE_NO_LINE 5

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void init_circular_buffer(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, SensorData sd)
{
    cb->data[cb->head] = sd;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static SensorData read_sensors(void)
{
    SensorData sd;
    sd.left    = gpioRead(LEFT_SENSOR_PIN);
    sd.center  = gpioRead(CENTER_SENSOR_PIN);
    sd.right   = gpioRead(RIGHT_SENSOR_PIN);
    return sd;
}

static void control_motor_forward(void)
{
    /* Placeholder: drive motors forward. */
    printf("Moving forward\n");
}

static void control_motor_left(void)
{
    /* Placeholder: turn left. */
    printf("Turning left\n");
}

static void control_motor_right(void)
{
    /* Placeholder: turn right. */
    printf("Turning right\n");
}

static void control_motor_stop(void)
{
    /* Placeholder: stop motors. */
    printf("Stopping\n");
}

static void check_alert_condition(CircularBuffer *cb)
{
    if (cb->count < CONSECUTIVE_NO_LINE)
        return;

    int no_line_count = 0;
    for (int i = 0; i < CONSECUTIVE_NO_LINE; i++) {
        int idx = (cb->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        if (cb->data[idx].center == 1)
            no_line_count++;
    }

    if (no_line_count == CONSECUTIVE_NO_LINE) {
        printf("Alert: center sensor reports no line for %d consecutive readings.\n",
               CONSECUTIVE_NO_LINE);
        gpioWrite(ALERT_LED_PIN, 1);
        sleep(ALERT_DURATION_S);
        gpioWrite(ALERT_LED_PIN, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs. */
    if (gpioSetMode(LEFT_SENSOR_PIN,   PI_INPUT) != 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN,  PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set sensor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert LED pin as output and ensure it is off. */
    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set alert LED pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_LED_PIN, 0);

    /* Register signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer sensor_buffer;
    init_circular_buffer(&sensor_buffer);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (g_running) {
        SensorData sensor_data = read_sensors();

        add_to_buffer(&sensor_buffer, sensor_data);

        check_alert_condition(&sensor_buffer);

        if (sensor_data.center == 0) {
            control_motor_forward();
        } else if (sensor_data.left == 1) {
            control_motor_left();
        } else if (sensor_data.right == 1) {
            control_motor_right();
        } else {
            control_motor_stop();
        }

        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown: stop motors and release pigpio. */
    control_motor_stop();
    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

