#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <ctype.h>
#include <pigpio.h>

#define PORT 5000
#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Shutdown");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) return 1;
    if (init_log() < 0) { gpioTerminate(); return 1; }
    if ((server_fd = init_socket()) < 0) { cleanup(); return 1; }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        client_fd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            log_event("Accept error");
            break;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &caddr.sin_addr, ip, sizeof(ip));
        printf("Connection from %s\n", ip);
        log_event("Connection accepted");

        char buffer[BUFFER_SIZE];
        ssize_t n;
        while ((n = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
            buffer[n] = '\0';
            char *cmd = strdup(buffer);
            if (!cmd) {
                log_event("Memory allocation failed");
                break;
            }
            for (char *p = cmd; *p; p++) *p = (char)tolower((unsigned char)*p);
            char *nl = strpbrk(cmd, "\r\n");
            if (nl) *nl = '\0';
            char *ws = strpbrk(cmd, " \t");
            if (ws) *ws = '\0';
            if (strcmp(cmd, "on") == 0) {
                gpioWrite(RELAY_GPIO, 1);
                log_event("Relay ON");
            } else if (strcmp(cmd, "off") == 0) {
                gpioWrite(RELAY_GPIO, 0);
                log_event("Relay OFF");
            } else {
                log_event("Invalid command");
            }
            free(cmd);
        }
        if (n < 0) {
            perror("recv");
            log_event("Recv error");
        }
        close(client_fd);
        client_fd = -1;
        log_event("Connection closed");
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

