/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F liquid-flow monitor with safety relay.
 *
 * Wiring:
 *   Sensor 1 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   Sensor 1 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   Sensor 2 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   Sensor 2 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   Relay IN      -> GPIO 18 (BCM)  [active-high]
 *   Relay VCC     -> 5 V
 *   Relay GND     -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x36   /* SLF3S-1300F default I2C address */
#define SENSOR2_ADDR         0x37   /* SLF3S-1300F default I2C address */
#define RELAY_GPIO           18     /* BCM numbering */
#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_DELAY_US        100000 /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F command bytes (16-bit, big-endian on the wire) */
#define CMD_START_MEASUREMENT 0x3608
#define CMD_READ_FLOW_RATE    0x0400

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static bool g_relay_state = false;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static bool init_i2c(void);
static bool init_relay(void);
static bool read_flow_rate(int handle, float *flow_rate);
static uint8_t crc8(const uint8_t *data, int len);
static void log_flow_rate(float flow_rate1, float flow_rate2);
static void control_relay(float flow_rate1, float flow_rate2);

/* ----------------------------- CRC-8 ------------------------------------- */
/* SLF3S-1300F CRC-8: polynomial 0x31, initial value 0xFF, no final XOR. */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_state = false;
    }
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioTerminate();
}

/* ----------------------------- I2C init ---------------------------------- */
static bool init_i2c(void)
{
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        return false;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        return false;
    }

    return true;
}

/* ----------------------------- Relay init -------------------------------- */
static bool init_relay(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        return false;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing relay state to LOW\n");
        return false;
    }
    g_relay_state = false;
    return true;
}

/* ----------------------------- Read flow rate ---------------------------- */
static bool read_flow_rate(int handle, float *flow_rate)
{
    char cmd[2] = { (char)(CMD_READ_FLOW_RATE >> 8),
                    (char)(CMD_READ_FLOW_RATE & 0xFF) };
    char buf[3];

    /* Start a single-shot measurement */
    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing start-measurement command to handle %d\n", handle);
        return false;
    }

    /* Wait for the measurement to complete (typical ~10 ms) */
    gpioDelay(20000); /* 20 ms */

    /* Read 3 bytes: MSB, LSB, CRC */
    if (i2cReadDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading 3 bytes from handle %d\n", handle);
        return false;
    }

    /* CRC check */
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return false;
    }

    uint16_t raw = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *flow_rate = (float)raw * 0.01f; /* SLF3S-1300F: 0.01 counts/second */
    return true;
}

/* ----------------------------- Log flow rate ----------------------------- */
static void log_flow_rate(float flow_rate1, float flow_rate2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            timestamp, ms, flow_rate1, flow_rate2);
    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(float flow_rate1, float flow_rate2)
{
    bool below_threshold = (flow_rate1 < FLOW_THRESHOLD_ML_MIN ||
                            flow_rate2 < FLOW_THRESHOLD_ML_MIN);

    if (below_threshold && !g_relay_state) {
        if (gpioWrite(RELAY_GPIO, 1) == 0) {
            g_relay_state = true;
            printf("Relay energized (both sensors below %.1f ml/min)\n",
                   FLOW_THRESHOLD_ML_MIN);
        } else {
            fprintf(stderr, "Error energizing relay\n");
        }
    } else if (!below_threshold && g_relay_state) {
        if (gpioWrite(RELAY_GPIO, 0) == 0) {
            g_relay_state = false;
            printf("Relay de-energized (both sensors at or above %.1f ml/min)\n",
                   FLOW_THRESHOLD_ML_MIN);
        } else {
            fprintf(stderr, "Error de-energizing relay\n");
        }
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (!init_i2c()) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (!init_relay()) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F sensors on I2C bus %d (addr 0x%02X, 0x%02X).\n",
           I2C_BUS, SENSOR1_ADDR, SENSOR2_ADDR);
    printf("Relay on GPIO %d. Threshold: %.1f ml/min. Press Ctrl+C to exit.\n",
           RELAY_GPIO, FLOW_THRESHOLD_ML_MIN);

    while (g_running) {
        float flow_rate1 = 0.0f, flow_rate2 = 0.0f;
        bool ok1 = read_flow_rate(g_i2c_handle1, &flow_rate1);
        bool ok2 = read_flow_rate(g_i2c_handle2, &flow_rate2);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Warning: sensor read failed, skipping cycle\n");
        } else {
            log_flow_rate(flow_rate1, flow_rate2);
            control_relay(flow_rate1, flow_rate2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

