#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds in microseconds */
#define POLL_INTERVAL_US 200000    /* 200 ms in microseconds */
#define DRY_THRESHOLD 3            /* consecutive dry polls before rearming */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int motor_stop(void)
{
    if (gpioWrite(MOTOR_ENABLE_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_ENABLE_PIN (stop): %s", pigpio_error(0));
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_IN1_PIN (stop): %s", pigpio_error(0));
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_IN2_PIN (stop): %s", pigpio_error(0));
        return -1;
    }
    syslog(LOG_INFO, "Motor stopped.");
    return 0;
}

static int motor_run(void)
{
    if (gpioWrite(MOTOR_ENABLE_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_ENABLE_PIN (run): %s", pigpio_error(0));
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_IN1_PIN (run): %s", pigpio_error(0));
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to write MOTOR_IN2_PIN (run): %s", pigpio_error(0));
        return -1;
    }
    syslog(LOG_INFO, "Motor started (close window).");
    return 0;
}

static int rain_detected(void)
{
    return (gpioRead(RAIN_SENSOR_PIN) == 0);
}

static int init_gpio(void)
{
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set RAIN_SENSOR_PIN (BCM %d) as input: %s",
               RAIN_SENSOR_PIN, pigpio_error(0));
        return -1;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set pull-up on RAIN_SENSOR_PIN (BCM %d): %s",
               RAIN_SENSOR_PIN, pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MOTOR_ENABLE_PIN (BCM %d) as output: %s",
               MOTOR_ENABLE_PIN, pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MOTOR_IN1_PIN (BCM %d) as output: %s",
               MOTOR_IN1_PIN, pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MOTOR_IN2_PIN (BCM %d) as output: %s",
               MOTOR_IN2_PIN, pigpio_error(0));
        return -1;
    }
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor stop failed.");
        return -1;
    }
    syslog(LOG_INFO, "GPIO initialized: sensor=BCM%d, enable=BCM%d, in1=BCM%d, in2=BCM%d",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);
    return 0;
}

static void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up GPIO and exiting.");
    motor_stop();
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %m");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (BCM %d, rising edge = dry -> wet).",
           RAIN_SENSOR_PIN);

    int dry_count = 0;
    int last_rain_state = 1;  /* assume dry at startup (pull-up high) */

    while (g_running) {
        int rain = rain_detected();

        if (rain != last_rain_state) {
            if (rain) {
                syslog(LOG_INFO, "Rain detected (BCM %d low).", RAIN_SENSOR_PIN);
            } else {
                syslog(LOG_INFO, "Dry (BCM %d high).", RAIN_SENSOR_PIN);
                dry_count++;
                if (dry_count >= DRY_THRESHOLD) {
                    dry_count = 0;
                    syslog(LOG_INFO, "Dry for %d consecutive polls. Rearming.",
                           DRY_THRESHOLD);
                }
            }
            last_rain_state = rain;
        }

        if (rain && dry_count < DRY_THRESHOLD) {
            if (motor_run() < 0) {
                syslog(LOG_ERR, "Failed to start motor.");
            } else {
                syslog(LOG_INFO, "Running motor for %d seconds.",
                       MOTOR_RUN_TIME_US / 1000000);
                if (gpioDelay(MOTOR_RUN_TIME_US) < 0) {
                    syslog(LOG_ERR, "gpioDelay failed: %s", pigpio_error(0));
                }
                if (motor_stop() < 0) {
                    syslog(LOG_ERR, "Failed to stop motor.");
                }
            }
        }

        if (gpioDelay(POLL_INTERVAL_US) < 0) {
            syslog(LOG_ERR, "gpioDelay failed: %s", pigpio_error(0));
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

