#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define POLL_DELAY_US  10000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_US) != 0)
        exit(EXIT_FAILURE);
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, UNLOCK_PULSE_US) != 0)
        exit(EXIT_FAILURE);
    printf("Door unlocked.\n");
    fflush(stdout);
}

static void shutdown_system(void)
{
    printf("Shutting down...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, 0) != 0)
        exit(EXIT_FAILURE);
    gpioTerminate();
    printf("System shutdown complete.\n");
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
                while (g_running) {
                    if (gpioRead(LOCK_BUTTON) != 0)
                        break;
                    gpioDelay(POLL_DELAY_US);
                }
            }
        } else if (unlock_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
                while (g_running) {
                    if (gpioRead(UNLOCK_BUTTON) != 0)
                        break;
                    gpioDelay(POLL_DELAY_US);
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    shutdown_system();
    return EXIT_SUCCESS;
}

