#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define LED_ON_DURATION_S 60
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(FILE *fp, const char *event_type, time_t duration)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - %s - Duration: %ld seconds\n", ts, event_type, (long)duration) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PIR pin as input with pull-down */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(PIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    int last_state = 0;

    while (g_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (current_state == 1 && last_state == 0) {
            /* Rising edge: motion detected */
            printf("Motion detected!\n");

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN, 1) failed\n");
                break;
            }

            /* Log activation event */
            if (log_event(log_fp, "Motion Detected", 0) != 0) {
                fprintf(stderr, "Failed to log activation event\n");
                break;
            }

            /* Keep floodlight on for the configured duration */
            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                break;
            }

            while (g_running) {
                time_t now = time(NULL);
                if (now == (time_t)-1) {
                    fprintf(stderr, "time() failed: %s\n", strerror(errno));
                    break;
                }
                if (difftime(now, start_time) >= LED_ON_DURATION_S) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
                break;
            }

            /* Log deactivation event */
            if (log_event(log_fp, "Motion Detected", LED_ON_DURATION_S) != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
                break;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown: ensure floodlight is OFF */
    gpioWrite(LED_PIN, 0);

    /* Close log file */
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
    }

    gpioTerminate();

    printf("Motion detection system stopped.\n");
    return EXIT_SUCCESS;
}

