                }
                if (difftime(now, start_time) >= LED_ON_DURATION_S) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
                break;
            }

            /* Log deactivation event */
            if (log_event(log_fp, "Motion Detected", LED_ON_DURATION_S) != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
                break;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown: ensure floodlight is OFF */
    gpioWrite(LED_PIN, 0);

    /* Close log file */
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
    }

    gpioTerminate();

    printf("Motion detection system stopped.\n");
    return EXIT_SUCCESS;
}

