    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    relay_state = false;

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_data = 0;
        if (read_touch_data(&touch_data) < 0) {
            fprintf(stderr, "Error reading touch data, retrying...\n");
