#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define MAX_COMMAND_LENGTH 256
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *format, ...) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);

    if (log_file) {
        fprintf(log_file, "%s: ", timestamp);
        va_start(args, format);
        vfprintf(log_file, format, args);
        va_end(args);
        fflush(log_file);
    }
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
    if (server_fd >= 0) {
        shutdown(server_fd, SHUT_RDWR);
        close(server_fd);
        server_fd = -1;
    }
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_width = 1000 + (angle * 2000 / 180);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        log_message(LOG_ERR, "Failed to set servo pulse width: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[MAX_COMMAND_LENGTH];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        return;
    }
    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
        return;
    }
    buffer[bytes_received] = '\0';

    char *command = strtok(buffer, " \r\n");
    if (command == NULL) {
        log_message(LOG_ERR, "Empty command received");
        send(client_socket, "Invalid command\n", 16, 0);
        return;
    }

    if (strcmp(command, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value >= 0) {
            char response[32];
            snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
            send(client_socket, response, strlen(response), 0);
        } else {
            send(client_socket, "PIR:ERROR\n", 10, 0);
        }
    } else if (strncmp(command, "the library's API call", 22) == 0) {
        char *angle_str = strtok(NULL, " \r\n");
        if (angle_str == NULL) {
            log_message(LOG_ERR, "Missing angle argument");
            send(client_socket, "Invalid command\n", 16, 0);
            return;
        }
        int angle = atoi(angle_str);
        if (set_servo_angle(angle) == 0) {
            char response[32];
            snprintf(response, sizeof(response), "Servo set to %d\n", angle);
            send(client_socket, response, strlen(response), 0);
        } else {
            send(client_socket, "Servo set failed\n", 17, 0);
        }
    } else {
        log_message(LOG_ERR, "Unknown command: %s", command);
        send(client_socket, "Invalid command\n", 16, 0);
    }
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set servo pin mode");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set PIR pin mode");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        log_message(LOG_ERR, "Failed to set PIR pull-down");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Server listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            if (running && errno != EINTR) {
                log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            }
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "Connection from %s:%d", client_ip, ntohs(client_address.sin_port));

        handle_client(client_socket);
        close(client_socket);
    }

    log_message(LOG_INFO, "Shutting down");
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    closelog();
    return EXIT_SUCCESS;
}

