#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define BH1750_CONT_H  0x10
#define BH1750_ONE_TIME_H  0x20
#define BH1750_CONV_MS  120
#define GROW_LIGHT_PIN 23
#define LUX_THRESHOLD  150
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_MS      2000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_init(int handle)
{
    if (i2cWriteByte(handle, BH1750_CONT_H) < 0) {
        fprintf(stderr, "Error: failed to set BH1750 continuous mode.\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out)
{
    if (i2cWriteByte(handle, BH1750_ONE_TIME_H) < 0) {
        fprintf(stderr, "Error: failed to trigger one-time measurement.\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 2).\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, lux);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GROW_LIGHT_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BH1750 not responding at 0x%02X.\n", BH1750_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GROW_LIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", GROW_LIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GROW_LIGHT_PIN, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux;
        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);
            if (lux < LUX_THRESHOLD) {
                gpioWrite(GROW_LIGHT_PIN, 1);
                printf("Lux %.2f < %.0f -> relay ON\n", lux, LUX_THRESHOLD);
            } else {
                gpioWrite(GROW_LIGHT_PIN, 0);
                printf("Lux %.2f >= %.0f -> relay OFF\n", lux, LUX_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

