/*
 * Raspberry Pi 3 Model B+ — TAL220B load-cell monitor with solenoid lock
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:  gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lpigpio -lrt
 * Run:    sudo ./weight_monitor [--scale <factor>] [--threshold <grams>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HX711_DOUT_PIN    23          /* GPIO23, physical pin 16 */
#define HX711_SCK_PIN     24          /* GPIO24, physical pin 18 */
#define SOLENOID_PIN      25          /* GPIO25, physical pin 22 */

#define TARE_READINGS     10          /* Number of tare readings */
#define MEASURE_READINGS  5           /* Number of readings per measurement cycle */
#define POLL_INTERVAL_MS  500         /* Main-loop poll interval */
#define SOLENOID_HOLD_MS  200         /* Solenoid hold duration */
#define HX711_TIMEOUT_US  1000000     /* 1 s timeout waiting for DOUT to go LOW */
#define HX711_MAX_RETRIES 3           /* Max retries on a single HX711 read */
#define HX711_SETTLE_US   1000        /* 1 ms settle after SCK high/low */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static double g_scale_factor = 1.0;
static double g_threshold_grams = 1000.0;

/* --------------------------- Function prototypes -------------------------- */
static int  init_gpio(void);
static int  read_tare_weight(int32_t *out_raw);
static int  read_weight(int32_t *out_raw);
static double raw_to_grams(int32_t raw);
static bool weight_exceeds_threshold(double grams);
static void activate_solenoid(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- Main ------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                g_scale_factor = atof(optarg);
                if (g_scale_factor <= 0.0) {
                    fprintf(stderr, "Invalid scale factor: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                g_threshold_grams = atof(optarg);
                if (g_threshold_grams <= 0.0) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale_factor] [-t threshold_grams]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor (scale=%.2f, threshold=%.1f g)",
           g_scale_factor, g_threshold_grams);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    int32_t tare_raw = 0;
    if (read_tare_weight(&tare_raw) != 0) {
        syslog(LOG_ERR, "Tare failed after %d retries; aborting", HX711_MAX_RETRIES);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Tare complete: raw=%d", tare_raw);
    tare_raw = 0; /* Reset for measurement loop */

    while (g_running) {
        int32_t sum = 0;
        for (int i = 0; i < MEASURE_READINGS; i++) {
            int32_t raw;
            if (read_weight(&raw) != 0) {
                syslog(LOG_ERR, "Weight read failed; retrying");
                continue;
            }
            sum += raw;
            gpioDelay(POLL_INTERVAL_MS * 1000); /* gpioDelay takes microseconds */
        }
        if (sum == 0) {
            syslog(LOG_ERR, "All weight reads failed; aborting");
            break;
        }
        double grams = raw_to_grams(sum / MEASURE_READINGS);
        syslog(LOG_INFO, "Weight: %.2f g", grams);
        if (weight_exceeds_threshold(grams)) {
            syslog(LOG_INFO, "Threshold exceeded; activating solenoid");
            activate_solenoid();
        }
    }

    cleanup();
    syslog(LOG_INFO, "Weight monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}

/* --------------------------- GPIO initialization -------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711 DOUT pin %d as input", HX711_DOUT_PIN);
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set HX711 SCK pin %d as output", HX711_SCK_PIN);
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin %d as output", SOLENOID_PIN);
        return -1;
    }

    /* Ensure SCK is LOW and solenoid is OFF at startup */
    if (gpioWrite(HX711_SCK_PIN, 0) != 0 || gpioWrite(SOLENOID_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO states");
        return -1;
    }
    return 0;
}

/* --------------------------- Tare reading --------------------------------- */
static int read_tare_weight(int32_t *out_raw)
{
    for (int attempt = 1; attempt <= HX711_MAX_RETRIES; attempt++) {
        int32_t raw = 0;
        if (read_weight(&raw) == 0) {
            *out_raw = raw;
            return 0;
        }
        syslog(LOG_WARNING, "Tare read %d/%d failed", attempt, HX711_MAX_RETRIES);
        gpioDelay(100000); /* 100 ms between retries */
    }
    return -1;
}

/* --------------------------- Weight reading ------------------------------- */
static int read_weight(int32_t *out_raw)
{
    /* Wait for DOUT to go LOW (data ready) with timeout */
    uint32_t waited = 0;
    while (gpioRead(HX711_DOUT_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 DOUT timeout (no data ready)");
            return -1;
        }
        gpioDelay(100); /* 100 us granularity */
        waited += 100;
    }

    /* Read 24 bits MSB-first, then one extra clock pulse for Channel A gain 128 */
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
            syslog(LOG_ERR, "SCK high write failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
        value <<= 1;
        if (gpioRead(HX711_DOUT_PIN) == 1) {
            value |= 1;
        }
        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            syslog(LOG_ERR, "SCK low write failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
    }
    /* 25th clock pulse selects Channel A gain 128 */
    if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
        syslog(LOG_ERR, "SCK high (25th pulse) failed");
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
        syslog(LOG_ERR, "SCK low (25th pulse) failed");
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (value & 0x800000) {
        value |= 0xFF000000; /* Sign-extend */
    }
    *out_raw = value;
    return 0;
}

/* --------------------------- Conversion ----------------------------------- */
static double raw_to_grams(int32_t raw)
{
    return (double)raw / g_scale_factor;
}

/* --------------------------- Threshold check ------------------------------ */
static bool weight_exceeds_threshold(double grams)
{
    return grams > g_threshold_grams;
}

/* --------------------------- Solenoid control ----------------------------- */
static void activate_solenoid(void)
{
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH");
        return;
    }
    gpioDelay(SOLENOID_HOLD_MS * 1000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW");
    }
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    /* Ensure solenoid is OFF */
    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

