#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define GPIO_PIN            17
#define GPIO_MODE           PI_OUTPUT
#define GPIO_INIT_VALUE     0
#define MQTT_KEEPALIVE      60
#define MQTT_RECONNECT_DELAY 5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mqtt = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

static void cleanup(void)
{
    if (g_mqtt) {
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
}

static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Connected to MQTT broker at %s:%d",
                 MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        log_message(LOG_INFO, buf);
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT connection error: %s", mosquitto_strerror(result));
        log_message(LOG_ERR, buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)userdata;
    if (rc == 0) {
        log_message(LOG_INFO, "Disconnected cleanly");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        log_message(LOG_ERR, "Received empty or null MQTT message payload");
        return;
    }

    char payload[256];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) != 0) {
            log_message(LOG_ERR, "Failed to energize relay");
        } else {
            log_message(LOG_INFO, "Relay energized");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) != 0) {
            log_message(LOG_ERR, "Failed to de-energize relay");
        } else {
            log_message(LOG_INFO, "Relay de-energized");
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "Invalid payload: '%s'", payload);
        log_message(LOG_ERR, buf);
    }
}

int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, GPIO_MODE) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_PIN, GPIO_INIT_VALUE) != 0) {
        log_message(LOG_ERR, "Failed to initialize GPIO17 to LOW");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    g_mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mqtt) {
        log_message(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mqtt, on_connect);
    mosquitto_disconnect_callback_set(g_mqtt, on_disconnect);
    mosquitto_message_callback_set(g_mqtt, on_message);

    int rc = mosquitto_connect(g_mqtt, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(g_mqtt);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to start MQTT loop: %s", mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "MQTT relay controller started");

    while (g_running) {
        rc = mosquitto_loop(g_mqtt, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            char buf[128];
            snprintf(buf, sizeof(buf), "MQTT loop error: %s", mosquitto_strerror(rc));
            log_message(LOG_ERR, buf);
            sleep(MQTT_RECONNECT_DELAY);
            rc = mosquitto_reconnect(g_mqtt);
            if (rc != MOSQ_ERR_SUCCESS) {
                char buf2[128];
                snprintf(buf2, sizeof(buf2), "Reconnect failed: %s", mosquitto_strerror(rc));
                log_message(LOG_ERR, buf2);
            }
        }
    }

    log_message(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

