/*
 * Closed-loop DC motor speed control for a miniature vehicle.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   DRV8833 H-bridge on GPIO 17 (PWM A), GPIO 18 (DIR A),
 *   GPIO 22 (PWM B), GPIO 23 (DIR B).
 *   Quadrature encoders:
 *     Encoder A: GPIO 4 (phase A), GPIO 5 (phase B)
 *     Encoder B: GPIO 6 (phase A), GPIO 12 (phase B)
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM  17
#define MOTOR_A_DIR  18
#define MOTOR_B_PWM  22
#define MOTOR_B_DIR  23

#define ENCODER_A_A  4
#define ENCODER_A_B  5
#define ENCODER_B_A  6
#define ENCODER_B_B  12

/* ---- Control parameters ---- */
#define TARGET_RPM   50.0
#define PWM_FREQ     10000   /* 10 kHz */
#define PWM_RANGE    255
#define TICKS_PER_REV 64
#define STALL_TIMEOUT_S 2.0

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int32_t g_enc_a = 0;
static volatile int32_t g_enc_b = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void motor_a_forward(int pwm);
static void motor_a_reverse(int pwm);
static void motor_b_forward(int pwm);
static void motor_b_reverse(int pwm);
static void motor_stop(void);
static double calculate_pid(double setpoint, double process_variable,
                            double *integral, double *previous_error,
                            double kp, double ki, double kd, double dt);
static void log_data(double rpm_a, double rpm_b, int pwm_a, int pwm_b);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Encoder ISRs (rising edge) ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_enc_a++;
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_enc_b++;
}

/* ---- Motor control helpers ---- */
static void motor_a_forward(int pwm)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioWrite(MOTOR_A_DIR, 0);
    gpioPWM(MOTOR_A_PWM, pwm);
}

static void motor_a_reverse(int pwm)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioWrite(MOTOR_A_DIR, 1);
    gpioPWM(MOTOR_A_PWM, pwm);
}

static void motor_b_forward(int pwm)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_B_PWM, pwm);
}

static void motor_b_reverse(int pwm)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioWrite(MOTOR_B_DIR, 1);
    gpioPWM(MOTOR_B_PWM, pwm);
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
}

/* ---- PI controller ---- */
static double calculate_pid(double setpoint, double process_variable,
                            double *integral, double *previous_error,
                            double kp, double ki, double kd, double dt)
{
    double error = setpoint - process_variable;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

/* ---- Data logging ---- */
static void log_data(double rpm_a, double rpm_b, int pwm_a, int pwm_b)
{
    printf("Motor A: RPM=%.2f, PWM=%d | Motor B: RPM=%.2f, PWM=%d\n",
           rpm_a, pwm_a, rpm_b, pwm_b);
    fflush(stdout);
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins ---- */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure encoder pins ---- */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups on encoder inputs (quadrature decoding) */
    if (gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set encoder pull-ups.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register ISRs ---- */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder A phase A.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder A phase B.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder B phase A.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for Encoder B phase B.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM ---- */
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- PID state ---- */
    double integral_a = 0.0, previous_error_a = 0.0;
    double integral_b = 0.0, previous_error_b = 0.0;
    double dt = 0.1; /* 100 ms */

    /* ---- Main control loop ---- */
    while (g_running) {
        /* Read encoder counts (non-atomic, but acceptable for control loop) */
        int32_t enc_a = g_enc_a;
        int32_t enc_b = g_enc_b;
        g_enc_a = 0;
        g_enc_b = 0;

        /* RPM calculation (1 tick = 1/64 revolution) */
        double rpm_a = (double)enc_a / (double)TICKS_PER_REV / dt * 60.0;
        double rpm_b = (double)enc_b / (double)TICKS_PER_REV / dt * 60.0;

        /* Stall detection */
        if (enc_a == 0 && enc_b == 0) {
            static double last_stall_warn = 0.0;
            double now = time_time();
            if (now - last_stall_warn < STALL_TIMEOUT_S) {
                continue;
            }
            fprintf(stderr, "Warning: no encoder ticks for %.1f s — possible stall.\n",
                    STALL_TIMEOUT_S);
            last_stall_warn = now;
        }

        /* PI control */
        double pwm_a = (double)calculate_pid(TARGET_RPM, rpm_a,
                                              &integral_a, &previous_error_a,
                                              1.0, 0.1, 0.0, dt);
        double pwm_b = (double)calculate_pid(TARGET_RPM, rpm_b,
                                              &integral_b, &previous_error_b,
                                              1.0, 0.1, 0.0, dt);

        /* Clamp PWM to 0-255 */
        if (pwm_a < 0) pwm_a = 0; else if (pwm_a > PWM_RANGE) pwm_a = PWM_RANGE;
        if (pwm_b < 0) pwm_b = 0; else if (pwm_b > PWM_RANGE) pwm_b = PWM_RANGE;

        /* Drive motors */
        motor_a_forward((int)pwm_a);
        motor_b_forward((int)pwm_b);

        /* Log data */
        log_data(rpm_a, rpm_b, (int)pwm_a, (int)pwm_b);

        /* Sleep 100 ms */
        time_sleep(dt);
    }

    /* ---- Cleanup ---- */
    motor_stop();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

