/*
 * Raspberry Pi 4 Model B – BH1750 ambient light monitor with relay control.
 *
 * Hardware:
 *   - BH1750 light sensor on I2C bus 1, address 0x23 (ADDR pin low).
 *   - 12 V LED strip driven through a relay on GPIO 17 (BCM).
 *
 * Behaviour:
 *   - Polls lux every 5 s.
 *   - Activates relay when lux < 50 (dusk).
 *   - Deactivates relay when lux > 200 (dawn), with hysteresis.
 *   - Logs each reading and relay state change to chicken_coop_log.txt.
 *   - Safely shuts down on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o coop coop.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23          /* ADDR pin -> GND */
#define RELAY_GPIO           17            /* BCM 17, active-high relay */
#define LUX_THRESHOLD_DUSK   50.0f
#define LUX_THRESHOLD_DAWN   200.0f
#define POLL_INTERVAL_SEC    5
#define MODE_SETTLE_MS       180           /* BH1750 needs >= 180 ms after mode */
#define LOG_FILE             "chicken_coop_log.txt"

/* BH1750 power-on / mode commands (single-shot, no wait, no interrupt) */
#define BH1750_PWR_ON        0x01
#define BH1750_CONT_HIGHRES  0x10          /* 1 lx resolution, ~120 ms */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_fp     = NULL;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  bh1750_init(int handle);
static int  bh1750_read_lux(int handle, float *lux_out);
static int  relay_set(int gpio, int on);
static int  log_event(const char *msg);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ------------------------------- BH1750 ---------------------------------- */
static int bh1750_init(int handle)
{
    /* Power on */
    if (i2cWriteByte(handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "[BH1750] Failed to power on sensor.\n");
        return -1;
    }
    gpioDelay(10000);       /* 10 ms settle after power-on */

    /* Set continuous high-resolution mode (1 lx, ~120 ms conversion) */
    if (i2cWriteByte(handle, BH1750_CONT_HIGHRES) < 0) {
        fprintf(stderr, "[BH1750] Failed to set continuous high-res mode.\n");
        return -1;
    }
    gpioDelay(MODE_SETTLE_MS * 1000);  /* 180 ms for first conversion */
    return 0;
}

/*
 * Read lux from the BH1750.
 * Returns 0 on success and stores lux in *lux_out; -1 on error.
 */
static int bh1750_read_lux(int handle, float *lux_out)
{
    char buf[2];
    int  rc;

    /* Trigger a measurement (no wait, no interrupt) */
    rc = i2cWriteByte(handle, BH1750_CONT_HIGHRES);
    if (rc < 0) {
        fprintf(stderr, "[BH1750] Trigger write failed.\n");
        return -1;
    }

    /* Wait for the conversion to complete (~120 ms) */
    gpioDelay(120000);

    /* Read 2 bytes (MSB first) */
    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[BH1750] Read failed (rc=%d).\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------- Relay ----------------------------------- */
static int relay_set(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) < 0) {
        fprintf(stderr, "[Relay] gpioWrite(%d, %d) failed.\n", gpio, on);
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging ---------------------------------- */
static int log_event(const char *msg)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed.\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[Log] strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s: %s\n", ts, msg) < 0) {
        fprintf(stderr, "[Log] fprintf failed.\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[Log] fflush failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure relay is off before releasing GPIO */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed.\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (relay_set(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise relay state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at BH1750 address */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (bh1750_init(g_i2c_handle) < 0) {
        fprintf(stderr, "BH1750 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write a session header */
    if (log_event("Session started") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;   /* 0 = off, 1 = on */
    int relay_active = 0;  /* 0 = dusk, 1 = dawn */

    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Lux = %.2f, Relay = %s",
                     lux, relay_state ? "ON" : "OFF");
            if (log_event(msg) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            /* Dusk: activate relay below threshold */
            if (lux < LUX_THRESHOLD_DUSK && !relay_active) {
                if (relay_set(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                    relay_active = 1;
                    log_event("Relay activated (dusk)");
                }
            }
            /* Dawn: deactivate relay above threshold */
            else if (lux > LUX_THRESHOLD_DAWN && relay_active) {
                if (relay_set(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                    relay_active = 0;
                    log_event("Relay deactivated (dawn)");
                }
            }
        } else {
            /* Sensor read failure: log and ensure relay is off */
            fprintf(stderr, "Sensor read failed; turning relay off.\n");
            if (relay_set(RELAY_GPIO, 0) == 0) {
                relay_state = 0;
                relay_active = 0;
                log_event("Relay forced off (sensor error)");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* Graceful shutdown */
    log_event("Session ended");
    cleanup();
    return EXIT_SUCCESS;
}

