                TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (ret=%d)\n",
                RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialise relay state (ret=%d)\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(relay_state);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor (ret=%d)\n", touch_state);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int confirmed = gpioRead(TOUCH_SENSOR_PIN);
            if (confirmed < 0) {
                fprintf(stderr, "Error: failed to read touch sensor during debounce (ret=%d)\n", confirmed);
                break;
            }

            if (confirmed == 1) {
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write relay (ret=%d)\n", ret);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

