#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN    27
#define LOG_FILE        "water_flow.log"
#define DEBOUNCE_US     1000000  /* 1 second debounce */
#define SAMPLE_INTERVAL 1        /* seconds between readings */
#define FLOW_THRESHOLD_HIGH 5.0f
#define FLOW_THRESHOLD_LOW  4.5f

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static pthread_mutex_t g_pulse_mutex;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only set a flag                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: pigpio dispatches this on the flow sensor pin edge              */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&g_pulse_mutex);
    g_pulse_count++;
    pthread_mutex_unlock(&g_pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — pigpio dispatches on the main thread         */
/* ------------------------------------------------------------------ */
static void alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    /* Debounce: ignore pulses that arrive within DEBOUNCE_US of the last */
    static uint32_t last_tick = 0;
    static int      last_level = -1;
    uint32_t now = tick;

    if (last_level == level && (now - last_tick) < DEBOUNCE_US) {
        return;
    }
    last_level = level;
    last_tick  = now;

    pthread_mutex_lock(&g_pulse_mutex);
    g_pulse_count++;
    pthread_mutex_unlock(&g_pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* Convert pulse count (per second) to LPM                            */
/* ------------------------------------------------------------------ */
static float pulses_to_lpm(int pulses)
{
    return (float)pulses / 60.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a timestamp                                      */
/* ------------------------------------------------------------------ */
static void log_reading(float lpm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, LPM: %.2f\n", ts, lpm);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Log a state change event                                            */
/* ------------------------------------------------------------------ */
static void log_state_change(int solenoid_state)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, Solenoid: %s\n", ts,
            solenoid_state ? "OPEN" : "CLOSED");
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup_resources(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    pthread_mutex_destroy(&g_pulse_mutex);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize mutex ---- */
    if (pthread_mutex_init(&g_pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        pthread_mutex_destroy(&g_pulse_mutex);
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        pthread_mutex_destroy(&g_pulse_mutex);
        return EXIT_FAILURE;
    }

    /* ---- Configure flow sensor pin ---- */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", FLOW_SENSOR_PIN);
        cleanup_resources();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the pin reads LOW when sensor is idle */
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed for pin %d\n", FLOW_SENSOR_PIN);
    }

    /* Register ISR on both edges (pigpio dispatches on the main thread) */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, EITHER_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for pin %d\n", FLOW_SENSOR_PIN);
        cleanup_resources();
        return EXIT_FAILURE;
    }

    /* ---- Configure solenoid pin ---- */
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for solenoid pin %d\n", SOLENOID_PIN);
        cleanup_resources();
        return EXIT_FAILURE;
    }

    /* Start with solenoid open (HIGH) */
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to set solenoid HIGH\n");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup_resources();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started.  Flow sensor on GPIO %d, solenoid on GPIO %d.\n",
           FLOW_SENSOR_PIN, SOLENOID_PIN);
    printf("Threshold HIGH: %.1f LPM, LOW: %.1f LPM.  Press Ctrl+C to exit.\n",
           FLOW_THRESHOLD_HIGH, FLOW_THRESHOLD_LOW);

    /* ---- Main loop ---- */
    int solenoid_state = 1;  /* 1 = open (HIGH) */
    int last_solenoid_state = solenoid_state;

    while (g_running) {
        sleep(SAMPLE_INTERVAL);

        pthread_mutex_lock(&g_pulse_mutex);
        int pulses = g_pulse_count;
        g_pulse_count = 0;
        pthread_mutex_unlock(&g_pulse_mutex);

        float lpm = pulses_to_lpm(pulses);

        log_reading(lpm);

        /* Hysteresis control */
        if (lpm > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_PIN, 0) == 0) {
                solenoid_state = 0;
                log_state_change(solenoid_state);
            } else {
                fprintf(stderr, "Error: gpioWrite failed to close solenoid\n");
            }
        } else if (lpm < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                solenoid_state = 1;
                log_state_change(solenoid_state);
            } else {
                fprintf(stderr, "Error: gpioWrite failed to open solenoid\n");
            }
        }

        if (solenoid_state != last_solenoid_state) {
            last_solenoid_state = solenoid_state;
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Ensure solenoid is open (safe state) */
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to set solenoid open during shutdown\n");
    }

    cleanup_resources();
    printf("Water flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

