#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define TCP_PORT 12345
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DISPENSE_DELAY_US 1000000
#define HX711_TIMEOUT 1000
#define HX711_SETTLE_US 1000
#define HX711_SETTLE_MS 1

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = 1.0;
static double known_weight = 0.0;
static double actual_weight = 0.0;
static double target_weight = 0.0;
static int api_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) {
        shutdown(client_fd, SHUT_RDWR);
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (api_handle >= 0) {
        close(api_handle);
        api_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s\n", CONFIG_FILE, strerror(errno));
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "known_weight") == 0) {
            known_weight = atof(value);
        }
    }
    fclose(fp);
    printf("Config: calibration_factor=%.2f, known_weight=%.2f\n", calibration_factor, known_weight);
    return 0;
}

static int read_hx711(int *out) {
    int count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++count > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout (sensor absent or not ready)\n");
            return -1;
        }
        gpioDelay(1);
    }
    int value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) value |= 1;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    value ^= 0x800000;
    *out = value;
    return 0;
}

static double calibrate_hx711(int raw) {
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(double pulse_width_us) {
    if (pulse_width_us < 1000 || pulse_width_us > 2000) {
        fprintf(stderr, "Error: Invalid pulse width %.2f us\n", pulse_width_us);
        return -1;
    }
    if (gpioServo(SERVO_PIN, (int)pulse_width_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    return 0;
}

static int dispense(double target_weight) {
    if (api_handle < 0) {
        fprintf(stderr, "Error: API handle invalid\n");
        return -1;
    }
    if (gpioServo(SERVO_PIN, 1500) < 0) {
        fprintf(stderr, "Error: Failed to set servo to dispense position\n");
        return -1;
    }
    gpioDelay(DISPENSE_DELAY_US);
    if (gpioServo(SERVO_PIN, 1500) < 0) {
        fprintf(stderr, "Error: Failed to set servo to hold position\n");
        return -1;
    }
    gpioDelay(100000);
    int raw = 0;
    if (read_hx711(&raw) < 0) return -1;
    actual_weight = calibrate_hx711(raw);
    double pulse_width = 1500.0 + (target_weight - known_weight) * 100.0;
    if (set_servo_pulse(pulse_width) < 0) return -1;
    gpioDelay(DISPENSE_DELAY_US);
    if (gpioServo(SERVO_PIN, 1500) < 0) {
        fprintf(stderr, "Error: Failed to set servo to hold position\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int log_dispensing_event(double target, double actual, const char *error) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
