#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DEFAULT_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for relay pin %d\n", RELAY_PIN);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_DEFAULT_MS;
    int relay_state = 0;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 1000) {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return EXIT_FAILURE;
        }
        debounce_ms = (int)val;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Touch sensor monitoring started. Debounce: %d ms. Press Ctrl+C to exit.\n", debounce_ms);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1) {
            gpioDelay(debounce_ms * 1000);

            int touch_state_after = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_state_after < 0) {
                fprintf(stderr, "Error: gpioRead failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (touch_state_after == 1) {
                relay_state = !relay_state;
                if (set_relay(relay_state) == 0) {
                    log_relay_state(relay_state);
                }
            }
        }

        gpioDelay(10000);
    }

    set_relay(0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

