#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP_ANGLE 10
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse_width = (int)(((float)angle / (float)MAX_ANGLE) *
                            (float)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) +
                            (float)MIN_PULSE_WIDTH);

    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

    int rc = gpioServo(SERVO_PIN, pulse_width);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed (pin %d, pw %d): %s\n",
                SERVO_PIN, pulse_width, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int read_key(void)
{
    int ch = getchar();
    if (ch == EOF) return -1;
    return ch;
}

static void restore_terminal(void)
{
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) == 0) {
        tty.c_lflag |= (ICANON | ECHO);
        tty.c_cc[VMIN] = 1;
        tty.c_cc[VTIME] = 0;
        tcsetattr(STDIN_FILENO, TCSANOW, &tty);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(90) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) == 0) {
        tty.c_lflag &= ~(ICANON | ECHO);
        tty.c_cc[VMIN] = 0;
        tty.c_cc[VTIME] = 1;
        if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
            perror("tcsetattr");
        }
    }

    int angle = 90;
    printf("Servo angle: %d° (1500 µs)\n", angle);
    fflush(stdout);

    while (g_running) {
        int ch = read_key();
        if (ch == EOF) break;

        if (ch == '+') {
            angle += STEP_ANGLE;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
        } else if (ch == '-') {
            angle -= STEP_ANGLE;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
        } else if (ch == 'q') {
            break;
        }

        if (set_servo_angle(angle) != 0) {
            break;
        }
