/*
 * RPM monitor for a conveyor belt motor using an A3144 Hall-effect sensor.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - A3144 Hall-effect sensor on GPIO 17 (BCM 17, physical pin 11)
 *   - Two-pole magnet on the motor shaft
 *   - Internal pull-up enabled on the GPIO line
 *
 * Behavior:
 *   - Edge-triggered rising-edge counting (one pulse per revolution)
 *   - 2 ms debounce window to reject contact bounce and double-edge noise
 *   - RPM computed every 5 seconds using CLOCK_MONOTONIC
 *   - Log file updated every 5 seconds in CSV format: timestamp,RPM
 *   - Clean shutdown on SIGINT / SIGTERM
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define DEBOUNCE_US       2000   /* 2 ms debounce window */
#define SAMPLE_INTERVAL_S 5      /* seconds between RPM reports */
#define LOG_FILE          "motor_rpm.log"

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Return a heap-allocated ISO-8601 timestamp string.
 * Caller must free the result.
 */
static char *get_timestamp(void)
{
    time_t rawtime;
    struct tm tm_info;
    char *buf = malloc(32);
    if (!buf) {
        perror("malloc");
        return NULL;
    }

    time(&rawtime);
    if (!localtime_r(&rawtime, &tm_info)) {
        perror("localtime_r");
        free(buf);
        return NULL;
    }

    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(buf);
        return NULL;
    }
    return buf;
}

/*
 * Compute RPM from pulse count over a given interval.
 * Returns 0.0 on error or if no pulses were counted.
 */
static double calculate_rpm(unsigned long pulses, double interval_s)
{
    if (interval_s <= 0.0)
        return 0.0;

    /* One pulse per revolution => RPM = pulses / interval (seconds) */
    return (double)pulses / interval_s;
}

/*
 * Log RPM to file and stdout.
 * Returns 0 on success, -1 on failure.
 */
static int log_rpm(double rpm)
{
    char *ts = get_timestamp();
    if (!ts) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf log");
        free(ts);
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush log");
        free(ts);
        return -1;
    }

    printf("%s, RPM: %.2f\n", ts, rpm);
    free(ts);
    return 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */

static volatile unsigned long g_pulse_count = 0;
static volatile uint32_t      g_last_tick    = 0;

/*
 * pigpio alert callback: fires on every edge of the GPIO line.
 * We count rising edges and apply a 2 ms debounce window.
 */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 1)            /* only rising edges */
        return;

    /* Debounce: ignore pulses within DEBOUNCE_US of the last accepted one */
    uint32_t elapsed = tick - g_last_tick;
    if (elapsed < DEBOUNCE_US)
        return;
    g_last_tick = tick;

    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO 17 as input with internal pull-up ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for rising-edge detection ---- */
    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,RPM\n");
        fflush(g_log_fp);
    }

    printf("Monitoring RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* ---- Main loop ---- */
    time_t last_report_time = time(NULL);

    while (g_running) {
        sleep(SAMPLE_INTERVAL_S);

        if (!g_running)
            break;

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            continue;
        }

        /* RPM for this 5-second window */
        double rpm = calculate_rpm(g_pulse_count, (double)(now - last_report_time));
        g_pulse_count = 0;   /* reset for next interval */

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        last_report_time = now;
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Disable callback before tearing down */
    gpioSetAlertFunc(GPIO_PIN, NULL);

    if (g_log_fp) {
        if (fclose(g_log_fp) != 0)
            perror("fclose log");
        g_log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

