#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000
#define RELAY_HOLD_TIMEOUT_S 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay pin %d to OFF\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

static int read_touch_sensor(void) {
    return gpioRead(TOUCH_SENSOR_PIN);
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: failed to write relay pin %d\n", RELAY_PIN);
        return -1;
    }
    return 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch_state = 0;
    time_t touch_start_time = 0;
    int pigpio_initialized = 1;

    while (program_running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            log_error("Failed to read touch sensor pin");
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            touch_start_time = time(NULL);
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                log_error("Failed to control relay");
                break;
            }
        } else if (touch_state == 1 && last_touch_state == 1) {
            if (difftime(time(NULL), touch_start_time) >= RELAY_HOLD_TIMEOUT_S) {
                relay_state = 0;
                if (control_relay(relay_state) != 0) {
                    log_error("Failed to control relay");
                    break;
                }
            }
        }

        last_touch_state = touch_state;
        usleep(POLL_INTERVAL_US);
    }

    if (pigpio_initialized) {
        cleanup_gpio();
    }
    return EXIT_SUCCESS;
}

