#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define PWM_FREQUENCY      1000
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

#define LOG_FILE_NAME      "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_flow_count = 0;
static FILE                 *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit and clean up.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: increment the pulse-count on every rising edge of the sensor. */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_flow_count++;
}

/* ------------------------------------------------------------------ */
/* Compute a proportional PWM duty cycle from the current flow rate.  */
/* Returns a value in [0, PWM_RANGE].                                  */
/* ------------------------------------------------------------------ */
static int compute_pwm_duty(float target_flow, float current_flow)
{
    float error = target_flow - current_flow;
    float duty  = error * 1.0f;          /* Kp = 1.0 */

    if (duty < 0.0f)   duty = 0.0f;
    if (duty > (float)PWM_RANGE) duty = (float)PWM_RANGE;

    return (int)duty;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row: timestamp_ms,flow_rate,valve_position.            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

    if (fprintf(fp, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
    }
    if (fflush(fp) != 0) {
        perror("fflush");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call from any exit path.                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure valve is off before releasing resources. */
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioPWM(0) failed during cleanup\n");
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(enable,0) failed during cleanup\n");
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L/min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *target_str = argv[1];
    if (strcmp(target_str, "-t") == 0) {
        fprintf(stderr, "Error: target_flow_rate must follow -t\n");
        return EXIT_FAILURE;
    }

    float target_flow_rate = strtof(target_str, NULL);
    if (target_flow_rate <= 0.0f) {
        fprintf(stderr, "Error: target_flow_rate must be positive\n");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure valve enable pin (active-high) ---- */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(enable, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(enable, 1) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure valve PWM pin ---- */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(pwm, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure flow sensor pin with interrupt on rising edge ---- */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(sensor, INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0,
                         flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_L/min,valve_position\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        /* Snapshot and reset the pulse count. */
        uint32_t count = g_flow_count;
        g_flow_count   = 0;

        /* Flow rate in L/min (1 pulse = 1 L/min). */
        float current_flow_rate = (float)count;

        /* Proportional controller. */
        int pwm_duty = compute_pwm_duty(target_flow_rate, current_flow_rate);

        /* Apply PWM to the valve. */
        if (gpioPWM(VALVE_PWM_PIN, pwm_duty) < 0) {
            fprintf(stderr, "Warning: gpioPWM(%d) failed\n", pwm_duty);
        }

        /* Log this iteration. */
        log_data(g_log_file, current_flow_rate, pwm_duty);

        /* Sleep for the sample interval. */
        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

