#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define LOG_FILE "/var/log/door_access.log"
#define RFID_READER_SPI_CHANNEL 0
#define RFID_READER_SPI_SPEED 100000
#define RFID_READER_SPI_FLAGS 0
#define RFID_READER_READ_TIMEOUT_MS 100
#define RFID_READER_READ_RETRIES 4
#define RFID_READER_READ_DELAY_MS 10
#define RFID_READER_READ_MIN_MS 100
#define RFID_READER_READ_MAX_MS 500
#define RFID_READER_READ_MIN_BYTES 10
#define RFID_READER_READ_MAX_BYTES 10
#define RFID_READER_READ_EXPECTED_BYTES 10
#define RFID_READER_READ_EXPECTED_VALUE 0x00
#define LOCK_DISENGAGE_DELAY_MS 5000
#define BUTTON_DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LOCK_2_GPIO);
        return -1;
    }
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_GPIO);
        return -1;
    }

    if (gpioWrite(LOCK_1_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", LOCK_1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK_2_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", LOCK_2_GPIO);
        return -1;
    }

    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(RFID_READER_SPI_CHANNEL, RFID_READER_SPI_SPEED, RFID_READER_SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_rfid_reader(unsigned char *data, int *data_len) {
    int bytes_read = 0;
    int retries = RFID_READER_READ_RETRIES;
    int delay_ms = RFID_READER_READ_DELAY_MS;

    while (retries > 0 && bytes_read < RFID_READER_READ_EXPECTED_BYTES) {
        bytes_read = spiRead(spi_handle, (char *)data, RFID_READER_READ_EXPECTED_BYTES);
        if (bytes_read < 0) {
            fprintf(stderr, "SPI read error: %s\n", pigpio_error(bytes_read));
            retries--;
            if (retries > 0) {
                gpioDelay(delay_ms * 1000);
                delay_ms = (delay_ms * 2 < RFID_READER_READ_MAX_MS) ? delay_ms * 2 : RFID_READER_READ_MAX_MS;
            }
        } else if (bytes_read == 0) {
            retries--;
            if (retries > 0) {
                gpioDelay(delay_ms * 1000);
                delay_ms = (delay_ms * 2 < RFID_READER_READ_MAX_MS) ? delay_ms * 2 : RFID_READER_READ_MAX_MS;
            }
        } else if (bytes_read < RFID_READER_READ_EXPECTED_BYTES) {
            retries--;
            if (retries > 0) {
                gpioDelay(delay_ms * 1000);
                delay_ms = (delay_ms * 2 < RFID_READER_READ_MAX_MS) ? delay_ms * 2 : RFID_READER_READ_MAX_MS;
            }
        } else {
            if (data[0] == RFID_READER_READ_EXPECTED_VALUE) {
                *data_len = bytes_read;
                return 0;
            }
            retries--;
            if (retries > 0) {
                gpioDelay(delay_ms * 1000);
                delay_ms = (delay_ms * 2 < RFID_READER_READ_MAX_MS) ? delay_ms * 2 : RFID_READER_READ_MAX_MS;
            }
        }
    }

    fprintf(stderr, "RFID read failed after %d retries\n", RFID_READER_READ_RETRIES);
    return -1;
}

static int verify_rfid_data(const unsigned char *data, int data_len) {
    if (data_len < RFID_READER_READ_EXPECTED_BYTES) {
        fprintf(stderr, "RFID data too short: %d bytes\n", data_len);
        return -1;
    }

    for (int i = 0; i < RFID_READER_READ_EXPECTED_BYTES; i++) {
        if (data[i] != RFID_READER_READ_EXPECTED_VALUE) {
            fprintf(stderr, "RFID data mismatch at byte %d: expected 0x%02X, got 0x%02X\n",
                    i, RFID_READER_READ_EXPECTED_VALUE, data[i]);
            return -1;
        }
    }

    return 0;
}

static int engage_lock(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

static int disengage_lock(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

static int log_access(const char *event, const unsigned char *data, int data_len) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - %s - %s\n", timestamp, event, data ? "valid tag" : "invalid tag") < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK_1_GPIO, 1);
    gpioWrite(LOCK_2_GPIO, 1);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    unsigned char rfid_data[RFID_READER_READ_EXPECTED_BYTES];
    int rfid_data_len = 0;
    int button_pressed = 0;
