    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (button_debounce_active) {
            button_debounce_timer += POLL_INTERVAL_MS;
            if (button_debounce_timer >= BUTTON_DEBOUNCE_MS) {
                button_debounce_active = 0;
                button_debounce_timer = 0;
            }
            continue;
        }

        int button_state = gpioRead(BUTTON_GPIO);
