static encoder_state_t g_enc1 = {0, 0, 0};
static encoder_state_t g_enc2 = {0, 0, 0};

/* ---- Motor control ---- */
static void motor_set(int en, int in1, int in2, int speed) {
    int duty = (speed < 0) ? 0 : speed;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(en, duty) < 0) {
        fprintf(stderr, "gpioPWM(en=%d) failed\n", en);
        return;
    }
    if (duty > 0) {
        if (gpioWrite(in1, 1) < 0) fprintf(stderr, "gpioWrite(in1) failed\n");
        if (gpioWrite(in2, 0) < 0) fprintf(stderr, "gpioWrite(in2) failed\n");
    } else {
        if (gpioWrite(in1, 0) < 0) fprintf(stderr, "gpioWrite(in1) failed\n");
        if (gpioWrite(in2, 0) < 0) fprintf(stderr, "gpioWrite(in2) failed\n");
    }
}

/* ---- PID ---- */
static double pid_update(double setpoint, double actual, double *integral,
                          double *prev_error) {
    double error = setpoint - actual;
    *integral += error;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    double deriv = error - *prev_error;
    double output = KP * error + KI * (*integral) + KD * deriv;
    *prev_error = error;
    return output;
}

/* ---- Encoder thread ---- */
static void *encoder_thread(void *arg) {
    int a_pin = *(int *)arg;
    int b_pin = a_pin + 1;
    int last_a = gpioRead(a_pin);
    int last_b = gpioRead(b_pin);
    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "gpioRead init failed on pin %d\n", a_pin);
        return NULL;
    }
    while (g_running) {
        int a = gpioRead(a_pin);
        int b = gpioRead(b_pin);
        if (a < 0 || b < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", a_pin);
            continue;
        }
        pthread_mutex_lock(&g_enc_mutex);
        if (a != last_a) {
            if (a == b) {
                g_enc1.count++;
            } else {
                g_enc1.count--;
            }
        }
        if (b != last_b) {
            if (b == a) {
                g_enc2.count++;
            } else {
                g_enc2.count--;
            }
        }
        last_a = a;
        last_b = b;
        pthread_mutex_unlock(&g_enc_mutex);
        gpioDelay(1000); /* 1 ms */
    }
    return NULL;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    motor_set(MOTOR1_ENA, 0, 0, 0);
    motor_set(MOTOR2_ENB, 0, 0, 0);
    gpioTerminate();
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Motor control pins */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode motor failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    motor_set(MOTOR1_ENA, 0, 0, 0);
    motor_set(MOTOR2_ENB, 0, 0, 0);

    /* Encoder pins */
    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode encoder failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Encoder A pins: both edges, B pin reads direction */
    if (gpioSetAlertFuncEx(ENCODER1_A, NULL, NULL) < 0 ||
        gpioSetAlertFuncEx(ENCODER2_A, NULL, NULL)) {
        fprintf(stderr, "gpioSetAlertFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetEdgeDetection(ENCODER1_A, EITHER_EDGE) < 0 ||
        gpioSetEdgeDetection(ENCODER2_A, EITHER_EDGE) < 0) {
        fprintf(stderr, "gpioSetEdgeDetection failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Software PWM */
    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Log file */
    g_log = fopen("motor_log.csv", "w");
    if (!g_log) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log, "timestamp,motor1_rpm,motor2_rpm,pid_p,pid_i,pid_d,pid_output\n");
    fflush(g_log);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Encoder threads */
    pthread_t enc1, enc2;
    int a_pins[2] = {ENCODER1_A, ENCODER2_A};
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&enc1, NULL, encoder_thread, &a_pins[i]) != 0) {
            fprintf(stderr, "pthread_create failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }
    pthread_join(enc1, NULL);
    pthread_join(enc2, NULL);

    /* PID state */
    double integral = 0.0;
    double prev_error = 0.0;

    /* Main control loop */
    while (g_running) {
        pthread_mutex_lock(&g_enc_mutex);
        long enc1_count = g_enc1.count;
        long enc2_count = g_enc2.count;
        g_enc1.count = 0;
        g_enc2.count = 0;
        pthread_mutex_unlock(&g_enc_mutex);

        /* RPM = (counts / 60) * (1000000 / 60) = counts * 16666.67 / 60 */
        double rpm1 = (double)enc1_count * 16666.67 / 60.0;
        double rpm2 = (double)enc2_count * 16666.67 / 60.0;

        double pid_out = pid_update(TARGET_RPM, rpm1, &integral, &prev_error);
        int speed1 = (int)pid_out;
        int speed2 = (int)pid_out;

        motor_set(MOTOR1_ENA, 0, 0, speed1);
        motor_set(MOTOR2_ENB, 0, 0, speed2);

        time_t now = time(NULL);
        fprintf(g_log, "%ld,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                (long)now, rpm1, rpm2, KP * rpm1, KI * integral, KD * (rpm1 - prev_error), pid_out);
        fflush(g_log);

        gpioDelay(SAMPLE_TIME_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

