#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5E
#define RELAY_GPIO 17
#define STABILIZATION_DELAY_MS 100
#define POLL_DELAY_MS 100

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_ELECTRODE_FILTER 0x5D
#define MPR121_ELECTRODE_CHARGE_TIME 0x5C
#define MPR121_ELECTRODE_CURRENT 0x5B
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpr121_init(void) {
    uint8_t soft_reset = 0x63;
    if (mpr121_write_reg(MPR121_SOFTRESET, soft_reset) < 0) {
        return -1;
    }
    usleep(10000);

    /* Stop mode: set ELE_CONFIG to 0x00 */
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        return -1;
    }

    /* Configure filter and charge time for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_ELECTRODE_FILTER + i, 0x01) < 0) {
            return -1;
        }
        if (mpr121_write_reg(MPR121_ELECTRODE_CHARGE_TIME + i, 0x01) < 0) {
            return -1;
        }
    }

    /* Set touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_TOUCH_THRESHOLD + i * 2, 0x0C) < 0) {
            return -1;
        }
        if (mpr121_write_reg(MPR121_RELEASE_THRESHOLD + i * 2, 0x06) < 0) {
            return -1;
        }
    }

    /* Set electrode current to 0x0F */
    if (mpr121_write_reg(MPR121_ELECTRODE_CURRENT, 0x0F) < 0) {
        return -1;
    }

    /* Enable all 12 electrodes in run mode: ELE_CONFIG = 0x0C */
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        return -1;
    }

    usleep(STABILIZATION_DELAY_MS * 1000);
    return 0;
}

static int read_touch_status(uint16_t *status) {
    uint8_t low, high;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0) {
        return -1;
    }
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0) {
        return -1;
    }
    *status = ((uint16_t)high << 8) | low;
    return 0;
}

static void toggle_relay(void) {
    static bool relay_state = false;
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
        return;
    }
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        if (touch_status > 0) {
            toggle_relay();
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

