#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

typedef struct {
    int duty1;
    int duty2;
    int duration_ms;
} MotorStep;

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_motor_duty(int pin, int duty) {
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", pin);
    }
}

static void stop_motors(void) {
    set_motor_duty(MOTOR1_PIN, 0);
    set_motor_duty(MOTOR2_PIN, 0);
}

static MotorStep *generate_pattern(int *pattern_length) {
    int length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    MotorStep *pattern = (MotorStep *)malloc(length * sizeof(MotorStep));
    if (pattern == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern\n");
        *pattern_length = 0;
        return NULL;
    }

    for (int i = 0; i < length; i++) {
        pattern[i].duty1 = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        pattern[i].duty2 = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        pattern[i].duration_ms = (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1)) + MIN_STEP_DURATION_MS;
    }

    *pattern_length = length;
    return pattern;
}

static void play_pattern(const MotorStep *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length && !shutdown_requested; i++) {
        set_motor_duty(MOTOR1_PIN, pattern[i].duty1);
        set_motor_duty(MOTOR2_PIN, pattern[i].duty2);
        gpioDelay(pattern[i].duration_ms * 1000);
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    while (!shutdown_requested) {
        int pattern_length = 0;
        MotorStep *pattern = generate_pattern(&pattern_length);

        if (pattern != NULL) {
            play_pattern(pattern, pattern_length);
            free(pattern);
        } else {
            fprintf(stderr, "Warning: pattern generation failed, retrying...\n");
        }

        if (!shutdown_requested) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    stop_motors();
    gpioTerminate();
    return EXIT_SUCCESS;
}

