#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define DEFAULT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;
static double threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= HX711_TIMEOUT_US) {
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    return value;
}

static double calculate_weight(int raw_value) {
    return ((double)raw_value - offset) / scale_factor;
}

static int load_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Could not read calibration data from '%s'. Using defaults.\n", CALIBRATION_FILE);
        scale_factor = DEFAULT_SCALE_FACTOR;
        offset = DEFAULT_OFFSET;
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int save_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file '%s' for writing.\n", CALIBRATION_FILE);
        return -1;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration saved: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int calibrate_scale(void) {
    int raw_value;
    double sum = 0.0;
    int valid_readings = 0;

    printf("Calibrating scale... Please ensure no weight is on the load cell.\n");
    gpioDelay(2000000);

    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Warning: HX711 read timeout during calibration.\n");
            continue;
        }
        sum += (double)raw_value;
        valid_readings++;
        gpioDelay(10000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid HX711 readings during calibration.\n");
        return -1;
    }

    offset = sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static void log_weight(double weight) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open weight log file '%s'.\n", WEIGHT_LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (load_calibration_data() != 0) {
        if (calibrate_scale() != 0) {
            fprintf(stderr, "Error: Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration_data();
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read timeout. Skipping iteration.\n");
            gpioDelay(500000);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > threshold) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight threshold exceeded! Solenoid engaged.\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        log_weight(weight);
        gpioDelay(500000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Weight monitoring stopped.\n");
    return 0;
}

