#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define THRESHOLD 100.0
#define LOCK_DURATION 5
#define POLL_INTERVAL 1
#define HX711_TIMEOUT_US 1000000
#define LOG_FILE "stock_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static int hx711_read_raw(int *out) {
    if (gpioSetMode(DT_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(SCK_PIN, PI_OUTPUT) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(DT_PIN) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) return -2;
        gpioDelay(100);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(SCK_PIN, 1) < 0) return -3;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(DT_PIN)) value |= 1;
        if (gpioWrite(SCK_PIN, 0) < 0) return -3;
        gpioDelay(1);
    }

    if (gpioWrite(SCK_PIN, 1) < 0) return -3;
    gpioDelay(1);
    if (gpioWrite(SCK_PIN, 0) < 0) return -3;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;
    *out = value;
    return 0;
}

static double hx711_read_weight(int gain) {
    int raw;
    if (hx711_read_raw(&raw) != 0) return -1.0;
    return (double)raw / 1000.0;
}

static void activate_lock(int duration) {
    if (gpioWrite(LOCK_PIN, 1) < 0) {
        log_event("ERROR: Failed to activate lock");
        return;
    }
    log_event("Lock activated");
    sleep(duration);
    if (gpioWrite(LOCK_PIN, 0) < 0) {
        log_event("ERROR: Failed to deactivate lock");
        return;
    }
    log_event("Lock deactivated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LOCK_PIN, PI_OUTPUT) < 0) {
        log_event("ERROR: Failed to set lock pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(LOCK_PIN, 0) < 0) {
        log_event("ERROR: Failed to initialize lock pin state");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    while (running) {
        double weight = hx711_read_weight(128);
        if (weight < 0) {
            log_event("ERROR: HX711 read failed");
        } else {
            char buf[128];
            snprintf(buf, sizeof(buf), "Weight: %.2f g", weight);
            log_event(buf);
            if (weight < THRESHOLD) {
                activate_lock(LOCK_DURATION);
            }
        }
        sleep(POLL_INTERVAL);
    }

    gpioWrite(LOCK_PIN, 0);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

