#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN      4
#define HX711_CLOCK_PIN     17
#define SOLENOID_PIN        27

#define WEIGHT_THRESHOLD    5.0f
#define CALIBRATION_FILE    "calibration.txt"
#define LOG_FILE            "security.log"
#define SAMPLE_INTERVAL_US  100000
#define HX711_TIMEOUT_US    100000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_hx711(int data_pin, int clock_pin, int32_t *out)
{
    uint32_t elapsed = 0;
    while (gpioRead(data_pin) == 1) {
        if (elapsed >= HX711_TIMEOUT_US) {
            return -1;
        }
        gpioDelay(100);
        elapsed += 100;
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin)) {
            value |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    int32_t sign = 1;
    if (value & 0x800000) {
        sign = -1;
        value ^= 0x7FFFFF;
    }

    *out = (int32_t)value * sign;
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, float *calibration_factor)
{
    float sum = 0.0f;
    int valid_samples = 0;

    printf("Place a known weight on the load cell and press Enter.\n");
    fflush(stdout);
    while (getchar() != '\n');

    for (int i = 0; i < 10; i++) {
        int32_t raw;
        if (read_hx711(data_pin, clock_pin, &raw) != 0) {
            fprintf(stderr, "HX711 read timeout during calibration.\n");
            return -1;
        }
        sum += (float)raw;
        valid_samples++;
        gpioDelay(100000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "Calibration failed: no valid samples.\n");
        return -1;
    }

    *calibration_factor = sum / valid_samples;
    printf("Calibration factor: %.2f\n", *calibration_factor);
    return 0;
}

static int log_event(float weight)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed.\n");
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(g_log_fp, "%s, Weight: %.2f kg\n", ts, weight) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(SOLENOID_PIN, 0);

    float calibration_factor = 0.0f;
    bool calibrated = false;

    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%f", &calibration_factor) == 1) {
            calibrated = true;
            printf("Calibration factor loaded: %.2f\n", calibration_factor);
        } else {
            fprintf(stderr, "Invalid calibration file. Re-calibrating...\n");
            fclose(fp);
        }
    } else {
        fprintf(stderr, "Calibration file not found. Re-calibrating...\n");
    }

    if (!calibrated) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &calibration_factor) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fp = fopen(CALIBRATION_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open calibration file for writing.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fprintf(fp, "%.2f\n", calibration_factor);
        fclose(fp);
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int32_t raw;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw) != 0) {
            fprintf(stderr, "HX711 read timeout. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float weight = (float)raw / calibration_factor;

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Engaging solenoid.\n");
            gpioWrite(SOLENOID_PIN, 1);
            gpioDelay(5000000);
            gpioWrite(SOLENOID_PIN, 0);
            printf("Solenoid released.\n");

            if (log_event(weight) != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }

    return EXIT_SUCCESS;
}

