#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN  20
#define LOG_FILE   "relay_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Relay is now %s\n", ts, relay_state ? "ON" : "OFF") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state on GPIO%d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_sensor = -1;

    while (running) {
        int sensor = gpioRead(SENSOR_PIN);
        if (sensor < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", SENSOR_PIN);
            break;
        }

        if (sensor != last_sensor) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO%d\n", RELAY_PIN);
                break;
            }

            if (log_event(relay_state) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }

            last_sensor = sensor;
        }

        usleep(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

