#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define DEFAULT_DURATION 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int read_watering_duration(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: configuration file is empty.\n");
        } else {
            fprintf(stderr, "Error reading configuration file: %s\n",
                    strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long val = strtol(line, &endptr, 10);
    if (endptr == line) {
        fprintf(stderr, "Error: configuration file contains no valid integer.\n");
        return -1;
    }
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error: configuration file contains trailing characters.\n");
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: watering duration %ld out of range [%d, %d].\n",
                val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

static int sleep_interruptible(unsigned int seconds)
{
    unsigned int remaining = seconds;
    while (remaining > 0 && g_running) {
        remaining = sleep(remaining);
    }
    return (g_running) ? 0 : -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error: failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    int duration = DEFAULT_DURATION;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        goto cleanup;
    }

    printf("Watering system started. Duration: %d seconds.\n", duration);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to activate valve: %s\n",
                strerror(errno));
        goto cleanup;
    }
    printf("Valve activated.\n");
    fflush(stdout);

    if (sleep_interruptible((unsigned int)duration) != 0) {
        if (!g_running) {
            printf("Watering interrupted by signal.\n");
        } else {
            fprintf(stderr, "Error: watering duration exceeded.\n");
        }
        goto cleanup;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to deactivate valve: %s\n",
                strerror(errno));
        goto cleanup;
    }
    printf("Valve deactivated.\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

