#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_LEFT_PIN    4
#define SENSOR_MID_PIN     17
#define SENSOR_RIGHT_PIN   27

#define MOTOR_LEFT_PWM_PIN  22
#define MOTOR_RIGHT_PWM_PIN 23

#define MOTOR_LEFT_DIR_PIN  24
#define MOTOR_RIGHT_DIR_PIN 25

/* ---- Control parameters ---- */
#define BASE_SPEED          150          /* 0–255 */
#define PWM_FREQUENCY       1000         /* Hz */
#define PWM_RANGE           255
#define SAMPLE_PERIOD_US    10000        /* 10 ms */
#define LOG_FILE_NAME       "trace_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static void motor_set_direction(int left_dir, int right_dir)
{
    if (gpioWrite(MOTOR_LEFT_DIR_PIN, left_dir) < 0)
        fprintf(stderr, "Warning: gpioWrite(MOTOR_LEFT_DIR_PIN) failed\n");
    if (gpioWrite(MOTOR_RIGHT_DIR_PIN, right_dir) < 0)
        fprintf(stderr, "Warning: gpioWrite(MOTOR_RIGHT_DIR_PIN) failed\n");
}

static void motor_set_speed(int left_speed, int right_speed)
{
    if (gpioPWM(MOTOR_LEFT_PWM_PIN, left_speed) < 0)
        fprintf(stderr, "Warning: gpioPWM(MOTOR_LEFT_PWM_PIN) failed\n");
    if (gpioPWM(MOTOR_RIGHT_PWM_PIN, right_speed) < 0)
        fprintf(stderr, "Warning: gpioPWM(MOTOR_RIGHT_PWM_PIN) failed\n");
}

static void motor_stop(void)
{
    motor_set_direction(0, 0);
    motor_set_speed(0, 0);
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Keywish 3-Way IR Tracking Sensor: the active-low digital output
 * reads 0 when the sensor detects a line and 1 when it does not.
 * We invert the raw value to get a 0 = line detected, 1 = no line.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Warning: gpioRead(%d) failed\n", pin);
        return 1;                       /* default to no-line */
    }
    return (v == 0) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
/* Control logic                                                       */
/* ------------------------------------------------------------------ */
static void control(int left, int mid, int right,
                    int *left_speed, int *right_speed)
{
    if (mid == 0) {                    /* line detected in centre */
        *left_speed  = BASE_SPEED;
        *right_speed = BASE_SPEED;
    } else if (left == 1 && right == 0) {
        *left_speed  = BASE_SPEED / 2;
        *right_speed = BASE_SPEED;
    } else if (left == 0 && right == 1) {
        *left_speed  = BASE_SPEED;
        *right_speed = BASE_SPEED / 2;
    } else {
        *left_speed  = 0;
        *right_speed = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int left, int mid, int right,
                     int left_speed, int right_speed)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
            ts, left, mid, right, left_speed, right_speed);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int left, mid, right;
    int left_speed, right_speed;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_LEFT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_LEFT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_MID_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_MID_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_RIGHT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor PWM pins as outputs ---- */
    if (gpioSetMode(MOTOR_LEFT_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_LEFT_PWM_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_RIGHT_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_RIGHT_PWM_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor direction pins as outputs ---- */
    if (gpioSetMode(MOTOR_LEFT_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_LEFT_DIR_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_RIGHT_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(MOTOR_RIGHT_DIR_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,left,mid,right,left_speed,right_speed\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main control loop ---- */
    while (g_running) {
        left   = read_sensor(SENSOR_LEFT_PIN);
        mid    = read_sensor(SENSOR_MID_PIN);
        right  = read_sensor(SENSOR_RIGHT_PIN);

        control(left, mid, right, &left_speed, &right_speed);

        motor_set_speed(left_speed, right_speed);
        log_data(left, mid, right, left_speed, right_speed);

        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    motor_stop();
    cleanup();
    return EXIT_SUCCESS;
}

