#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

static int read_bh1750(int handle, uint16_t *lux) {
    if (handle < 0) return -1;
    if (i2cWriteByte(handle, 0x10) < 0) return -1;
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *lux = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("ERROR: gpioWrite failed");
        return;
    }
    log_event(state ? "Relay ON" : "Relay OFF");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (running) {
        uint16_t lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %u", lux);
            log_event(msg);
            control_relay(RELAY_GPIO, lux < LUX_THRESHOLD ? 1 : 0);
        } else {
            log_event("ERROR: BH1750 read failed");
        }
        gpioDelay(1000000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

