#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY_US 100000
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulsewidth(int pin, int pulsewidth) {
    if (pulsewidth < SERVO_MIN_PULSEWIDTH || pulsewidth > SERVO_MAX_PULSEWIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulsewidth, SERVO_MIN_PULSEWIDTH, SERVO_MAX_PULSEWIDTH);
        return -1;
    }
    if (gpioServo(pin, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_button(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return val;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_val = read_button(LOCK_BUTTON_PIN);
        if (lock_val < 0) {
            break;
        }
        if (lock_val == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            lock_val = read_button(LOCK_BUTTON_PIN);
            if (lock_val == 0) {
                if (set_servo_pulsewidth(SERVO_PIN, SERVO_MIN_PULSEWIDTH) == 0) {
                    printf("Locking door...\n");
                }
                while (running) {
                    int unlock_val = read_button(UNLOCK_BUTTON_PIN);
                    if (unlock_val < 0) {
                        break;
                    }
                    if (unlock_val == 0) {
                        gpioDelay(DEBOUNCE_DELAY_US);
                        unlock_val = read_button(UNLOCK_BUTTON_PIN);
                        if (unlock_val == 0) {
                            if (set_servo_pulsewidth(SERVO_PIN, SERVO_MAX_PULSEWIDTH) == 0) {
                                printf("Unlocking door...\n");
                            }
                            break;
                        }
                    }
                    gpioDelay(10000);
                }
            }
        }
        gpioDelay(10000);
    }

    set_servo_pulsewidth(SERVO_PIN, 0);
    gpioTerminate();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

