        if (set_motor(MOTOR1_PIN, MOTOR1_DURATION_MS) < 0) {
            break;
        }
        if (!running) {
            break;
        }
        if (set_motor(MOTOR2_PIN, MOTOR2_DURATION_MS) < 0) {
            break;
        }
    }

    /* Ensure motors are off by driving the lines low */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

