#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <zmq.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"
#define SOUND_SENSOR_PIN    17
#define ALARM_LED_PIN       27
#define ZMQ_ENDPOINT        "tcp://*:5555"
#define ZMQ_TOPIC           "SOUND_ALERTS"
#define POLL_INTERVAL_US    10000
#define ALARM_DURATION_US   1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_line,
                      struct gpiod_line **led_line)
{
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *sound_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(*sound_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip,
                         struct gpiod_line *sound_line,
                         struct gpiod_line *led_line)
{
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line)
        gpiod_line_release(sound_line);
    if (chip)
        gpiod_chip_close(chip);
}

static int setup_zmq(void **ctx, void **socket)
{
    *ctx = zmq_ctx_new();
    if (!*ctx) {
        perror("zmq_ctx_new");
        return -1;
    }

    *socket = zmq_socket(*ctx, ZMQ_SUB);
    if (!*socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(*ctx);
        *ctx = NULL;
        return -1;
    }

    if (zmq_connect(*socket, ZMQ_ENDPOINT) == -1) {
        perror("zmq_connect");
        zmq_close(*socket);
        *socket = NULL;
        zmq_ctx_destroy(*ctx);
        *ctx = NULL;
        return -1;
    }

    if (zmq_setsockopt(*socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) == -1) {
        perror("zmq_setsockopt");
        zmq_close(*socket);
        *socket = NULL;
        zmq_ctx_destroy(*ctx);
        *ctx = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_zmq(void *ctx, void *socket)
{
    if (socket) {
        zmq_close(socket);
        socket = NULL;
    }
    if (ctx) {
        zmq_ctx_destroy(ctx);
        ctx = NULL;
    }
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor | alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s (choose sound_sensor or alarm_node)\n", mode);
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    void *zmq_ctx = NULL;
    void *zmq_socket = NULL;
    int rc = EXIT_FAILURE;

    if (strcmp(mode, "sound_sensor") == 0) {
        if (setup_gpio(&chip, &sound_line, &led_line) != 0)
            goto cleanup;

        printf("Sound sensor mode started. Press Ctrl+C to exit.\n");

        while (g_running) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value");
                break;
            }

            if (val == 0) {
                char msg[64];
                time_t now = time(NULL);
                struct tm tm_info;
                char time_str[32];
                localtime_r(&now, &tm_info);
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
                snprintf(msg, sizeof(msg), "%s - Sound detected!", time_str);

                if (zmq_socket) {
                    if (zmq_send(zmq_socket, msg, strlen(msg), 0) == -1) {
                        perror("zmq_send");
                        break;
                    }
                }
            }

            usleep(POLL_INTERVAL_US);
        }

        gpiod_line_set_value(led_line, 0);
        rc = EXIT_SUCCESS;
    } else {
        if (setup_zmq(&zmq_ctx, &zmq_socket) != 0)
            goto cleanup;

        if (setup_gpio(&chip, &sound_line, &led_line) != 0)
            goto cleanup;

        printf("Alarm node mode started. Press Ctrl+C to exit.\n");

        while (g_running) {
            char buffer[256];
            int bytes = zmq_recv(zmq_socket, buffer, sizeof(buffer) - 1, 0);
            if (bytes == -1) {
                if (errno == EINTR)
                    continue;
                perror("zmq_recv");
                break;
            }
            if (bytes > 0) {
                buffer[bytes] = '\0';
                printf("Received: %s\n", buffer);
                gpiod_line_set_value(led_line, 1);
                usleep(ALARM_DURATION_US);
                gpiod_line_set_value(led_line, 0);
            }
        }

        gpiod_line_set_value(led_line, 0);
        rc = EXIT_SUCCESS;
    }

cleanup:
    cleanup_gpio(chip, sound_line, led_line);
    cleanup_zmq(zmq_ctx, zmq_socket);
    return rc;
}

