 * NEC IR Remote Decoder for Raspberry Pi 3 Model B+
 * IR receiver: TSOP38238 on GPIO17 (BCM)
 * MQTT broker: localhost:1883, topic ir/decoded
 *
 * Build: gcc -O2 -Wall -Wextra -o ir_decoder ir_decoder.c -lpigpio -lmosquitto -lrt
 * Run:   sudo ./ir_decoder
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO          17
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "ir/decoded"
#define MAX_PULSES       100
#define PULSE_TIMEOUT_US 200000
#define TICK_US          10000

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK     9000
#define NEC_HDR_SPACE    4500
#define NEC_BIT_MARK     560
#define NEC_ONE_SPACE    1690
#define NEC_ZERO_SPACE   560
#define NEC_TOL          200

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mqtt = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Pulse timing state                                                  */
/* ------------------------------------------------------------------ */
typedef struct {
    uint32_t ticks;          /* pigpio tick (microseconds) */
    uint32_t count;          /* number of valid pulses */
    uint32_t last_tick;      /* last edge tick */
    uint32_t last_level;     /* last edge level */
} pulse_state_t;

static pulse_state_t g_pulse = {0};

/* ------------------------------------------------------------------ */
/* NEC decoding                                                        */
/* ------------------------------------------------------------------ */
static bool in_range(uint32_t val, uint32_t target, uint32_t tol)
{
    return (val >= target - tol) && (val <= target + tol);
}

/*
 * Decode a full 32-bit NEC frame.
 * Returns true on success and stores the command in *cmd.
 * Extended NEC (no inverted address) is accepted.
 */
static bool decode_nec(const uint32_t *pulses, uint32_t count, uint32_t *cmd)
{
    if (count < 32) {
        syslog(LOG_ERR, "NEC: too few pulses (%u)", count);
        return false;
    }

    /* Validate header */
    if (!in_range(pulses[0], NEC_HDR_MARK, NEC_TOL) ||
        !in_range(pulses[1], NEC_HDR_SPACE, NEC_TOL)) {
        syslog(LOG_ERR, "NEC: invalid header (mark=%u space=%u)",
               pulses[0], pulses[1]);
        return false;
    }

    uint32_t address = 0;
    uint32_t command = 0;

    for (uint32_t i = 0; i < 32; i++) {
        uint32_t idx = 2 + i * 2;
        if (idx + 1 >= count) {
            syslog(LOG_ERR, "NEC: incomplete frame at bit %u", i);
            return false;
        }

        uint32_t mark  = pulses[idx];
        uint32_t space = pulses[idx + 1];

        if (!in_range(mark, NEC_BIT_MARK, NEC_TOL)) {
            syslog(LOG_ERR, "NEC: invalid bit mark at bit %u (mark=%u)", i, mark);
            return false;
        }

        if (in_range(space, NEC_ONE_SPACE, NEC_TOL)) {
            command |= (1u << i);
        } else if (in_range(space, NEC_ZERO_SPACE, NEC_TOL)) {
            /* clear bit */
        } else {
            syslog(LOG_ERR, "NEC: invalid bit space at bit %u (space=%u)", i, space);
            return false;
        }

        address |= (command & (1u << i)) ? (1u << i) : 0;
    }

    /* Validate inverted address */
    uint32_t inv = ~address;
    if (inv != (command & 0x0000FFFFu)) {
        syslog(LOG_ERR, "NEC: address mismatch (0x%08X ~ 0x%08X = 0x%08X)",
               address, inv, command & 0x0000FFFFu);
        return false;
    }

    *cmd = command;
    return true;
}

/* ------------------------------------------------------------------ */
/* GPIO alert callback (falling edge)                                  */
/* ------------------------------------------------------------------ */
static void ir_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0) {
        return; /* only falling edges */
    }

    pulse_state_t *st = (pulse_state_t *)userdata;
    uint32_t elapsed = tick - st->last_tick;

    if (st->count == 0) {
        st->last_tick = tick;
        st->last_level = 0;
        return;
    }

    /* Check for long gap (timeout) */
    if (elapsed > PULSE_TIMEOUT_US) {
        st->count = 0;
        st->last_tick = tick;
        st->last_level = 0;
        return;
    }

    /* Store falling-edge pulse */
    if (st->count < MAX_PULSES) {
        st->ticks[st->count++] = elapsed;
    } else {
        syslog(LOG_ERR, "NEC: pulse buffer overflow (%u pulses)", st->count);
        st->count = 0;
        st->last_tick = tick;
        st->last_level = 0;
        return;
    }

    st->last_tick = tick;
    st->last_level = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_publish(uint32_t command)
{
    if (!g_mqtt) {
        syslog(LOG_ERR, "MQTT client not initialized");
        return;
    }

    char payload[64];
    int len = snprintf(payload, sizeof(payload), "{\"command\":%u}", command);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "MQTT payload formatting failed");
        return;
    }

    int rc = mosquitto_publish(g_mqtt, NULL, MQTT_TOPIC, (int)strlen(payload),
                               payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mqtt) {
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = NULL;
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure GPIO */
    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", IR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register alert callback (falling edge) */
    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, &g_pulse) != 0) {
        syslog(LOG_ERR, "gpioSetAlertFuncEx(%d) failed", IR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize Mosquitto */
    mosquitto_lib_init();
    g_mqtt = mosquitto_new(NULL, true, NULL);
    if (!g_mqtt) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mqtt, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mqtt, mqtt_disconnect_callback);

    int rc = mosquitto_connect(g_mqtt, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    if (mosquitto_loop_start(g_mqtt) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started (GPIO%d -> MQTT %s:%d)",
           IR_GPIO, MQTT_HOST, MQTT_PORT);

    /* Main loop */
    while (g_running) {
        mosquitto_loop(g_mqtt, 100, 1);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

