#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS     4
#define BH1750_ADDR     0x23
#define BH1750_CONT     0x10
#define BH1750_ONE_TIME 0x20
#define CONV_DELAY_MS   180
#define LOOP_DELAY_MS   1000

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int i2c_open(int *fd, int addr)
{
    int fd0 = open(I2C_BUS, O_RDWR);
    if (fd0 < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd0, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd0);
        return -1;
    }
    *fd = fd0;
    return 0;
}

static int bh1750_read(int fd, float *lux)
{
    unsigned char cmd = BH1750_ONE_TIME;
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "BH1750 write(0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(CONV_DELAY_MS * 1000);

    unsigned char buf[2];
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: got %zd bytes (%s)\n", n, strerror(errno));
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const char *msg)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        i2c_fds[i] = -1;

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_open(&i2c_fds[i], BH1750_ADDR + i) < 0) {
            for (int j = 0; j < i; j++)
                close(i2c_fds[j]);
            return EXIT_FAILURE;
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++)
            close(i2c_fds[i]);
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL): %s\n", strerror(errno));
        close(sockfd);
        for (int i = 0; i < NUM_SENSORS; i++)
            close(i2c_fds[i]);
        return EXIT_FAILURE;
    }

    while (!g_terminate) {
        float lux[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read(i2c_fds[i], &lux[i]) < 0) {
                fprintf(stderr, "Sensor %d read failed; using NaN\n", i + 1);
                lux[i] = NAN;
                error = 1;
            }
        }

        if (error) {
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        char msg[256];
        int len = snprintf(msg, sizeof(msg), "1,%.1f;2,%.1f;3,%.1f;4,%.1f",
                           lux[0], lux[1], lux[2], lux[3]);
        if (len < 0 || (size_t)len >= sizeof(msg)) {
            fprintf(stderr, "snprintf buffer error\n");
            break;
        }

        if (send_multicast(sockfd, msg) < 0)
            break;

        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++)
        if (i2c_fds[i] >= 0)
            close(i2c_fds[i]);
    if (sockfd >= 0)
        close(sockfd);

    if (g_terminate)
        fprintf(stderr, "Terminated cleanly.\n");
    return g_terminate ? EXIT_SUCCESS : EXIT_FAILURE;
}

