#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300_ADDR   0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_length(int fd)
{
    /* Issue a zero-length I2C write to generate a start condition. */
    if (write(fd, NULL, 0) < 0) {
        if (errno == EREMOTEIO) {
            fprintf(stderr, "Error: sensor not responding (ENXIO).\n");
            return -1;
        }
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EREMOTEIO) {
            fprintf(stderr, "Error: sensor not responding (ENXIO).\n");
            return -1;
        }
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)len) {
        fprintf(stderr, "Error: short read: got %zd of %zu bytes.\n", n, len);
        return -1;
    }
    return 0;
}

static int parse_sensor_data(const uint8_t *buf, float *flow_rate)
{
    /*
     * Honeywell AWM7300V: 14-bit flow value in the first two bytes.
     * Byte 0: bits 7-4 = MSB of flow, bits 3-0 = reserved.
     * Byte 1: bits 7-0 = LSB of flow.
     * SLPM = ( (byte0 & 0x0F) << 8 | byte1 ) / 16383.0 * 100.0
     */
    uint16_t raw = ((uint16_t)(buf[0] & 0x0F) << 8) | buf[1];
    *flow_rate = (float)raw / 16383.0f * 100.0f;
    return 0;
}

static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
