        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t buf[2];
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (i2c_write_zero_length(g_i2c_fd) == 0) {
                if (read_sensor_data(g_i2c_fd, buf, sizeof(buf)) == 0) {
                    float flow_rate;
