                        if (log_flow_rate(g_log_fp, flow_rate) == 0) {
                            success = 1;
                            break;
                        }
                    }
                }
            }
            retries++;
            if (retries < MAX_RETRIES && g_running) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!success) {
            fprintf(stderr, "Error: sensor read failed after %d retries.\n", MAX_RETRIES);
        }

        if (g_running) {
            sleep(SAMPLE_PERIOD);
        }
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Warning: fclose() failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }
