/*
 * AS7341 10-Channel Spectral & Lux Monitor for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  Address: 0x5C  (SDO tied to GND)
 *
 * Build: gcc -O2 -Wall -o as7341_monitor as7341_monitor.c
 *
 * Reads spectral channels F1-F8, Clear, and NIR every 5 s, computes a
 * simplified lux approximation, and appends a CSV row with a timestamp.
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

/* ---- AS7341 constants (per Adafruit AS7341 Arduino library) ---- */
#define AS7341_I2C_ADDR        0x5C
#define AS7341_REG_ENABLE      0x01
#define AS7341_REG_ATIME       0x01
#define AS7341_REG_ID          0x00
#define AS7341_REG_CFG6        0x06
#define AS7341_REG_CH0_DATA    0x10
#define AS7341_REG_CH1_DATA    0x12
#define AS7341_REG_CH2_DATA    0x14
#define AS7341_REG_CH3_DATA    0x16
#define AS7341_REG_CH4_DATA    0x18
#define AS7341_REG_CH5_DATA    0x1A
#define AS7341_REG_CH6_DATA    0x1C
#define AS7341_REG_CH7_DATA    0x1E
#define AS7341_REG_CLEAR_DATA  0x20
#define AS7341_REG_NIR_DATA    0x22

#define AS7341_ID_VALUE        0x41
#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x10
#define AS7341_ATIME_100MS     0x80
#define AS7341_CFG6_SMUX_10CH  0x00

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "spectral_log.csv"
#define SAMPLE_PERIOD  5   /* seconds */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_REG_ID, &id) != 0)
        return -1;
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-on delay */

    /* Set integration time to 100 ms (ATIME = 0x80) */
    if (i2c_write_reg8(fd, AS7341_REG_ATIME, AS7341_ATIME_100MS) != 0)
        return -1;

    /* Configure SMUX for 10-channel mode (no IR blocking) */
    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_CFG6_SMUX_10CH) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    usleep(10000);  /* allow first integration cycle to complete */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_spectral_data(int fd, uint16_t ch[8], uint16_t clear, uint16_t nir)
{
    if (i2c_read_reg16(fd, AS7341_REG_CH0_DATA, &ch[0]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH1_DATA, &ch[1]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH2_DATA, &ch[2]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH3_DATA, &ch[3]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH4_DATA, &ch[4]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH5_DATA, &ch[5]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH6_DATA, &ch[6]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CH7_DATA, &ch[7]) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CLEAR_DATA, &clear) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_NIR_DATA, &nir) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static double calculate_lux(const uint16_t ch[8], uint16_t clear, uint16_t nir)
{
    /* Simplified approximation: sum of spectral channels scaled by clear */
    double sum = 0.0;
    for (int i = 0; i < 8; i++)
        sum += (double)ch[i];
    sum += (double)nir;
    return (sum / (double)clear) * 100.0;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const uint16_t ch[8], uint16_t clear, uint16_t nir, double lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%.2f\n",
                ts, ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], clear, nir, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,ch1,ch2,ch3,ch4,ch5,ch6,ch7,clear,nir,lux\n");
        fflush(g_log);
    }

    printf("AS7341 monitoring started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        uint16_t ch[8], clear, nir;

        if (read_spectral_data(g_i2c_fd, ch, clear, nir) != 0) {
            fprintf(stderr, "Spectral read failed; continuing.\n");
        } else {
            double lux = calculate_lux(ch, clear, nir);
            if (log_data(g_log, ch, clear, nir, lux) != 0)
                fprintf(stderr, "Logging failed.\n");
            printf("ch1=%u ch2=%u ch3=%u ch4=%u ch5=%u ch6=%u ch7=%u clear=%u nir=%u lux=%.2f\n",
                   ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], clear, nir, lux);
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

