#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>
#include <math.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B921600
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 100
#define MAX_RANGE 100.0
#define MAX_VELOCITY 10.0
#define MAGIC_WORD_LEN 8
#define TLV_HEADER_LEN 8
#define FRAME_HEADER_LEN 24
#define MAX_FRAME_SIZE 8192

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static FILE *csv_file = NULL;

typedef struct {
    float range;
    float velocity;
} RadarData;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 (device disconnected)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd, uint8_t *buf, size_t buf_len) {
    static const uint8_t magic[MAGIC_WORD_LEN] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    uint8_t byte;
    size_t i = 0;

    while (i < buf_len - MAGIC_WORD_LEN + 1) {
        if (read_exact(fd, &byte, 1) != 0) return -1;
        if (byte == magic[i]) {
            if (i == MAGIC_WORD_LEN - 1) return 0;
        } else {
            i = 0;
        }
    }
    return -1;
}

static int read_frame_header(int fd, uint8_t *buf, size_t buf_len) {
    if (find_magic_word(fd, buf, buf_len) != 0) return -1;
    if (read_exact(fd, buf + MAGIC_WORD_LEN, FRAME_HEADER_LEN - MAGIC_WORD_LEN) != 0) return -1;
    return 0;
}

static int read_tlv_header(int fd, uint8_t *buf, size_t buf_len) {
    if (read_exact(fd, buf, TLV_HEADER_LEN) != 0) return -1;
    uint32_t tlv_type = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    uint32_t tlv_length = (buf[4] << 24) | (buf[5] << 16) | (buf[6] << 8) | buf[7];
    if (tlv_type != 1) {
        fprintf(stderr, "Unexpected TLV type: %u\n", tlv_type);
        return -1;
    }
    if (tlv_length > buf_len - TLV_HEADER_LEN) {
        fprintf(stderr, "TLV length exceeds buffer: %u\n", tlv_length);
        return -1;
    }
    return 0;
}

static int read_object_data(int fd, uint8_t *buf, size_t buf_len, int *num_objects) {
    uint32_t num_objects_raw;
    if (read_exact(fd, buf, 4) != 0) return -1;
    num_objects_raw = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    if (num_objects_raw > MAX_OBJECTS) {
        fprintf(stderr, "Invalid object count: %u\n", num_objects_raw);
        return -1;
    }
    *num_objects = (int)num_objects_raw;
    if (read_exact(fd, buf, *num_objects * 16) != 0) return -1;
    return 0;
}

static void process_object_data(const uint8_t *buf, int num_objects, RadarData *data) {
    for (int i = 0; i < num_objects; i++) {
        int offset = i * 16;
        uint16_t range_idx = (buf[offset] << 8) | buf[offset + 1];
        uint16_t doppler_idx = (buf[offset + 2] << 8) | buf[offset + 3];
        uint16_t peak_val = (buf[offset + 4] << 8) | buf[offset + 5];
        uint16_t x = (buf[offset + 6] << 8) | buf[offset + 7];
        uint16_t y = (buf[offset + 8] << 8) | buf[offset + 9];
        uint16_t z = (buf[offset + 10] << 8) | buf[offset + 11];
        uint16_t velocity = (buf[offset + 12] << 8) | buf[offset + 13];
        uint16_t peak_conf = (buf[offset + 14] << 8) | buf[offset + 15];

        if (range_idx > 0 && doppler_idx > 0 && peak_val > 0) {
            data[i].range = (float)range_idx / 10.0;
            data[i].velocity = (float)velocity / 10.0;
        } else {
            data[i].range = 0.0;
            data[i].velocity = 0.0;
        }
    }
}

static int write_csv(RadarData *data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        if (fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, data[i].range, data[i].velocity) < 0) {
            perror("Error writing to CSV");
            return -1;
        }
    }
    fflush(csv_file);
    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

