            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading UART: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            fprintf(stderr, "Warning: UART reported EOF (sensor absent or bus error).\n");
            break;
        }

        read_buf[n] = '\0';

        for (ssize_t i = 0; i < n; i++) {
            char c = read_buf[i];
            if (c == '\n' || c == '\r') {
                if (line_len > 0) {
                    line_buf[line_len] = '\0';
                    if (parse_line(line_buf, timestamp, sizeof(timestamp)) == 0) {
                        printf("Timestamp: %s, Range: %.2f meters\n", timestamp, atof(line_buf));
                        fflush(stdout);
                    } else {
                        fprintf(stderr, "Invalid data line: %s\n", line_buf);
                    }
                    line_len = 0;
                }
            } else if (line_len < LINE_BUF_SIZE - 1) {
                line_buf[line_len++] = c;
            } else {
                fprintf(stderr, "Warning: line buffer overflow, discarding.\n");
                line_len = 0;
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    return EXIT_SUCCESS;
}

