#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define UART_DEVICE        "/dev/ttyAMA0"
#define BAUD_RATE          115200
#define POLL_DELAY_US      100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_uart_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    gpioTerminate();
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
    }

    return 0;
}

static int initialize_uart(void)
{
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
